INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('paracetamol', 'Paracetamol 500mg', 'Paracetamol (Asetaminofen)', 'Demam & Nyeri', 'Obat Bebas (Hijau)', 'Tablet / Kaplet / Sirup', 'Meredakan demam, sakit kepala, sakit gigi, dan nyeri ringan hingga sedang.', 'Dewasa: 1-2 tablet (500-1000mg) 3-4 kali sehari sesudah makan. Maksimal 4000mg dalam 24 jam.', '["Paracetamol 500mg", "Paracetamol", "Paracetamol Generik", "Asetaminofen"]', '["paracetamol", "parasetamol", "asetaminofen", "paracetam0l", "paracetamol 500 mg", "paracetamol 500mg", "panadol biru", "panadol merah"]', '["p4r4cet4mol", "parac3tamol", "paracetam0l", "paracetamo", "paracetamo1", "paracetamoi", "paracetarnol", "parasetamol"]', 'DBL8504503710A1', 'paracetamol', 'acetaminophen');
