INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('mylanta', 'Mylanta', 'Aluminium Hydroxide, Magnesium Hydroxide, Simethicone', 'Lambung & Maag', 'Obat Bebas (Hijau)', 'Tablet Kunyah / Cair Suspensi', 'Meredakan rasa perih di ulu hati, kembung, dan rasa begah asam lambung.', 'Dewasa: 1-2 tablet dikunyah 1 jam setelah makan dan sebelum tidur.', '["Mylanta"]', '["mylanta", "mylanta cair", "mylanta tablet"]', '[]', 'DBL1441200210A1', 'mylanta', 'aluminiumhydroxidemagnesiumhydroxidesimethicone');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('polysilane', 'Polysilane', 'Dimethicone, Aluminium Hydroxide, Magnesium Hydroxide', 'Lambung & Maag', 'Obat Bebas (Hijau)', 'Tablet Kunyah / Suspensi Cair', 'Mengatasi kelebihan asam lambung, nyeri tukak lambung, dan kembung gas berlebih.', 'Dewasa: 1-2 tablet 3-4 kali sehari 1 jam sebelum makan atau saat perut kosong.', '["Polysilane"]', '["polysilane", "polysilane cair", "polysilane tablet kunyah"]', '[]', 'DBL7821624210A1', 'polysilane', 'dimethiconealuminiumhydroxidemagnesiumhydroxide');
