INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('teh-hijau', 'Teh Hijau', 'Teh Hijau', 'Pengobatan Umum', 'Obat Keras (Lingkaran Merah K)', 'Sediaan oral/topikal sesuai instruksi kemasan.', 'Mendukung penurunan berat badan', 'Gunakan sesuai petunjuk dokter atau aturan pakai pada kemasan.', '["Teh Hijau"]', '["teh hijau", "th hijau", "teh hija", "teh hljau", "teh h1jau", "t3h hijau", "teh hij4u"]', '["t3h hijau", "teh h1jau", "teh hij4u", "teh hija", "teh hljau", "th hijau"]', 'DKL10000818A1', 'tehhijau', 'tehhijau');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('galantamine', 'Galantamine', 'Galantamine', 'Cholinesterase inhibitors', 'Obat Keras (Lingkaran Merah K)', 'Kapsul lepas lambat, tablet, sirop', 'Meringankan gejala penyakit Alzheimer', 'Galantamine hanya boleh digunakan sesuai anjuran dokter. Berikut ini adalah dosis umum penggunaan galantamine dalam pengobatan penyakit Alzheimer berdasarkan bentuk obatnya:', '["Galantamine", "tablet", "PPOK", "gangguan irama jantung", "tukak lambung", "perdarahan saluran pencernaan"]', '["galantamine", "tukak lambung", "gangguan irama jantung", "galantarnine", "tablet", "galantam1ne", "ppok", "galantamlne", "gaiantamine", "galantamin3", "ga1antamine", "g4l4nt4mine", "galantamin"]', '["g4l4nt4mine", "ga1antamine", "gaiantamine", "galantam1ne", "galantamin", "galantamin3", "galantamlne", "galantarnine"]', 'DKL10001121A1', 'galantamine', 'galantamine');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('afatinib', 'Afatinib', 'Afatinib', 'Obat antikanker golongan penghambat protein kinase', 'Obat Keras (Lingkaran Merah K)', 'Tablet', 'Menangani kanker paru jenis non-small cell lung cancer (NSCLC) stadium lanjut atau kanker paru-paru stadium 4 yang sudah menyebar ke organ lain.', 'Dalam pengobatan kanker paru-paru non sel kecil, dosis afatinib adalah 40 mg, 1 kali sehari. Dosis dapat ditingkatkan menjadi 50 mg, 1 kali sehari, tergantung pada respons pasien terhadap pengobatan. Pemberian obat dapat dihentikan jika kondisi pasien memburuk atau muncul efek samping yang berat.', '["Afatinib", "penyakit ginjal", "penyakit jantung", "atau penyakit paru-paru lain", "termasuk suplemen dan produk herbal", "mungkin sedang hamil"]', '["penyakit ginjal", "penyakit jantung", "afatini", "aphatinib", "afatinib", "atau penyakit paru-paru lain", "afatlnlb", "aatinib", "termasuk suplemen dan produk herbal", "4f4tinib", "afat1n1b"]', '["4f4tinib", "aatinib", "afat1n1b", "afatini", "afatlnlb", "aphatinib"]', 'DKL10000798A1', 'afatinib', 'afatinib');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('ocuflam', 'Ocuflam', 'Fluorometholone', 'Kortikosteroid', 'Obat Keras (Lingkaran Merah K)', 'Tetes mata', 'Meredakan peradangan pada mata, misalnya akibat uveitis, cedera mata, atau operasi mata', 'Secara umum, dosis penggunaan Ocuflam untuk mengobati peradangan pada mata adalah:', '["Ocuflam"]', '["ocufl4m", "ocuflam", "0cuflam", "osuflam", "fluorometholone", "ocuflarn", "ocuphlam", "ocufiam", "ocufla", "ocuf1am"]', '["0cuflam", "ocuf1am", "ocufiam", "ocufl4m", "ocufla", "ocuflarn", "ocuphlam", "osuflam"]', 'DKL10000711A1', 'ocuflam', 'fluorometholone');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('raniphil', 'Raniphil', 'Ranitidin 150 mg', 'Antagonis H2', 'Obat Keras (Lingkaran Merah K)', 'Tablet salut selaput', 'Menurunkan produksi asam lambung', 'Dosis penggunaan Raniphil ditentukan berdasarkan kondisi yang akan diatasi, tingkat keparahannya, serta usia pasien. Berikut ini adalah dosisnya:', '["Raniphil"]', '["rniphil", "ranitidin 150 mg", "raniphil", "raniphii", "r4niphil", "ranlphll", "ran1ph1l", "raniphi", "raniphi1", "ranifil"]', '["r4niphil", "ran1ph1l", "ranifil", "raniphi", "raniphi1", "raniphii", "ranlphll", "rniphil"]', 'DKL10000823A1', 'raniphil', 'ranitidin150mg');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('abrocitinib', 'Abrocitinib', 'Abrocitinib', 'Obat imunosupresan', 'Obat Keras (Lingkaran Merah K)', 'Tablet', 'Mengatasi penyakit dermatitis atopik', 'Dosis dan aturan pakai abrocitinib akan ditentukan oleh dokter berdasarkan usia atau kondisi pasien. Secara umum, berikut adalah dosis abrocitinib:', '["Abrocitinib", "penyakit ginjal", "penyakit liver", "gangguan pembekuan darah", "gangguan sistem kekebalan tubuh", "anemia"]', '["penyakit ginjal", "4brocitinib", "penyakit liver", "arocitinib", "abrocitini", "abrocltlnlb", "gangguan sistem kekebalan tubuh", "abrocitinib", "abr0citinib", "abroc1t1n1b", "gangguan pembekuan darah", "abrositinib"]', '["4brocitinib", "abr0citinib", "abroc1t1n1b", "abrocitini", "abrocltlnlb", "abrositinib", "arocitinib"]', 'DKL10001126A1', 'abrocitinib', 'abrocitinib');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('acalabrutinib', 'Acalabrutinib', 'Acalabrutinib', 'Penghambat protein kinase', 'Obat Keras (Lingkaran Merah K)', 'Kapsul', 'Mengobati leukemia limfostik kronis (LLK) atau limfoma limfostik kecil (LLS), dan limfoma sel mantel (LSM)', 'Acalabrutinib digunakan untuk menangani limfoma sel mantel yang tidak membaik dengan terapi lain, serta untuk leukemia limfositik kronis atau limfoma limfositik kecil. Dosis umumnya adalah 100 mg, diminum 2 kali sehari dengan jarak 12 jam antardosis.', '["Acalabrutinib", "penyakit infeksi", "gangguan irama jantung aritmia", "menyusui", "mungkin hamil", "membelah"]', '["acalabrutinib", "acalabrutlnlb", "aca1abrutinib", "acalabrutini", "4c4l4brutinib", "acalabrut1n1b", "menyusui", "acaiabrutinib", "gangguan irama jantung aritmia", "asalabrutinib", "aalabrutinib", "mungkin hamil", "penyakit infeksi"]', '["4c4l4brutinib", "aalabrutinib", "aca1abrutinib", "acaiabrutinib", "acalabrut1n1b", "acalabrutini", "acalabrutlnlb", "asalabrutinib"]', 'DKL10001329A1', 'acalabrutinib', 'acalabrutinib');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('galdom', 'Galdom', 'Domperidone', 'Antiemetik jenis antagonis dopamin', 'Obat Keras (Lingkaran Merah K)', 'Tablet dan suspensi', 'Mengatasi mual dan muntah', 'Berikut adalah dosis umum penggunaan Galdom untuk mengatasi mual dan muntah berdasarkan bentuk obatnya:', '["Galdom"]', '["g4ldom", "galdo", "gald0m", "galdorn", "gldom", "galdom", "ga1dom", "gaidom", "domperidone"]', '["g4ldom", "ga1dom", "gaidom", "gald0m", "galdo", "galdorn", "gldom"]', 'DKL10000596A1', 'galdom', 'domperidone');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('xalatan', 'Xalatan', 'Latanoprost', 'Analog prostaglandin', 'Obat Keras (Lingkaran Merah K)', 'Tetes mata', 'Menurunkan tekanan di dalam mata akibat glaukoma sudut terbuka atau hipertensi okular', 'Obat tetes mata Xalatan digunakan untuk mengatasi tekanan intraokular pada orang yang menderita glaukoma sudut terbuka dan glaukoma sudut tertutup kronis atau hipertensi okular.', '["Xalatan"]', '["xalatan", "xalata", "x4l4t4n", "ksalatan", "latanoprost", "xlatan", "xa1atan", "xaiatan"]', '["ksalatan", "x4l4t4n", "xa1atan", "xaiatan", "xalata", "xlatan"]', 'DKL10000713A1', 'xalatan', 'latanoprost');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('lamivudine', 'Lamivudine', 'Lamivudine', 'Obat antivirus', 'Obat Keras (Lingkaran Merah K)', 'Tablet', 'Mengatasi infeksi virus hepatitis B dan HIV', 'Berikut ini adalah dosis umum penggunaan lamivudine berdasarkan kondisi dan usia pasien:', '["Heplav", "Hiviral", "Lamivudine", "penyakit ginjal", "diabetes", "pankreatitis"]', '["penyakit ginjal", "hiviral", "lamlvudlne", "lamivudine", "lamivudin3", "3tc", "iamivudine", "larnivudine", "heplav", "l4mivudine", "1amivudine", "lam1vud1ne", "lamivudin"]', '["1amivudine", "iamivudine", "l4mivudine", "lam1vud1ne", "lamivudin", "lamivudin3", "lamlvudlne", "larnivudine"]', 'DKL10001038A1', 'lamivudine', 'lamivudine');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('decafil', 'Decafil', 'Aminofilin', 'Bronkodilator', 'Obat Bebas Terbatas (Lingkaran Biru)', 'Tablet', 'Mengatasi gangguan pernapasan, seperti mengi dan sesak napas, akibat asma, bronkitis kronis, atau penyakit paru obstruktif kronis.', 'Rekomendasi dosis Decafil untuk dewasa dan anak usia >12 tahun adalah 1–3 tablet (150–450 mg), 2 kali sehari. Sementara itu, dosis Decafil untuk anak usia 6–12 tahun ditentukan oleh dokter berdasarkan berat badan (BB) anak.', '["Decafil"]', '["dcafil", "decaf1l", "aminofilin", "dec4fil", "decafii", "decafi1", "decafil", "decafll", "decafi", "d3cafil"]', '["d3cafil", "dcafil", "dec4fil", "decaf1l", "decafi", "decafi1", "decafii", "decafll"]', 'DTL10000680A1', 'decafil', 'aminofilin');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('ocuson', 'Ocuson', 'Dexchlorpheniramine dan betamethasone', 'Antihistamin dan kortikosteroid', 'Obat Keras (Lingkaran Merah K)', 'Tablet', 'Mengatasi gejala alergi dan peradangan', 'Dosis umum penggunaan Ocuson untuk mengatasi gejala alergi dan peradangan pada dewasa dan anak usia di atas 12 tahun adalah 1–2 tablet, 3–4 kali sehari. Dosis maksimal sebanyak 8 tablet per hari.', '["Ocuson"]', '["ocuso", "ocu5on", "dexchlorpheniramine dan betamethasone", "ocuson", "ouson", "osuson", "0cus0n"]', '["0cus0n", "ocu5on", "ocuso", "osuson", "ouson"]', 'DKL10000631A1', 'ocuson', 'dexchlorpheniraminedanbetamethasone');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('lamodex-krim', 'Lamodex Krim', 'Clobetasol propionate 0,05%', 'Kortikosteroid topikal', 'Obat Keras (Lingkaran Merah K)', 'Krim', 'Meredakan peradangan di kulit, misalnya akibat eksim, psoriasis, dermatitis, lichen planus , atau lupus', 'Untuk mengatasi peradangan kulit yang berat, seperti psoriasis atau eksim yang parah, oleskan Lamodex krim secara merata pada area kulit yang perlu diobati, 1–2 kali sehari atau sesuai petunjuk dokter.', '["Lamodex Krim"]', '["l4modex krim", "iamodex krim", "lamodex kr1m", "1amodex krim", "lamod3x krim", "clobetasol propionate 0,05%", "lamodex kri", "lamodex krim", "lam0dex krim", "lamodeks krim"]', '["1amodex krim", "iamodex krim", "l4modex krim", "lam0dex krim", "lamod3x krim", "lamodeks krim", "lamodex kr1m", "lamodex kri"]', 'DKL10001149A1', 'lamodexkrim', 'clobetasolpropionate005');
