INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('xaliquis', 'Xaliquis', 'Apixaban', 'Antikoagulan jenis penghambat faktor Xa', 'Obat Keras (Lingkaran Merah K)', 'Tablet salut selaput', 'Mencegah stroke dan penggumpalan darah', 'Dosis Xaliquis tergantung pada tujuan pengobatan, serta kondisi dan usia pasien. Di bawah ini adalah dosis umum Xaliquis untuk orang dewasa:', '["Xaliquis"]', '["apixaban", "xallquls", "xaliquis", "ksaliquis", "xaiiquis", "xal1qu1s", "xa1iquis", "xaliqui5", "xaliqui", "x4liquis"]', '["ksaliquis", "x4liquis", "xa1iquis", "xaiiquis", "xal1qu1s", "xaliqui", "xaliqui5", "xallquls"]', 'DKL10000848A1', 'xaliquis', 'apixaban');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('ranitidin', 'Ranitidin', 'Ranitidin', 'Antagonis H2', 'Obat Keras (Lingkaran Merah K)', 'Tablet, kaplet, sirop, dan cairan suntik', 'Menurunkan produksi asam lambung berlebih', 'Dosis ranitidin ditentukan berdasarkan kondisi yang akan diatasi, tingkat keparahan penyakit, dan usia pasien. Berikut adalah dosis ranitidin oral:', '["Ranitidin", "Acran", "Bloxer", "Fordin", "Gasela", "Gasticid"]', '["rnitidin", "r4nitidin", "acran", "ranltldln", "ranitidin", "fordin", "ran1t1d1n", "gasela", "ranitidi", "bloxer"]', '["r4nitidin", "ran1t1d1n", "ranitidi", "ranltldln", "rnitidin"]', 'DKL10000930A1', 'ranitidin', 'ranitidin');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('afibramol', 'Afibramol', 'Paracetamol', 'Analgesik-antipiretik', 'Obat Bebas Terbatas (Lingkaran Biru)', 'Kaplet', 'Menurunkan demam, misalnya setelah vaksinasi', 'Berikut ini adalah dosis umum penggunaan Afibramol untuk mengatasi gejala flu berdasarkan usia pasien:', '["Afibramol"]', '["afibramol", "4fibr4mol", "aflbramol", "afibrarnol", "afibramoi", "afibramo", "afibramo1", "afibram0l", "paracetamol", "af1bramol"]', '["4fibr4mol", "af1bramol", "afibram0l", "afibramo", "afibramo1", "afibramoi", "afibrarnol", "aflbramol"]', 'DTL10000909A1', 'afibramol', 'paracetamol');
