INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('almacon', 'Almacon', 'Aluminium hidroksida , magnesium hidroksida, dan dimethicone', 'Antasida dan antiflatulensi (antikembung)', 'Obat Bebas (Hijau)', 'Tablet kunyah', 'Meredakan gejala sakit maag akibat kelebihan asam lambung, termasuk pada gastritis, tukak lambung, dan ulkus duodenum', 'Untuk mengatasi gejala maag, Anda dapat mengonsumsi Almacon berdasarkan dengan dosis umum penggunaan berikut ini:', '["Almacon"]', '["amacon", "almason", "almacon", "almaco", "a1macon", "4lm4con", "aluminium hidroksida , magnesium hidroksida, dan dimethicone", "almac0n", "alrnacon", "aimacon"]', '["4lm4con", "a1macon", "aimacon", "almac0n", "almaco", "almason", "alrnacon", "amacon"]', 'DBL10000699A1', 'almacon', 'aluminiumhidroksidamagnesiumhidroksidadandimethicone');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('ace-inhibitor', 'ACE Inhibitor', 'ACE Inhibitor', 'Pengobatan Umum', 'Obat Keras (Lingkaran Merah K)', 'Sediaan oral/topikal sesuai instruksi kemasan.', 'Mengatasi gangguan kesehatan dan meredakan gejala sesuai petunjuk medis.', 'Jenis dan merek dagang ACE inhibitor berbeda-beda. Dosis ACE inhibitor akan ditentukan oleh dokter berdasarkan jenis dan bentuk obat, serta usia dan kondisi pasien. Berikut adalah rinciannya:', '["ACE Inhibitor", "penyakit asam urat", "mungkin hamil", "merencanakan kehamilan", "vitamin", "atau suplemen lain"]', '["4ce inhibitor", "ace inhibito", "merencanakan kehamilan", "ace inhibit0r", "ase inhibitor", "vitamin", "penyakit asam urat", "ac3 inhibitor", "ace inhibitor", "ae inhibitor", "ace 1nh1b1tor", "mungkin hamil", "ace lnhlbltor"]', '["4ce inhibitor", "ac3 inhibitor", "ace 1nh1b1tor", "ace inhibit0r", "ace inhibito", "ace lnhlbltor", "ae inhibitor", "ase inhibitor"]', 'DKL10001169A1', 'aceinhibitor', 'aceinhibitor');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('odanostin', 'Odanostin', 'Ondansetron', 'Antiemetik', 'Obat Keras (Lingkaran Merah K)', 'Kaplet salut selaput', 'Mencegah dan menghentikan mual serta muntah', 'Berdasarkan kandungannya, berikut adalah dosis Odanostin berdasarkan tujuan penggunaannya:', '["Odanostin"]', '["od4nostin", "odanostln", "0dan0stin", "oanostin", "odano5tin", "odanosti", "ondansetron", "odanost1n", "odanostin"]', '["0dan0stin", "oanostin", "od4nostin", "odano5tin", "odanost1n", "odanosti", "odanostln"]', 'DKL10000943A1', 'odanostin', 'ondansetron');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('maaggel', 'Maag Gel', 'Setiap 5 ml Maag Gel mengandung 500 mg calcium carbonate, 250 mg magnesium trisilicate, dan 40 mg simeticone', 'Antasida', 'Obat Bebas (Hijau)', 'Suspensi', 'Meredakan gejala asam lambung berlebih pada GERD , gastritis, atau tukak lambung', 'Dosis Maag Gel untuk meredakan asam lambung berlebih berdasarkan usia pasien adalah sebagai berikut:', '["Maag Gel"]', '["m44g gel", "setiap 5 ml maag gel mengandung 500 mg calcium carbonate, 250 mg magnesium trisilicate, dan 40 mg simeticone", "maag g3l", "maag ge1", "mag gel", "maag ge", "maag gel", "maag gei", "rnaag gel"]', '["m44g gel", "maag g3l", "maag ge", "maag ge1", "maag gei", "mag gel", "rnaag gel"]', 'DBL10000686A1', 'maaggel', 'setiap5mlmaaggelmengandung500mgcalciumcarbonate250mgmagnesiumtrisilicatedan40mgsimeticone');
