INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('decamox-forte', 'Decamox Forte', 'Amoxicillin', 'Antibiotik jenis penicillin', 'Obat Keras (Lingkaran Merah K)', 'Kaplet', 'Mengobati berbagai infeksi bakteri', 'Dosis Decamox Forte akan disesuaikan oleh dokter berdasarkan usia dan kondisi yang diderita pasien. Pada anak-anak, dosis Decamox Forte akan disesuaikan dengan berat badan (BB) pasien.', '["Decamox Forte"]', '["decamox fort", "decam0x f0rte", "decamox phorte", "d3camox fort3", "dec4mox forte", "decamoks forte", "amoxicillin", "decamox forte", "dcamox forte", "decarnox forte"]', '["d3camox fort3", "dcamox forte", "dec4mox forte", "decam0x f0rte", "decamoks forte", "decamox fort", "decamox phorte", "decarnox forte"]', 'DKL10001249A1', 'decamoxforte', 'amoxicillin');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('acarbose', 'Acarbose', 'Acarbose', 'Antidiabetes', 'Obat Keras (Lingkaran Merah K)', 'Tablet', 'Mengontrol kadar gula darah pada penderita diabetes tipe 2', 'Dosis minum acarbose akan disesuaikan dengan kondisi pasien dan respon tubuh terhadap pengobatan. Namun, dosis awal acarbose untuk orang dewasa umumnya adalah 25–50 m, 3 kali sehari. Jika diperlukan, dosis dapat ditingkatkan menjadi 100–200 mg, 3 kali sehari setelah 4–8 minggu.', '["Acarbose", "Acarbose Tablet Dexa Medica", "Acrios", "Capribose", "Diarvit", "Eclid"]', '["acarbose tablet dexa medica", "acarbos", "acrios", "diarvit", "acarbose", "asarbose", "acarb0se", "aarbose", "capribose", "acarbos3", "4c4rbose", "acarbo5e"]', '["4c4rbose", "aarbose", "acarb0se", "acarbo5e", "acarbos", "acarbos3", "asarbose"]', 'DKL10000800A1', 'acarbose', 'acarbose');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('telfast', 'Telfast', 'Fexofenadine hydrochloride', 'Antihistamin', 'Obat Keras (Lingkaran Merah K)', 'Tablet', 'Mengatasi gejala alergi', 'Dosis dan aturan pakai Telfast akan ditentukan oleh dokter. Secara umum, berikut ini adalah dosis Telfast:', '["Telfast"]', '["teifast", "telfa5t", "tlfast", "telphast", "te1fast", "t3lfast", "telfas", "fexofenadine hydrochloride", "telfast", "telf4st"]', '["t3lfast", "te1fast", "teifast", "telf4st", "telfa5t", "telfas", "telphast", "tlfast"]', 'DKL10000723A1', 'telfast', 'fexofenadinehydrochloride');
