INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('galepsi', 'Galepsi', 'Gabapentin 300 mg', 'Antikonvulsan atau antikejang', 'Obat Keras (Lingkaran Merah K)', 'Kapsul', 'Meredakan kejang epilepsi dan nyeri saraf (neuropati), termasuk yang dipicu oleh herpes zoster .', 'Dosis Galepsi akan mengikuti usia, kondisi, dan respons pasien terhadap pengobatan. Berikut adalah dosis umum untuk Galepsi berdasarkan kondisi dan usia pasien:', '["Galepsi"]', '["galeps", "ga1epsi", "galepsl", "gal3psi", "galeps1", "gaiepsi", "gabapentin 300 mg", "galepsi", "galep5i", "g4lepsi"]', '["g4lepsi", "ga1epsi", "gaiepsi", "gal3psi", "galep5i", "galeps", "galeps1", "galepsl"]', 'DKL10000709A1', 'galepsi', 'gabapentin300mg');
