INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('galflux', 'Galflux', 'Domperidone', 'Antiemetik dan prokinetik', 'Obat Keras (Lingkaran Merah K)', 'Tablet cepat larut, tablet salut selaput', 'Menghentikan mual dan muntah akibat gangguan pencernaan', 'Dosis domperidone pada Galflux yang disarankan untuk dewasa dan anak usia ≥12 tahun adalah 10–20 mg (1–2 tablet), 3 kali sehari. Lama pengobatan maksimal 1 minggu.', '["Galflux"]', '["galfluks", "g4lflux", "gaifiux", "galflux", "galflu", "ga1f1ux", "glflux", "domperidone", "galphlux"]', '["g4lflux", "ga1f1ux", "gaifiux", "galflu", "galfluks", "galphlux", "glflux"]', 'DKL10000723A1', 'galflux', 'domperidone');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('ranolazine', 'Ranolazine', 'Ranolazine', 'Obat antiangina', 'Obat Keras (Lingkaran Merah K)', 'Tablet pelepasan lambat', 'Mencegah atau mengurangi terjadinya angina pektoris', 'Dosis ranolazine untuk mengatasi angina pektoris adalah:', '["Ranolazine"]', '["ranolazine", "ranolaz1ne", "ran0lazine", "r4nol4zine", "ranolasine", "ranoiazine", "rano1azine", "ranolazin3", "ranolazin"]', '["r4nol4zine", "ran0lazine", "rano1azine", "ranoiazine", "ranolasine", "ranolaz1ne", "ranolazin", "ranolazin3"]', 'DKL10001043A1', 'ranolazine', 'ranolazine');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('xanax', 'Xanax', 'Alprazolam', 'Obat penenang golongan benzodiazepine', 'Obat Keras (Lingkaran Merah K)', 'Kaplet dan tablet sublingual', 'Mengobati gangguan kecemasan dan gangguan panik', 'Dosis Xanax akan disesuaikan dengan kondisi kesehatan, usia, dan respons pasien terhadap obat. Dokter akan memberikan dosis rendah terlebih dahulu, kemudian menaikkan dosisnya secara bertahap bila perlu, hingga sesuai dengan kebutuhan pasien.', '["Xanax"]', '["ksanaks", "x4n4x", "alprazolam", "xanax"]', '["ksanaks", "x4n4x"]', 'DKL10000512A1', 'xanax', 'alprazolam');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('decasurik', 'Decasurik', 'Allopurinol', 'Obat penghambat xanthine-oxidase', 'Obat Keras (Lingkaran Merah K)', 'Tablet', 'Menurunkan kadar asam urat dalam darah dan mencegah terbentuknya kristal asam urat.', 'Dokter akan menentukan dosis Decasurik berdasarkan kondisi dan usia pasien, serta respon tubuh terhadap pengobatan. Berikut ini adalah dosis umum pemberian Decasurk berdasarkan kondisi:', '["Decasurik"]', '["dcasurik", "deca5urik", "decasur1k", "dec4surik", "allopurinol", "decasurlk", "d3casurik", "decasurik", "desasurik", "decasuri"]', '["d3casurik", "dcasurik", "dec4surik", "deca5urik", "decasur1k", "decasuri", "decasurlk", "desasurik"]', 'DKL10000923A1', 'decasurik', 'allopurinol');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('imboost-kids', 'Imboost Kids', 'Echinacea purpurea dan zinc picolinate', 'Suplemen', 'Obat Bebas (Hijau)', 'Tablet isap dan sirop', 'Menjaga daya tahan tubuh anak', 'Untuk meningkatkan daya tahan tubuh anak, Anda dapat memberikan Imboost Kids sesuai dengan dosis umum penggunaan berikut ini:', '["Imboost Kids"]', '["imboost kids", "iboost kids", "echinacea purpurea dan zinc picolinate", "1mboost k1ds", "irnboost kids", "imboost kid", "lmboost klds", "imboo5t kid5", "imb00st kids"]', '["1mboost k1ds", "iboost kids", "imb00st kids", "imboo5t kid5", "imboost kid", "irnboost kids", "lmboost klds"]', 'DBL10001160A1', 'imboostkids', 'echinaceapurpureadanzincpicolinate');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('acebutolol', 'Acebutolol', 'Acebutolol', 'Penghambat beta ( beta blockers )', 'Obat Keras (Lingkaran Merah K)', 'Kapsul', 'Mengobati hipertensi, aritmia, atau angina pektoris', 'Dosis acebutolol ditentukan berdasarkan kondisi pasien dan respons tubuh terhadap obat. Berikut ini adalah dosis acebutolol untuk orang dewasa berdasarkan tujuan penggunaannya:', '["Acebutolol", "aritmia", "sindrom Raynaud", "asma", "penyakit paru obstruktif kronis PPOK", "sleep apnea"]', '["aritmia", "acebuto1o1", "acebutolol", "acebut0l0l", "sindrom raynaud", "asebutolol", "4cebutolol", "ac3butolol", "acebutoioi", "aebutolol", "asma", "acebutolo", "penyakit paru obstruktif kronis ppok"]', '["4cebutolol", "ac3butolol", "acebut0l0l", "acebuto1o1", "acebutoioi", "acebutolo", "aebutolol", "asebutolol"]', 'DKL10001034A1', 'acebutolol', 'acebutolol');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('xalkori', 'Xalkori', 'Crizotinib', 'Penghambat protein kinase', 'Obat Keras (Lingkaran Merah K)', 'Kapsul', 'Mengobati kanker paru jenis non-small cell yang sudah menyebar ke organ lain dan limfoma jenis anaplastic large cell lymphom a yang kambuh', 'Dosis Xalkori tergantung pada kondisi, respons pasien terhadap obat, serta obat lain yang diminum.', '["Xalkori"]', '["xalkor1", "xalkor", "ksalkori", "xalk0ri", "xaikori", "x4lkori", "xa1kori", "xalkori", "crizotinib", "xalkorl"]', '["ksalkori", "x4lkori", "xa1kori", "xaikori", "xalk0ri", "xalkor", "xalkor1", "xalkorl"]', 'DKL10000730A1', 'xalkori', 'crizotinib');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('maagmeta-plus', 'Maagmeta Plus', 'Aluminium hidroksida , magnesium hidroksida, dan simethicone', 'Antasida dan antiflatulensi (antikembung)', 'Obat Bebas (Hijau)', 'Tablet kunyah', 'Meredakan gejala sakit maag akibat kelebihan asam lambung, termasuk pada gastritis, tukak lambung, dan ulkus duodenum', 'Secara umum, dosis penggunaan Maagmeta Plus untuk mengatasi gejala maag adalah:', '["Maagmeta Plus"]', '["maagm3ta plus", "maagmeta p1us", "maagmeta plus", "maagmeta plu5", "magmeta plus", "rnaagrneta plus", "aluminium hidroksida , magnesium hidroksida, dan simethicone", "maagmeta pius", "maagmeta plu", "m44gmet4 plus"]', '["m44gmet4 plus", "maagm3ta plus", "maagmeta p1us", "maagmeta pius", "maagmeta plu", "maagmeta plu5", "magmeta plus", "rnaagrneta plus"]', 'DBL10001249A1', 'maagmetaplus', 'aluminiumhidroksidamagnesiumhidroksidadansimethicone');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('ranivel', 'Ranivel', 'Ranitidin', 'Antagonis H2', 'Obat Keras (Lingkaran Merah K)', 'Tablet, sirop, dan suntik', 'Menurunkan produksi asam lambung', 'Dosis Ranivel ditentukan berdasarkan sediaan obat, kondisi yang diatasi, tingkat keparahan penyakit, serta usia pasien. Secara umum dosis Ranivel yang diberikan kepada pasien adalah:', '["Ranivel"]', '["ranivei", "r4nivel", "raniv3l", "rnivel", "ran1vel", "ranitidin", "ranivel", "ranive", "ranive1", "ranlvel"]', '["r4nivel", "ran1vel", "raniv3l", "ranive", "ranive1", "ranivei", "ranlvel", "rnivel"]', 'DKL10000721A1', 'ranivel', 'ranitidin');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('gallium-nitrate', 'Gallium Nitrate', 'Gallium Nitrate', 'Penurun kalsium dalam darah', 'Obat Keras (Lingkaran Merah K)', 'Suntik', 'Menurunkan kadar kalsium dalam darah pada pasien kanker', 'Dokter akan memberikan gallium nitrate sesuai kondisi dan respons tubuh pasien. Secara umum, dosis gallium nitrate untuk mengobati hiperkalsemia pada pasien kanker yang berusia dewasa adalah 100–200 mg/m² luas permukaan tubuh per hari.', '["Gallium Nitrate"]', '["g4llium nitr4te", "ga11ium nitrate", "gallium nitrat", "galllum nltrate", "gallium nitrate", "galliurn nitrate", "gallium nitrat3", "gaiiium nitrate", "gall1um n1trate"]', '["g4llium nitr4te", "ga11ium nitrate", "gaiiium nitrate", "gall1um n1trate", "gallium nitrat", "gallium nitrat3", "galliurn nitrate", "galllum nltrate"]', 'DKL10001474A1', 'galliumnitrate', 'galliumnitrate');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('ofloxacin', 'Ofloxacin', 'Ofloxacin', 'Obat resep', 'Obat Keras (Lingkaran Merah K)', 'Tablet', 'Mengobati infeksi bakteri', 'Dosis dan durasi penggunaan ofloxacin akan ditentukan oleh dokter sesuai dengan jenis penyakit infeksi, tingkat keparahan infeksi, serta usia dan kondisi kesehatan pasien. Berikut adalah rincian dosis ofloxacin tablet atau kaplet:', '["Ofloxacin"]', '["ofloxacin", "ofioxacin", "ofloxac1n", "0fl0xacin", "oflox4cin", "ofloxaci", "of1oxacin", "ofloxacln", "ofloksacin"]', '["0fl0xacin", "of1oxacin", "ofioxacin", "ofloksacin", "oflox4cin", "ofloxac1n", "ofloxaci", "ofloxacln"]', 'DKL10000931A1', 'ofloxacin', 'ofloxacin');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('rantin', 'Rantin', 'Ranitidin', 'Antagonis reseptor H2', 'Obat Keras (Lingkaran Merah K)', 'Tablet salut selaput dan suntik', 'Mengatasi sakit maag, tukak lambung,GERD, dan kondisi akibat kelebihan asam lambung', 'Dosis Rantin dapat berbeda-beda pada setiap orang, tergantung pada jenis gangguan yang diobati, tingkat keparahan kondisi, serta usia pasien.', '["Rantin"]', '["rantln", "ranitidin", "ranti", "r4ntin", "rntin", "rantin", "rant1n"]', '["r4ntin", "rant1n", "ranti", "rantln", "rntin"]', 'DKL10000620A1', 'rantin', 'ranitidin');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('ubitine', 'Ubitine', 'Ubiquinol 100 mg, L-carnitine fumarate 400 mg, vitamin E 100 IU, asam folat 800 mcg', 'Suplemen', 'Obat Bebas (Hijau)', 'Kapsul lunak', 'Membantu memelihara kesehatan tubuh', 'Ubitine bisa dikonsumsi sebanyak 1 kapsul lunak, 1 kali sehari.', '["Ubitine"]', '["ubiquinol 100 mg, l-carnitine fumarate 400 mg, vitamin e 100 iu, asam folat 800 mcg", "ubitine", "uitine", "ubitin3", "ubltlne", "ub1t1ne", "ubitin"]', '["ub1t1ne", "ubitin", "ubitin3", "ubltlne", "uitine"]', 'DBL10000720A1', 'ubitine', 'ubiquinol100mglcarnitinefumarate400mgvitamine100iuasamfolat800mcg');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('acepress', 'Acepress', 'Captopril', 'ACE inhibitor', 'Obat Keras (Lingkaran Merah K)', 'Tablet', 'Mengatasi tekanan darah tinggi', 'Dosis Acepress akan ditentukan oleh dokter berdasarkan kondisi dan usia pasien. Secara umum, berikut ini dosis Acepress sesuai kondisi yang ditangani:', '["Acepress"]', '["ac3pr3ss", "aepress", "acepre55", "captopril", "asepress", "acepress", "acepres", "4cepress"]', '["4cepress", "ac3pr3ss", "acepre55", "acepres", "aepress", "asepress"]', 'DKL10000822A1', 'acepress', 'captopril');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('xantia', 'Xantia', 'Astaxanthin', 'Suplemen', 'Obat Bebas (Hijau)', 'Kapsul', 'Membantu mengurangi peradangan serta menunjang daya tahan tubuh dan kesehatan mata, jantung, serta kulit.', 'Hingga saat ini, dosis pasti astaxanthin dalam Xantia untuk mengatasi kondisi medis tertentu belum ditetapkan secara resmi. Namun, secara umum, suplemen ini biasanya dikonsumsi dalam dosis 4–18 mg per hari, dengan penggunaan maksimal hingga 12 minggu.', '["Xantia"]', '["xantla", "astaxanthin", "xant1a", "xanti", "x4nti4", "ksantia", "xntia", "xantia"]', '["ksantia", "x4nti4", "xant1a", "xanti", "xantla", "xntia"]', 'DBL10000613A1', 'xantia', 'astaxanthin');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('alloris', 'Alloris', 'Loratadine', 'Antihistamin', 'Obat Keras (Lingkaran Merah K)', 'Tablet dan sirop', 'Meredakan gejala alergi , termasuk biduran , rhinitis alergi, atau konjungtivitis alergi', 'Berikut ini adalah dosis umum penggunaan Alloris berdasarkan bentuk sediaannya:', '["Alloris"]', '["allorls", "4lloris", "all0ris", "allori5", "allor1s", "a11oris", "aiioris", "allori", "loratadine", "alloris"]', '["4lloris", "a11oris", "aiioris", "all0ris", "allor1s", "allori", "allori5", "allorls"]', 'DKL10000726A1', 'alloris', 'loratadine');
