INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('decitabine', 'Decitabine', 'Decitabine', 'Obat kemoterapi', 'Obat Keras (Lingkaran Merah K)', 'Serbuk injeksi', 'Mengobati sindrom mielodisplasia atau leukemia mieloblastik akut', 'Dosis decitabine akan disesuaikan dengan kondisi yang ditangani, luas permukaan tubuh (LPT), dan respons pasien terhadap obat. Berikut adalah rincian dosis decitabine untuk pasien dewasa:', '["Decitabine", "penyakit liver", "diabetes", "penyakit jantung", "mungkin hamil", "menyusui"]', '["penyakit jantung", "penyakit liver", "decitabine", "decitabin", "decit4bine", "dcitabine", "dec1tab1ne", "decltablne", "diabetes", "d3citabin3", "desitabine", "mungkin hamil"]', '["d3citabin3", "dcitabine", "dec1tab1ne", "decit4bine", "decitabin", "decltablne", "desitabine"]', 'DKL10001000A1', 'decitabine', 'decitabine');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('macrogol', 'Macrogol', 'Macrogol', 'Obat pencahar', 'Obat Keras (Lingkaran Merah K)', 'Serbuk dan cairan enema', 'Mengatasi sembelit atau konstipasi, dan untuk mengosongkan usus sebelum prosedur operasi usus dan pemeriksaan kolonoskopi.', 'Macrogol atau polyethylene glycol terdiri dari macrogol 4000 dan polyethylene glycol 3350. Macrogol 4000 tidak diperuntukan bagi anak-anak usia kurang dari 8 tahun.', '["Macrogol", "Daylax", "Laxon", "Microlax", "Niflec", "radang usus"]', '["daylax", "macrogo1", "masrogol", "macrogol", "microlax", "niflec", "macrogoi", "macr0g0l", "m4crogol", "laxon", "macrogo", "mcrogol", "rnacrogol"]', '["m4crogol", "macr0g0l", "macrogo", "macrogo1", "macrogoi", "masrogol", "mcrogol", "rnacrogol"]', 'DKL10000820A1', 'macrogol', 'macrogol');
