INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('madopar', 'Madopar', 'Levodopa 100 mg dan benserazide 25 mg', 'Antiparkinson', 'Obat Keras (Lingkaran Merah K)', 'Tablet dispersible', 'Meringankan gejala penyakit parkinson', 'Madopar merupakan obat yang hanya bisa digunakan dengan resep dokter. Secara umum, berikut adalah rincian dosis Madopar untuk mengobati penyakit Parkinson berdasarkan obat tambahan yang digunakan:', '["Madopar"]', '["madopa", "madopar", "rnadopar", "mad0par", "mdopar", "m4dop4r", "levodopa 100 mg dan benserazide 25 mg"]', '["m4dop4r", "mad0par", "madopa", "mdopar", "rnadopar"]', 'DKL10000708A1', 'madopar', 'levodopa100mgdanbenserazide25mg');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('xanturic', 'Xanturic', 'Allopurinol', 'Obat penghambat xanthine-oxidase', 'Obat Keras (Lingkaran Merah K)', 'Tablet', 'Menurunkan kadar asam urat dalam darah', 'Dokter akan menentukan dosis Xanturic sesuai dengan kondisi dan usia pasien. Berikut adalah dosis umumnya:', '["Xanturic"]', '["xanturlc", "xantur1c", "xanturic", "xanturi", "xanturis", "ksanturic", "xnturic", "x4nturic", "allopurinol"]', '["ksanturic", "x4nturic", "xantur1c", "xanturi", "xanturis", "xanturlc", "xnturic"]', 'DKL10000846A1', 'xanturic', 'allopurinol');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('galpect', 'Galpect', 'Ambroxol', 'Obat pengencer dahak jenis mukolitik', 'Obat Keras (Lingkaran Merah K)', 'Tablet dan sirop', 'Mengencerkan dahak', 'Galpect dapat digunakan dalam pengobatan bronkitis kronis maupun bronkitis akut. Selain itu, Galpect bisa dimanfaatkan sebagai obat batuk berdahak pada sejumlah kondisi, seperti:', '["Galpect"]', '["galpect", "galp3ct", "galpec", "glpect", "ga1pect", "gaipect", "galpest", "ambroxol", "g4lpect"]', '["g4lpect", "ga1pect", "gaipect", "galp3ct", "galpec", "galpest", "glpect"]', 'DKL10000704A1', 'galpect', 'ambroxol');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('ufiquin', 'Ufiquin', 'Hidroquinone', 'Obat pencerah kulit', 'Obat Keras (Lingkaran Merah K)', 'Krim', 'Mencerahkan kulit yang menggelap atau mengalami hiperpigmentasi karena paparan sinar matahari, penuaan atau peradangan pada kulit', 'Ufiquin merupakan obat resep yang harus digunakan sesuai anjuran dokter. Dosis penggunaan Ufiquin umumnya adalah 1–2 kali sehari, yang dapat dioleskan secara tipis ke kulit yang ingin diobati. Penggunaannya secara rutin sesuai arahan dokter bisa membuat kulit menjadi lebih cerah.', '["Ufiquin"]', '["ufiquin", "uflquln", "hidroquinone", "uf1qu1n", "ufiqui", "uiquin", "uphiquin"]', '["uf1qu1n", "ufiqui", "uflquln", "uiquin", "uphiquin"]', 'DKL10000737A1', 'ufiquin', 'hidroquinone');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('ratanshaqin', 'Ratanshaqin', 'Hidroquinone', 'Obat pencerah kulit', 'Obat Keras (Lingkaran Merah K)', 'Krim', 'Mencerahkan kulit yang menggelap atau mengalami hiperpigmentasi karena paparan sinar matahari, penuaan atau peradangan pada kulit', 'Dosis penggunaan Ratanshaqin akan ditentukan dokter berdasarkan kondisi kulit pasien. Namun, dosis penggunaan obat ini umumnya adalah 1–2 kali sehari. Oleskan obat ini secara tipis ke kulit yang bermasalah dan gunakan tabir surya setiap harinya agar kulit tidak terbakar atau mengalami sunburn.', '["Ratanshaqin"]', '["ratanshaqin", "ratanshaq1n", "hidroquinone", "ratanshaqi", "rtanshaqin", "ratan5haqin", "r4t4nsh4qin", "ratanshaqln"]', '["r4t4nsh4qin", "ratan5haqin", "ratanshaq1n", "ratanshaqi", "ratanshaqln", "rtanshaqin"]', 'DKL10001146A1', 'ratanshaqin', 'hidroquinone');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('imdros', 'Imdros', 'Imatinib', 'Obat antikanker golongan penghambat protein kinase', 'Obat Keras (Lingkaran Merah K)', 'Tablet salut selaput', 'Mengobati leukemia, tumor pada saluran cerna (GIST), sindrom mielodisplasia , kelebihan sel eosinofil, mastocytosis sistemik agresif, serta kanker kulit langka yang sulit diangkat dengan operasi', 'Dosis dan lama pengobatan dengan Imdros akan ditentukan dokter berdasarkan usia, kondisi kesehatan, dan respons tubuh pasien terhadap obat. Berikut panduan umum dosis imatinib dalam Imdros untuk berbagai kondisi:', '["Imdros"]', '["imdr0s", "irndros", "1mdros", "lmdros", "imdro", "imdros", "idros", "imdro5", "imatinib"]', '["1mdros", "idros", "imdr0s", "imdro", "imdro5", "irndros", "lmdros"]', 'DKL10000622A1', 'imdros', 'imatinib');
