INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('xarelto', 'Xarelto', 'Rivaroxaban', 'Antikoagulan jenis penghambat faktor Xa', 'Obat Keras (Lingkaran Merah K)', 'Tablet', 'Mencegah dan mengobati deep vein thrombosis ( DVT ) atau emboli paru', 'Berikut adalah dosis Xarelto berdasarkan tujuan penggunaannya:', '["Xarelto"]', '["rivaroxaban", "x4relto", "xarelt", "xrelto", "ksarelto", "xarelt0", "xar3lto", "xareito", "xarelto", "xare1to"]', '["ksarelto", "x4relto", "xar3lto", "xare1to", "xareito", "xarelt", "xarelt0", "xrelto"]', 'DKL10000735A1', 'xarelto', 'rivaroxaban');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('aflucaps-pe', 'Aflucaps PE', 'Paracetamol 500 mg, phenylephrine 10 mg, chlorpheniramine maleate 2 mg', 'Kombinasi analgetik-antipiretik , dekongestan , dan antihistamin', 'Obat Bebas Terbatas (Lingkaran Biru)', 'Kaplet', 'Meredakan gejala flu, seperti demam , sakit kepala , dan bersin-bersin', 'Untuk meredakan gejala flu, seperti demam, hidung tersumbat, dan bersin-bersin, inilah dosis umum penggunaan Aflucaps PE:', '["Aflucaps PE"]', '["aflucaps p", "aflusaps pe", "afiucaps pe", "4fluc4ps pe", "aflucaps pe", "aflucaps p3", "paracetamol 500 mg, phenylephrine 10 mg, chlorpheniramine maleate 2 mg", "aflucap5 pe", "af1ucaps pe", "alucaps pe"]', '["4fluc4ps pe", "af1ucaps pe", "afiucaps pe", "aflucap5 pe", "aflucaps p", "aflucaps p3", "aflusaps pe", "alucaps pe"]', 'DTL10000996A1', 'aflucapspe', 'paracetamol500mgphenylephrine10mgchlorpheniraminemaleate2mg');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('acethion', 'Acethion', 'Glutathione', 'Suplemen dan terapi pendukung', 'Obat Bebas (Hijau)', 'Kapsul', 'Membantu menunjang kesehatan kulit dan sebagai antioksidan', 'Dosis umum glutathione dalam Acethion biasanya berkisar antara 50–600 mg per hari, dengan dosis yang paling sering digunakan pada suplemen sekitar 250 mg per hari.', '["Acethion"]', '["aceth1on", "aethion", "acetion", "ac3thion", "4cethion", "acethio", "acethi0n", "acethlon", "glutathione", "acethion"]', '["4cethion", "ac3thion", "aceth1on", "acethi0n", "acethio", "acethlon", "acetion", "aethion"]', 'DBL10000811A1', 'acethion', 'glutathione');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('decolgen-fx', 'Decolgen FX', 'Paracetamol 650 mg, chlorphenamine maleate 30 mg, dan pseudoephedrine HCl 30 mg', 'Obat flu kombinasi dekongestan (pseudoephedrine), antihistamin (chlorphenamine), dan analgetik-antipiretik (paracetamol)', 'Obat Bebas Terbatas (Lingkaran Biru)', 'Kaplet', 'Mengatasi gejala flu , seperti demam, sakit kepala, hidung tersumbat, bersin, dan batuk.', 'Untuk mengatasi berbagai gejala flu, Anda dapat menggunakan Decolgen FX dengan dosis umum penggunaannya berikut ini:', '["Decolgen FX"]', '["dec0lgen fx", "decolgen phx", "deco1gen fx", "decolgen fks", "decoigen fx", "decolgen fx", "paracetamol 650 mg, chlorphenamine maleate 30 mg, dan pseudoephedrine hcl 30 mg", "dcolgen fx", "decolgen f", "d3colg3n fx"]', '["d3colg3n fx", "dcolgen fx", "dec0lgen fx", "deco1gen fx", "decoigen fx", "decolgen f", "decolgen fks", "decolgen phx"]', 'DTL10000991A1', 'decolgenfx', 'paracetamol650mgchlorphenaminemaleate30mgdanpseudoephedrinehcl30mg');
