INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('xelica', 'Xelica', 'Celecoxib', 'OAINS jenis COX-2 inhibitor', 'Obat Keras (Lingkaran Merah K)', 'Kapsul', 'Meredakan nyeri akibat osteoarthritis, rheumatoid arthritis, ankylosing spondylitis , juvenile idiopathic arthritis, migrain akut , atau dismenore', 'Dosis dan jangka waktu penggunaan Xelica akan ditentukan oleh dokter sesuai dengan kondisi dan usia pasien. Berikut ini adalah dosis umum penggunaan Xelica:', '["Xelica"]', '["celecoxib", "xelica", "kselica", "xe1ica", "xelic", "xel1ca", "xelic4", "xeiica", "xelisa", "x3lica"]', '["kselica", "x3lica", "xe1ica", "xeiica", "xel1ca", "xelic", "xelic4", "xelisa"]', 'DKL10000598A1', 'xelica', 'celecoxib');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('oksitosin', 'Oksitosin', 'Oksitosin', 'Hormon sintetis', 'Obat Keras (Lingkaran Merah K)', 'Suntik', 'Memicu kontraksi rahim , mengontrol perdarahan setelah melahirkan , dan membantu keluarnya ASI', 'Dosis oksitosin yang diberikan berbeda-beda tergantung pada tujuan pemberiannya. Berikut ini adalah dosis umum penggunaan oksitosin pada orang dewasa berdasarkan tujuan pemakaian:', '["Oksitosin", "Decatosin", "Induxin", "Oxyla", "Oxytocin", "Protocin"]', '["ok5ito5in", "oksltosln", "ositosin", "oxyla", "oksitosi", "oks1tos1n", "oxytocin", "0ksit0sin", "oksitosin", "induxin", "decatosin"]', '["0ksit0sin", "ok5ito5in", "oks1tos1n", "oksitosi", "oksltosln", "ositosin"]', 'DKL10000963A1', 'oksitosin', 'oksitosin');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('magaldrate', 'Magaldrate', 'Magaldrate', 'Antasida', 'Obat Bebas (Hijau)', 'Suspensi dan tablet kunyah', 'Mengatasi penyakit asam lambung , gastritis, tukak lambung, atau tukak duodenum', 'Dosis umum penggunaan magaldrate adalah 480–1080 mg, 3–4 kali sehari. Dosis maksimal adalah 8.640 mg per hari.', '["Magaldrate", "gastritis", "tukak lambung", "penyakit hati", "tekanan darah tinggi", "gagal jantung"]', '["m4g4ldr4te", "gastritis", "tukak lambung", "magaldrat3", "maga1drate", "tekanan darah tinggi", "magaidrate", "mgaldrate", "penyakit hati", "magaldrat", "magaldrate", "rnagaldrate"]', '["m4g4ldr4te", "maga1drate", "magaidrate", "magaldrat", "magaldrat3", "mgaldrate", "rnagaldrate"]', 'DBL10001010A1', 'magaldrate', 'magaldrate');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('afucid', 'Afucid', 'Asam fusidat 2%', 'Antibiotik', 'Obat Keras (Lingkaran Merah K)', 'Krim dan salep', 'Mengobati infeksi kulit akibat bakteri', 'Beberapa penyakit kulit yang bisa diobati dengan Afucid antara lain:', '["Afucid"]', '["afusid", "asam fusidat 2%", "afucid", "afuci", "afucld", "afuc1d", "4fucid", "aphucid", "aucid"]', '["4fucid", "afuc1d", "afuci", "afucld", "afusid", "aphucid", "aucid"]', 'DKL10000588A1', 'afucid', 'asamfusidat2');
