INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('almen', 'Almen', 'Donepezil', 'Obat penyakit degenerasi saraf golongan penghambat enzim asetilkolinesterase ( acetylcholinesterase inhibitor )', 'Obat Keras (Lingkaran Merah K)', 'Tablet salut selaput', 'Menangani demensia pada penyakit Alzheimer', 'Dosis Almen akan disesuaikan dengan kondisi dan respons pasien terhadap pengobatan. Berikut rekomendasi umum dosis donepezil dalam Almen:', '["Almen"]', '["aimen", "donepezil", "alrnen", "a1men", "alm3n", "almen", "4lmen"]', '["4lmen", "a1men", "aimen", "alm3n", "alrnen"]', 'DKL10000493A1', 'almen', 'donepezil');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('decolsin', 'Decolsin', 'Paracetamol, pseudoephedrine, chlorpheniramine, dextromethorphan, dan guaifenesin', 'Analgesik dan antipiretik, dekongestan, antihistamin, antitusif, serta ekspektoran', 'Obat Bebas Terbatas (Lingkaran Biru)', 'Kapsul dan sirop', 'Meredakan gejala flu dan batuk, baik batuk berdahak, maupun batuk tidak berdahak', 'Dosis penggunaan Decolsin dapat berbeda-beda, tergantung pada usia dan varian yang digunakan. Berikut adalah dosis Decolsin untuk meredakan gejala flu dan batuk berdasarkan jenis produknya:', '["Decolsin"]', '["decols1n", "decolsin", "dcolsin", "deco1sin", "d3colsin", "decoisin", "paracetamol, pseudoephedrine, chlorpheniramine, dextromethorphan, dan guaifenesin", "dec0lsin", "decol5in", "decolsi"]', '["d3colsin", "dcolsin", "dec0lsin", "deco1sin", "decoisin", "decol5in", "decols1n", "decolsi"]', 'DTL10000817A1', 'decolsin', 'paracetamolpseudoephedrinechlorpheniraminedextromethorphandanguaifenesin');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('rathinoin', 'Rathinoin', 'Tretinoin', 'Retinoid topikal', 'Obat Keras (Lingkaran Merah K)', 'Lotion', 'Mengobati jerawat, meratakan warna kulit, mengurangi garis halus atau kerutan, mengatasi kulit kasar, dan kerusakan kulit lain yang disebabkan paparan sinar matahari', 'Dokter akan menyesuaikan dosis penggunaan obat ini sesuai dengan kondisi kulit pasien dan respon terhadap pengobatan. Namun, ada dosis umum penggunaan Rathinoin berdasarkan tujuan pengobatan.', '["Rathinoin"]', '["rathinoi", "rath1no1n", "r4thinoin", "rthinoin", "tretinoin", "rathin0in", "rathinoin", "ratinoin", "rathlnoln"]', '["r4thinoin", "rath1no1n", "rathin0in", "rathinoi", "rathlnoln", "ratinoin", "rthinoin"]', 'DKL10000940A1', 'rathinoin', 'tretinoin');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('acetin', 'Acetin', 'Acetylcysteine', 'Obat pengencer dahak jenis mukolitik', 'Obat Keras (Lingkaran Merah K)', 'Kapsul dan tablet effervescent', 'Mengencerkan dahak yang kental akibat penyakit saluran pernapasan, seperti bronkiektasis , bronkitis, kistik fibrosis , atau emfisema', 'Berikut adalah dosis Acetin berdasarkan kondisi yang diobati dan sediaan obatnya:', '["Acetin"]', '["acet1n", "acetin", "4cetin", "asetin", "acetylcysteine", "aetin", "aceti", "ac3tin", "acetln"]', '["4cetin", "ac3tin", "acet1n", "aceti", "acetln", "aetin", "asetin"]', 'DKL10000596A1', 'acetin', 'acetylcysteine');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('ufiscab-krim', 'Ufiscab Krim', 'Permethrin 5%', 'Obat antiparasit', 'Obat Keras (Lingkaran Merah K)', 'Krim', 'Mengobati kudis, kutu di kulit kepala, dan kutu kemaluan', 'Berikut ini adalah dosis penggunaan Ufiscab krim berdasarkan kondisi yang ditangani:', '["Ufiscab Krim"]', '["uflscab krlm", "ufissab krim", "ufiscab krim", "permethrin 5%", "ufi5cab krim", "uf1scab kr1m", "ufiscab kri", "ufiscab krirn", "ufisc4b krim", "uiscab krim"]', '["uf1scab kr1m", "ufi5cab krim", "ufisc4b krim", "ufiscab kri", "ufiscab krirn", "ufissab krim", "uflscab krlm", "uiscab krim"]', 'DKL10001136A1', 'ufiscabkrim', 'permethrin5');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('imetasone', 'Imetasone', 'Desoximetasone 0,25%', 'Kortikosteroid topikal', 'Obat Keras (Lingkaran Merah K)', 'Krim', 'Mengatasi keluhan akibat kondisi radang kulit, seperti pada eksim, reaksi alergi, dermatitis, atau psoriasis', 'Untuk mengatasi gejala radang kulit pada eksim, dermatitis atopik, reaksi alergi, atau psoriasis, oleskan krim Imetasone secara merata pada area kulit yang perlu diobati, 2 kali sehari atau sesuai petunjuk dokter. Lama penggunaan tidak boleh lebih dari 2 minggu tanpa evaluasi oleh dokter.', '["Imetasone"]', '["ietasone", "imetason", "desoximetasone 0,25%", "1metasone", "imetasone", "imet4sone", "imetas0ne", "imeta5one", "irnetasone", "im3tason3"]', '["1metasone", "ietasone", "im3tason3", "imet4sone", "imeta5one", "imetas0ne", "imetason", "irnetasone"]', 'DKL10000933A1', 'imetasone', 'desoximetasone025');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('maganol', 'Maganol', 'Paracetamol', 'Analgetik-antipiretik', 'Obat Bebas (Hijau)', 'Kaplet dan infus', 'Meredakan nyeri', 'Berikut adalah dosis umum penggunaan Maganol untuk meredakan demam dan nyeri berdasarkan varian produk dan usia pasien:', '["Maganol"]', '["magano", "magan0l", "rnaganol", "magano1", "maganoi", "m4g4nol", "maganol", "mganol", "paracetamol"]', '["m4g4nol", "magan0l", "magano", "magano1", "maganoi", "mganol", "rnaganol"]', 'DBL10000703A1', 'maganol', 'paracetamol');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('imfuro-krim', 'Imfuro Krim', 'Mometasone furoate', 'Kortikosteroid topikal', 'Obat Keras (Lingkaran Merah K)', 'Krim', 'Meredakan gatal-gatal dan peradangan pada kulit.', 'Beberapa penyakit kulit yang bisa diobati dengan Imfuro krim meliputi alergi kulit, psoriasis, atau dermatitis, termasuk eksim, yang tergolong berat atau tidak membaik dengan krim kortikosteroid ringan, seperti hydrocortisone.', '["Imfuro Krim"]', '["imfuro kri", "imphuro krim", "lmfuro krlm", "1mfuro kr1m", "imfuro krim", "imfur0 krim", "mometasone furoate", "irnfuro krirn", "ifuro krim"]', '["1mfuro kr1m", "ifuro krim", "imfur0 krim", "imfuro kri", "imphuro krim", "irnfuro krirn", "lmfuro krlm"]', 'DKL10001061A1', 'imfurokrim', 'mometasonefuroate');
