INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('xepamol', 'Xepamol', 'Paracetamol', 'Analgetik-antipiretik', 'Obat Bebas (Hijau)', 'Tablet, sirop, dan drops', 'Meredakan nyeri', 'Berikut adalah dosis umum penggunaan Xepamol untuk meredakan demam dan nyeri berdasarkan bentuk obat dan usia pasien:', '["Xepamol"]', '["xepamoi", "xeparnol", "ksepamol", "xepamo1", "xep4mol", "xepamol", "x3pamol", "xepam0l", "xepamo", "paracetamol"]', '["ksepamol", "x3pamol", "xep4mol", "xepam0l", "xepamo", "xepamo1", "xepamoi", "xeparnol"]', 'DBL10000726A1', 'xepamol', 'paracetamol');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('gamalix', 'Gamalix', 'Pregabalin', 'Obat antikonvulsan', 'Obat Keras (Lingkaran Merah K)', 'Kapsul', 'Mengendalikan kejang pada penderita epilepsi', 'Dalam pengobatan nyeri neuropati, fibromyalgia, epilepsi, atau gangguan kecemasan, rekomendasi dosis Gamalix untuk orang dewasa adalah 150–600 mg per hari, dibagi dalam 2–3 kali jadwal konsumsi, tergantung pada kondisi yang ditangani.', '["Gamalix"]', '["g4m4lix", "gamalix", "gamal1x", "gamaliks", "gama1ix", "pregabalin", "garnalix", "gamali", "gamallx", "gamaiix"]', '["g4m4lix", "gama1ix", "gamaiix", "gamal1x", "gamali", "gamaliks", "gamallx", "garnalix"]', 'DKL10000707A1', 'gamalix', 'pregabalin');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('magnesium-sitrat', 'Magnesium Sitrat', 'Magnesium Sitrat', 'Suplemen dan obat pencahar', 'Obat Bebas (Hijau)', 'Tablet, kapsul, sirop', 'Sebagai suplemen mineral dan untuk mengatasi sembelit', 'Berikut ini adalah dosis umum magnesium sitrat berdasarkan tujuan penggunaan, jenis kelamin, dan usia pasien:', '["Magnesium Sitrat", "kapsul", "sumbatan usus", "kolitis ulseratif", "penyakit jantung", "menyusui"]', '["penyakit jantung", "magneslum sltrat", "mgnesium sitrat", "magnes1um s1trat", "magne5ium 5itrat", "magnesium sitrat", "sumbatan usus", "rnagnesiurn sitrat", "kolitis ulseratif", "m4gnesium sitr4t", "magnesium sitra", "magn3sium sitrat", "kapsul"]', '["m4gnesium sitr4t", "magn3sium sitrat", "magne5ium 5itrat", "magnes1um s1trat", "magnesium sitra", "magneslum sltrat", "mgnesium sitrat", "rnagnesiurn sitrat"]', 'DBL10001597A1', 'magnesiumsitrat', 'magnesiumsitrat');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('olaz', 'Olaz', 'Olanzapine', 'Antipsikotik', 'Obat Keras (Lingkaran Merah K)', 'Tablet salut selaput', 'Meringankan gejala skizofrenia dan gangguan bipolar', 'Dosis dan aturan pakai Olaz ditentukan dokter berdasarkan kondisi, usia, dan respons pasien terhadap pengobatan. Secara umum, berikut adalah umum penggunaan Olaz:', '["Olaz"]', '["olas", "ol4z", "olanzapine", "o1az", "olaz", "0laz", "oiaz"]', '["0laz", "o1az", "oiaz", "ol4z", "olas"]', 'DKL10000406A1', 'olaz', 'olanzapine');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('ailin-cool', 'Ailin Cool', 'Ailin Cool', 'Obat tetes mata', 'Obat Keras (Lingkaran Merah K)', 'Tetes mata', 'Meredakan gejala iritasi mata ringan, termasuk mata merah , kering, dan gatal', 'Untuk mengatasi mata merah akibat iritasi ringan, teteskan 1–2 tetes Ailin Cool pada mata yang merah, 3–4 kali sehari.', '["Ailin Cool"]', '["aiiin cooi", "ailin coo", "4ilin cool", "ailin cool", "ai1in coo1", "a1l1n cool", "alin cool", "ailin c00l", "ailin sool"]', '["4ilin cool", "a1l1n cool", "ai1in coo1", "aiiin cooi", "ailin c00l", "ailin coo", "ailin sool", "alin cool"]', 'DKL10000922A1', 'ailincool', 'ailincool');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('econazine-krim', 'Econazine Krim', 'Econazole nitrate dan triamcinolone acetonide', 'Antijamur azole dan kortikosteroid topikal', 'Obat Keras (Lingkaran Merah K)', 'Krim', 'Mengobati infeksi jamur di kulit yang disertai gejala peradangan berat, seperti kutu air , tinea cruris, kurap , atau candidiasis .', 'Dosis umum penggunaan Econazine krim untuk mengatasi infeksi jamur di kulit berdasarkan usia pasien adalah:', '["Econazine Krim"]', '["econazlne krlm", "econaz1ne kr1m", "ec0nazine krim", "3conazin3 krim", "econ4zine krim", "econazole nitrate dan triamcinolone acetonide", "econazine krim", "econasine krim", "econazine krirn", "econazine kri"]', '["3conazin3 krim", "ec0nazine krim", "econ4zine krim", "econasine krim", "econaz1ne kr1m", "econazine kri", "econazine krirn", "econazlne krlm"]', 'DKL10001359A1', 'econazinekrim', 'econazolenitratedantriamcinoloneacetonide');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('ulmo', 'Ulmo', 'Famotidine', 'Antagonis H2', 'Obat Keras (Lingkaran Merah K)', 'Kaplet', 'Mengatasi gejala pada tukak lambung, ulkus duodenum, penyakit asam lambung, atau sindrom Zollinger–Ellison', 'Ulmo digunakan untuk mengatasi penyakit yang disebabkan oleh naiknya produksi asam lambung berlebih. Berikut adalah dosis umum Ulmo berdasarkan kondisi yang diobati dan usia pasien:', '["Ulmo"]', '["uimo", "ulmo", "famotidine", "ulrno", "ulm0", "u1mo"]', '["u1mo", "uimo", "ulm0", "ulrno"]', 'DKL10000413A1', 'ulmo', 'famotidine');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('imipenem-cilastatin', 'Imipenem-Cilastatin', 'Imipenem-Cilastatin', 'Antibiotik carbapenem', 'Obat Keras (Lingkaran Merah K)', 'Suntik', 'Mengatasi infeksi bakteri yang responsif terhadap imipenem-cilastatin', 'Dosis yang diresepkan oleh dokter tergantung pada kondisi dan usia pasien. Obat ini tersedia dengan kandungan 250/250 mg atau 500/500 mg, imipenem/cilastatin.', '["Imipenem-Cilastatin", "Fiocilas", "Imiclast", "Imipex", "Pelascap", "Pelastin"]', '["imipex", "imipenem-cil4st4tin", "1m1penem-c1lastat1n", "iipenem-cilastatin", "imipenem-ci1astatin", "imipenem-cilastati", "imipenem-cilastatin", "imipenem-ciiastatin", "imiclast", "fiocilas", "imipenem-cila5tatin", "imip3n3m-cilastatin", "pelascap"]', '["1m1penem-c1lastat1n", "iipenem-cilastatin", "imip3n3m-cilastatin", "imipenem-ci1astatin", "imipenem-ciiastatin", "imipenem-cil4st4tin", "imipenem-cila5tatin", "imipenem-cilastati"]', 'DKL10001901A1', 'imipenemcilastatin', 'imipenemcilastatin');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('acetylcysteine-sirup', 'Acetylcysteine Sirup', 'Acetylcysteine Sirup', 'Obat mukolitik (pengencer dahak)', 'Obat Bebas Terbatas (Lingkaran Biru)', 'Sirup kering', 'Mengencerkan dahak', 'Umumnya, tiap 5 ml acetylcysteine sirup mengandung 100 mg acetylcysteine. Berikut adalah dosis umum penggunaan acetylcysteine sirup untuk mengencerkan dahak akibat gangguan saluran pernapasan:', '["Acetylcysteine Sirup", "Muco-Ace", "asma", "gagal jantung kongestif", "penyakit ginjal", "tukak lambung"]', '["penyakit ginjal", "acetylcy5teine 5irup", "acetylcyste1ne s1rup", "gagal jantung kongestif", "acetylcysteine sirup", "4cetylcysteine sirup", "acetylcysteine siru", "acetylcystelne slrup", "acety1cysteine sirup", "asma", "acetyicysteine sirup", "muco-ace", "ac3tylcyst3in3 sirup"]', '["4cetylcysteine sirup", "ac3tylcyst3in3 sirup", "acety1cysteine sirup", "acetyicysteine sirup", "acetylcy5teine 5irup", "acetylcyste1ne s1rup", "acetylcysteine siru", "acetylcystelne slrup"]', 'DTL10002041A1', 'acetylcysteinesirup', 'acetylcysteinesirup');
