INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('olmesartan', 'Olmesartan', 'Olmesartan', 'Antihipertensi golongan penghambat reseptor angiotensin II', 'Obat Keras (Lingkaran Merah K)', 'Tablet salut selaput', 'Menurunkan tekanan darah tinggi (hipertensi)', 'Dosis yang diresepkan dokter akan disesuaikan dengan usia dan berat badan (BB) pasien. Berikut adalah rincian dosis olmesartan untuk penderita hipertensi:', '["Olmesartan", "Losatec", "Normetec", "Olmetec", "Olmetec Plus", "seperti azilsartan medoxomil"]', '["olm3sartan", "o1mesartan", "oimesartan", "olmetec plus", "olmes4rt4n", "olmesarta", "olrnesartan", "olme5artan", "olmesartan", "losatec", "normetec", "0lmesartan", "olmetec"]', '["0lmesartan", "o1mesartan", "oimesartan", "olm3sartan", "olme5artan", "olmes4rt4n", "olmesarta", "olrnesartan"]', 'DKL10001046A1', 'olmesartan', 'olmesartan');
