INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('ulpraz', 'Ulpraz', 'Omeprazole 20 mg', 'Penghambat pompa proton', 'Obat Keras (Lingkaran Merah K)', 'Kapsul lepas tunda', 'Menurunkan produksi asam lambung pada kondisi t ukak lambung, gastroesophageal reflux disease (GERD), tukak duodenum, dan sindrom Zollinger-Ellison.', 'Dosis Ulpraz tergantung pada kondisi dan usia pasien. Berikut adalah dosis umum pemberian Ulpraz berdasarkan kondisi pasien:', '["Ulpraz"]', '["ulpraz", "ulpr4z", "uipraz", "omeprazole 20 mg", "upraz", "ulpra", "ulpras", "u1praz"]', '["u1praz", "uipraz", "ulpr4z", "ulpra", "ulpras", "upraz"]', 'DKL10000638A1', 'ulpraz', 'omeprazole20mg');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('ganciclovir', 'Ganciclovir', 'Ganciclovir', 'Antivirus', 'Obat Keras (Lingkaran Merah K)', 'Suntik', 'Mengobati infeksi cytomegalovirus (CMV)', 'Ganciclovir digunakan untuk mengatasi dan mencegah terjadinya infeksi cytomegalovirus (CMV). Berikut adalah dosis ganciclovir untuk orang dewasa berdasarkan tujuan pengobatannya:', '["Ganciclovir", "acyclovir", "trombositopenia", "menyusui", "seperti flu atau campak", "suplemen"]', '["ganciciovir", "ganciclovir", "trombositopenia", "gancicl0vir", "g4nciclovir", "ganciclovi", "seperti flu atau campak", "menyusui", "acyclovir", "gancic1ovir", "gancidovir", "ganc1clov1r", "ganclclovlr"]', '["g4nciclovir", "ganc1clov1r", "gancic1ovir", "ganciciovir", "gancicl0vir", "ganciclovi", "gancidovir", "ganclclovlr"]', 'DKL10001137A1', 'ganciclovir', 'ganciclovir');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('rebamipide', 'Rebamipide', 'Rebamipide', 'Antasida', 'Obat Keras (Lingkaran Merah K)', 'Tablet', 'Mengatasi penyakit lambung, seperti ulkus lambung dan gastritis', 'Dosis rebamipide untuk mengatasi tukak lambung dan gastritis pada orang dewasa adalah 100 mg 3 kali sehari. Pada pengobatan tukak lambung, obat ini mungkin akan dikombinasikan dengan obat lambung lain, seperti penghambat pompa proton, antikolinergik, atau antagonis H2.', '["Rebamipide"]', '["rebamlplde", "r3bamipid3", "rebarnipide", "rebamipide", "rbamipide", "rebam1p1de", "rebamipid", "reb4mipide"]', '["r3bamipid3", "rbamipide", "reb4mipide", "rebam1p1de", "rebamipid", "rebamlplde", "rebarnipide"]', 'DKL10001010A1', 'rebamipide', 'rebamipide');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('akilen', 'Akilen', 'Ofloxacin', 'Obat resep', 'Obat Keras (Lingkaran Merah K)', 'Tablet salut selaput', 'Mengatasi infeksi bakteri, seperti infeksi saluran kemih, saluran napas, saluran pencernaan, kulit, tulang, hingga sendi', 'Dosis Akilen akan disesuaikan dengan jenis infeksi, tingkat keparahan, usia, serta kondisi kesehatan Anda. Berikut ini beberapa contoh aturan pakai Akilen yang umum diberikan:', '["Akilen"]', '["ofloxacin", "4kilen", "ak1len", "akllen", "akil3n", "aki1en", "akile", "ailen", "akilen", "akiien"]', '["4kilen", "ailen", "ak1len", "aki1en", "akiien", "akil3n", "akile", "akllen"]', 'DKL10000596A1', 'akilen', 'ofloxacin');
