INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('ecoroxib', 'Ecoroxib', 'Etoricoxib', 'Obat antiinflamasi nonsteroid ( OAINS ) jenis COX-2 inhibitor', 'Obat Keras (Lingkaran Merah K)', 'Tablet salut selaput', 'Meredakan nyeri dan peradangan', 'Dosis Ecoroxib akan ditentukan oleh dokter berdasarkan kondisi dan usia pasien. Berikut ini adalah dosis umum penggunaan Ecoroxib:', '["Ecoroxib"]', '["ecoroxlb", "ecoroxi", "esoroxib", "eoroxib", "ecoroksib", "etoricoxib", "ec0r0xib", "3coroxib", "ecoroxib", "ecorox1b"]', '["3coroxib", "ec0r0xib", "ecoroksib", "ecorox1b", "ecoroxi", "ecoroxlb", "eoroxib", "esoroxib"]', 'DKL10000827A1', 'ecoroxib', 'etoricoxib');
