INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('olodaterol', 'Olodaterol', 'Olodaterol', 'Bronkodilator jenis agonis beta', 'Obat Keras (Lingkaran Merah K)', 'Cairan inhalasi (hirup)', 'Meredakan dan mencegah munculnya gejala penyempitan saluran pernapasan akibat PPOK', 'Olodaterol tersedia dalam bentuk cairan yang dihirup dengan alat inhaler. Dosis olodaterol inhaler sebagai obat untuk mencegah kekambuhan dan meredakan gejala penyakit paru obstruktif kronis adalah 2 inhalasi 1 kali sehari. Sekali inhalasi setara dengan 2,5 mcg.', '["Olodaterol", "Infortispir Respimat", "Spiolto Respimat", "penyakit jantung", "hipertensi", "diabetes"]', '["penyakit jantung", "0l0dater0l", "infortispir respimat", "olod4terol", "spiolto respimat", "olodatero", "hipertensi", "oiodateroi", "o1odatero1", "olodaterol", "olodat3rol", "oodaterol"]', '["0l0dater0l", "o1odatero1", "oiodateroi", "olod4terol", "olodat3rol", "olodatero", "oodaterol"]', 'DKL10001045A1', 'olodaterol', 'olodaterol');
