INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('garkene', 'Garkene', 'Asam valproat', 'Antikonvulsan', 'Obat Keras (Lingkaran Merah K)', 'Sirop', 'Mengatasi kejang', 'Dosis Garkene bisa berbeda-beda tergantung usia, berat badan dan tingkat keparahannya. Berikut panduan dosis umum asam valproat dalam Garkene:', '["Garkene"]', '["g4rkene", "asam valproat", "garken", "gark3n3", "garkene", "grkene"]', '["g4rkene", "gark3n3", "garken", "grkene"]', 'DKL10000701A1', 'garkene', 'asamvalproat');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('janumet-xr', 'Janumet XR', 'Sitagliptin dan Metformin HCl', 'Antidiabetes', 'Obat Keras (Lingkaran Merah K)', 'Tablet lepas lambat', 'Mengendalikan kadar gula darah pada penderita diabetes tipe 2', 'Janumet XR memiliki bentuk sediaan tablet lepas lambat. Dosis Janumet XR yang diberikan dokter tergantung pada kondisi, respons pasien terhadap obat, dan obat lain yang diminum.', '["Janumet XR"]', '["janumet x", "janumet ksr", "janumet xr", "janum3t xr", "janurnet xr", "jnumet xr", "j4numet xr", "sitagliptin dan metformin hcl"]', '["j4numet xr", "janum3t xr", "janumet ksr", "janumet x", "janurnet xr", "jnumet xr"]', 'DKL10000926A1', 'janumetxr', 'sitagliptindanmetforminhcl');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('edopect', 'Edopect', 'Erdosteine', 'Mukolitik', 'Obat Keras (Lingkaran Merah K)', 'Kapsul dan sirop kering', 'Meringankan keluhan batuk berdahak akibat bronkitis akut maupun bronkitis kronis', 'Dosis Edopect akan disesuaikan dengan usia dan kondisi pasien, serta sediaan obat yang digunakan. Itulah sebabnya, setiap pasien bisa mendapatkan dosis yang berbeda.', '["Edopect"]', '["erdosteine", "edopect", "edopec", "ed0pect", "edopest", "eopect", "3dop3ct"]', '["3dop3ct", "ed0pect", "edopec", "edopest", "eopect"]', 'DKL10000708A1', 'edopect', 'erdosteine');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('januvia', 'Januvia', 'Sitagliptin', 'Antidiabetes', 'Obat Keras (Lingkaran Merah K)', 'Tablet', 'Mengendalikan kadar gula darah pada penderita diabetes tipe 2', 'Januvia hadir dalam sediaan tablet. Dokter akan menyesuaikan dosis obat ini dengan kondisi pasien. Namun, dosis Januvia secara umum untuk mengatasi diabetes tipe 2 adalah 100 mg per hari.', '["Januvia"]', '["januv1a", "jnuvia", "januvia", "januvi", "j4nuvi4", "januvla", "sitagliptin"]', '["j4nuvi4", "januv1a", "januvi", "januvla", "jnuvia"]', 'DKL10000718A1', 'januvia', 'sitagliptin');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('gasela', 'Gasela', 'Ranitidin 150 mg', 'Antagonis H2', 'Obat Keras (Lingkaran Merah K)', 'Tablet salut selaput', 'Menurunkan produksi asam lambung', 'Berikut ini adalah dosis umum penggunaan Gasela berdasarkan kondisi dan usia pasien:', '["Gasela"]', '["gaseia", "gas3la", "g4sel4", "ranitidin 150 mg", "ga5ela", "gsela", "gasel", "gase1a", "gasela"]', '["g4sel4", "ga5ela", "gas3la", "gase1a", "gaseia", "gasel", "gsela"]', 'DKL10000589A1', 'gasela', 'ranitidin150mg');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('om3heart', 'Om3Heart', 'Tiap kapsul mengandung minyak ikan alami 600 mg setara dengan EPA 180 mg dan DHA 120 mg', 'Suplemen kesehatan', 'Obat Tradisional / Jamu (Logo Pohon)', 'Kapsul lunak', 'Memelihara kesehatan tubuh', 'Dosis Om3Heart dapat berbeda untuk setiap orang, tergantung usia, kondisi kesehatan, dan tujuan penggunaan. Umumnya, Om3Heart dapat dikonsumsi 2 kapsul per hari.', '["Om3Heart"]', '["o3heart", "tiap kapsul mengandung minyak ikan alami 600 mg setara dengan epa 180 mg dan dha 120 mg", "om3he4rt", "om3h3art", "om3heart", "om3hear", "orn3heart", "0m3heart"]', '["0m3heart", "o3heart", "om3h3art", "om3he4rt", "om3hear", "orn3heart"]', 'TR10000739A1', 'om3heart', 'tiapkapsulmengandungminyakikanalami600mgsetaradenganepa180mgdandha120mg');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('makrodex', 'Makrodex', '150 roxithromycin', 'Antibiotik makrolid', 'Obat Keras (Lingkaran Merah K)', 'Tablet', 'Mengobati infeksi bakteri', 'Dosis penggunaan Makrodex akan ditentukan dokter sesuai jenis infeksi, usia pasien, tingkat keparahan, serta kondisi kesehatan pasien. Umumnya, dosis Makrodex untuk mengobati infeksi bakteri sesuai usia pasien adalah:', '["Makrodex"]', '["makrode", "makrod3x", "mkrodex", "makrodeks", "150 roxithromycin", "rnakrodex", "makrodex", "makr0dex", "m4krodex"]', '["m4krodex", "makr0dex", "makrod3x", "makrode", "makrodeks", "mkrodex", "rnakrodex"]', 'DKL10000827A1', 'makrodex', '150roxithromycin');
