INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('omalizumab', 'Omalizumab', 'Omalizumab', 'Antibodi monoklonal', 'Obat Keras (Lingkaran Merah K)', 'Suntik', 'Mengobati asma', 'Omalizumab akan disuntikkan langsung oleh dokter atau petugas medis di bawah pengawasan dokter. Penyuntikan dilakukan ke bawah kulit (subkutan/SC) Dosis yang diberikan tergantung pada kondisi kesehatan dan respons tubuh pasien.', '["Omalizumab", "serbuk sari", "seperti demam", "kelenjar getah bening bengkak", "tidak enak badan", "atau menderita penyakit infeksi"]', '["serbuk sari", "0malizumab", "omalisumab", "oma1izumab", "tidak enak badan", "omal1zumab", "omaiizumab", "om4lizum4b", "omalizumab", "omalizuma", "seperti demam", "oalizumab", "kelenjar getah bening bengkak"]', '["0malizumab", "oalizumab", "om4lizum4b", "oma1izumab", "omaiizumab", "omal1zumab", "omalisumab", "omalizuma"]', 'DKL10001041A1', 'omalizumab', 'omalizumab');
