INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('makrolid', 'Makrolid', 'Makrolid', 'Pengobatan Umum', 'Obat Keras (Lingkaran Merah K)', 'Sediaan oral/topikal sesuai instruksi kemasan.', 'Mengatasi gangguan kesehatan dan meredakan gejala sesuai petunjuk medis.', 'Berikut adalah obat-obatan yang termasuk dalam golongan antibiotik makrolid, beserta merek dagang dan dosisnya:', '["Makrolid", "Infeksi saluran pernapasan", "seperti pneumonia", "sinusitis", "dan pertusis Radang tenggorokan", "radang amandel"]', '["makroli", "infeksi saluran pernapasan", "makrolld", "dan pertusis radang tenggorokan", "makro1id", "sinusitis", "makrol1d", "makr0lid", "m4krolid", "makrolid", "mkrolid", "makroiid", "seperti pneumonia"]', '["m4krolid", "makr0lid", "makro1id", "makroiid", "makrol1d", "makroli", "makrolld", "mkrolid"]', 'DKL10000819A1', 'makrolid', 'makrolid');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('gasogal', 'Gasogal', 'Eperisone hydrochloride 50 mg', 'Obat pelemas otot', 'Obat Keras (Lingkaran Merah K)', 'Tablet salut selaput', 'Meredakan nyeri dan kaku otot', 'Ketika memberikan e-resep atau resep langsung, dokter akan menjelaskan mengenai dosis Gasogal. Dosis obat ini biasanya disesuaikan dengan usia dan kondisi pasien. Namun, untuk orang dewasa, dosis umum Gasogal adalah1 tablet, 3 kali sehari.', '["Gasogal"]', '["gasogal", "ga5ogal", "eperisone hydrochloride 50 mg", "gasogai", "gas0gal", "gsogal", "gasoga", "g4sog4l", "gasoga1"]', '["g4sog4l", "ga5ogal", "gas0gal", "gasoga", "gasoga1", "gasogai", "gsogal"]', 'DKL10000702A1', 'gasogal', 'eperisonehydrochloride50mg');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('reco-tetes-telinga', 'Reco Tetes Telinga', 'Chloramphenicol', 'Antibiotik', 'Obat Keras (Lingkaran Merah K)', 'Tetes telinga', 'Mengatasi otitis eksterna', 'Berikut adalah dosis umum penggunaan Reco Tetes Telinga untuk mengatasi otitis eksterna:', '["Reco Tetes Telinga"]', '["reco tetes teling", "reco tetes tel1nga", "reco tete5 telinga", "rco tetes telinga", "rec0 tetes telinga", "reco tetes te1inga", "reco tetes telinga", "r3co t3t3s t3linga", "chloramphenicol", "reco tetes teiinga"]', '["r3co t3t3s t3linga", "rco tetes telinga", "rec0 tetes telinga", "reco tete5 telinga", "reco tetes te1inga", "reco tetes teiinga", "reco tetes tel1nga", "reco tetes teling"]', 'DKL10001682A1', 'recotetestelinga', 'chloramphenicol');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('edotin', 'Edotin', 'Erdosteine', 'Obat mukolitik', 'Obat Keras (Lingkaran Merah K)', 'Kapsul dan sirop kering', 'Meredakan batuk berdahak pada gangguan saluran pernapasan, seperti bronkitis atau infeksi pernapasan lain', 'Dokter akan menjelaskan mengenai dosis penggunaan obat ini ketika memberikan e-resep atau resep biasa. Setiap pasien akan diresepkan dosis Edotin yang berbeda, tergantung pada usia dan kondisi pasien.', '["Edotin"]', '["erdosteine", "eotin", "3dotin", "edot1n", "edotin", "ed0tin", "edotln", "edoti"]', '["3dotin", "ed0tin", "edot1n", "edoti", "edotln", "eotin"]', 'DKL10000611A1', 'edotin', 'erdosteine');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('ultracet', 'Ultracet', 'Paracetamol 325 mg dan tramadol HCl 37,5 mg', 'Obat pereda nyeri', 'Obat Keras (Lingkaran Merah K)', 'Tablet', 'Meredakan nyeri', 'Berikut ini adalah dosis umum penggunaan Ultracet untuk mengatasi nyeri sedang hingga berat:', '["Ultracet"]', '["ultr4cet", "paracetamol 325 mg dan tramadol hcl 37,5 mg", "ultraset", "ultrace", "utracet", "uitracet", "u1tracet", "ultracet", "ultrac3t"]', '["u1tracet", "uitracet", "ultr4cet", "ultrac3t", "ultrace", "ultraset", "utracet"]', 'DKL10000836A1', 'ultracet', 'paracetamol325mgdantramadolhcl375mg');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('aclam', 'Aclam', '125 mg amoxicillin dan 31,25 mg asam klavulanat per 5 ml', 'Antibiotik', 'Obat Keras (Lingkaran Merah K)', 'Sirop kering', 'Mengobati infeksi bakteri', 'Dosis Aclam tidak sama untuk setiap orang. Hal ini tergantung pada beberapa faktor, seperti usia, berat badan, jenis infeksi yang dialami dan tingkat keparahan infeksi. Berikut dosis umum penggunaan Aclam sirop kering:', '["Aclam"]', '["4cl4m", "aclarn", "adam", "aslam", "aciam", "aclam", "ac1am", "125 mg amoxicillin dan 31,25 mg asam klavulanat per 5 ml"]', '["4cl4m", "ac1am", "aciam", "aclarn", "adam", "aslam"]', 'DKL10000478A1', 'aclam', '125mgamoxicillindan3125mgasamklavulanatper5ml');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('omberzol', 'Omberzol', 'Omeprazole', 'Penghambat pompa proton', 'Obat Keras (Lingkaran Merah K)', 'Kapsul lepas tunda', 'Mengurangi produksi asam lambung berlebih', 'Dokter akan menentukan dosis Omberzol berdasarkan kondisi yang akan ditangani dan usia pasien. Namun, secara umum, dosis Omberzol adalah sebagai berikut:', '["Omberzol"]', '["ombersol", "omberzo1", "0mberz0l", "ornberzol", "omb3rzol", "oberzol", "omberzo", "omberzoi", "omeprazole", "omberzol"]', '["0mberz0l", "oberzol", "omb3rzol", "ombersol", "omberzo", "omberzo1", "omberzoi", "ornberzol"]', 'DKL10000842A1', 'omberzol', 'omeprazole');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('albendazole', 'Albendazole', 'Albendazole', 'Obat cacing (antelmintik)', 'Obat Keras (Lingkaran Merah K)', 'Tablet kunyah dan suspensi', 'Mengobati infeksi cacing.', 'Dosis albendazole yang diberikan oleh dokter dapat berbeda, tergantung jenis infeksi cacing yang dialami pasien. Pada beberapa kondisi, dosis albendazole akan disesuaikan dengan berat badan (BB) pasien. Berikut rincian dosis albendazole:', '["Albendazole", "Vermic", "epilepsi", "gangguan penglihatan atau penyakit mata", "penyakit ginjal", "atau kelainan darah"]', '["penyakit ginjal", "4lbend4zole", "a1bendazo1e", "albendazol", "epilepsi", "abendazole", "alb3ndazol3", "albendasole", "albendaz0le", "albendazole", "vermic", "gangguan penglihatan atau penyakit mata", "aibendazoie"]', '["4lbend4zole", "a1bendazo1e", "abendazole", "aibendazoie", "alb3ndazol3", "albendasole", "albendaz0le", "albendazol"]', 'DKL10001121A1', 'albendazole', 'albendazole');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('xiltrop', 'Xiltrop', 'Amoxicillin', 'Antibiotik jenis penicillin', 'Obat Keras (Lingkaran Merah K)', 'Kaplet dan sirop kering', 'Mengobati berbagai infeksi bakteri', 'Dosis Xiltrop akan disesuaikan oleh dokter berdasarkan usia dan kondisi yang diderita pasien. Pada anak-anak, dosis Xiltrop akan disesuaikan dengan berat badan (BB) pasien.', '["Xiltrop"]', '["xiitrop", "xiltr0p", "ksiltrop", "x1ltrop", "amoxicillin", "xiltro", "xlltrop", "xiltrop", "xltrop", "xi1trop"]', '["ksiltrop", "x1ltrop", "xi1trop", "xiitrop", "xiltr0p", "xiltro", "xlltrop", "xltrop"]', 'DKL10000754A1', 'xiltrop', 'amoxicillin');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('alaxan-fr', 'Alaxan FR', 'Ibuprofen 200 mg dan paracetamol 325 mg', 'Obat antiinflamasi nonsteroid (OAINS), analgesik dan antipiretik', 'Obat Bebas Terbatas (Lingkaran Biru)', 'Kapsul', 'Meredakan nyeri ringan hingga sedang, serta menurunkan demam', 'Dosis umum penggunaan Alaxan FR untuk mengatasi nyeri dan demam adalah:', '["Alaxan FR"]', '["alaksan fr", "aaxan fr", "alaxan f", "alaxan fr", "alaxan phr", "a1axan fr", "aiaxan fr", "ibuprofen 200 mg dan paracetamol 325 mg", "4l4x4n fr"]', '["4l4x4n fr", "a1axan fr", "aaxan fr", "aiaxan fr", "alaksan fr", "alaxan f", "alaxan phr"]', 'DTL10000781A1', 'alaxanfr', 'ibuprofen200mgdanparacetamol325mg');
