INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('omecidal', 'Omecidal', 'Mebhydrolin 50 mg', 'Antihistamin', 'Obat Keras (Lingkaran Merah K)', 'Kapsul', 'Meredakan gejala alergi pada rhinitis alergi, konjungtivitis alergi, atau biduran', 'Dosis dan durasi pengobatan akan disesuaikan oleh dokter berdasarkan kondisi dan jenis penyakit pasien. Umumnya, dosis Omecidal untuk mengatasi gejala alergi, seperti rhinitis alergi, konjungtivitis alergi, atau biduran, berdasarkan usia pasien adalah:', '["Omecidal"]', '["0mecidal", "omecid4l", "omecidal", "om3cidal", "omecida", "omecidai", "omecida1", "omec1dal", "oecidal", "mebhydrolin 50 mg"]', '["0mecidal", "oecidal", "om3cidal", "omec1dal", "omecid4l", "omecida", "omecida1", "omecidai"]', 'DKL10000798A1', 'omecidal', 'mebhydrolin50mg');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('edoxaban', 'Edoxaban', 'Edoxaban', 'Antikoagulan jenis penghambat faktor Xa', 'Obat Keras (Lingkaran Merah K)', 'Tablet salut selaput', 'Mencegah terjadinya stroke pada penderita gangguan irama jantung jenis atrial fibrilasi', 'Dosis edoxaban yang diberikan dokter tergantung pada kondisi dan berat badan (BB) pasien. Berikut adalah dosis edoxaban untuk orang dewasa berdasarkan tujuan penggunaannya:', '["Edoxaban", "hipertensi", "penyakit liver", "sindrom antifosfolipid", "penyakit ginjal", "penyakit jantung"]', '["penyakit ginjal", "edoxaba", "penyakit liver", "eoxaban", "hipertensi", "edox4b4n", "ed0xaban", "edoxaban", "edoksaban", "sindrom antifosfolipid", "3doxaban"]', '["3doxaban", "ed0xaban", "edoksaban", "edox4b4n", "edoxaba", "eoxaban"]', 'DKL10000802A1', 'edoxaban', 'edoxaban');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('gastran', 'Gastran', 'Aluminium hidroksida 200 mg, magnesium hidroksida 200 mg, dan simethicone 20 mg', 'Antasida dan antiflatulensi (antikembung)', 'Obat Bebas (Hijau)', 'Tablet', 'Mengatasi gejala sakit maag akibat kelebihan asam lambung, termasuk pada gastritis, tukak lambung, dan ulkus duodenum', 'Mengetahui dosis yang tepat sangat penting agar Gastran bekerja efektif dan aman. Berikut ini adalah dosis umum penggunaan Gastran untuk mengatasi sakit maag:', '["Gastran"]', '["ga5tran", "gstran", "g4str4n", "aluminium hidroksida 200 mg, magnesium hidroksida 200 mg, dan simethicone 20 mg", "gastra", "gastran"]', '["g4str4n", "ga5tran", "gastra", "gstran"]', 'DBL10000720A1', 'gastran', 'aluminiumhidroksida200mgmagnesiumhidroksida200mgdansimethicone20mg');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('aclonac', 'Aclonac', 'Natrium diclofenac 25 mg', 'Obat anti inflamasi nonsteroid (OAINS)', 'Obat Keras (Lingkaran Merah K)', 'Tablet', 'Menangani peradangan, seperti nyeri dan bengkak pada kondisi nyeri haid, radang sendi, atau nyeri setelah operasi', 'Dosis Aclonac akan disesuaikan oleh dokter dengan kondisi dan usia pasien, serta responsnya terhadap pengobatan. Berikut ini adalah dosis umum Aclonac berdasarkan usia:', '["Aclonac"]', '["aslonas", "adonac", "acl0nac", "aclonac", "natrium diclofenac 25 mg", "ac1onac", "aclona", "acionac", "alonac", "4clon4c"]', '["4clon4c", "ac1onac", "acionac", "acl0nac", "aclona", "adonac", "alonac", "aslonas"]', 'DKL10000689A1', 'aclonac', 'natriumdiclofenac25mg');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('maltofer', 'Maltofer', 'Iron polymaltose complex', 'Obat', 'Obat Bebas (Hijau)', 'Tablet kunyah, sirop, drops', 'Pengobatan pada defisiensi zat besi tanpa anemia dan anemia defisiensi besi dan sebagai terapi pencegahan defisiensi zat besi selama kehamilan', 'Maltofer tersedia dalam bentuk sediaan drops, sirop, atau tablet kunyah. Maltofer drops mengandung zat besi sebanyak 50 mg/ml, di mana 1 ml setara dengan 20 tetes (drops). Maltofer sirop mengandung zat besi sebanyak 10 mg/ml. Maltofer tablet kunyah mengandung 100 mg zat besi di tiap tabletnya.', '["Maltofer"]', '["maltofe", "mltofer", "m4ltofer", "iron polymaltose complex", "maltofer", "malt0fer", "maltof3r", "ma1tofer", "maitofer", "maltopher"]', '["m4ltofer", "ma1tofer", "maitofer", "malt0fer", "maltof3r", "maltofe", "maltopher", "mltofer"]', 'DBL10000826A1', 'maltofer', 'ironpolymaltosecomplex');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('abacavir', 'Abacavir', 'Abacavir', 'Antivirus nucleoside reverse transciptase inhibitors (NRTIs)', 'Obat Keras (Lingkaran Merah K)', 'Tablet', 'Memperlambat perkembangan infeksi HIV', 'Dosis abacavir akan ditentukan dokter berdasarkan usia dan kondisi pasien, serta respons pasien terhadap pengobatan. Pada anak-anak, dosis abacavir ditentukan berdasarkan berat badannya (BB). Dosis dapat berubah jika berat badan anak naik atau turun.', '["Abacavir", "Abacavex", "seperti sirosis dan gagal hati", "seperti kolesterol tinggi", "diabetes", "produk herbal"]', '["abacavir", "abacav1r", "abacavlr", "abacavex", "seperti kolesterol tinggi", "4b4c4vir", "abasavir", "diabetes", "seperti sirosis dan gagal hati", "abacavi", "aacavir"]', '["4b4c4vir", "aacavir", "abacav1r", "abacavi", "abacavlr", "abasavir"]', 'DKL10000793A1', 'abacavir', 'abacavir');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('efavirenz', 'Efavirenz', 'Efavirenz', 'Antivirus non-nucleoside reverse transcriptase inhibitor (NNRTI)', 'Obat Keras (Lingkaran Merah K)', 'Tablet, kapsul', 'Mengontrol dan mencegah infeksi HIV', 'Efavirenz dikombinasikan dengan obat antivirus lain dalam pengobatan HIV. Berikut ini adalah pembagian dosis efavirenz berdasarkan tujuan pengobatan, usia, dan berat badan pasien:', '["Efavirenz"]', '["efaviren", "efavlrenz", "eavirenz", "efav1renz", "ephavirenz", "efavirenz", "ef4virenz", "efavirens", "3favir3nz"]', '["3favir3nz", "eavirenz", "ef4virenz", "efav1renz", "efaviren", "efavirens", "efavlrenz", "ephavirenz"]', 'DKL10000938A1', 'efavirenz', 'efavirenz');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('reco-tetes-mata', 'Reco Tetes Mata', 'Chloramphenicol', 'Antibiotik', 'Obat Keras (Lingkaran Merah K)', 'Tetes mata', 'Mengatasi infeksi bakteri pada mata (misalnya konjungtivitis bakterial)', 'Dosis umum Chloramphenicol dalam Reco Tetes Mata yang biasa dianjurkan adalah 1–2 tetes. Teteskan pada mata yang sakit 6 kali sehari atau lebih jika diperlukan. Durasi pengobatan 5 hari.', '["Reco Tetes Mata"]', '["reco tete5 mata", "reco tetes m4t4", "r3co t3t3s mata", "reso tetes mata", "reco tetes mat", "chloramphenicol", "reco tetes rnata", "rco tetes mata", "rec0 tetes mata", "reco tetes mata"]', '["r3co t3t3s mata", "rco tetes mata", "rec0 tetes mata", "reco tete5 mata", "reco tetes m4t4", "reco tetes mat", "reco tetes rnata", "reso tetes mata"]', 'DKL10001361A1', 'recotetesmata', 'chloramphenicol');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('kadiflam', 'Kadiflam', 'Diclofenac potassium', 'Obat resep', 'Obat Keras (Lingkaran Merah K)', 'Tablet', 'Meredakan nyeri dan peradangan, contohnya pada radang sendi, sakit gigi, atau migrain', 'Dosis Kadiflam akan disesuaikan oleh dokter berdasarkan kondisi dan usia pasien. Berikut ini adalah dosis umum penggunaan Kadiflam:', '["Kadiflam"]', '["diclofenac potassium", "kadif1am", "kadifla", "kadifiam", "kadiphlam", "k4difl4m", "kadiflam", "kadiflarn", "kadlflam", "kad1flam"]', '["k4difl4m", "kad1flam", "kadif1am", "kadifiam", "kadifla", "kadiflarn", "kadiphlam", "kadlflam"]', 'DKL10000793A1', 'kadiflam', 'diclofenacpotassium');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('ultraflu-flu-dan-batuk', 'Ultraflu Flu dan Batuk', 'Paracetamol , chlorpheniramine maleate, phenylpropanolamine , dan dextromethorphan HBr', 'Kombinasi analgetik-antipiretik (paracetamol), antihistamin (chlorpheniramine), dekongestan (phenylpropanolamine), dan antitusif (dextromethorphan HBr)', 'Obat Bebas Terbatas (Lingkaran Biru)', 'Kaplet', 'Meringankan gejala flu yang disertai batuk kering', 'Berikut ini adalah dosis umum penggunaan Ultraflu Flu dan Batuk untuk meredakan gejala flu yang disertai batuk kering:', '["Ultraflu Flu dan Batuk"]', '["uitrafiu fiu dan batuk", "ultraphlu phlu dan batuk", "ultraflu flu dan batu", "ultraflu flu dan batuk", "paracetamol , chlorpheniramine maleate, phenylpropanolamine , dan dextromethorphan hbr", "ultr4flu flu d4n b4tuk", "u1traf1u f1u dan batuk", "utraflu flu dan batuk"]', '["u1traf1u f1u dan batuk", "uitrafiu fiu dan batuk", "ultr4flu flu d4n b4tuk", "ultraflu flu dan batu", "ultraphlu phlu dan batuk", "utraflu flu dan batuk"]', 'DTL10002048A1', 'ultraflufludanbatuk', 'paracetamolchlorpheniraminemaleatephenylpropanolaminedandextromethorphanhbr');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('ximetha', 'Ximetha', 'Desoximetasone', 'Kortikosteroid topikal', 'Obat Keras (Lingkaran Merah K)', 'Krim', 'Meredakan gatal-gatal dan gejala peradangan pada kulit akibat sejumlah kondisi, seperti dermatitis , eksim, atau psoriasis', 'Untuk meredakan keluhan radang kulit, oleskan krim Ximetha secara merata pada area kulit yang perlu diobati, 1–2 kali sehari atau sesuai petunjuk dokter. Lama pengobatan tidak boleh lebih dari 4 minggu.', '["Ximetha"]', '["ximeta", "xlmetha", "ximeth4", "desoximetasone", "x1metha", "ximetha", "ximeth", "ksimetha", "xim3tha", "xirnetha"]', '["ksimetha", "x1metha", "xim3tha", "ximeta", "ximeth", "ximeth4", "xirnetha", "xlmetha"]', 'DKL10000720A1', 'ximetha', 'desoximetasone');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('omecold', 'Omecold', 'Paracetamol , phenylpropanolamine, chlorpheniramine maleate', 'Kombinasi analgetik-antipiretik , dekongestan , dan antihistamin', 'Obat Bebas Terbatas (Lingkaran Biru)', 'Tablet', 'Meredakan gejala flu, seperti demam , sakit kepala , dan bersin-bersin', 'Dosis umum penggunaan Omecold untuk meredakan gejala flu, seperti demam, hidung tersumbat, dan bersin-bersin adalah:', '["Omecold"]', '["0mec0ld", "ornecold", "omeco1d", "omecoid", "omecold", "omesold", "paracetamol , phenylpropanolamine, chlorpheniramine maleate", "oecold", "omecol", "om3cold"]', '["0mec0ld", "oecold", "om3cold", "omeco1d", "omecoid", "omecol", "omesold", "ornecold"]', 'DTL10000707A1', 'omecold', 'paracetamolphenylpropanolaminechlorpheniraminemaleate');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('albiotin', 'Albiotin', 'Clindamycin', 'Antibiotik golongan lincosamide atau lincomycin', 'Obat Keras (Lingkaran Merah K)', 'Kapsul', 'Mengobati infeksi bakteri', 'Dokter akan memberikan Albiotin kepada pasien dengan dosis yang berbeda, tergantung pada usia, kondisi, dan respon tubuh terhadap obat. Berikut adalah dosis umum Albiotin berdasarkan kelompok usia:', '["Albiotin"]', '["albi0tin", "aibiotin", "alb1ot1n", "albiotin", "abiotin", "4lbiotin", "clindamycin", "a1biotin", "albioti", "alblotln"]', '["4lbiotin", "a1biotin", "abiotin", "aibiotin", "alb1ot1n", "albi0tin", "albioti", "alblotln"]', 'DKL10000818A1', 'albiotin', 'clindamycin');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('maltofer-drops', 'Maltofer Drops', 'Iron (III) Hydroxide Polymaltose Complex', 'Obat', 'Obat Bebas (Hijau)', 'Obat tetes oral ( drops )', 'Mengatasi kekurangan atau defisiensi zat besi tanpa anemia dan anemia defisiensi besi', 'Maltofer drops mengandung zat besi sebanyak 50 mg/ml, di mana 1 ml setara dengan 20 tetes (drops). Dosis pemberian Maltofer Drops akan disesuaikan dengan kondisi pasien atau seberapa parah kekurangan zat besi yang dialami. Dosis umum pemberian Maltofer Drops berdasarkan kondisi dan usia, yaitu:', '["Maltofer Drops"]', '["maltofer drop5", "m4ltofer drops", "maltofer drops", "maltofer drop", "malt0fer dr0ps", "maltof3r drops", "ma1tofer drops", "iron (iii) hydroxide polymaltose complex", "maitofer drops", "maltopher drops"]', '["m4ltofer drops", "ma1tofer drops", "maitofer drops", "malt0fer dr0ps", "maltof3r drops", "maltofer drop", "maltofer drop5", "maltopher drops"]', 'DBL10001378A1', 'maltoferdrops', 'ironiiihydroxidepolymaltosecomplex');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('omecough', 'Omecough', 'Paracetamol, guaifenesin , dextromethorphan HBr, dan chlorpheniramine maleate', 'Obat flu dan batuk kombinasi analgetik-antipiretik (paracetamol), antihistamin (chlorpheniramine), ekspektoran (guaifenesin), dan antitusif (dextromethorphan HBr)', 'Obat Bebas Terbatas (Lingkaran Biru)', 'Sirop', 'Meredakan gejala flu , seperti demam, batuk, dan pilek', 'Untuk meredakan demam, batuk, dan flu, Anda bisa memberikan dosis umum penggunaan Omecough berikut ini kepada anak:', '["Omecough"]', '["oecough", "omesough", "ornecough", "omecough", "omecoug", "om3cough", "0mec0ugh", "paracetamol, guaifenesin , dextromethorphan hbr, dan chlorpheniramine maleate"]', '["0mec0ugh", "oecough", "om3cough", "omecoug", "omesough", "ornecough"]', 'DTL10000823A1', 'omecough', 'paracetamolguaifenesindextromethorphanhbrdanchlorpheniraminemaleate');
