INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('kafein', 'Kafein', 'Kafein', 'Stimulan sistem saraf pusat', 'Obat Keras (Lingkaran Merah K)', 'Kaplet, tablet, serbuk, dan suntik', 'Mengurangi rasa kantuk dan meningkatkan kewaspadaan', 'Dosis kafein ditentukan berdasarkan usia, kondisi pasien, dan respons tubuh pasien terhadap obat. Berikut ini adalah pembagian dosis kafein berdasarkan tujuan penggunaannya:', '["Kafein", "Bimagen", "bodrex migra", "Cafmosol", "Farsifen Plus", "Fasidol Plus"]', '["kafein", "kaf3in", "kfein", "kafeln", "kaphein", "kafei", "k4fein", "cafmosol", "bodrex migra", "farsifen plus", "bimagen", "kafe1n"]', '["k4fein", "kaf3in", "kafe1n", "kafei", "kafeln", "kaphein", "kfein"]', 'DKL10000590A1', 'kafein', 'kafein');
