INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('ximex-tetrium', 'Ximex Tetrium', 'Tetracaine HCl 5 mg', 'Obat bius (anestesi) lokal', 'Obat Keras (Lingkaran Merah K)', 'Tetes mata', 'Menghilangkan sementara rasa sakit di mata sebelum prosedur medis', 'Berikut ini adalah dosis Ximex Tetrium sebagai obat bius untuk orang dewasa berdasarkan kondisi yang akan ditangani:', '["Ximex Tetrium"]', '["ximex tetriu", "xlmex tetrlum", "ximex tetrium", "tetracaine hcl 5 mg", "ksimeks tetrium", "xirnex tetriurn", "xim3x t3trium", "xmex tetrium", "x1mex tetr1um"]', '["ksimeks tetrium", "x1mex tetr1um", "xim3x t3trium", "ximex tetriu", "xirnex tetriurn", "xlmex tetrlum", "xmex tetrium"]', 'DKL10001301A1', 'ximextetrium', 'tetracainehcl5mg');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('effient', 'Effient', 'Prasugrel', 'Pengencer darah ( antiplatelet)', 'Obat Keras (Lingkaran Merah K)', 'Tablet', 'Mencegah penggumpalan darah yang bisa menyebabkan serangan jantung dan stroke', 'Dosis Effient dan lama pengobatan akan ditentukan oleh dokter berdasarkan kondisi dan respons pasien terhadap pengobatan. Secara umum, berikut adalah dosis Effient untuk orang dewasa:', '["Effient"]', '["efient", "ephphient", "effient", "efflent", "effien", "3ffi3nt", "prasugrel", "eff1ent"]', '["3ffi3nt", "eff1ent", "effien", "efflent", "efient", "ephphient"]', 'DKL10000705A1', 'effient', 'prasugrel');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('aclovir-krim', 'Aclovir Krim', 'Acyclovir 5%', 'Obat antivirus', 'Obat Keras (Lingkaran Merah K)', 'Krim', 'Mengatasi gejala herpes simpleks di kulit, termasuk area bibir dan kelamin', 'Berikut ini adalah dosis umum penggunaan Aclovir krim berdasarkan kondisi dan usia pasien:', '["Aclovir Krim"]', '["aciovir krim", "aclov1r kr1m", "4clovir krim", "aclovir krirn", "aclovlr krlm", "ac1ovir krim", "aclovir krim", "acl0vir krim", "acyclovir 5%", "aclovir kri"]', '["4clovir krim", "ac1ovir krim", "aciovir krim", "acl0vir krim", "aclov1r kr1m", "aclovir kri", "aclovir krirn", "aclovlr krlm"]', 'DKL10001155A1', 'aclovirkrim', 'acyclovir5');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('alovell', 'Alovell', 'Alendronate', 'Bisfosfonat', 'Obat Keras (Lingkaran Merah K)', 'Tablet', 'Mencegah atau mengobati osteoporosis pada pria, wanita yang telah menopause, serta osteoporosis akibat penggunaan obat kortikosteroid dalam jangka panjang', 'Berikut adalah dosis umum penggunaan Alovell berdasarkan kondisi yang akan ditangani:', '["Alovell"]', '["aovell", "alov3ll", "4lovell", "alovel", "aioveii", "al0vell", "alendronate", "alovell", "a1ove11"]', '["4lovell", "a1ove11", "aioveii", "al0vell", "alov3ll", "alovel", "aovell"]', 'DKL10000719A1', 'alovell', 'alendronate');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('ultraway-c-500', 'Ultraway C 500', 'Vitamin C', 'Suplemen vitamin', 'Obat Bebas (Hijau)', 'Kapsul lunak', 'Mencegah dan mengatasi kekurangan vitamin C', 'Dosis Ultraway C 500 tergantung pada usia, kebutuhan, serta kondisi kesehatan pasien. Umumnya, dosis untuk dewasa adalah 1 tablet per hari, sesuai petunjuk pada kemasan atau anjuran dokter. Sementara, dosis untuk anak-anak perlu menyesuaikan saran dokter.', '["Ultraway C 500"]', '["uitraway c 500", "ultraway c 500", "ultraway s 500", "utraway c 500", "u1traway c 500", "ultr4w4y c 500", "ultraway c 50", "vitamin c"]', '["u1traway c 500", "uitraway c 500", "ultr4w4y c 500", "ultraway c 50", "ultraway s 500", "utraway c 500"]', 'DBL10001137A1', 'ultrawayc500', 'vitaminc');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('aclonac-cool', 'Aclonac Cool', 'Diclofenac 1% dan menthol 4%', 'Obat antiinflamasi nonsteroid (OAINS)', 'Obat Bebas Terbatas (Lingkaran Biru)', 'Gel', 'Meredakan nyeri dan peradangan pada sendi dan otot', 'Secara umum, dosis Aclonac Cool untuk meredakan nyeri dan peradangan adalah:', '["Aclonac Cool"]', '["diclofenac 1% dan menthol 4%", "acionac cooi", "aclonac cool", "adonac cool", "aslonas sool", "4clon4c cool", "ac1onac coo1", "acl0nac c00l", "alonac cool", "aclonac coo"]', '["4clon4c cool", "ac1onac coo1", "acionac cooi", "acl0nac c00l", "aclonac coo", "adonac cool", "alonac cool", "aslonas sool"]', 'DTL10001118A1', 'aclonaccool', 'diclofenac1danmenthol4');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('alcet', 'Alcet', 'Cetirizine', 'Obat antihistamin', 'Obat Keras (Lingkaran Merah K)', 'Tablet dan sirop', 'Meredakan gejala alergi', 'Dosis Alcet dapat berbeda-beda untuk tiap pasien. Berikut ini adalah dosis umum penggunaan obat ini berdasarkan usia pasien:', '["Alcet"]', '["alset", "4lcet", "alcet", "a1cet", "aicet", "cetirizine", "alc3t"]', '["4lcet", "a1cet", "aicet", "alc3t", "alset"]', 'DKL10000489A1', 'alcet', 'cetirizine');
