INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('eficap', 'Eficap', 'Sucralfate 500 mg', 'Anti-ulkus atau antiulcerant', 'Obat Keras (Lingkaran Merah K)', 'Tablet', 'Mengobati tukak lambung, ulkus duodenum , atau gastritis kronis', 'Dosis umum Eficap untuk orang dewasa adalah 1 tablet (500 mg), sebanyak 4 kali sehari. Obat ini sebaiknya diminum saat perut kosong, yaitu 1 jam sebelum makan atau sebelum tidur malam.', '["Eficap"]', '["ef1cap", "eflcap", "eficap", "efisap", "3ficap", "sucralfate 500 mg", "ephicap", "eicap", "efic4p", "efica"]', '["3ficap", "ef1cap", "efic4p", "efica", "efisap", "eflcap", "eicap", "ephicap"]', 'DKL10000584A1', 'eficap', 'sucralfate500mg');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('saccharomyces', 'Saccharomyces', 'Saccharomyces', 'Probiotik', 'Obat Bebas (Hijau)', 'Kapsul dan tablet', 'Mencegah dan meredakan diare', 'Berikut ini adalah rekomendasi dosis penggunaan Saccharomyces berdasarkan usia pasien:', '["Saccharomyces", "Normagut", "Nutracare Enzyme Plus", "sistem imun lemah", "infeksi saluran kemih yang berulang", "diabetes"]', '["diare lebih dari 2 hari disertai demam", "saccharomyce", "nutracare enzyme plus", "sccharomyces", "s4cch4romyces", "saccharomyces", "normagut", "saccharomyc3s", "sistem imun lemah", "saccharornyces", "sacchar0myces", "5accharomyce5"]', '["5accharomyce5", "s4cch4romyces", "sacchar0myces", "saccharomyc3s", "saccharomyce", "saccharornyces", "sccharomyces"]', 'DBL10001349A1', 'saccharomyces', 'saccharomyces');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('xolair', 'Xolair', 'Omalizumab', 'Antibodi monoklonal', 'Obat Keras (Lingkaran Merah K)', 'Suntik', 'Meredakan gejala alergi yang disertai peradangan', 'Penyuntikan Xolair dilakukan ke bawah kulit (subkutan/SC). Dosis yang diberikan akan ditentukan oleh dokter sesuai kondisi kesehatan dan respons tubuh pasien.', '["Xolair"]', '["xol4ir", "xo1air", "xolair", "xolai", "omalizumab", "xola1r", "x0lair", "ksolair", "xlair", "xoiair"]', '["ksolair", "x0lair", "xlair", "xo1air", "xoiair", "xol4ir", "xola1r", "xolai"]', 'DKL10000623A1', 'xolair', 'omalizumab');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('omedeson', 'Omedeson', 'Dexamethasone', 'Kortikosteroid', 'Obat Keras (Lingkaran Merah K)', 'Kaplet', 'Meredakan peradangan, reaksi alergi, penyakit autoimun , asma, dan gangguan kulit atau sendi', 'Dosis Omedeson ditentukan oleh dokter berdasarkan kondisi yang ditangani, tingkat keparahan penyakit, serta respons pasien terhadap pengobatan.', '["Omedeson"]', '["omede5on", "omedeso", "omedeson", "dexamethasone", "0medes0n", "om3d3son", "ornedeson", "oedeson"]', '["0medes0n", "oedeson", "om3d3son", "omede5on", "omedeso", "ornedeson"]', 'DKL10000826A1', 'omedeson', 'dexamethasone');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('umeclidinium', 'Umeclidinium', 'Umeclidinium', 'Antikolinergik', 'Obat Keras (Lingkaran Merah K)', 'Inhaler', 'Meredakan gejala penyakit paru obstruktif kronik ( PPOK ), seperti bronkitis kronis atau emfisema', 'Dosis umum penggunaan umeclidunium untuk mengatasi gejala penyakit paru obstruktif kronik (PPOK) adalah sebanyak 1 inhalasi, 1 kali sehari. Obat ini tidak boleh digunakan lebih dari 1 kali dalam sehari.', '["Umeclidinium", "penyakit jantung", "pembesaran prostat", "kesulitan buang air kecil", "asma", "suplemen"]', '["pembesaran prostat", "penyakit jantung", "um3clidinium", "umec1idinium", "umeciidinium", "ueclidinium", "umeclidiniu", "umeclldlnlum", "umeclidinium", "umedidinium", "asma", "umecl1d1n1um", "kesulitan buang air kecil"]', '["ueclidinium", "um3clidinium", "umec1idinium", "umeciidinium", "umecl1d1n1um", "umeclidiniu", "umeclldlnlum", "umedidinium"]', 'DKL10001253A1', 'umeclidinium', 'umeclidinium');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('eficap-sirup', 'Eficap Sirup', 'Sucralfate 500 mg', 'Anti-ulkus', 'Obat Keras (Lingkaran Merah K)', 'Suspensi', 'Mengatasi tukak lambung, ulkus duodenum , atau gastritis kronis.', 'Gunakan sesuai petunjuk dokter atau aturan pakai pada kemasan.', '["Eficap Sirup"]', '["eicap sirup", "efisap sirup", "eficap 5irup", "ef1cap s1rup", "3ficap sirup", "eflcap slrup", "sucralfate 500 mg", "eficap sirup", "efic4p sirup", "eficap siru"]', '["3ficap sirup", "ef1cap s1rup", "efic4p sirup", "eficap 5irup", "eficap siru", "efisap sirup", "eflcap slrup", "eicap sirup"]', 'DKL10001147A1', 'eficapsirup', 'sucralfate500mg');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('sabun-kojie-san', 'Sabun Kojie San', 'Coconut oil, 4% kojic acid dipalmitate, cancaya papaya, ascorbyl palmitate sebagai vitamin C, retinyl palmitate sebagai vitamin A, dan tocopheryl acetate sebagai vitamin E.', 'Produk perawatan kulit Mencerahkan kulit Melembapkan kulit Melindungi kulit dari kerusakan akibat paparan radikal bebas', 'Obat Bebas (Hijau)', 'Sediaan oral/topikal sesuai instruksi kemasan.', 'Mengatasi gangguan kesehatan dan meredakan gejala sesuai petunjuk medis.', 'Gunakan Sabun Kojie San saat mandi untuk membersihkan seluruh tubuh Anda, termasuk area leher, lengan, dan tungkai. Untuk hasil yang lebih optimal, gunakan dua kali sehari dan lanjutkan dengan pelembap setelah mandi.', '["Sabun Kojie San"]', '["sabun kojie sa", "sabun kojle san", "coconut oil, 4% kojic acid dipalmitate, cancaya papaya, ascorbyl palmitate sebagai vitamin c, retinyl palmitate sebagai vitamin a, dan tocopheryl acetate sebagai vitamin e.", "sabun kojie san", "sbun kojie san", "sabun koji3 san", "sabun koj1e san", "s4bun kojie s4n", "sabun k0jie san", "5abun kojie 5an"]', '["5abun kojie 5an", "s4bun kojie s4n", "sabun k0jie san", "sabun koj1e san", "sabun koji3 san", "sabun kojie sa", "sabun kojle san", "sbun kojie san"]', 'DBL10001357A1', 'sabunkojiesan', 'coconutoil4kojicaciddipalmitatecancayapapayaascorbylpalmitatesebagaivitamincretinylpalmitatesebagaivitaminadantocopherylacetatesebagaivitamine');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('acran', 'Acran', 'Ranitidin 150 mg', 'Antagonis H2', 'Obat Keras (Lingkaran Merah K)', 'Tablet salut selaput', 'Menurunkan produksi asam lambung', 'Berikut ini adalah dosis umum penggunaan Acran berdasarkan usia dan kondisi yang ditangani:', '["Acran"]', '["asran", "4cr4n", "ranitidin 150 mg", "acran"]', '["4cr4n", "asran"]', 'DKL10000485A1', 'acran', 'ranitidin150mg');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('kalcinol-n', 'Kalcinol N', 'Kombinasi fluocinolone 0,25 mg dan neomycin 0,5 mg', 'Kombinasi kortikosteroid topikal (fluocinolone) dan antibiotik topikal golongan aminoglikosida (neomycin)', 'Obat Keras (Lingkaran Merah K)', 'Krim', 'Mengatasi dermatitis yang disertai infeksi bakteri', 'Kalcinol N umumnya digunakan dalam pengobatan radang kulit yang disertai infeksi bakteri, termasuk eksim, psoriasis, dan lichen planus. Oleskan krim Kalcinol N secara merata pada area kulit yang perlu diobati, 2–4 kali sehari. Lama pengobatan 5–7 hari atau sesuai petunjuk dokter.', '["Kalcinol N"]', '["kalclnol n", "kombinasi fluocinolone 0,25 mg dan neomycin 0,5 mg", "kalcinol n", "ka1cino1 n", "k4lcinol n", "kalc1nol n", "kalcinol ", "kaicinoi n", "kalsinol n", "kalcin0l n"]', '["k4lcinol n", "ka1cino1 n", "kaicinoi n", "kalc1nol n", "kalcin0l n", "kalcinol ", "kalclnol n", "kalsinol n"]', 'DKL10000923A1', 'kalcinoln', 'kombinasifluocinolone025mgdanneomycin05mg');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('maprotiline', 'Maprotiline', 'Maprotiline', 'Antidepresan golongan trisiklik', 'Obat Keras (Lingkaran Merah K)', 'Tablet salut selaput', 'Mengatasi depresi', 'Berikut adalah dosis maprotiline untuk mengobati depresi ringan hingga berat:', '["Maprotiline", "Maprotiline HCl", "Tilsan", "penyakit liver", "glaukoma", "diabetes"]', '["penyakit liver", "maprotiiine", "maprotlllne", "glaukoma", "maprot1l1ne", "m4protiline", "maprotilin3", "maprotilin", "tilsan", "mapr0tiline", "maproti1ine", "maprotiline", "maprotiline hcl"]', '["m4protiline", "mapr0tiline", "maprot1l1ne", "maproti1ine", "maprotiiine", "maprotilin", "maprotilin3", "maprotlllne"]', 'DKL10001156A1', 'maprotiline', 'maprotiline');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('gastrofer', 'Gastrofer', 'Omeprazole', 'Penghambat pompa proton', 'Obat Keras (Lingkaran Merah K)', 'Kapsul lepas tunda dan suntik', 'Mengurangi produksi asam lambung', 'Berikut ini adalah dosis umum penggunaan Gastrofer berdasarkan bentuk obat dan kondisi pasien:', '["Gastrofer"]', '["g4strofer", "gastrofer", "ga5trofer", "gastrof3r", "gstrofer", "gastropher", "gastrofe", "gastr0fer", "omeprazole"]', '["g4strofer", "ga5trofer", "gastr0fer", "gastrof3r", "gastrofe", "gastropher", "gstrofer"]', 'DKL10000941A1', 'gastrofer', 'omeprazole');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('kaflam', 'Kaflam', 'Diclofenac potassium', 'Obat anti inflamasi nonsteroid (OAINS)', 'Obat Keras (Lingkaran Merah K)', 'Tablet salut selaput', 'Mengatasi gejala peradangan, seperti nyeri dan bengkak, pada kondisi sakit gigi, kram menstruasi, migrain , serta nyeri sendi dan nyeri otot karena rheumatoid arthritis dan osteoarthritis', 'Dokter akan memberitahu dosis Kaflam ketika memberikan e-resep saat pasien berkonsultasi. Dosis akan disesuaikan dengan tujuan pengobatan, usia, dan respons pasien terhadap pengobatan.', '["Kaflam"]', '["kaflarn", "diclofenac potassium", "k4fl4m", "kafla", "kaflam", "kflam", "kaphlam", "kafiam", "kaf1am"]', '["k4fl4m", "kaf1am", "kafiam", "kafla", "kaflarn", "kaphlam", "kflam"]', 'DKL10000588A1', 'kaflam', 'diclofenacpotassium');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('alclometasone', 'Alclometasone', 'Alclometasone', 'Kortikosteroid topikal', 'Obat Keras (Lingkaran Merah K)', 'Krim', 'Meredakan peradangan pada kulit, misalnya akibat dermatitis kontak , reaksi alergi, eksim , psoriasis , atau gigitan serangga .', 'Oleskan krim alclometasone tipis-tipis pada area kulit yang mengalami peradangan, 2–3 kali sehari sesuai kebutuhan. Lama pengobatan dengan alclometasone adalah sampai 7 hari. Pengobatan yang lebih dari 7 hari harus dengan pengawasan dokter.', '["Alclometasone", "misalnya akibat dermatitis kontak", "reaksi alergi", "eksim", "psoriasis", "gangguan sistem imun"]', '["alclometa5one", "alcl0metas0ne", "aclometasone", "eksim", "4lclomet4sone", "reaksi alergi", "a1c1ometasone", "aiciometasone", "alclom3tason3", "misalnya akibat dermatitis kontak", "psoriasis", "alclometasone", "alclometason"]', '["4lclomet4sone", "a1c1ometasone", "aclometasone", "aiciometasone", "alcl0metas0ne", "alclom3tason3", "alclometa5one", "alclometason"]', 'DKL10001351A1', 'alclometasone', 'alclometasone');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('maoi', 'MAOI', 'MAOI', 'Pengobatan Umum', 'Obat Keras (Lingkaran Merah K)', 'Sediaan oral/topikal sesuai instruksi kemasan.', 'Mengatasi gangguan kesehatan dan meredakan gejala sesuai petunjuk medis.', 'Berikut adalah jenis-jenis obat yang termasuk dalam golongan MAOI, berserta merek dagang, bentuk sediaan, dan dosis sesuai dengan kondisi serta usia pasien:', '["MAOI", "yang dapat ditandai dengan kegelisahan", "demam tinggi", "keringat berlebih", "jantung berdebar", "dan kehilangan koordinasi tubuh Jenis"]', '["jantung berdebar", "ma0i", "rnaoi", "demam tinggi", "mao1", "maol", "yang dapat ditandai dengan kegelisahan", "m4oi", "maoi", "keringat berlebih"]', '["m4oi", "ma0i", "mao1", "maol", "rnaoi"]', 'DKL10000294A1', 'maoi', 'maoi');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('xonce', 'Xonce', 'Vitamin C', 'Suplemen vitamin', 'Obat Bebas (Hijau)', 'Tablet', 'Mencegah dan mengatasi kekurangan vitamin C', 'Dosis dan aturan pakai Xonce ditentukan oleh dokter berdasarkan kondisi pasien. Secara umum, Xonce diminum 1 tablet sehari.', '["Xonce"]', '["ksonce", "xonse", "x0nce", "xonc3", "xonce", "vitamin c"]', '["ksonce", "x0nce", "xonc3", "xonse"]', 'DBL10000509A1', 'xonce', 'vitaminc');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('efisol-c', 'Efisol C', 'Dequalinium chloride 0,25 mg', 'Antiseptik mulut dan tenggorokan', 'Obat Bebas (Hijau)', 'Tablet isap', 'Mengatasi infeksi ringan pada rongga mulut dan tenggorokan yang disebabkan oleh bakteri atau jamur', 'Dosis Efisol C untuk mengatasi infeksi ringan pada rongga mulut dan tenggorokan adalah 1 tablet isap, setiap 3 jam. Dosis bisa dikurangi menjadi 1 tablet, setiap 5 jam, jika gejala infeksi dan radang di tenggorokan atau rongga mulut sudah membaik. Dosis maksimal 8 tablet isap per hari.', '["Efisol C"]', '["efisol c", "efi5ol c", "efis0l c", "efisol s", "dequalinium chloride 0,25 mg", "ef1sol c", "efiso1 c", "3fisol c", "efisol ", "efisoi c"]', '["3fisol c", "ef1sol c", "efi5ol c", "efis0l c", "efiso1 c", "efisoi c", "efisol ", "efisol s"]', 'DBL10000709A1', 'efisolc', 'dequaliniumchloride025mg');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('alco-flu', 'Alco Flu', 'Pseudoephedrine HCl 30 mg dan brompheniramine maleate 2 mg', 'Kombinasi antihistamin (brompheniramine) dan dekongestan (pseudoephedrine HCl)', 'Obat Bebas Terbatas (Lingkaran Biru)', 'Sirop', 'Mengatasi gejala flu berupa hidung tersumbat, hidung meler, bersin-bersin, serta gejala alergi pada saluran pernapasan atas.', 'Untuk membantu meredakan gejala flu dan alergi, Alco Flu dapat digunakan dengan dosis berikut:', '["Alco Flu"]', '["also flu", "alco fl", "pseudoephedrine hcl 30 mg dan brompheniramine maleate 2 mg", "alc0 flu", "alco phlu", "aco flu", "a1co f1u", "alco flu", "4lco flu", "aico fiu"]', '["4lco flu", "a1co f1u", "aco flu", "aico fiu", "alc0 flu", "alco fl", "alco phlu", "also flu"]', 'DTL10000710A1', 'alcoflu', 'pseudoephedrinehcl30mgdanbrompheniraminemaleate2mg');
