INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('kaldifen', 'Kaldifen', 'Diclofenac 50 mg', 'Obat antiinflamasi nonsteroid ( OAINS )', 'Obat Keras (Lingkaran Merah K)', 'Tablet', 'Meringankan nyeri ringan hingga sedang, termasuk: Nyeri sendi akibat radang sendi Nyeri akibat terkilir atau cedera Nyeri pascaoperasi Migrain', 'Berdasarkan kandungannya, dosis Kaldifen untuk meredakan nyeri ringan hingga sedang adalah 50 mg, 3 kali sehari. Dosis maksimal adalah 150 mg per hari.', '["Kaldifen"]', '["kaldifen", "kaldif3n", "diclofenac 50 mg", "kaidifen", "kaldlfen", "kaldife", "kaldiphen", "k4ldifen", "kald1fen", "ka1difen"]', '["k4ldifen", "ka1difen", "kaidifen", "kald1fen", "kaldif3n", "kaldife", "kaldiphen", "kaldlfen"]', 'DKL10000798A1', 'kaldifen', 'diclofenac50mg');
