INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('actacort', 'Actacort', 'Budesonide', 'Kortikosteroid', 'Obat Keras (Lingkaran Merah K)', 'Suspensi inhalasi', 'Mengendalikan peradangan saluran napas (asma, PPOK )', 'Dosis Actacort ditentukan oleh dokter berdasarkan usia, tingkat keparahan penyakit, serta respons pasien terhadap terapi. Gunakan dosis terendah yang efektif untuk mengendalikan gejala.', '["Actacort"]', '["actacort", "4ct4cort", "budesonide", "atacort", "astasort", "actac0rt", "actacor"]', '["4ct4cort", "actac0rt", "actacor", "astasort", "atacort"]', 'DKL10000817A1', 'actacort', 'budesonide');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('alofar', 'Alofar', 'Allopurinol', 'Penghambat xanthine-oxidase', 'Obat Keras (Lingkaran Merah K)', 'Kaplet', 'Menurunkan kadar asam urat tinggi dalam darah', 'Dosis Alofar yang diresepkan oleh dokter dapat berbeda-beda pada tiap pasien. Berikut ini adalah dosis umum penggunaan Alofar berdasarkan kondisi pasien:', '["Alofar"]', '["al0far", "4lof4r", "alofa", "allopurinol", "aofar", "a1ofar", "aiofar", "alofar", "alophar"]', '["4lof4r", "a1ofar", "aiofar", "al0far", "alofa", "alophar", "aofar"]', 'DKL10000597A1', 'alofar', 'allopurinol');
