INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('matrovir', 'Matrovir', 'Acyclovir', 'Obat antivirus', 'Obat Keras (Lingkaran Merah K)', 'Tablet', 'Menangani infeksi virus herpes, seperti cacar air, herpes genital , atau cacar ular (herpes zoster)', 'Dosis Matrovir yang diberikan oleh dokter dapat berbeda, tergantung pada usia dan kondisi yang ditangani. Berikut adalah rekomendasi dosis acyclovir dalam Matrovir tablet:', '["Matrovir"]', '["matrovi", "matr0vir", "matrovlr", "m4trovir", "matrov1r", "matrovir", "acyclovir", "rnatrovir", "mtrovir"]', '["m4trovir", "matr0vir", "matrov1r", "matrovi", "matrovlr", "mtrovir", "rnatrovir"]', 'DKL10000852A1', 'matrovir', 'acyclovir');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('sagestam', 'Sagestam', 'Gentamicin 3 mg per 1 ml', 'Antibiotik golongan aminoglikosida', 'Obat Keras (Lingkaran Merah K)', 'Tetes mata atau telinga', 'Mengobati infeksi mata yang disebabkan oleh bakteri', 'Dosis Sagestam untuk mengobati infeksi mata karena bakteri adalah 1–2 tetes pada mata yang sakit tiap 4 jam, atau tiap 1 jam untuk mengatasi infeksi mata yang parah. Frekuensi pemakaian obat bisa dikurangi secara bertahap ketika infeksi mata mulai membaik.', '["Sagestam"]', '["s4gest4m", "gentamicin 3 mg per 1 ml", "sagesta", "5age5tam", "sgestam", "sagestarn", "sag3stam", "sagestam"]', '["5age5tam", "s4gest4m", "sag3stam", "sagesta", "sagestarn", "sgestam"]', 'DKL10000821A1', 'sagestam', 'gentamicin3mgper1ml');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('xyzal', 'Xyzal', 'Levocetirizine', 'Antihistamin', 'Obat Keras (Lingkaran Merah K)', 'Kaplet salut selaput', 'Meredakan gejala alergi', 'Berdasarkan kandungannya, berikut adalah dosis Xyzal untuk mengatasi gejala alergi:', '["Xyzal"]', '["xysal", "ksyzal", "levocetirizine", "xyzal", "xyz4l", "xyza1", "xyzai"]', '["ksyzal", "xysal", "xyz4l", "xyza1", "xyzai"]', 'DKL10000536A1', 'xyzal', 'levocetirizine');
