INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('undecylenic-acid', 'Undecylenic Acid', 'Undecylenic Acid', 'Obat antijamur', 'Obat Bebas (Hijau)', 'Krim', 'Mengobati infeksi jamur kulit', 'Untuk mengobati kutu air (tinea pedis), kurap badan (tinea corporis), atau kurap selangkangan (tinea cruris), oleskan undecylenic acid ke area kulit yang bermasalah, 2 kali sehari selama masih ada keluhan, hingga 2 minggu setelah keluhan menghilang.', '["Undecylenic Acid", "kurap badan tinea corporis", "atau kurap selangkangan tinea cruris", "bila infeksi memburuk atau mengganggu", "seperti undecylenic acid", "seperti perih dan kemerahan"]', '["atau kurap selangkangan tinea cruris", "udecylenic acid", "undecy1enic acid", "kurap badan tinea corporis", "undecylenlc acld", "undecylenic 4cid", "und3cyl3nic acid", "bila infeksi memburuk atau mengganggu", "undecylen1c ac1d", "undecylenic aci", "2 kali sehari selama masih ada keluhan", "undecylenic acid", "undecyienic acid"]', '["udecylenic acid", "und3cyl3nic acid", "undecy1enic acid", "undecyienic acid", "undecylen1c ac1d", "undecylenic 4cid", "undecylenic aci", "undecylenlc acld"]', 'DBL10001540A1', 'undecylenicacid', 'undecylenicacid');
