INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('yafix', 'Yafix', 'Cefixime', 'Antibiotik golongan sefalosporin', 'Obat Keras (Lingkaran Merah K)', 'Sirop kering', 'Mengobati infeksi bakteri', 'Dosis Yafix berbeda-beda, sesuai dengan kondisi, tingkat keparahan infeksi, usia dan berat badan pasien. Berikut rincian dosisnya:', '["Yafix"]', '["y4fix", "cefixime", "yafiks", "yafix", "yaphix", "yaflx", "yaf1x"]', '["y4fix", "yaf1x", "yafiks", "yaflx", "yaphix"]', 'DKL10000513A1', 'yafix', 'cefixime');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('actifed', 'Actifed', 'Actifed', 'Dekongestan dan antihistamin', 'Obat Bebas Terbatas (Lingkaran Biru)', 'Sirop', 'Meringankan gejala flu, batuk pilek, dan alergi.', 'Dosis Actifed tergantung pada jenis produk, kondisi, dan usia pasien. Secara umum, berikut adalah dosis Actifed untuk meringankan gejala flu, pilek, batuk, dan alergi:', '["Actifed"]', '["astifed", "act1fed", "actif3d", "actife", "4ctifed", "actiphed", "actlfed", "atifed", "actifed"]', '["4ctifed", "act1fed", "actif3d", "actife", "actiphed", "actlfed", "astifed", "atifed"]', 'DTL10000688A1', 'actifed', 'actifed');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('alectinib', 'Alectinib', 'Alectinib', 'Penghambat ALK', 'Obat Keras (Lingkaran Merah K)', 'Kapsul', 'Menangani kanker paru jenis non-small cell dengan ALK positif', 'Dosis alectinib adalah 600 mg yang diminum 2 kali sehari. Dosis dapat dikurangi, ditunda sementara, atau dihentikan jika kondisi memburuk atau terjadi efek samping yang berat.', '["Alectinib"]', '["alectinib", "alectlnlb", "alectini", "alect1n1b", "4lectinib", "aectinib", "a1ectinib", "al3ctinib", "aiectinib"]', '["4lectinib", "a1ectinib", "aectinib", "aiectinib", "al3ctinib", "alect1n1b", "alectini", "alectlnlb"]', 'DKL10000907A1', 'alectinib', 'alectinib');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('gavistal', 'Gavistal', 'Metoclopramide', 'Obat antiemetik', 'Obat Keras (Lingkaran Merah K)', 'Tablet dan drops (tetes)', 'Menghentikan mual dan muntah akibat gangguan pencernaan, seperti penyakit asam lambung (GERD)', 'Berikut ini adalah rekomendasi dosis metoclopramide pada Gavistal berdasarkan tujuan penggunaanya:', '["Gavistal"]', '["metoclopramide", "gav1stal", "g4vist4l", "gavista1", "gavlstal", "gavista", "gvistal", "gavistai", "gavi5tal", "gavistal"]', '["g4vist4l", "gav1stal", "gavi5tal", "gavista", "gavista1", "gavistai", "gavlstal", "gvistal"]', 'DKL10000827A1', 'gavistal', 'metoclopramide');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('unidine', 'Unidine', 'Povidone iodine', 'Antiseptik kulit', 'Obat Bebas Terbatas (Lingkaran Biru)', 'Cairan antiseptik', 'Membersihkan luka dan membantu mencegah infeksi pada luka ringan.', 'Gunakan Unidine sesuai petunjuk pada kemasan atau anjuran dokter. Secara umum, Unidine dioleskan pada area kulit yang luka atau perlu dibersihkan 1–3 kali sehari. Gunakan obat secukupnya dan hindari penggunaan berlebihan.', '["Unidine"]', '["uidine", "unidin", "unldlne", "unidine", "povidone iodine", "un1d1ne", "unidin3"]', '["uidine", "un1d1ne", "unidin", "unidin3", "unldlne"]', 'DTL10000716A1', 'unidine', 'povidoneiodine');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('palbonat', 'Palbonat', 'Palbociclib', 'Terapi target untuk kanker', 'Obat Keras (Lingkaran Merah K)', 'Kapsul', 'Pengobatan kanker payudara stadium lanjut atau yang sudah menyebar (metastasis)', 'Dosis Palbonat bisa berbeda pada tiap orang, tergantung jenis gangguan yang dialami dan seberapa parah kondisinya. Secara umum, dosisnya adalah sebagai berikut:', '["Palbonat"]', '["palb0nat", "palbociclib", "pa1bonat", "palbonat", "palbona", "p4lbon4t", "plbonat", "paibonat"]', '["p4lbon4t", "pa1bonat", "paibonat", "palb0nat", "palbona", "plbonat"]', 'DKL10000817A1', 'palbonat', 'palbociclib');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('efomet-xr', 'Efomet XR', 'Metformin', 'Antidiabetes golongan biguanide', 'Obat Keras (Lingkaran Merah K)', 'Tablet pelepasan lambat', 'Mengontrol kadar gula darah pada penderita diabetes tipe 2', 'Dalam pengobatan diabetes tipe 2, Efomet XR bisa digunakan sebagai obat tunggal atau dikombinasikan dengan obat lain yang tergolong antidiabetes, termasuk insulin suntik.', '["Efomet XR"]', '["eomet xr", "ef0met xr", "3fom3t xr", "efomet ksr", "efomet xr", "efornet xr", "metformin", "efomet x", "ephomet xr"]', '["3fom3t xr", "ef0met xr", "efomet ksr", "efomet x", "efornet xr", "eomet xr", "ephomet xr"]', 'DKL10000810A1', 'efometxr', 'metformin');
