INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('actifed-hijau', 'Actifed Hijau', 'Pseudoephedrine HCL, triprolidine , dan guaifenesin', 'Kombinasi dekongestan , antihistamin , dan dekongestan', 'Obat Bebas Terbatas (Lingkaran Biru)', 'Sirop', 'Meredakan gejala pilek dan batuk berdahak', 'Dosis konsumsi Actifed Hijau sudah tercantum dalam kemasan dan Anda bisa berkonsultasi dengan dokter untuk mendapatkan dosis yang tepat. Dosis umum pemberian obat ini berdasarkan usia, yaitu:', '["Actifed Hijau"]', '["pseudoephedrine hcl, triprolidine , dan guaifenesin", "actifed hija", "actiphed hijau", "actifed hijau", "act1fed h1jau", "actif3d hijau", "atifed hijau", "actlfed hljau", "astifed hijau", "4ctifed hij4u"]', '["4ctifed hij4u", "act1fed h1jau", "actif3d hijau", "actifed hija", "actiphed hijau", "actlfed hljau", "astifed hijau", "atifed hijau"]', 'DTL10001217A1', 'actifedhijau', 'pseudoephedrinehcltriprolidinedanguaifenesin');
