INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('gefitero', 'Gefitero', 'Gefitinib', 'Obat antikanker golongan penghambat protein kinase', 'Obat Keras (Lingkaran Merah K)', 'Tablet salut selaput', 'Mengobati kanker paru-paru jenis non-small cell lung cancer (NSCLC)', 'Dokter akan menyesuaikan dosis dan lama pengobatan Gefitero berdasarkan kondisi kesehatan Anda. Secara umum, untuk pengobatan kanker paru-paru, dosis standar gefitinib dalam Gefitero adalah 250 mg sekali sehari.', '["Gefitero"]', '["gefitero", "gef1tero", "gefiter0", "gefiter", "gephitero", "gefitinib", "gfitero", "g3fit3ro", "gefltero"]', '["g3fit3ro", "gef1tero", "gefiter", "gefiter0", "gefltero", "gephitero", "gfitero"]', 'DKL10000821A1', 'gefitero', 'gefitinib');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('ekacetol', 'Ekacetol', 'Paracetamol', 'Analgetik-antipiretik', 'Obat Bebas (Hijau)', 'Kaplet dan sirop', 'Meredakan nyeri', 'Berikut adalah dosis umum penggunaan Ekacetol untuk meredakan demam dan nyeri berdasarkan usia pasien:', '["Ekacetol"]', '["ekacetol", "ek4cetol", "ekaceto1", "ekaceto", "ekasetol", "ekacet0l", "3kac3tol", "ekacetoi", "eacetol", "paracetamol"]', '["3kac3tol", "eacetol", "ek4cetol", "ekacet0l", "ekaceto", "ekaceto1", "ekacetoi", "ekasetol"]', 'DBL10000808A1', 'ekacetol', 'paracetamol');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('paliperidone', 'Paliperidone', 'Paliperidone', 'Antipsikotik', 'Obat Keras (Lingkaran Merah K)', 'Tablet lepas lambat, cairan suntik', 'Meredakan gejala skizofrenia dan gejala skizoafektif', 'Dosis paliperidone yang diberikan dokter bisa berbeda, tergantung pada bentuk obat, kondisi yang ditangani, dan usia pasien. Pada kondisi tertentu, dosis paliperidone untuk anak-anak disesuaikan dengan berat badan (BB) pasien. Berikut adalah rinciannya:', '["Paliperidone", "Invega", "Invega Trinza", "penyakit liver", "penyakit Parkinson", "glaukoma"]', '["p4liperidone", "paliperidon", "paliperidone", "invega", "penyakit liver", "pal1per1done", "penyakit parkinson", "pallperldone", "paliperid0ne", "palip3ridon3", "paiiperidone", "pa1iperidone", "invega trinza"]', '["p4liperidone", "pa1iperidone", "paiiperidone", "pal1per1done", "palip3ridon3", "paliperid0ne", "paliperidon", "pallperldone"]', 'DKL10001244A1', 'paliperidone', 'paliperidone');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('salbron-ekspektoran', 'Salbron Ekspektoran', 'Salbutamol dan guaifenesin', 'Kombinasi bronkodilator ( beta-2-agonist dengan reaksi cepat) dan ekspektoran (pengencer dahak)', 'Obat Keras (Lingkaran Merah K)', 'Sirop', 'Meredakan sesak napas, mengi, atau batuk berdahak akibat asma, bronkitis kronis, emfisema, dan penyakit paru obstruktif kronis', 'Dosis Salbron Ekspektoran akan disesuaikan dengan kondisi dan usia pasien. Berikut adalah takaran umum penggunaan Salbron Ekspektoran.', '["Salbron Ekspektoran"]', '["saibron ekspektoran", "5albron ek5pektoran", "salbron 3ksp3ktoran", "sa1bron ekspektoran", "slbron ekspektoran", "salbron ekspektora", "salbutamol dan guaifenesin", "salbr0n ekspekt0ran", "salbron ekspektoran", "s4lbron ekspektor4n"]', '["5albron ek5pektoran", "s4lbron ekspektor4n", "sa1bron ekspektoran", "saibron ekspektoran", "salbr0n ekspekt0ran", "salbron 3ksp3ktoran", "salbron ekspektora", "slbron ekspektoran"]', 'DKL10001912A1', 'salbronekspektoran', 'salbutamoldanguaifenesin');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('palenox', 'Palenox', 'Adapalene 0,1%', 'Obat resep', 'Obat Keras (Lingkaran Merah K)', 'Gel', 'Mengatasi jerawat ( acne vulgaris )', 'Untuk mengatasi jerawat ringan hingga sedang, oleskan Palenox tipis-tipis dan merata 1 kali sehari di bagian kulit yang berjerawat pada malam hari.', '["Palenox"]', '["palenox", "pa1enox", "paienox", "pal3nox", "palen0x", "palenoks", "paleno", "plenox", "p4lenox", "adapalene 0,1%"]', '["p4lenox", "pa1enox", "paienox", "pal3nox", "palen0x", "paleno", "palenoks", "plenox"]', 'DKL10000727A1', 'palenox', 'adapalene01');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('kalmethasone', 'Kalmethasone', 'Dexamethasone', 'Kortikosteroid', 'Obat Keras (Lingkaran Merah K)', 'Tablet', 'Meredakan peradangan', 'Dosis Kalmethasone akan disesuaikan oleh dokter dengan kondisi dan usia pasien. Berikut adalah penjelasannya:', '["Kalmethasone"]', '["kalmethasone", "k4lmeth4sone", "kaimethasone", "kalmethason", "kalmetasone", "kalm3thason3", "dexamethasone", "kalmethas0ne", "kalmetha5one", "ka1methasone"]', '["k4lmeth4sone", "ka1methasone", "kaimethasone", "kalm3thason3", "kalmetasone", "kalmetha5one", "kalmethas0ne", "kalmethason"]', 'DKL10001244A1', 'kalmethasone', 'dexamethasone');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('actifed-kuning', 'Actifed Kuning', 'Pseudoephedrine dan triprolidine', 'Kombinasi dekongestan dan antihistamin', 'Obat Bebas Terbatas (Lingkaran Biru)', 'Sirop', 'Meredakan gejala batuk pilik, flu, dan rhinitis alergi', 'Dosis minum Actifed telah tercantum dalam kemasan, tetapi Anda bisa berkonsultasi dengan dokter terlebih dahulu melalui Chat Bersama Dokter untuk mendapatkan dosis yang tepat.', '["Actifed Kuning"]', '["atifed kuning", "4ctifed kuning", "astifed kuning", "actif3d kuning", "act1fed kun1ng", "actiphed kuning", "actifed kuning", "actifed kunin", "pseudoephedrine dan triprolidine", "actlfed kunlng"]', '["4ctifed kuning", "act1fed kun1ng", "actif3d kuning", "actifed kunin", "actiphed kuning", "actlfed kunlng", "astifed kuning", "atifed kuning"]', 'DTL10001340A1', 'actifedkuning', 'pseudoephedrinedantriprolidine');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('unisia', 'Unisia', 'Amlodipine 5 mg dan candesartan 8 mg', 'Antagonis kalsium dan angiotensin II receptor blocke r (ARB)', 'Obat Keras (Lingkaran Merah K)', 'Tablet', 'Mengatasi tekanan darah tinggi', 'Berikut ini adalah dosis umum penggunaan Unisia untuk mengatasi hipertensi:', '["Unisia"]', '["amlodipine 5 mg dan candesartan 8 mg", "unisi4", "uni5ia", "unlsla", "unisia", "unisi", "un1s1a", "uisia"]', '["uisia", "un1s1a", "uni5ia", "unisi", "unisi4", "unlsla"]', 'DKL10000617A1', 'unisia', 'amlodipine5mgdancandesartan8mg');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('gefitinib', 'Gefitinib', 'Gefitinib', 'Obat antikanker golongan penghambat protein kinase', 'Obat Keras (Lingkaran Merah K)', 'Tablet', 'Mengobati kanker paru-paru jenis non-small cell lung cancer (NSCLC)', 'Dokter akan menentukan dosis dan durasi pengobatan dengan gefitinib sesuai kondisi pasien. Secara umum, dosis gefitinib untuk mengobati kanker paru-paru adalah 250 mg, 1 kali sehari.', '["Gefitinib", "Gefitero", "Gefiza", "Genessa", "Gefinib", "Iressa"]', '["gefitero", "gefiza", "g3fitinib", "gefltlnlb", "gefitinib", "genessa", "gefinib", "gef1t1n1b", "gfitinib", "gephitinib", "gefitini"]', '["g3fitinib", "gef1t1n1b", "gefitini", "gefltlnlb", "gephitinib", "gfitinib"]', 'DKL10000913A1', 'gefitinib', 'gefitinib');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('ekacetol-forte', 'Ekacetol Forte', 'Paracetamol', 'Analgetik-antipiretik', 'Obat Bebas (Hijau)', 'Kaplet', 'Meredakan nyeri', 'Berikut adalah dosis umum penggunaan Ekacetol Forte untuk meredakan demam dan nyeri:', '["Ekacetol Forte"]', '["ekacetol forte", "ekacetol fort", "3kac3tol fort3", "ekacet0l f0rte", "ekaceto1 forte", "ek4cetol forte", "ekacetol phorte", "ekacetoi forte", "eacetol forte", "paracetamol"]', '["3kac3tol fort3", "eacetol forte", "ek4cetol forte", "ekacet0l f0rte", "ekaceto1 forte", "ekacetoi forte", "ekacetol fort", "ekacetol phorte"]', 'DBL10001352A1', 'ekacetolforte', 'paracetamol');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('kalmicetine', 'Kalmicetine', 'Chloramphenicol', 'Antibiotik', 'Obat Keras (Lingkaran Merah K)', 'Kapsul', 'Mengatasi infeksi bakteri', 'Agar pengobatan infeksi berjalan efektif, dosis Kalmicetine perlu disesuaikan dengan kondisi masing-masing pasien. Dokter akan menentukan jumlah obat berdasarkan usia, berat badan, hingga tingkat keparahan penyakit. Simak rekomendasi umum dosis Kalmicetine berikut ini:', '["Kalmicetine"]', '["k4lmicetine", "ka1micetine", "kalmic3tin3", "kaimicetine", "kalmicetin", "kalmicetine", "kalm1cet1ne", "chloramphenicol", "kalmisetine", "kalmlcetlne"]', '["k4lmicetine", "ka1micetine", "kaimicetine", "kalm1cet1ne", "kalmic3tin3", "kalmicetin", "kalmisetine", "kalmlcetlne"]', 'DKL10001126A1', 'kalmicetine', 'chloramphenicol');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('alegysal', 'Alegysal', 'Pemirolast', 'Antihistamin', 'Obat Keras (Lingkaran Merah K)', 'Tetes mata', 'Mengatasi gejala alergi pada mata', 'Dosis umum pemakaian Alegysal adalah sebanyak 1 tetes, 2 kali sehari pada pagi dan sore hari.', '["Alegysal"]', '["4legys4l", "pemirolast", "al3gysal", "alegy5al", "alegysal", "aiegysai", "alegysa", "aegysal", "a1egysa1"]', '["4legys4l", "a1egysa1", "aegysal", "aiegysai", "al3gysal", "alegy5al", "alegysa"]', 'DKL10000818A1', 'alegysal', 'pemirolast');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('yalone', 'Yalone', 'Methylprednisolone', 'Kortikosteroid', 'Obat Keras (Lingkaran Merah K)', 'Tablet', 'Mengurangi peradangan', 'Dosis Yalone bisa berbeda-beda untuk setiap orang. Dokter akan menyesuaikannya berdasarkan kondisi kesehatan Anda dan bagaimana tubuh merespons pengobatan. Berikut ini adalah rekomendasi dosis methylprednisolone yang terdapat dalam Yalone:', '["Yalone"]', '["ya1one", "yalone", "yal0ne", "methylprednisolone", "yaione", "yalon3", "ylone", "yalon", "y4lone"]', '["y4lone", "ya1one", "yaione", "yal0ne", "yalon", "yalon3", "ylone"]', 'DKL10000616A1', 'yalone', 'methylprednisolone');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('maxgenta', 'Maxgenta', 'Kombinasi betametason dan gentamicin', 'Kombinasi kortikosteroid topikal dan antibiotik topikal dari golongan aminoglikosida', 'Obat Keras (Lingkaran Merah K)', 'Krim', 'Mengatasi peradangan atau infeksi bakteri pada kulit', 'Penggunaan Maxgenta harus sesuai petunjuk dokter, karena dosisnya bisa berbeda tergantung kondisi kulit. Secara umum, Maxgenta dapat dioleskan tipis-tipis pada area kulit yang bermasalah sebanyak 2–3 kali sehari.', '["Maxgenta"]', '["maxg3nta", "mxgenta", "maxgent", "maxgenta", "kombinasi betametason dan gentamicin", "maksgenta", "rnaxgenta", "m4xgent4"]', '["m4xgent4", "maksgenta", "maxg3nta", "maxgent", "mxgenta", "rnaxgenta"]', 'DKL10000821A1', 'maxgenta', 'kombinasibetametasondangentamicin');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('salbugen', 'Salbugen', 'Salbutamol', 'Bronkodilator ( beta-2-agonist dengan reaksi cepat)', 'Obat Keras (Lingkaran Merah K)', 'Tablet dan sirop', 'Mengurangi batuk, sesak napas, dan mengi , akibat serangan asma, bronkitis kronis, dan emfisema', 'Berikut ini adalah dosis Salbugen untuk meredakan gejala penyempitan saluran pernapasan:', '["Salbugen"]', '["5albugen", "salbugen", "s4lbugen", "slbugen", "saibugen", "salbuge", "sa1bugen", "salbug3n", "salbutamol"]', '["5albugen", "s4lbugen", "sa1bugen", "saibugen", "salbug3n", "salbuge", "slbugen"]', 'DKL10000817A1', 'salbugen', 'salbutamol');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('palonosetron', 'Palonosetron', 'Palonosetron', 'Antiemetik', 'Obat Bebas (Hijau)', 'Kapsul dan suntik', 'Mencegah mual dan muntah akibat kemoterapi atau operasi', 'Berikut adalah dosis palonosetron untuk mencegah mual dan muntah berdasarkan tujuan pengobatan dan bentuk obatnya:', '["Palonosetron"]', '["pa1onosetron", "palonosetron", "plonosetron", "paionosetron", "palonosetro", "palonos3tron", "pal0n0setr0n", "p4lonosetron", "palono5etron"]', '["p4lonosetron", "pa1onosetron", "paionosetron", "pal0n0setr0n", "palono5etron", "palonos3tron", "palonosetro", "plonosetron"]', 'DBL10001284A1', 'palonosetron', 'palonosetron');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('uperio', 'Uperio', 'Sacubitril dan valsartan', 'Obat antihipertensi', 'Obat Keras (Lingkaran Merah K)', 'Tablet', 'Mengobati gagal jantung', 'Dosis Uperio yang diberikan dokter dapat berbeda, tergantung pada kondisi kesehatan dan respons tubuh pasien terhadap pengobatan. Dosis awal Uperio adalah 100 mg, 2 kali sehari. Dosis dapat ditingkatkan setelah 2–4 minggu. Untuk dosis pemeliharaan, minumlah obat ini 200 mg, 2 kali sehari.', '["Uperio"]', '["uerio", "uper1o", "sacubitril dan valsartan", "uperi", "uperlo", "up3rio", "uperi0", "uperio"]', '["uerio", "up3rio", "uper1o", "uperi", "uperi0", "uperlo"]', 'DKL10000628A1', 'uperio', 'sacubitrildanvalsartan');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('alena', 'Alena', 'Estazolam', 'Obat penenang golongan benzodiazepine', 'Obat Keras (Lingkaran Merah K)', 'Sediaan oral/topikal sesuai instruksi kemasan.', 'Mengatasi insomnia', 'Alena hanya boleh digunakan dalam jangka pendek, sekitar 1–2 minggu. Berikut ini adalah dosis umum Alena untuk mengatasi insomnia:', '["Alena"]', '["al3na", "a1ena", "alena", "aiena", "estazolam", "4len4"]', '["4len4", "a1ena", "aiena", "al3na"]', 'DKL10000481A1', 'alena', 'estazolam');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('yaricef', 'Yaricef', 'Cefadroxil', 'Antibiotik sefalosporin', 'Obat Keras (Lingkaran Merah K)', 'Kapsul', 'Mengobati infeksi bakteri', 'Dosis dan durasi penggunaan Yaricef akan ditentukan oleh dokter sesuai dengan kondisi yang ditangani.', '["Yaricef"]', '["cefadroxil", "yricef", "yarice", "yarlcef", "yar1cef", "yarisef", "yaricef", "yariceph", "yaric3f", "y4ricef"]', '["y4ricef", "yar1cef", "yaric3f", "yarice", "yariceph", "yarisef", "yarlcef", "yricef"]', 'DKL10000707A1', 'yaricef', 'cefadroxil');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('ekspektoran', 'Ekspektoran', 'Ekspektoran', 'Pengobatan Umum', 'Obat Keras (Lingkaran Merah K)', 'Sediaan oral/topikal sesuai instruksi kemasan.', 'Mengatasi gangguan kesehatan dan meredakan gejala sesuai petunjuk medis.', 'Berikut adalah beberapa jenis obat yang termasuk dalam golongan ekspektoran, beserta merek dagang dan dosisnya:', '["Ekspektoran", "Anakonidin", "Actifed Plus Expectorant", "Benadryl Wet Cough", "Bisolvon Extra", "Bodrex Batuk Pilek"]', '["benadryl wet cough", "bisolvon extra", "actifed plus expectorant", "espektoran", "ekspekt0ran", "ekspektoran", "ekspektora", "ekspektor4n", "anakonidin", "3ksp3ktoran", "ek5pektoran"]', '["3ksp3ktoran", "ek5pektoran", "ekspekt0ran", "ekspektor4n", "ekspektora", "espektoran"]', 'DKL10001159A1', 'ekspektoran', 'ekspektoran');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('actifed-merah', 'Actifed Merah', '1,25 mg triprolidine , 30 mg pseudoephedrine , dan 10 mg dextromethorphan', 'Obat batuk kombinasi dekongestan (pseudoephedrine), antihistamin (triprolidine), dan antitusif (dextromethorphan)', 'Obat Bebas Terbatas (Lingkaran Biru)', 'Sirop', 'Mengatasi gejala flu atau rhinitis alergi , seperti batuk pilek, hidung tersumbat, dan sinusitis', 'Berikut ini adalah dosis umum Actifed Merah yang bisa digunakan untuk mengatasi batuk kering dan gejala flu, seperti bersin-bersin:', '["Actifed Merah"]', '["1,25 mg triprolidine , 30 mg pseudoephedrine , dan 10 mg dextromethorphan", "actifed merah", "act1fed merah", "actif3d m3rah", "actifed mera", "actiphed merah", "astifed merah", "4ctifed mer4h", "actlfed merah", "actifed rnerah"]', '["4ctifed mer4h", "act1fed merah", "actif3d m3rah", "actifed mera", "actifed rnerah", "actiphed merah", "actlfed merah", "astifed merah"]', 'DTL10001213A1', 'actifedmerah', '125mgtriprolidine30mgpseudoephedrinedan10mgdextromethorphan');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('pamol', 'Pamol', 'Pamol Tablet:', 'Analgesik dan antipiretik', 'Obat Bebas (Hijau)', 'Tablet, kaplet, sirop , drops', 'Meredakan nyeri dan demam', 'Pembagian dosis Pamol berdasarkan jenis obat dan usia pasien untuk meredakan demam dan nyeri adalah:', '["Pamol"]', '["p4mol", "pamol", "pam0l", "parnol", "pamo1", "pamoi", "pamol tablet:"]', '["p4mol", "pam0l", "pamo1", "pamoi", "parnol"]', 'DBL10000505A1', 'pamol', 'pamoltablet');
