INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('eliquis', 'Eliquis', 'Apixaban', 'Antikoagulan jenis penghambat faktor Xa', 'Obat Keras (Lingkaran Merah K)', 'Tablet salut selaput', 'Mencegah stroke dan penggumpalan darah', 'Agar penggunaan Eliquis efektif dan aman, dosis obat harus disesuaikan dengan kondisi kesehatan masing-masing pasien. Berikut panduan umum dosis apixaban dalam Eliquis berdasarkan jenis kondisi medis yang sering ditangani:', '["Eliquis"]', '["apixaban", "eliqui", "3liquis", "eliquis", "eiquis", "ellquls", "el1qu1s", "e1iquis", "eiiquis", "eliqui5"]', '["3liquis", "e1iquis", "eiiquis", "eiquis", "el1qu1s", "eliqui", "eliqui5", "ellquls"]', 'DKL10000732A1', 'eliquis', 'apixaban');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('kalpepsa', 'Kalpepsa', 'Sukralfat 100 ml', 'Anti-ulkus', 'Obat Keras (Lingkaran Merah K)', 'Suspensi', 'Mengatasi tukak lambung, ulkus duodenum , atau gastritis kronis.', 'Dosis Kalpepsa akan disesuaikan dengan kondisi medis dan respons pasien terhadap kandungan sukralfat di dalam obat ini. Berikut adalah dosis umum dari Kalpepsa:', '["Kalpepsa"]', '["klpepsa", "kalp3psa", "k4lpeps4", "ka1pepsa", "kalpep5a", "sukralfat 100 ml", "kalpeps", "kaipepsa", "kalpepsa"]', '["k4lpeps4", "ka1pepsa", "kaipepsa", "kalp3psa", "kalpep5a", "kalpeps", "klpepsa"]', 'DKL10000817A1', 'kalpepsa', 'sukralfat100ml');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('salbuven', 'Salbuven', 'Salbutamol', 'Bronkodilator ( beta-2-agonist dengan reaksi cepat)', 'Obat Keras (Lingkaran Merah K)', 'Tablet', 'Meredakan sesak napas, batuk, dan mengi , akibat serangan asma, emfisema, dan bronkitis kronis', 'Dosis Salbuven akan ditentukan oleh dokter berdasarkan usia, berat badan, serta kondisi kesehatan pasien. Secara umum, berikut adalah dosis Salbuven untuk meredakan gejala penyempitan saluran pernapasan:', '["Salbuven"]', '["slbuven", "salbuven", "sa1buven", "salbuve", "saibuven", "s4lbuven", "salbuv3n", "5albuven", "salbutamol"]', '["5albuven", "s4lbuven", "sa1buven", "saibuven", "salbuv3n", "salbuve", "slbuven"]', 'DKL10000832A1', 'salbuven', 'salbutamol');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('salbutamol-ipratropium', 'Salbutamol-Ipratropium', 'Salbutamol-Ipratropium', 'Kombinasi bronkodilator jenis agonis beta-2 (salbutamol) dan bronkodilator jenis antikolinergik (ipratropium)', 'Obat Keras (Lingkaran Merah K)', 'Larutan inhalasi', 'Mengatasi gejala asma dan penyakit paru obstruktif kronis ( PPOK )', 'Secara umum, berikut ini adalah dosis salbutamol-ipratropium untuk meredakan gejala penyempitan saluran pernapasan atau bronkospasme:', '["Salbutamol-Ipratropium", "Combivent", "Farbivent", "Inhavent", "Lasalcom", "Meprovent"]', '["salbutam0l-ipratr0pium", "inhavent", "salbutamol-ipratropium", "5albutamol-ipratropium", "saibutamoi-ipratropium", "farbivent", "salbutamol-1pratrop1um", "sa1butamo1-ipratropium", "lasalcom", "combivent", "salbutamol-lpratroplum", "salbutamol-ipratropiu", "s4lbut4mol-ipr4tropium"]', '["5albutamol-ipratropium", "s4lbut4mol-ipr4tropium", "sa1butamo1-ipratropium", "saibutamoi-ipratropium", "salbutam0l-ipratr0pium", "salbutamol-1pratrop1um", "salbutamol-ipratropiu", "salbutamol-lpratroplum"]', 'DKL10002269A1', 'salbutamolipratropium', 'salbutamolipratropium');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('urdafalk', 'Urdafalk', 'Asam ursodeoksikolat', 'Derivat asam empedu', 'Obat Keras (Lingkaran Merah K)', 'Kaplet', 'Mencegah dan mengatasi batu empedu ukuran kecil (diameter ≤20 mm), untuk pasien yang menolak atau tidak memungkinkan ditangani dengan operasi', 'Dosis dan aturan pakai Urdafalk ditentukan dokter sesuai usia, berat badan, dan kondisi pasien. Dosis Urdafalk yang biasanya diberikan adalah:', '["Urdafalk"]', '["urdaphalk", "udafalk", "urdafa1k", "urd4f4lk", "urdafal", "asam ursodeoksikolat", "urdafalk", "urdafaik"]', '["udafalk", "urd4f4lk", "urdafa1k", "urdafaik", "urdafal", "urdaphalk"]', 'DKL10000810A1', 'urdafalk', 'asamursodeoksikolat');
