INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('halothane', 'Halothane', 'Halothane', 'Anestesi atau obat bius', 'Obat Keras (Lingkaran Merah K)', 'Cairan inhaler', 'Menghilangkan kesadaran pasien selama prosedur operasi', 'Dosis halothane yang diberikan tergantung pada kondisi pasien dan prosedur medis yang akan dilakukan. Dosis yang diberikan bisa dalam bentuk persen volume/volume (% v/v).', '["Halothane", "diabetes", "pheochromocytoma", "kejang", "myasthenia gravis", "penyakit jantung"]', '["halothane", "ha1othane", "kejang", "haiothane", "hal0thane", "hlothane", "halothan", "halotane", "halothan3", "pheochromocytoma", "diabetes", "h4loth4ne", "myasthenia gravis"]', '["h4loth4ne", "ha1othane", "haiothane", "hal0thane", "halotane", "halothan", "halothan3", "hlothane"]', 'DKL10000916A1', 'halothane', 'halothane');
