INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('urdahex', 'Urdahex', 'Asam ursodeoksikolat 250 mg', 'Derivat asam empedu', 'Obat Keras (Lingkaran Merah K)', 'Kapsul', 'Melarutkan batu empedu ukuran kecil', 'Dosis Urdahex akan disesuaikan dengan kondisi, berat badan, dan respons pasien terhadap obat ini. Namun, umumnya dokter akan menyarankan pasien untuk mengonsumsi obat ini 8–10 mg/kg BB/hari, yang dapat dibagi ke dalam 2–3 dosis.', '["Urdahex"]', '["urdah3x", "udahex", "urdahe", "asam ursodeoksikolat 250 mg", "urdahex", "urd4hex", "urdaheks"]', '["udahex", "urd4hex", "urdah3x", "urdahe", "urdaheks"]', 'DKL10000721A1', 'urdahex', 'asamursodeoksikolat250mg');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('maxprinol', 'Maxprinol', 'Methisoprinol', 'Antivirus', 'Obat Keras (Lingkaran Merah K)', 'Tablet dan sirop', 'Mengatasi penyakit infeksi akibat virus, seperti herpes simpleks, campak , dan cacar air', 'Maxprinol mengandung 500 mg methisoprinol dalam setiap 1 tabletnya. Dokter akan menentukan dosis Maxprinol berdasarkan berat badan pasien.', '["Maxprinol"]', '["maxprino1", "maxprino", "maksprinol", "maxprinoi", "methisoprinol", "maxprlnol", "maxprinol", "m4xprinol", "maxprin0l", "maxpr1nol"]', '["m4xprinol", "maksprinol", "maxpr1nol", "maxprin0l", "maxprino", "maxprino1", "maxprinoi", "maxprlnol"]', 'DKL10000954A1', 'maxprinol', 'methisoprinol');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('b-mycin', 'B-Mycin', 'Kombinasi betametason dan gentamicin', 'Kombinasi kortikosteroid topikal dan antibiotik topikal dari golongan aminoglikosida', 'Obat Keras (Lingkaran Merah K)', 'Krim', 'Mengatasi peradangan atau infeksi bakteri pada kulit', 'Dosis B-Mycin dapat berbeda-beda tergantung kondisi kulit sehingga penggunaannya harus dengan resep dokter. Meski begitu, obat ini umumnya dapat dioleskan tipis-tipis di area kulit yang bermasalah 2–3 kali sehari.', '["B-Mycin"]', '["b-mycln", "b-myc1n", "kombinasi betametason dan gentamicin", "b-myci", "b-mycin", "b-rnycin", "bmycin", "b-mysin"]', '["b-myc1n", "b-myci", "b-mycln", "b-mysin", "b-rnycin", "bmycin"]', 'DKL10000623A1', 'bmycin', 'kombinasibetametasondangentamicin');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('kalsirox', 'Kalsirox', 'Deferasirox', 'Agen pengkelat besi', 'Obat Keras (Lingkaran Merah K)', 'Tablet dispersibel', 'Menangani kelebihan zat besi akibat transfusi darah berulang pada thalasemia atau anemia sel sabit', 'Secara umum, berikut adalah dosis Kalsirox untuk mengatasi penumpukan zat besi akibat transfusi darah yang berulang dan terus-menerus:', '["Kalsirox"]', '["kalsirox", "kalsiro", "kalsiroks", "kal5irox", "ka1sirox", "k4lsirox", "deferasirox", "kaisirox", "kals1rox", "kalsir0x"]', '["k4lsirox", "ka1sirox", "kaisirox", "kal5irox", "kals1rox", "kalsir0x", "kalsiro", "kalsiroks"]', 'DKL10000845A1', 'kalsirox', 'deferasirox');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('maxpro', 'Maxpro', 'Cefixime trihydrate', 'Antibiotik sefalosporin', 'Obat Keras (Lingkaran Merah K)', 'Tablet dan drops', 'Mengobati infeksi bakteri', 'Berikut ini adalah dosis umum penggunaan Maxpro berdasarkan usia dan kondisi pasien:', '["Maxpro"]', '["maxpro", "maxpr", "mxpro", "maxpr0", "m4xpro", "rnaxpro", "makspro", "cefixime trihydrate"]', '["m4xpro", "makspro", "maxpr", "maxpr0", "mxpro", "rnaxpro"]', 'DKL10000631A1', 'maxpro', 'cefiximetrihydrate');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('hametasone-krim', 'Hametasone Krim', 'Mometasone furoate', 'Kortikosteroid topikal', 'Obat Keras (Lingkaran Merah K)', 'Krim', 'Meredakan gatal-gatal dan peradangan pada kulit.', 'Beberapa penyakit kulit yang bisa diobati dengan Hametasone krim meliputi alergi kulit, psoriasis, atau dermatitis, termasuk eksim. Hametasone krim digunakan 1 kali sehari sampai gejala radang kulit mereda. Penggunaan obat ini tidak lebih dari 3 minggu.', '["Hametasone Krim"]', '["h4met4sone krim", "ham3tason3 krim", "hametasone kri", "hametasone krlm", "mometasone furoate", "harnetasone krirn", "hametas0ne krim", "hameta5one krim", "hametasone kr1m", "hametasone krim"]', '["h4met4sone krim", "ham3tason3 krim", "hameta5one krim", "hametas0ne krim", "hametasone kr1m", "hametasone kri", "hametasone krlm", "harnetasone krirn"]', 'DKL10001464A1', 'hametasonekrim', 'mometasonefuroate');
