INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('pamol-supositoria', 'Pamol Supositoria', 'Paracetamol', 'Analgetik dan antipiretik', 'Obat Bebas (Hijau)', 'Supositoria', 'Meredakan nyeri dan demam', 'Pembagian dosis Pamol supositoria berdasarkan usia pasien untuk meredakan demam dan nyeri adalah:', '["Pamol Supositoria"]', '["pamo1 supositoria", "pamol supos1tor1a", "pamoi supositoria", "pamol suposltorla", "p4mol supositori4", "pamol supositori", "pamol supositoria", "pamol 5upo5itoria", "pam0l sup0sit0ria", "paracetamol"]', '["p4mol supositori4", "pam0l sup0sit0ria", "pamo1 supositoria", "pamoi supositoria", "pamol 5upo5itoria", "pamol supos1tor1a", "pamol supositori", "pamol suposltorla"]', 'DBL10001723A1', 'pamolsupositoria', 'paracetamol');
