INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('urdex', 'Urdex', 'Asam ursodeoksikolat 250 mg', 'Derivat asam empedu', 'Obat Keras (Lingkaran Merah K)', 'Kapsul', 'Meluruhkan batu empedu berukuran kecil, mencegah terbentuknya batu empedu, khususnya pada penderita obesitas atau pasien yang menjalani penurunan berat badan dengan cepat', 'Saat pasien berkonsultasi secara langsung atau via chat, dokter akan menentukan dan menjelaskan dosis Urdex sesuai kondisi kesehatan. Namun, dosis umum pemberian Urdex, yaitu 8–10 mg/kgBB, yang dapat dibagi ke dalam 2–3 dosis terpisah.', '["Urdex"]', '["urdex", "urdeks", "urd3x", "asam ursodeoksikolat 250 mg"]', '["urd3x", "urdeks"]', 'DKL10000520A1', 'urdex', 'asamursodeoksikolat250mg');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('yeztugo', 'Yeztugo', 'Yeztugo', 'Antiretroviral', 'Obat Keras (Lingkaran Merah K)', 'Tablet dan suntik', 'Menangani infeksi virus HIV tipe 1 (HIV-1)', 'Dosis awal Yeztugo diberikan secara oral atau suntik, kemudian dilanjutkan dengan dosis pemeliharaan melalui suntikan subkutan/SC (di dalam kulit).', '["Yeztugo"]', '["yeztug0", "yeztugo", "yeztug", "y3ztugo", "yestugo", "yztugo"]', '["y3ztugo", "yestugo", "yeztug", "yeztug0", "yztugo"]', 'DKL10000759A1', 'yeztugo', 'yeztugo');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('hansaplast-plester', 'Hansaplast', 'Hansaplast', 'Plester luka atau perawatan luka', 'Obat Keras (Lingkaran Merah K)', 'Sediaan oral/topikal sesuai instruksi kemasan.', 'Melindungi luka dari kotoran dan bakteri, serta mengurangi risiko infeksi pada luka', 'Pastikan untuk menggunakan Hansaplast sesuai dengan kebutuhan.', '["Hansaplast"]', '["han5apla5t", "hansapiast", "hansap1ast", "hnsaplast", "hansaplast", "hansaplas", "h4ns4pl4st"]', '["h4ns4pl4st", "han5apla5t", "hansap1ast", "hansapiast", "hansaplas", "hnsaplast"]', 'DKL10001039A1', 'hansaplast', 'hansaplast');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('baby-and-me-organic', 'Baby&Me Organic', 'Baby&Me Organic', 'Pengobatan Umum', 'Obat Keras (Lingkaran Merah K)', 'Sediaan oral/topikal sesuai instruksi kemasan.', 'Mengatasi gangguan kesehatan dan meredakan gejala sesuai petunjuk medis.', 'Di bawah ini adalah takaran penggunaan Baby&Me Organic yang dibagi berdasarkan usia bayi:', '["Baby&Me Organic"]', '["baby&me organlc", "baby&rne organic", "b4by&me org4nic", "baby&me organ1c", "baby&m3 organic", "baby&me organi", "baby&me organic", "baby&me organis", "baby&me 0rganic"]', '["b4by&me org4nic", "baby&m3 organic", "baby&me 0rganic", "baby&me organ1c", "baby&me organi", "baby&me organis", "baby&me organlc", "baby&rne organic"]', 'DKL10001337A1', 'babymeorganic', 'babymeorganic');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('elkana-cl', 'Elkana CL', 'Tiap 5 ml Elkana CL Sirup mengandung 2.400 IU vitamin A, 400 IU vitamin D3, Cod liver oil 8 mg, 10 mg DHA, 15 mg AA, 12 mg curcuma extract, 4 mg vitamin B1, 1,2 mg vitamin B2, 1,2 mg vitamin B6, 4 mcg vitamin B12, 16 mg vitamin B3, 12 mg kolin, 12 mg inositol, 100 mg L-lisin HCL, 33,1 mg kalsium, 5,2 mg natrium, 500 mg GOS.', 'Suplemen vitamin', 'Obat Tradisional / Jamu (Logo Pohon)', 'Sirup', 'Membantu memenuhi kebutuhan vitamin dan kalsium', 'Berikut ini adalah dosis umum penggunaan Elkana CL untuk memenuhi kebutuhan vitamin dan kalsium:', '["Elkana CL"]', '["ekana cl", "elk4n4 cl", "tiap 5 ml elkana cl sirup mengandung 2.400 iu vitamin a, 400 iu vitamin d3, cod liver oil 8 mg, 10 mg dha, 15 mg aa, 12 mg curcuma extract, 4 mg vitamin b1, 1,2 mg vitamin b2, 1,2 mg vitamin b6, 4 mcg vitamin b12, 16 mg vitamin b3, 12 mg kolin, 12 mg inositol, 100 mg l-lisin hcl, 33,1 mg kalsium, 5,2 mg natrium, 500 mg gos.", "elkana cl", "e1kana c1", "elkana d", "eikana ci", "3lkana cl", "elkana c", "elkana sl"]', '["3lkana cl", "e1kana c1", "eikana ci", "ekana cl", "elk4n4 cl", "elkana c", "elkana d", "elkana sl"]', 'TR10000763A1', 'elkanacl', 'tiap5mlelkanaclsirupmengandung2400iuvitamina400iuvitamind3codliveroil8mg10mgdha15mgaa12mgcurcumaextract4mgvitaminb112mgvitaminb212mgvitaminb64mcgvitaminb1216mgvitaminb312mgkolin12mginositol100mgllisinhcl331mgkalsium52mgnatrium500mggos');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('alerhis', 'Alerhis', 'Loratadine 10 mg', 'Antihistamin', 'Obat Keras (Lingkaran Merah K)', 'Kaplet', 'Meredakan gejala alergi, termasuk biduran , ruam kulit akibat alergi, rhinitis alergi , dan konjungtivitis alerg i', 'Dokter akan menjelaskan dosis Alerhis ketika memberikan e-resep atau resep biasa saat pasien berkonsultasi. Dosis Alerhis biasanya akan disesuaikan dengan usia, kondisi, dan respons tubuh pasien terhadap pengobatan.', '["Alerhis"]', '["loratadine 10 mg", "alerh1s", "alerhis", "aierhis", "aerhis", "alerhi", "a1erhis", "alerhi5", "al3rhis", "4lerhis"]', '["4lerhis", "a1erhis", "aerhis", "aierhis", "al3rhis", "alerh1s", "alerhi", "alerhi5"]', 'DKL10000712A1', 'alerhis', 'loratadine10mg');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('alergine', 'Alergine', 'Cetirizine', 'Obat antihistamin', 'Obat Keras (Lingkaran Merah K)', 'Tablet dan sirop', 'Meredakan gejala alergi', 'Berikut ini adalah dosis umum penggunaan Alergine untuk mengatasi gejala alergi berdasarkan usia pasien:', '["Alergine"]', '["al3rgin3", "alergin", "alergine", "alerglne", "alerg1ne", "aergine", "cetirizine", "a1ergine", "4lergine", "aiergine"]', '["4lergine", "a1ergine", "aergine", "aiergine", "al3rgin3", "alerg1ne", "alergin", "alerglne"]', 'DKL10000807A1', 'alergine', 'cetirizine');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('kalsium', 'Kalsium', 'Kalsium', 'Suplemen mineral', 'Obat Bebas (Hijau)', 'Tablet, kapsul, dan sirop', 'Mencegah dan mengatasi defisiensi kalsium', 'Berikut adalah dosis umum penggunaan kalsium berdasarkan tujuan penggunaannya:', '["Kalsium", "Blackmores Calcimag Multi", "Calcifar", "Calcium Citrate", "Calcium Lactate", "CDR"]', '["kalsiu", "calcium citrate", "kaisium", "ka1sium", "kalsiurn", "calcium lactate", "kals1um", "k4lsium", "calcifar", "kalslum", "kalsium", "blackmores calcimag multi", "kal5ium"]', '["k4lsium", "ka1sium", "kaisium", "kal5ium", "kals1um", "kalsiu", "kalsiurn", "kalslum"]', 'DBL10000726A1', 'kalsium', 'kalsium');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('pamorelin', 'Pamorelin', 'Triptorelin', 'Agonis hormon pelepas gonadotropin (GnRH agonist)', 'Obat Keras (Lingkaran Merah K)', 'Suntik', 'Mengobati kanker prostat, pubertas dini, endometriosis, dan fibroid rahim', 'Dokter akan menentukan dosis Pamorelin berdasarkan kondisi yang sedang diderita pasien. Secara umum, berikut adalah dosis pemberian Pamorelin:', '["Pamorelin"]', '["pamor3lin", "pamorel1n", "pamoreli", "pamorelln", "triptorelin", "pam0relin", "pamore1in", "pamoreiin", "pamorelin", "p4morelin"]', '["p4morelin", "pam0relin", "pamor3lin", "pamore1in", "pamoreiin", "pamorel1n", "pamoreli", "pamorelln"]', 'DKL10000935A1', 'pamorelin', 'triptorelin');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('salep-88', 'Salep 88', 'Asam Salisilat, Asam Benzoat, Sulfur Praecipitatum', 'Antiseptik & Luar', 'Obat Bebas (Hijau)', 'Salep', 'Mengatasi berbagai infeksi kulit, seperti panu, kudis, kutu air, dan infeksi jamur pada kulit.', 'Oleskan 3 kali sehari secukupnya pada bagian yang sakit.', '["Salep 88"]', '["salep 88", "salep kulit 88", "salep delapan delapan"]', '["5alep 88", "s4lep 88", "sa1ep 88", "saiep 88", "sal3p 88", "salep 8", "slep 88"]', 'QD191716891', 'salep88', 'asamsalisilatacidumsalicylicum65asambenzoatacidumbenzoicum6danendapanbelerangsulfurpraecipitatum6');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('alpha-lipoic-acid', 'Alpha-Lipoic Acid', 'Alpha-Lipoic Acid', 'Suplemen antioksidan', 'Obat Keras (Lingkaran Merah K)', 'Tablet, kaplet, dan kapsul', 'Meredakan nyeri akibat neuropati diabetik', 'Dosis umum untuk alpha-lipoic acid adalah 600–1.800 mg per hari dengan maksimal penggunaan selama 6 bulan. Namun, dosis harian suplemen alpha-lipoic acid adalah 50–300 mg per hari.', '["Alpha-Lipoic Acid", "Acyfote", "Ageloc Y-Span", "Ala-Q Ten", "Alusskin Glutalusskin", "Canergy"]', '["alpha-lipois asid", "ala-q ten", "alfa-lipoic acid", "alpha-lip0ic acid", "alpha-l1po1c ac1d", "alpha-lipoic aci", "a1pha-1ipoic acid", "ala-600", "4lph4-lipoic 4cid", "alpha-lipoic acid", "ageloc y-span", "acyfote", "aipha-iipoic acid"]', '["4lph4-lipoic 4cid", "a1pha-1ipoic acid", "aipha-iipoic acid", "alfa-lipoic acid", "alpha-l1po1c ac1d", "alpha-lip0ic acid", "alpha-lipoic aci", "alpha-lipois asid"]', 'DKL10001540A1', 'alphalipoicacid', 'alphalipoicacid');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('urea-topikal', 'Urea Topikal', 'Urea Topikal', 'Emolien', 'Obat Keras (Lingkaran Merah K)', 'Krim', 'Melembapkan kulit dan mengatasi kulit kering, kasar, bersisik, dan iritasi kulit ringan akibat dermatitis atopik (eksim), psoriasis, iktiosis , atau keratosis', 'Urea topikal tersedia dalam beragam konsentrasi, mulai dari 10 sampai 50%. Selain itu, urea topikal juga bisa ditemukan dalam bentuk kombinasi dengan bahan lain.', '["Urea Topikal", "Betaha", "Erhalogy Pro Callus", "kasar"]', '["urea top1kal", "urea topikal", "carmed 10", "urea t0pikal", "ur3a topikal", "urea topika", "urea topika1", "betaha", "urea topikai", "uea topikal", "calmuderm 20", "carmed 20", "ure4 topik4l"]', '["uea topikal", "ur3a topikal", "ure4 topik4l", "urea t0pikal", "urea top1kal", "urea topika", "urea topika1", "urea topikai"]', 'DKL10001153A1', 'ureatopikal', 'ureatopikal');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('allercyl', 'Allercyl', 'Cetirizine', 'Obat antihistamin', 'Obat Bebas Terbatas (Lingkaran Biru)', 'Tablet dan sirop', 'Meredakan gejala alergi', 'Dosis Allercyl dapat berbeda-beda untuk tiap pasien. Berikut ini adalah dosis umum penggunaan Allercyl berdasarkan bentuk obat dan usia pasien:', '["Allercyl"]', '["4llercyl", "alercyl", "a11ercy1", "allercy", "aiiercyi", "all3rcyl", "allercyl", "cetirizine", "allersyl"]', '["4llercyl", "a11ercy1", "aiiercyi", "alercyl", "all3rcyl", "allercy", "allersyl"]', 'DTL10000824A1', 'allercyl', 'cetirizine');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('maxson', 'Maxson', '2,5 mg desoximetasone', 'Kortikosteroid topikal', 'Obat Keras (Lingkaran Merah K)', 'Salep dan krim', 'Meredakan peradangan di kulit akibat eksim, dermatitis, atau psoriasis', 'Berikut ini adalah dosis umum penggunaan Maxson untuk mengobati dermatitis, psoriasis, atau eksim:', '["Maxson"]', '["max5on", "m4xson", "maxso", "maxs0n", "maksson", "rnaxson", "mxson", "maxson", "2,5 mg desoximetasone"]', '["m4xson", "maksson", "max5on", "maxs0n", "maxso", "mxson", "rnaxson"]', 'DKL10000630A1', 'maxson', '25mgdesoximetasone');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('alermax', 'Alermax', 'Chlorpheniramine maleate', 'Antihistamin', 'Obat Bebas Terbatas (Lingkaran Biru)', 'Tablet', 'Meredakan gejala alergi', 'Secara umum, berikut ini adalah dosis dan aturan pakai Alermax:', '["Alermax"]', '["alerrnax", "al3rmax", "chlorpheniramine maleate", "aiermax", "alermax", "a1ermax", "alermaks", "aermax", "4lerm4x", "alerma"]', '["4lerm4x", "a1ermax", "aermax", "aiermax", "al3rmax", "alerma", "alermaks", "alerrnax"]', 'DTL10000714A1', 'alermax', 'chlorpheniraminemaleate');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('hansaplast-salep-luka', 'Hansaplast Salep Luka', 'White petrolatum, thin paraffin oil, ceresin wax, glycerin, panthenol, dan glyceryl stearate', 'Obat luka', 'Obat Bebas (Hijau)', 'Salep', 'Membantu menyembuhkan luka lecet , luka gores, luka sayat, atau luka bakar derajat ringan', 'Oleskan salep secukupnya pada kulit yang luka, kering, pecah-pecah, atau iritasi, sebanyak 1–2 kali sehari. Jika luka tidak membaik dalam beberapa hari atau justru memburuk, segera konsultasikan ke dokter.', '["Hansaplast Salep Luka"]', '["white petrolatum, thin paraffin oil, ceresin wax, glycerin, panthenol, dan glyceryl stearate", "hansaplast salep luka", "han5apla5t 5alep luka", "hansapiast saiep iuka", "hansaplast sal3p luka", "h4ns4pl4st s4lep luk4", "hnsaplast salep luka", "hansap1ast sa1ep 1uka", "hansaplast salep luk"]', '["h4ns4pl4st s4lep luk4", "han5apla5t 5alep luka", "hansap1ast sa1ep 1uka", "hansapiast saiep iuka", "hansaplast sal3p luka", "hansaplast salep luk", "hnsaplast salep luka"]', 'DBL10002001A1', 'hansaplastsalepluka', 'whitepetrolatumthinparaffinoilceresinwaxglycerinpanthenoldanglycerylstearate');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('bacitracin', 'Bacitracin', 'Bacitracin', 'Antibiotik polipetida', 'Obat Keras (Lingkaran Merah K)', 'Krim, salep, serbuk', 'Mencegah dan mengobati infeksi bakteri pada kulit yang terluka', 'Dosis bacitracin krim, salep, atau serbuk untuk mencegah infeksi bakteri pada kulit yang mengalami luka ringan, baik pada orang dewasa maupun anak-anak, adalah 1–3 kali sehari dengan cara dioleskan tipis-tipis pada area kulit yang terluka.', '["Bacitracin", "Bacitracin – Polymyxin B", "Enbatic", "Liposin", "NB Topical Ointment", "Nebacetin"]', '["enbatic", "bacltracln", "bacitracin – polymyxin b", "bac1trac1n", "b4citr4cin", "bacitraci", "nb topical ointment", "bacitracin", "bcitracin", "basitrasin", "liposin"]', '["b4citr4cin", "bac1trac1n", "bacitraci", "bacltracln", "basitrasin", "bcitracin"]', 'DKL10001008A1', 'bacitracin', 'bacitracin');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('kalsium-asetat', 'Kalsium Asetat', 'Kalsium Asetat', 'Pengikat fosfat', 'Obat Keras (Lingkaran Merah K)', 'Tablet', 'Menurunkan kadar fosfat dalam darah pada pasien end stage of renal disease yang sedang cuci darah', 'Untuk menangani hiperfosfatemia sebagai efek samping cuci darah, dosis awal kalsium asetat adalah 4–8 gram per hari yang bisa dibagi menjadi beberapa kali konsumsi. Dosis akan disesuaikan dengan kadar fosfat di dalam darah. Dosis maksimal adalah 12 gram per hari.', '["Kalsium Asetat", "Lenalace", "Phosbind", "gangguan irama jantung aritmia", "antasida", "atau obat lain"]', '["kals1um asetat", "k4lsium 4set4t", "phosbind", "kaisium asetat", "ka1sium asetat", "kalsiurn asetat", "antasida", "lenalace", "kalsium as3tat", "gangguan irama jantung aritmia", "kalsium aseta", "kal5ium a5etat", "kalsium asetat"]', '["k4lsium 4set4t", "ka1sium asetat", "kaisium asetat", "kal5ium a5etat", "kals1um asetat", "kalsium as3tat", "kalsium aseta", "kalsiurn asetat"]', 'DKL10001368A1', 'kalsiumasetat', 'kalsiumasetat');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('yodium', 'Yodium', 'Yodium', 'Suplemen mineral', 'Obat Bebas (Hijau)', 'Tablet, kaplet, kapsul, serbuk', 'Mengatasi kekurangan yodium dan mengatasi gangguan tiroid', 'Dosis umum suplementasi yodium untuk mencegah atau mengatasi kekurangan yodium adalah 150–250 mcg setiap hari.', '["Yodium", "Blackmores I-Folic", "Caviplex Mom", "Kalisto", "Maltiron", "Prenatal+DHA"]', '["maltiron", "y0dium", "yodiu", "yodlum", "kalisto", "yodium", "yod1um", "yodiurn", "caviplex mom", "blackmores i-folic", "ydium"]', '["y0dium", "ydium", "yod1um", "yodiu", "yodiurn", "yodlum"]', 'DBL10000631A1', 'yodium', 'yodium');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('maxstan', 'Maxstan', 'Asam mefenamat', 'Obat antiinflamasi nonsteroid ( NSAID )', 'Obat Keras (Lingkaran Merah K)', 'Kaplet salut selaput', 'Meredakan nyeri skala ringan hingga sedang, seperti pada dismenore', 'Dosis Maxstan sebagai obat penghilang nyeri adalah 500 mg (1 kaplet Maxstan), 3 kali sehari jika diperlukan. Lama pengobatan maksimal 7 hari, atau sesuai petunjuk dokter.', '["Maxstan"]', '["maxsta", "m4xst4n", "mxstan", "max5tan", "rnaxstan", "asam mefenamat", "maxstan", "maksstan"]', '["m4xst4n", "maksstan", "max5tan", "maxsta", "mxstan", "rnaxstan"]', 'DKL10000732A1', 'maxstan', 'asammefenamat');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('panadol', 'Panadol', 'Paracetamol, dextromethorpan, phenylephrine, pseudoephedrine, kafein', 'Analgesik & antipiretik', 'Obat Bebas Terbatas (Lingkaran Biru)', 'Kaplet', 'Meredakan demam, gejala flu, sakit kepala, dan sakit gigi', 'Dosis pemakaian Panadol tergantung pada varian obatnya. Berikut adalah rincian dosis berbagai varian Panadol berdasarkan usia pasien:', '["Panadol"]', '["panadol", "panado1", "pnadol", "panadoi", "paracetamol, dextromethorpan, phenylephrine, pseudoephedrine, kafein", "panado", "panad0l", "p4n4dol"]', '["p4n4dol", "panad0l", "panado", "panado1", "panadoi", "pnadol"]', 'DTL10000703A1', 'panadol', 'paracetamoldextromethorpanphenylephrinepseudoephedrinekafein');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('salgen-salep', 'Salgen Salep', 'Gentamicin', 'Antibiotik golongan aminoglikosida', 'Obat Keras (Lingkaran Merah K)', 'Salep kulit', 'Mengobati infeksi kulit yang disebabkan oleh bakteri.', 'Untuk mengobati infeksi kulit akibat bakteri, seperti impetigo, bisul, folikulitis, atau luka bernanah, oleskan salep Salgen secara merata pada area kulit yang perlu diobati, 3–4 kali sehari atau sesuai petunjuk dokter.', '["Salgen Salep"]', '["sa1gen sa1ep", "salgen sale", "5algen 5alep", "s4lgen s4lep", "slgen salep", "salgen salep", "gentamicin", "saigen saiep", "salg3n sal3p"]', '["5algen 5alep", "s4lgen s4lep", "sa1gen sa1ep", "saigen saiep", "salg3n sal3p", "salgen sale", "slgen salep"]', 'DKL10001135A1', 'salgensalep', 'gentamicin');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('elkana-syrup', 'Elkana Syrup', 'Tiap 5 ml Elkana Syrup Syrup mengandung 2.400 IU vitamin A, 4 mg vitamin B1, 1,2 mg vitamin B2, 1,2 mg vitamin B6, 4 mcg vitamin B12 , 60 mg vitamin C, 400 IU vitamin D, 16 mg nicotinamide (vitamin B3), 12 mg kolin, 12 mg inositol, 500 mg kalsium , 20 mg fosfor, 10 mg zat besi, 100 mcg iodium, 2,5 mg zinc, 0,1 mg tembaga, 5 mg magnesium, dan 0,25 mg mangan', 'Suplemen vitamin', 'Obat Tradisional / Jamu (Logo Pohon)', 'Sirup', 'Membantu memenuhi kebutuhan vitamin dan kalsium', 'Berikut ini adalah dosis umum penggunaan Elkana Syrup untuk membantu memenuhi kebutuhan nutrisi dan kalsium:', '["Elkana Syrup"]', '["e1kana syrup", "elkana syru", "tiap 5 ml elkana syrup syrup mengandung 2.400 iu vitamin a, 4 mg vitamin b1, 1,2 mg vitamin b2, 1,2 mg vitamin b6, 4 mcg vitamin b12 , 60 mg vitamin c, 400 iu vitamin d, 16 mg nicotinamide (vitamin b3), 12 mg kolin, 12 mg inositol, 500 mg kalsium , 20 mg fosfor, 10 mg zat besi, 100 mcg iodium, 2,5 mg zinc, 0,1 mg tembaga, 5 mg magnesium, dan 0,25 mg mangan", "elkana syrup", "elk4n4 syrup", "elkana 5yrup", "ekana syrup", "3lkana syrup", "eikana syrup"]', '["3lkana syrup", "e1kana syrup", "eikana syrup", "ekana syrup", "elk4n4 syrup", "elkana 5yrup", "elkana syru"]', 'TR10001167A1', 'elkanasyrup', 'tiap5mlelkanasyrupsyrupmengandung2400iuvitamina4mgvitaminb112mgvitaminb212mgvitaminb64mcgvitaminb1260mgvitaminc400iuvitamind16mgnicotinamidevitaminb312mgkolin12mginositol500mgkalsium20mgfosfor10mgzatbesi100mcgiodium25mgzinc01mgtembaga5mgmagnesiumdan025mgmangan');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('yekaflam', 'Yekaflam', 'Diclofenac potassium 50 mg', 'Obat antiinflamasi nonsteroid (OAINS)', 'Obat Keras (Lingkaran Merah K)', 'Tablet salut selaput', 'Meredakan nyeri dan peradangan, contohnya pada radang sendi, sakit gigi, atau migrain', 'Dosis Yekaflam yang diberikan dokter bisa berbeda-beda, tergantung kondisi yang ditangani, derajat keparahan penyakit, dan respons pasien terhadap obat. Secara umum, berikut adalah dosis Yekaflam untuk meredakan nyeri dan peradangan:', '["Yekaflam"]', '["yekaf1am", "yekafla", "yek4fl4m", "ykaflam", "yekaflam", "yekaflarn", "yekafiam", "yekaphlam", "diclofenac potassium 50 mg", "y3kaflam"]', '["y3kaflam", "yek4fl4m", "yekaf1am", "yekafiam", "yekafla", "yekaflarn", "yekaphlam", "ykaflam"]', 'DKL10000810A1', 'yekaflam', 'diclofenacpotassium50mg');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('kalsium-glukonat', 'Kalsium Glukonat', 'Kalsium Glukonat', 'Suplemen mineral', 'Obat Keras (Lingkaran Merah K)', 'Kapsul, kaplet, sirop, suntik', 'Mengatasi kondisi kekurangan kalsium', 'Kalsium glukonat hanya diberikan berdasarkan anjuran dokter. Berikut ini adalah dosis umum penggunaan kalsium glukonat berdasarkan bentuk obat, kondisi, dan usia pasien:', '["Kalsium Glukonat", "Calcium Gluconate", "Curvit", "Kalsis", "Takana", "Tonikum Bayer"]', '["curvit", "kals1um glukonat", "kalsium glukona", "kalsiurn glukonat", "takana", "kaisium giukonat", "kalsium glukonat", "calcium gluconate", "kal5ium glukonat", "k4lsium glukon4t", "ka1sium g1ukonat", "kalsis", "kalsium gluk0nat"]', '["k4lsium glukon4t", "ka1sium g1ukonat", "kaisium giukonat", "kal5ium glukonat", "kals1um glukonat", "kalsium gluk0nat", "kalsium glukona", "kalsiurn glukonat"]', 'DKL10001595A1', 'kalsiumglukonat', 'kalsiumglukonat');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('baclofen', 'Baclofen', 'Baclofen', 'Relaksan otot', 'Obat Keras (Lingkaran Merah K)', 'Tablet', 'Meredakan nyeri, kram, kaku, dan tegang pada otot', 'Dosis baclofen tablet untuk orang dewasa dan anak usia ≥12 tahun adalah 5 mg 3 kali sehari. Dosis dapat ditingkatkan sebanyak 5 mg setiap 3 hari, jika keluhan masih mengganggu. Dosis maksimal: 20 mg, 4 kali sehari.', '["Baclofen", "Falcofen", "kram", "kaku", "penyakit ginjal", "diabetes"]', '["penyakit ginjal", "kram", "b4clofen", "bacl0fen", "baclof3n", "falcofen", "baciofen", "bac1ofen", "baclophen", "baclofe", "baclofen", "kaku", "badofen"]', '["b4clofen", "bac1ofen", "baciofen", "bacl0fen", "baclof3n", "baclofe", "baclophen", "badofen"]', 'DKL10000794A1', 'baclofen', 'baclofen');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('salmeterol', 'Salmeterol', 'Salmeterol', 'Bronkodilator jenis long acting beta agonist (LABA)', 'Obat Keras (Lingkaran Merah K)', 'Larutan, serbuk, dan aerosol', 'Mencegah dan meringankan gejala mengi, sesak napas, dan batuk akibat asma atau penyakit paru obstruktif kronis', 'Berikut adalah dosis salmeterol berdasarkan tujuan penggunaannya:', '["Salmeterol", "Respitide", "Salmeflo", "Seretide Diskus"]', '["sa1metero1", "respitide", "flutias 50", "salmetero", "5almeterol", "s4lmeterol", "flusal 250", "salmeter0l", "salm3t3rol", "saimeteroi", "flutias 125", "salmeterol", "salrneterol"]', '["5almeterol", "s4lmeterol", "sa1metero1", "saimeteroi", "salm3t3rol", "salmeter0l", "salmetero", "salrneterol"]', 'DKL10001048A1', 'salmeterol', 'salmeterol');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('alerzin', 'Alerzin', 'Cetirizine', 'Antihistamin', 'Obat Keras (Lingkaran Merah K)', 'Tablet dan sirop', 'Meredakan gejala alergi, seperti rhinitis alergi , dermatitis atopik, atau biduran', 'Berikut ini adalah dosis umum penggunaan Alerzin untuk mengatasi rhinitis alergi dan biduran berdasarkan varian obat yang dipakai:', '["Alerzin"]', '["4lerzin", "al3rzin", "aerzin", "a1erzin", "alerzi", "aierzin", "alersin", "cetirizine", "alerzin", "alerz1n"]', '["4lerzin", "a1erzin", "aerzin", "aierzin", "al3rzin", "alersin", "alerz1n", "alerzi"]', 'DKL10000725A1', 'alerzin', 'cetirizine');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('uresix', 'Uresix', 'Furosemide', 'Diuretik', 'Obat Keras (Lingkaran Merah K)', 'Tablet dan suntik', 'Mengatasi edema dan tekanan darah tinggi', 'Uresix bisa diberikan dalam bentuk obat minum atau suntik. Dosis Uresix bentuk suntik akan ditentukan oleh dokter sesuai dengan kondisi pasien dan tingkat keparahannya. Sementara untuk Uresix tablet, dosis umumnya adalah:', '["Uresix"]', '["ure5ix", "uresiks", "uesix", "furosemide", "ureslx", "uresix", "ures1x", "ur3six", "uresi"]', '["uesix", "ur3six", "ure5ix", "ures1x", "uresi", "uresiks", "ureslx"]', 'DKL10000640A1', 'uresix', 'furosemide');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('alfentanil', 'Alfentanil', 'Alfentanil', 'Obat antinyeri golongan opioid', 'Obat Keras (Lingkaran Merah K)', 'Suntik', 'Meredakan nyeri sedang hingga berat saat seseorang menjalani pemasangan alat bantu napas dan ventilator dan digunakan dalam prosedur pembiusan umum atau total', 'Dokter akan menentukan dosis dan durasi penggunaan alfentanil sesuai tujuan penggunaan, usia, dan kondisi pasien.', '["Alfentanil", "dewasa", "penyakit jantung", "bradikardia denyut jantung lambat", "tekanan darah rendah hipotensi", "penyakit paru atau saluran pernapasan"]', '["penyakit jantung", "4lfent4nil", "aifentanii", "alfentani", "bradikardia denyut jantung lambat", "alfentan1l", "tekanan darah rendah hipotensi", "alfentanil", "a1fentani1", "alf3ntanil", "dewasa", "afentanil", "alfentanll"]', '["4lfent4nil", "a1fentani1", "afentanil", "aifentanii", "alf3ntanil", "alfentan1l", "alfentani", "alfentanll"]', 'DKL10001022A1', 'alfentanil', 'alfentanil');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('mebendazole', 'Mebendazole', 'Mebendazole', 'Obat antihelmintik (obat cacing)', 'Obat Keras (Lingkaran Merah K)', 'Tablet kunyah', 'Mengobati infeksi cacing', 'Berikut ini adalah dosis mebendazole untuk pasien dewasa dan anak-anak di atas 2 tahun berdasarkan kondisi yang akan ditangani:', '["Mebendazole", "Ora Cacingan", "Vermoran", "anemia", "penyakit Crohn", "kolitis ulseratif"]', '["ora cacingan", "vermoran", "mebendazo1e", "mebend4zole", "penyakit crohn", "anemia", "m3b3ndazol3", "mebendazol", "mbendazole", "mebendazoie", "mebendazole", "mebendasole", "mebendaz0le"]', '["m3b3ndazol3", "mbendazole", "mebend4zole", "mebendasole", "mebendaz0le", "mebendazo1e", "mebendazoie", "mebendazol"]', 'DKL10001126A1', 'mebendazole', 'mebendazole');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('hapsen', 'Hapsen', 'Bisoprolol 5 mg', 'Penghambat beta', 'Obat Keras (Lingkaran Merah K)', 'Tablet salut film', 'Mengatasi hipertensi, gagal jantung, angina, dan aritmia', 'Dosis konsumsi Hapsen akan ditentukan berdasarkan tingkat keparahan penyakit dan respons tubuh pasien. Namun, dosis minum Hapsen untuk pasien dewasa umumnya adalah 1,25–10 mg, 1 kali sehari. Pastikan Anda mengonsumsi Hapsen sesuai dengan anjuran dokter.', '["Hapsen"]', '["bisoprolol 5 mg", "haps3n", "hapsen", "h4psen", "hpsen", "hapse", "hap5en"]', '["h4psen", "hap5en", "haps3n", "hapse", "hpsen"]', 'DKL10000607A1', 'hapsen', 'bisoprolol5mg');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('yubipen', 'Yubipen', 'Ampicillin', 'Antibiotik penisilin', 'Obat Keras (Lingkaran Merah K)', 'Sirop kering', 'Mengobati penyakit infeksi bakteri pada berbagai bagian tubuh, misalnya saluran pernapasan, saluran pencernaan, atau saluran kemih', 'Dosis Yubipen akan ditentukan oleh dokter berdasarkan usia, berat badan, dan kondisi pasien. Secara umum, berikut adalah dosis Yubipen sirop kering untuk mengobati infeksi bakteri:', '["Yubipen"]', '["yubipe", "yub1pen", "yubipen", "ampicillin", "yublpen", "yubip3n", "ybipen"]', '["ybipen", "yub1pen", "yubip3n", "yubipe", "yublpen"]', 'DKL10000732A1', 'yubipen', 'ampicillin');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('bactoderm', 'Bactoderm', 'Mupirocin', 'Antibiotik', 'Obat Keras (Lingkaran Merah K)', 'Krim dan salep', 'Mengobati infeksi bakteri pada kulit', 'Oleskan Bactoderm ke kulit yang mengalami infeksi secara tipis-tipis, 3 kali sehari. Pengobatan dilakukan maksimal selama 10 hari. Jika setelah digunakan secara rutin selama 3–5 hari infeksi belum membaik, berkonsultasilah dengan dokter.', '["Bactoderm"]', '["bact0derm", "bactoderrn", "bactoderm", "mupirocin", "bactoder", "bactod3rm", "bctoderm", "b4ctoderm", "bastoderm"]', '["b4ctoderm", "bact0derm", "bactod3rm", "bactoder", "bactoderrn", "bastoderm", "bctoderm"]', 'DKL10000913A1', 'bactoderm', 'mupirocin');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('yosenob', 'Yosenob', 'Fenofibrate 300 mg', 'Obat penurun kolesterol golongan fibrat', 'Obat Keras (Lingkaran Merah K)', 'Kapsul', 'Menurunkan kadar kolesterol jahat (LDL) dan trigliserida, serta meningkatkan kadar kolesterol baik (HDL) di dalam darah', 'Dosis Yosenob pada setiap pasien bisa berbeda, tergantung kondisi dan respons tubuh terhadap pengobatan. Namun, dosis umum obat ini adalah 1 kapsul, 1 kali per hari.', '["Yosenob"]', '["y0sen0b", "yoseno", "ysenob", "yosenob", "fenofibrate 300 mg", "yos3nob", "yo5enob"]', '["y0sen0b", "yo5enob", "yos3nob", "yoseno", "ysenob"]', 'DKL10000735A1', 'yosenob', 'fenofibrate300mg');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('urief', 'Urief', 'Silodosin', 'Penghambat alfa ( alpha-blockers )', 'Obat Keras (Lingkaran Merah K)', 'Tablet', 'Meredakan gejala pembesaran kelenjar prostat jinak atau benign prostatic hyperplasia (BPH)', 'Berikut ini adalah dosis umum penggunaan Urief untuk meredakan gejala pembesaran kelenjar prostat jinak:', '["Urief"]', '["silodosin", "urief", "uri3f", "urlef", "ur1ef", "urieph"]', '["ur1ef", "uri3f", "urieph", "urlef"]', 'DKL10000507A1', 'urief', 'silodosin');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('elkana-tablet', 'Elkana Tablet', 'Tiap tablet Elkana mengandung 200 mg kalsium fosfat, 100 mg kalsium laktat, 20 mg vitamin B6 , 25 mg vitamin C, dan 100 IU vitamin D3', 'Suplemen vitamin', 'Obat Tradisional / Jamu (Logo Pohon)', 'Tablet', 'Membantu memenuhi kebutuhan vitamin dan kalsium', 'Dosis Elkana Tablet untuk orang dewasa dan anak-anak usia > 6 tahun adalah 1–2 tablet, 2 kali sehari.', '["Elkana Tablet"]', '["elk4n4 t4blet", "e1kana tab1et", "ekana tablet", "tiap tablet elkana mengandung 200 mg kalsium fosfat, 100 mg kalsium laktat, 20 mg vitamin b6 , 25 mg vitamin c, dan 100 iu vitamin d3", "elkana tablet", "3lkana tabl3t", "elkana table", "eikana tabiet"]', '["3lkana tabl3t", "e1kana tab1et", "eikana tabiet", "ekana tablet", "elk4n4 t4blet", "elkana table"]', 'TR10001224A1', 'elkanatablet', 'tiaptabletelkanamengandung200mgkalsiumfosfat100mgkalsiumlaktat20mgvitaminb625mgvitamincdan100iuvitamind3');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('urinter', 'Urinter', 'Asam pipemidat', 'Antibiotik quinolone', 'Obat Keras (Lingkaran Merah K)', 'Kapsul dan kaplet', 'Mengobati infeksi bakteri di saluran kemih, termasuk pada radang kandung kemih (cystitis), radang uretra (uretritis), radang panggul ginjal (pyelitis), radang ginjal (pielonefritis), dan radang prostat (prostatitis).', 'Dosis Urinter untuk mengatasi infeksi saluran kemih adalah:', '["Urinter"]', '["urinter", "ur1nter", "urinte", "urlnter", "asam pipemidat", "uinter", "urint3r"]', '["uinter", "ur1nter", "urint3r", "urinte", "urlnter"]', 'DKL10000745A1', 'urinter', 'asampipemidat');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('kalsium-karbonat', 'Kalsium Karbonat', 'Kalsium Karbonat', 'Suplemen mineral dan antasida', 'Obat Bebas (Hijau)', 'Tablet', 'Mengatasi kekurangan kalsium atau kelebihan asam lambung', 'Berikut ini adalah dosis umum penggunaan kalsium karbonat berdasarkan kondisi dan usia pasien:', '["Kalsium Karbonat", "Calos", "Calporosis D", "CDR", "Day-Cal", "Formical-B"]', '["day-cal", "ka1sium karbonat", "kalsium karb0nat", "kalsium karbona", "kalsiurn karbonat", "kals1um karbonat", "kal5ium karbonat", "k4lsium k4rbon4t", "kalsium karbonat", "cdr", "calos", "calporosis d", "kaisium karbonat"]', '["k4lsium k4rbon4t", "ka1sium karbonat", "kaisium karbonat", "kal5ium karbonat", "kals1um karbonat", "kalsium karb0nat", "kalsium karbona", "kalsiurn karbonat"]', 'DBL10001576A1', 'kalsiumkarbonat', 'kalsiumkarbonat');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('mebeverine', 'Mebeverine', 'Mebeverine', 'Antispasmodik', 'Obat Keras (Lingkaran Merah K)', 'Tablet', 'Mengatasi gejala sindrom iritasi usus besar dan radang usus besar', 'Dosis umum penggunaan mebeverine adalah 135 mg, 3 kali sehari. Dosis dapat dikurangi secara bertahap setelah gejala membaik, biasanya dalam 1–2 minggu.', '["Mebeverine", "Duspatalin", "penyakit hati", "penyakit ginjal", "sembelit yang parah", "penurunan berat badan"]', '["penyakit ginjal", "duspatalin", "mebeverin", "mebever1ne", "mebeverlne", "penyakit hati", "sembelit yang parah", "mbeverine", "mebeverine", "rnebeverine", "m3b3v3rin3"]', '["m3b3v3rin3", "mbeverine", "mebever1ne", "mebeverin", "mebeverlne", "rnebeverine"]', 'DKL10001026A1', 'mebeverine', 'mebeverine');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('salmeterol-fluticasone', 'Salmeterol-Fluticasone', 'Salmeterol-Fluticasone', 'Kombinasi bronkodilator β2 agonis (salmeterol) dan kortikosteroid inhalasi (fluticasone propionate)', 'Obat Keras (Lingkaran Merah K)', 'Serbuk inhaler dan aerosol', 'Mengontrol gejala asma dan penyakit paru obstruktif kronis ( PPOK )', 'Dosis penggunaan salmeterol-fluticasone ditentukan oleh dokter berdasarkan kondisi kesehatan pasien dan tingkat keparahan asma atau PPOK yang dialami. Secara umum, dosis salmeterol-fluticasone adalah:', '["Salmeterol-Fluticasone", "Friventil", "Flutias", "Respitide", "Salmeflo", "penyakit liver"]', '["sa1metero1-f1uticasone", "salmeterol-fluticason", "respitide", "saimeteroi-fiuticasone", "salmeterol-flut1casone", "salm3t3rol-fluticason3", "5almeterol-flutica5one", "salmeter0l-fluticas0ne", "salmeflo", "flutias", "s4lmeterol-flutic4sone", "friventil", "salmeterol-fluticasone"]', '["5almeterol-flutica5one", "s4lmeterol-flutic4sone", "sa1metero1-f1uticasone", "saimeteroi-fiuticasone", "salm3t3rol-fluticason3", "salmeter0l-fluticas0ne", "salmeterol-flut1casone", "salmeterol-fluticason"]', 'DKL10002242A1', 'salmeterolfluticasone', 'salmeterolfluticasone');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('panadol-biru', 'Panadol Biru', 'Paracetamol', 'Analgetik-antipiretik', 'Obat Bebas (Hijau)', 'Kaplet', 'Meredakan nyeri ringan hingga sedang, termasuk sakit gigi dan sakit kepala', 'Dewasa dan anak usia >12 tahun: 1–2 kaplet, 3–4 kali sehari. Dosis tidak boleh lebih dari 8 kaplet dalam 24 jam. Anak 6–12 tahun: ½–1 kaplet, 3–4 kali sehari. Dosis tidak boleh lebih dari 4 kaplet dalam 24 jam.', '["Panadol Biru"]', '["panadoi biru", "p4n4dol biru", "panadol b1ru", "panado1 biru", "panadol bir", "pnadol biru", "panadol biru", "panadol blru", "paracetamol", "panad0l biru"]', '["p4n4dol biru", "panad0l biru", "panado1 biru", "panadoi biru", "panadol b1ru", "panadol bir", "panadol blru", "pnadol biru"]', 'DBL10001137A1', 'panadolbiru', 'paracetamol');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('alfuzosin', 'Alfuzosin', 'Alfuzosin', 'Penghambat alfa ( alpha-blockers )', 'Obat Keras (Lingkaran Merah K)', 'Tablet lepas lambat', 'Meredakan gejala pembesaran kelenjar prostat jinak atau benign prostate hyperplasia (BPH)', 'Gunakan sesuai petunjuk dokter atau aturan pakai pada kemasan.', '["Alfuzosin", "kanker prostat", "penyakit ginjal", "katarak", "atau penyakit jantung dan pembuluh darah", "termasuk hipertensi"]', '["penyakit ginjal", "alfuzo5in", "alfuzosin", "alfuzos1n", "a1fuzosin", "afuzosin", "alfuz0sin", "4lfuzosin", "aifuzosin", "alfusosin", "atau penyakit jantung dan pembuluh darah", "katarak", "kanker prostat"]', '["4lfuzosin", "a1fuzosin", "afuzosin", "aifuzosin", "alfusosin", "alfuz0sin", "alfuzo5in", "alfuzos1n"]', 'DKL10000955A1', 'alfuzosin', 'alfuzosin');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('yulareb', 'Yulareb', 'Abemaciclib', 'Penghambat protein kinase', 'Obat Keras (Lingkaran Merah K)', 'Tablet', 'Mengobati kanker payudara', 'Dosis Yulareb tergantung pada kondisi, respons pasien terhadap obat, dan apakah pasien sedang mengonsumsi obat lain. Secara umum, dosis Yulareb untuk mengobati kanker payudara adalah 100–200 mg, diminum 2 kali sehari.', '["Yulareb"]', '["yulare", "yul4reb", "yular3b", "abemaciclib", "yu1areb", "yuiareb", "yulareb", "ylareb"]', '["ylareb", "yu1areb", "yuiareb", "yul4reb", "yular3b", "yulare"]', 'DKL10000724A1', 'yulareb', 'abemaciclib');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('bactoprim', 'Bactoprim', 'Trimethoprim dan sulfamethoxazole', 'Kombinasi antibiotik golongan sulfonamida dan trimethoprim', 'Obat Keras (Lingkaran Merah K)', 'Kapsul dan sirup', 'Mengatasi infeksi bakteri', 'Dosis Bactoprim ditentukan dokter berdasarkan usia, berat badan, berat infeksi, dan kondisi medis Anda. Ikuti petunjuk dosis dengan tepat untuk hasil optimal dan meminimalkan efek samping.', '["Bactoprim"]', '["b4ctoprim", "bact0prim", "bactoprim", "trimethoprim dan sulfamethoxazole", "bactoprirn", "bctoprim", "bactopr1m", "bactopri", "bactoprlm", "bastoprim"]', '["b4ctoprim", "bact0prim", "bactopr1m", "bactopri", "bactoprirn", "bactoprlm", "bastoprim", "bctoprim"]', 'DKL10000929A1', 'bactoprim', 'trimethoprimdansulfamethoxazole');
