INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('yusimox', 'Yusimox', 'Amoxicillin', 'Antibiotik penicillin', 'Obat Keras (Lingkaran Merah K)', 'Kaplet dan sirop kering', 'Mengobati infeksi bakteri', 'Dosis Yusimox yang diberikan dokter tergantung pada kondisi yang ditangani, serta usia dan berat badan (BB) pasien. Secara umum, berikut adalah rincian dosis Yusimox:', '["Yusimox"]', '["yu5imox", "yusim0x", "yusimo", "yusimoks", "yus1mox", "yuslmox", "amoxicillin", "yusimox", "ysimox", "yusirnox"]', '["ysimox", "yu5imox", "yus1mox", "yusim0x", "yusimo", "yusimoks", "yusirnox", "yuslmox"]', 'DKL10000766A1', 'yusimox', 'amoxicillin');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('urispas', 'Urispas', 'Flavoxate', 'Antimuskarinik atau antispasmodik', 'Obat Keras (Lingkaran Merah K)', 'Tablet salut selaput', 'Meredakan gejala akibat gangguan pada saluran kemih, termasuk radang kandung kemih ( cystitis ), radang prostat ( prostatitis ), radang uretra ( uretritis ), atau radang uretra dan kandung kemih (urethrocystitis)', 'Dosis umum penggunaan Urispas untuk mengatasi gangguan pada saluran kemih, yaitu:', '["Urispas"]', '["ur1spas", "flavoxate", "urisp4s", "uispas", "urlspas", "urispas", "uri5pa5", "urispa"]', '["uispas", "ur1spas", "uri5pa5", "urisp4s", "urispa", "urlspas"]', 'DKL10000743A1', 'urispas', 'flavoxate');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('elocon-salep', 'Elocon Salep', 'Mometasone furoate', 'Kortikosteroid topikal', 'Obat Keras (Lingkaran Merah K)', 'Salep', 'Meredakan gatal-gatal dan peradangan pada kulit, seperti pada eksim , psoriasis , atau alergi kulit .', 'Elocon salep digunakan 1 kali sehari sampai gejala radang kulit mereda. Penggunaan obat ini tidak lebih dari 3 minggu.', '["Elocon Salep"]', '["elocon sale", "el0c0n salep", "3locon sal3p", "elocon salep", "elocon s4lep", "eiocon saiep", "e1ocon sa1ep", "elocon 5alep", "mometasone furoate", "eloson salep"]', '["3locon sal3p", "e1ocon sa1ep", "eiocon saiep", "el0c0n salep", "elocon 5alep", "elocon s4lep", "elocon sale", "eloson salep"]', 'DKL10001141A1', 'eloconsalep', 'mometasonefuroate');
