INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('kaltrofen-gel', 'Kaltrofen Gel', 'Ketoprofen', 'Obat antiinflamasi nonsteroid ( OAINS )', 'Obat Keras (Lingkaran Merah K)', 'Gel', 'Meredakan nyeri dan peradangan pada sendi dan otot', 'Untuk meredakan gejala radang sendi atau nyeri karena keseleo, oleskan Kaltrofen gel sebanyak 2–4 gram (kira-kira 5–10 cm gel) pada area yang sakit, 2–4 kali sehari. Lama pengobatan maksimal 7 hari.', '["Kaltrofen Gel", "seperti Kaltrofen gel", "penyakit liver", "termasuk obat oles lain", "produk herbal", "seperti luka"]', '["termasuk obat oles lain", "kaltrofen gel", "penyakit liver", "ka1trofen ge1", "kaltrofen ge", "seperti kaltrofen gel", "kaltrof3n g3l", "produk herbal", "kaitrofen gei", "kaltr0fen gel", "k4ltrofen gel", "kltrofen gel", "kaltrophen gel", "ketoprofen"]', '["k4ltrofen gel", "ka1trofen ge1", "kaitrofen gei", "kaltr0fen gel", "kaltrof3n g3l", "kaltrofen ge", "kaltrophen gel", "kltrofen gel"]', 'DKL10001246A1', 'kaltrofengel', 'ketoprofen');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('panadol-flu-dan-batuk', 'Panadol Flu dan Batuk', 'Paracetamol , phenylephrine , dan dextromethorphan', 'Kombinasi analgetik-antipiretik , dekongestan , dan antitusif', 'Obat Bebas Terbatas (Lingkaran Biru)', 'Kaplet', 'Meredakan gejala flu, seperti demam, sakit kepala, dan hidung tersumbat, yang disertai batuk tidak berdahak', 'Gunakan Panadol Flu dan Batuk sesuai petunjuk pada kemasan obat, atau ikuti anjuran dokter. Jangan menggunakan Panadol Flu dan Batuk melebihi dosis yang dianjurkan atau menggunakannya bersama obat lain yang juga mengandung paracetamol.', '["Panadol Flu dan Batuk"]', '["paracetamol , phenylephrine , dan dextromethorphan", "panado1 f1u dan batuk", "panadol flu dan batuk", "p4n4dol flu d4n b4tuk", "panadol phlu dan batuk", "pnadol flu dan batuk", "panad0l flu dan batuk", "panadoi fiu dan batuk", "panadol flu dan batu"]', '["p4n4dol flu d4n b4tuk", "panad0l flu dan batuk", "panado1 f1u dan batuk", "panadoi fiu dan batuk", "panadol flu dan batu", "panadol phlu dan batuk", "pnadol flu dan batuk"]', 'DTL10001904A1', 'panadolfludanbatuk', 'paracetamolphenylephrinedandextromethorphan');
