INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('baloxavir-marboxil', 'Baloxavir Marboxil', 'Baloxavir Marboxil', 'Obat antivirus', 'Obat Keras (Lingkaran Merah K)', 'Tablet', 'Mengobati influenza', 'Baloxavir marboxil akan diberikan oleh dokter. Secara umum, dosis obat ini untuk mengobati influenza akut pada orang dewasa dan anak usia lebih dari 12 tahun sesuai dengan berat badannya adalah sebagai berikut:', '["Baloxavir Marboxil", "suplemen", "menyusui", "zat besi", "magnesium", "zinc"]', '["magnesium", "baioxavir marboxii", "ba1oxavir marboxi1", "baloxavir rnarboxil", "baloxavir marboxil", "baloxavir marboxi", "b4lox4vir m4rboxil", "baloxav1r marbox1l", "menyusui", "suplemen", "bal0xavir marb0xil", "baloksavir marboksil", "zat besi"]', '["b4lox4vir m4rboxil", "ba1oxavir marboxi1", "baioxavir marboxii", "bal0xavir marb0xil", "baloksavir marboksil", "baloxav1r marbox1l", "baloxavir marboxi", "baloxavir rnarboxil"]', 'DKL10001798A1', 'baloxavirmarboxil', 'baloxavirmarboxil');
