INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('balsem-lang', 'Balsem Lang', 'Balsem Lang', 'Obat herbal', 'Obat Bebas (Hijau)', 'Balsam', 'Meredakan pusing, masuk angin , pegal-pegal, nyeri sendi , keseleo, melegakan pernapasan, mabuk perjalanan, dan gatal-gatal karena gigitan serangga .', 'Oleskan Balsem Lang pada area tubuh yang nyeri sebanyak 3–4 kali sehari. Apabila dibutuhkan, pengolesan dapat diulangi secukupnya.', '["Balsem Lang"]', '["b4lsem l4ng", "ba1sem 1ang", "blsem lang", "balsem lan", "baisem iang", "bals3m lang", "balsem lang", "bal5em lang", "balsern lang"]', '["b4lsem l4ng", "ba1sem 1ang", "baisem iang", "bal5em lang", "bals3m lang", "balsem lan", "balsern lang", "blsem lang"]', 'DBL10001014A1', 'balsemlang', 'balsemlang');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('elomep', 'Elomep', 'Mometasone furoate 0,1%', 'Obat kortikosteroid topikal', 'Obat Keras (Lingkaran Merah K)', 'Krim', 'Mengatasi gejala peradangan di kulit akibat eksim, dermatitis , reaksi alergi, atau psoriasis', 'Berikut ini adalah dosis umum penggunaan Elomep untuk mengatasi gejala peradangan di kulit akibat eksim, psoriasis, maupun reaksi alergi:', '["Elomep"]', '["mometasone furoate 0,1%", "eomep", "e1omep", "3lom3p", "elomep", "elornep", "eiomep", "el0mep", "elome"]', '["3lom3p", "e1omep", "eiomep", "el0mep", "elome", "elornep", "eomep"]', 'DKL10000610A1', 'elomep', 'mometasonefuroate01');
