INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('harvit-d-1000-iu', 'Harvit D 1000 IU', 'Cholecalciferol (vitamin D3)', 'Suplemen vitamin', 'Obat Bebas (Hijau)', 'Kaplet salut selaput', 'Membantu memenuhi kebutuhan vitamin D dan menjaga kesehatan tulang .', 'Dosis Harvit D 100 IU biasanya disesuaikan dengan usia, kondisi, dan kebutuhan vitamin D setiap individu. Secara umum, dosis Harvit D 100 IU yang bisa dikonsumsi adalah 1 tablet, 1 kali sehari, setelah makan.', '["Harvit D 1000 IU"]', '["harvlt d 1000 lu", "harv1t d 1000 1u", "hrvit d 1000 iu", "cholecalciferol (vitamin d3)", "harvit d 1000 iu", "harvit d 1000 i", "h4rvit d 1000 iu"]', '["h4rvit d 1000 iu", "harv1t d 1000 1u", "harvit d 1000 i", "harvlt d 1000 lu", "hrvit d 1000 iu"]', 'DBL10001137A1', 'harvitd1000iu', 'cholecalciferolvitamind3');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('kaltrofen-supositoria', 'Kaltrofen Supositoria', 'Ketoprofen', 'Obat antiinflamasi nonsteroid ( NSAID )', 'Obat Keras (Lingkaran Merah K)', 'Supositoria', 'Meredakan gejala radang sendi pada rheumatoid arthritis , osteoarthritis, ankylosing spondylitis , atau penyakit asam urat', 'Dosis Kaltrofen supositoria untuk meringankan gejala radang sendi adalah 1 supositoria, 2 kali sehari. Jika dikombinasikan dengan Kaltrofen tablet, dosis Kaltrofen supositoria yang dianjurkan adalah 1 supositoria 1 kali sehari.', '["Kaltrofen Supositoria"]', '["kaltrofen 5upo5itoria", "k4ltrofen supositori4", "kaltrofen supositori", "ka1trofen supositoria", "kaltrofen supositoria", "kaitrofen supositoria", "kaltr0fen sup0sit0ria", "ketoprofen", "kaltrof3n supositoria", "kaltrofen supos1tor1a"]', '["k4ltrofen supositori4", "ka1trofen supositoria", "kaitrofen supositoria", "kaltr0fen sup0sit0ria", "kaltrof3n supositoria", "kaltrofen 5upo5itoria", "kaltrofen supos1tor1a", "kaltrofen supositori"]', 'DKL10002152A1', 'kaltrofensupositoria', 'ketoprofen');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('alif', 'Alif', 'Naproxen 500 mg per kaplet', 'Obat antiinflamasi nonsteroid ( NSAID )', 'Obat Keras (Lingkaran Merah K)', 'Kaplet', 'Meringankan gejala radang sendi pada rheumatoid arthritis , osteoarthritis , ankylosing spondylitis , atau serangan gout (asam urat)', 'Berikut adalah rekomendasi dosis naproxen dalam Alif berdasarkan tujuan penggunaannya:', '["Alif"]', '["4lif", "aliph", "allf", "alif", "naproxen 500 mg per kaplet", "al1f", "aiif", "a1if"]', '["4lif", "a1if", "aiif", "al1f", "aliph", "allf"]', 'DKL10000380A1', 'alif', 'naproxen500mgperkaplet');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('urlicon', 'Urlicon', 'Asam ursodeoksikolat 250 mg', 'Derivat asam empedu', 'Obat Keras (Lingkaran Merah K)', 'Kapsul', 'Melarutkan batu empedu ukuran kecil, mencegah terbentuknya batu empedu pada pasien yang menjalani penurunan berat badan dengan cepat, serta mengatasi kolangitis bilier primer (PBC).', 'Dosis Urlicon pada setiap pasien tergantung pada usia, kondisi kesehatan, berat badan, dan respons tubuh pasien terhadap obat. Namun, dosis obat ini pada orang dewasa umumnya adalah 2 kali per hari, 1 kapsul.', '["Urlicon"]', '["urllcon", "urlicon", "ur1icon", "asam ursodeoksikolat 250 mg", "uriicon", "ulicon", "urlico", "urlison", "urlic0n", "url1con"]', '["ulicon", "ur1icon", "uriicon", "url1con", "urlic0n", "urlico", "urlison", "urllcon"]', 'DKL10000732A1', 'urlicon', 'asamursodeoksikolat250mg');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('salven', 'Salven', 'Salbutamol Inhalasi 1 mg', 'Bronkodilator', 'Obat Keras (Lingkaran Merah K)', 'Inhaler', 'Meredakan gejala sesak napas akibat asma atau PPOK', 'Dosis penggunaan Salven berbeda-beda, tergantung pada usia, kondisi medis, dan tingkat keparahannya. Berikut ini adalah dosis umum penggunaan Salven:', '["Salven"]', '["salven", "salv3n", "salve", "5alven", "sa1ven", "saiven", "salbutamol inhalasi 1 mg", "slven", "s4lven"]', '["5alven", "s4lven", "sa1ven", "saiven", "salv3n", "salve", "slven"]', 'DKL10000617A1', 'salven', 'salbutamolinhalasi1mg');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('aliskiren', 'Aliskiren', 'Aliskiren', 'Penghambat renin ( renin inhibitor )', 'Obat Keras (Lingkaran Merah K)', 'Tablet', 'Menangani hipertensi', 'Dosis umum aliskiren untuk mengatasi hipertensi pada orang dewasa adalah 150 mg, 1 kali sehari. Bila diperlukan, dosis dapat ditingkatkan menjadi 300 mg, 1 kali sehari.', '["Aliskiren", "penyakit ginjal", "penyakit jantung", "seperti diare atau muntah-muntah", "termasuk suplemen dan produk herbal", "mungkin hamil"]', '["penyakit ginjal", "penyakit jantung", "aiskiren", "seperti diare atau muntah-muntah", "aliskire", "ali5kiren", "aliskiren", "a1iskiren", "al1sk1ren", "termasuk suplemen dan produk herbal", "aliskir3n", "4liskiren", "aiiskiren"]', '["4liskiren", "a1iskiren", "aiiskiren", "aiskiren", "al1sk1ren", "ali5kiren", "aliskir3n", "aliskire"]', 'DKL10000930A1', 'aliskiren', 'aliskiren');
