INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('nabumetone', 'Nabumetone', 'Nabumetone', 'Obat antiinflamasi nonsteroid ( OAINS )', 'Obat Keras (Lingkaran Merah K)', 'Tablet', 'Mengatasi gejala arthritis , seperti osteoarthritis dan rheumatoid arthritis', 'Dosis nabumetone untuk meredakan gejala radang sendi adalah 1.000 mg 1 kali sehari sebelum tidur. Jika perlu, bisa diberikan dosis tambahan sebanyak 500–1.000 mg pada pagi hari.', '["Nabumetone", "penyakit hati", "hipertensi", "penyakit ginjal", "perdarahan saluran pencernaan", "diabetes"]', '["penyakit ginjal", "n4bumetone", "hipertensi", "nabum3ton3", "perdarahan saluran pencernaan", "naburnetone", "penyakit hati", "nabumet0ne", "nabumetone", "nbumetone", "nabumeton"]', '["n4bumetone", "nabum3ton3", "nabumet0ne", "nabumeton", "naburnetone", "nbumetone"]', 'DKL10001038A1', 'nabumetone', 'nabumetone');
