INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('panadol-hijau', 'Panadol Hijau', 'Paracetamol , pseudoephedrine , dan dextromethorphan', 'Kombinasi analgetik-antipiretik , antitusif, dan dekongestan', 'Obat Bebas Terbatas (Lingkaran Biru)', 'Kaplet', 'Meredakan gejala flu, seperti demam, sakit kepala, dan hidung tersumbat, yang disertai batuk tidak berdahak', 'Gunakan Panadol Cold and Flu sesuai petunjuk pada kemasan obat, atau ikuti anjuran dokter. Jangan menggunakan Panadol hijau melebihi dosis yang dianjurkan atau menggunakannya bersama obat lain yang juga mengandung paracetamol.', '["Panadol Hijau"]', '["panadol hijau", "panadoi hijau", "panadol h1jau", "panadol hljau", "p4n4dol hij4u", "paracetamol , pseudoephedrine , dan dextromethorphan", "panado1 hijau", "panadol hija", "pnadol hijau", "panad0l hijau"]', '["p4n4dol hij4u", "panad0l hijau", "panado1 hijau", "panadoi hijau", "panadol h1jau", "panadol hija", "panadol hljau", "pnadol hijau"]', 'DTL10001232A1', 'panadolhijau', 'paracetamolpseudoephedrinedandextromethorphan');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('kalxetin', 'Kalxetin', 'Fluoxetine', 'Antidepresan selective serotonin reuptake inhibitors ( SSRIs )', 'Obat Keras (Lingkaran Merah K)', 'Kapsul', 'Mengatasi depresi, gangguan obsesif kompulsif, serangan panik, bulimia nervosa, atau gangguan disforik pramenstruasi', 'Berikut ini adalah dosis umum fluoxetine di dalam Kalxetin berdasarkan kondisi yang ditangani:', '["Kalxetin"]', '["kalxeti", "kalxet1n", "kalksetin", "kaixetin", "k4lxetin", "kalx3tin", "ka1xetin", "kalxetln", "fluoxetine", "kalxetin"]', '["k4lxetin", "ka1xetin", "kaixetin", "kalksetin", "kalx3tin", "kalxet1n", "kalxeti", "kalxetln"]', 'DKL10000832A1', 'kalxetin', 'fluoxetine');
