INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('elomox-cream', 'Elomox Cream', 'Mometasone furoate', 'Kortikosteroid topikal', 'Obat Keras (Lingkaran Merah K)', 'Krim', 'Mengatasi keluhan akibat kondisi radang kulit, seperti pada eksim, reaksi alergi, dermatitis, atau psoriasis', 'Untuk mengatasi radang kulit pada dermatitis atopik, reaksi alergi, atau psoriasis, gunakan Elomox cream 1 kali sehari sampai gejala mereda. Lama pengobatan maksimal 3 minggu.', '["Elomox Cream"]', '["elomoks cream", "elomox cream", "e1omox cream", "3lomox cr3am", "elomox sream", "elomox cre4m", "eiomox cream", "mometasone furoate", "el0m0x cream", "elomox crea"]', '["3lomox cr3am", "e1omox cream", "eiomox cream", "el0m0x cream", "elomoks cream", "elomox cre4m", "elomox crea", "elomox sream"]', 'DKL10001148A1', 'elomoxcream', 'mometasonefuroate');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('panagrip', 'Panagrip', 'Paracetamol', 'Analgetik-antipiretik', 'Obat Bebas (Hijau)', 'Tablet', 'Menurunkan demam', 'Dosis umum Panagrip untuk mengurangi nyeri dan menurunkan demam berdasarkan usia adalah sebagai berikut:', '["Panagrip"]', '["panagrlp", "pnagrip", "panagr1p", "panagrip", "p4n4grip", "panagri", "paracetamol"]', '["p4n4grip", "panagr1p", "panagri", "panagrlp", "pnagrip"]', 'DBL10000818A1', 'panagrip', 'paracetamol');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('zaldiar', 'Zaldiar', 'Paracetamol 325 mg dan tramadol HCl 37,5 mg', 'Obat pereda nyeri', 'Obat Keras (Lingkaran Merah K)', 'Tablet salut selaput', 'Meredakan nyeri', 'Berikut ini adalah dosis umum penggunaan Zaldiar untuk mengatasi nyeri sedang hingga berat:', '["Zaldiar"]', '["zaldia", "paracetamol 325 mg dan tramadol hcl 37,5 mg", "zaldlar", "za1diar", "zaldiar", "zldiar", "saldiar", "zaidiar", "zald1ar", "z4ldi4r"]', '["saldiar", "z4ldi4r", "za1diar", "zaidiar", "zald1ar", "zaldia", "zaldlar", "zldiar"]', 'DKL10000711A1', 'zaldiar', 'paracetamol325mgdantramadolhcl375mg');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('alitretinoin', 'Alitretinoin', 'Alitretinoin', 'Retinoid', 'Obat Keras (Lingkaran Merah K)', 'Gel, kapsul', 'Mengatasi lesi pada kulit yang disebabkan oleh sarkoma Kaposi dan eksim parah', 'Berikut ini adalah dosis umum penggunaan alitretinoin pada orang dewasa berdasarkan kondisi pasien dan bentuk obat:', '["Alitretinoin", "gagal ginjal", "hiperkolesterolemia", "hipotirodisme", "suplemen", "menyusui"]', '["al1tret1no1n", "aiitretinoin", "hipotirodisme", "alitretinoin", "alitr3tinoin", "gagal ginjal", "aitretinoin", "alitretin0in", "alitretinoi", "suplemen", "hiperkolesterolemia", "4litretinoin", "a1itretinoin"]', '["4litretinoin", "a1itretinoin", "aiitretinoin", "aitretinoin", "al1tret1no1n", "alitr3tinoin", "alitretin0in", "alitretinoi"]', 'DKL10001266A1', 'alitretinoin', 'alitretinoin');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('urogall', 'Urogall', 'Asam ursodeoksikolat 250 mg', 'Derivat asam empedu', 'Obat Keras (Lingkaran Merah K)', 'Kapsul', 'Melarutkan batu empedu ukuran kecil, mencegah terbentuknya batu empedu pada pasien yang menjalani penurunan berat badan dengan cepat, serta mengatasi kolangitis bilier primer (PBC).', 'Dosis Urogall ditentukan berdasarkan kondisi pasien, berat badan, dan respons terhadap pengobatan. Berikut merupakan dosis Urogall yang umumnya diberikan, berdasarkan tujuan pengobatan:', '["Urogall"]', '["urog4ll", "urogal", "asam ursodeoksikolat 250 mg", "urogaii", "ur0gall", "urogall", "uroga11", "uogall"]', '["uogall", "ur0gall", "urog4ll", "uroga11", "urogaii", "urogal"]', 'DKL10000726A1', 'urogall', 'asamursodeoksikolat250mg');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('abbotic', 'Abbotic', 'Clarithromycin', 'Antibiotik makrolid', 'Obat Keras (Lingkaran Merah K)', 'Tablet salut selaput dan sirop kering', 'Mengobati infeksi bakteri', 'Dokter akan memberitahu pasien dosis penggunaan Abbotic ketika memberikan e-resep atau resep langsung. Setiap pasien akan diberikan dosis yang berbeda karena pengobatan akan disesuaikan dengan kondisi pasien.', '["Abbotic"]', '["abbot1c", "abb0tic", "4bbotic", "abboti", "abotic", "abbotlc", "clarithromycin", "abbotis", "abbotic"]', '["4bbotic", "abb0tic", "abbot1c", "abboti", "abbotis", "abbotlc", "abotic"]', 'DKL10000692A1', 'abbotic', 'clarithromycin');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('elox', 'Elox', 'Mometasone furoate 0.1%', 'Obat kortikosteroid', 'Obat Keras (Lingkaran Merah K)', 'Krim', 'Mengurangi gejala peradangan pada kulit yang disebabkan oleh reaksi alergi , dermatitis seboroik , eksim, dan psoriasis.', 'Oleskan Elox ke area kulit yang bermasalah secara tipis-tipis 1 kali sehari. Jangan tutup area yang diobati dengan perban, kecuali bila memang disarankan oleh dokter.', '["Elox"]', '["mometasone furoate 0.1%", "eloks", "el0x", "3lox", "e1ox", "eiox", "elox"]', '["3lox", "e1ox", "eiox", "el0x", "eloks"]', 'DKL10000408A1', 'elox', 'mometasonefuroate01');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('baquinor', 'Baquinor', 'Ciprofloxacin', 'Antibiotik jenis quinolone', 'Obat Keras (Lingkaran Merah K)', 'Tablet, kaplet, infus', 'Mengatasi infeksi bakteri', 'Berikut ini adalah dosis umum penggunaan Baquinor berdasarkan kondisi pasien:', '["Baquinor"]', '["baqu1nor", "b4quinor", "baquinor", "baqulnor", "bquinor", "ciprofloxacin", "baquino", "baquin0r"]', '["b4quinor", "baqu1nor", "baquin0r", "baquino", "baqulnor", "bquinor"]', 'DKL10000833A1', 'baquinor', 'ciprofloxacin');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('nadolol', 'Nadolol', 'Nadolol', 'Penghambat beta', 'Obat Keras (Lingkaran Merah K)', 'Tablet', 'Menurunkan tekanan darah pada hipertensi, meredakan angina pektoris, dan mengobati gangguan irama jantung', 'Berikut adalah dosis nadolol sesuai kondisi yang ingin ditangani dan usia pasien:', '["Nadolol", "meredakan angina pektoris", "gagal jantung yang berat", "sindrom Raynaud", "penyakit ginjal", "PPOK"]', '["penyakit ginjal", "nado1o1", "nadoioi", "n4dolol", "ndolol", "nadolo", "nad0l0l", "meredakan angina pektoris", "sindrom raynaud", "gagal jantung yang berat", "nadolol"]', '["n4dolol", "nad0l0l", "nado1o1", "nadoioi", "nadolo", "ndolol"]', 'DKL10000713A1', 'nadolol', 'nadolol');
