INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('kamaflam', 'Kamaflam', 'Diclofenac potassium 50 mg', 'Obat anti inflamasi nonsteroid (OAINS)', 'Obat Keras (Lingkaran Merah K)', 'Tablet salut gula', 'Meredakan nyeri dan gejala peradangan, seperti nyeri dan bengkak pada kondisi nyeri sendi, nyeri setelah cedera, nyeri haid, dan nyeri setelah operasi.', 'Agar Kamaflam bekerja optimal dan aman digunakan, dosis obat ini harus disesuaikan dengan kondisi medis serta respons tubuh masing-masing pasien. Oleh karena itu, dokter dosis yang diresepkan dokter antar pasien bisa berbeda.', '["Kamaflam"]', '["kamaf1am", "kamafla", "k4m4fl4m", "karnaflarn", "kmaflam", "kamafiam", "kamaphlam", "diclofenac potassium 50 mg", "kamaflam"]', '["k4m4fl4m", "kamaf1am", "kamafiam", "kamafla", "kamaphlam", "karnaflarn", "kmaflam"]', 'DKL10000794A1', 'kamaflam', 'diclofenacpotassium50mg');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('baquinor-forte', 'Baquinor Forte', 'Ciprofloxacin 500 mg', 'Antibiotik jenis quinolone', 'Obat Keras (Lingkaran Merah K)', 'Tablet salut selaput', 'Mengatasi infeksi bakteri', 'Berikut ini adalah rekomendasi dosis ciprofloxacin yang terkandung dalam Baquinor Forte berdasarkan kondisi dan usia pasien:', '["Baquinor Forte"]', '["b4quinor forte", "bquinor forte", "baquinor forte", "baqulnor forte", "baquinor fort3", "ciprofloxacin 500 mg", "baquinor fort", "baqu1nor forte", "baquinor phorte", "baquin0r f0rte"]', '["b4quinor forte", "baqu1nor forte", "baquin0r f0rte", "baquinor fort", "baquinor fort3", "baquinor phorte", "baqulnor forte", "bquinor forte"]', 'DKL10001377A1', 'baquinorforte', 'ciprofloxacin500mg');
