INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('nadroparin', 'Nadroparin', 'Nadroparin', 'Antikoagulan', 'Obat Keras (Lingkaran Merah K)', 'Suntik', 'Mencegah dan mengatasi penggumpalan darah, seperti pada deep vein thrombosis dan emboli paru', 'Nadroparin dapat disuntikkan secara subkutan (di bawah kulit/SC), intravena (lewat pembuluh darah vena/IV), atau intraarterial (melalui pembuluh darah arteri).', '["Nadroparin", "misalnya batuk darah", "urine berdarah", "telinga", "mata", "hipertensi"]', '["nadr0parin", "nadroparln", "nadroparin", "nadropar1n", "ndroparin", "misalnya batuk darah", "n4drop4rin", "urine berdarah", "mata", "telinga", "nadropari"]', '["n4drop4rin", "nadr0parin", "nadropar1n", "nadropari", "nadroparln", "ndroparin"]', 'DKL10001038A1', 'nadroparin', 'nadroparin');
