INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('sambiloto', 'Sambiloto', 'Sambiloto', 'Pengobatan Umum', 'Obat Keras (Lingkaran Merah K)', 'Sediaan oral/topikal sesuai instruksi kemasan.', 'Meredakan gejala flu , seperti demam, sakit tenggorokan, bersin-bersin, dan batuk pilek.', 'Gunakan sesuai petunjuk dokter atau aturan pakai pada kemasan.', '["Sambiloto"]', '["sambi1oto", "sambiioto", "5ambiloto", "samblloto", "samb1loto", "sambil0t0", "s4mbiloto", "sambilot", "sambiloto"]', '["5ambiloto", "s4mbiloto", "samb1loto", "sambi1oto", "sambiioto", "sambil0t0", "sambilot", "samblloto"]', 'DKL10000938A1', 'sambiloto', 'sambiloto');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('elp', 'Elp', 'Escitalopram', 'Antidepresan jenis selective serotonin reuptake inhibitors (SSRIs)', 'Obat Keras (Lingkaran Merah K)', 'Tablet salut selaput', 'Mengatasi gejala depresi , gangguan kecemasan, gangguan obsesif kompulsif, serangan panik, atau fobia sosial', 'Berikut ini adalah dosis umum penggunaan Elp berdasarkan kondisi pasien:', '["Elp"]', '["escitalopram", "elp", "e1p", "eip", "3lp"]', '["3lp", "e1p", "eip"]', 'DKL10000289A1', 'elp', 'escitalopram');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('helixim', 'Helixim', 'Cefixime', 'Antibiotik golongan sefalosporin', 'Obat Keras (Lingkaran Merah K)', 'Kapsul dan sirop kering', 'Mengobati penyakit akibat infeksi bakteri, termasuk radang amandel , otitis media , dan infeksi saluran kemih', 'Dosis Helixim yang diberikan oleh dokter akan disesuaikan dengan bentuk obat yang digunakan, serta usia dan berat badan (BB) pasien. Secara umum, berikut adalah dosis Helixim berdasarkan sediaan obatnya:', '["Helixim"]', '["he1ixim", "helixi", "cefixime", "helixirn", "hellxlm", "heliksim", "hel1x1m", "helixim", "heiixim", "h3lixim"]', '["h3lixim", "he1ixim", "heiixim", "hel1x1m", "heliksim", "helixi", "helixirn", "hellxlm"]', 'DKL10000720A1', 'helixim', 'cefixime');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('pancuronium', 'Pancuronium', 'Pancuronium', 'Obat resep', 'Obat Keras (Lingkaran Merah K)', 'Suntik', 'Merelaksasikan otot saat intubasi endotrakeal atau selama operasi', 'Pancuronium diberikan dengan cara disuntikkan ke dalam pembuluh darah vena (intravena) oleh dokter atau petugas medis di bawah pengawasan dokter. Di bawah ini adalah pembagian dosis pancuronium berdasarkan tujuan penggunaannya:', '["Pancuronium", "penyakit ginjal", "penyakit jantung", "hipertensi", "gangguan saraf dan otot neuromuskular", "termasuk distrofi otot"]', '["penyakit ginjal", "penyakit jantung", "pancuron1um", "pancuronlum", "hipertensi", "pancur0nium", "pancuroniu", "pncuronium", "pancuronium", "gangguan saraf dan otot neuromuskular", "pansuronium", "pancuroniurn", "p4ncuronium"]', '["p4ncuronium", "pancur0nium", "pancuron1um", "pancuroniu", "pancuroniurn", "pancuronlum", "pansuronium", "pncuronium"]', 'DKL10001169A1', 'pancuronium', 'pancuronium');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('zantifar', 'Zantifar', 'Ranitidin', 'Antagonis reseptor H2', 'Obat Keras (Lingkaran Merah K)', 'Kaplet salut selaput', 'Mengatasi sakit maag, tukak lambung, GERD, dan kondisi akibat kelebihan asam lambung', 'Dosis Zantifar bisa berbeda pada tiap orang, tergantung dari jenis gangguan yang dialami, seberapa parah kondisinya, serta usia pasien. Umumnya, Zantifar tersedia dalam bentuk tablet atau suntikan, dan berikut ini adalah panduan penggunaannya secara umum:', '["Zantifar"]', '["zantifar", "zntifar", "zantifa", "ranitidin", "zantlfar", "z4ntif4r", "zant1far", "zantiphar", "santifar"]', '["santifar", "z4ntif4r", "zant1far", "zantifa", "zantiphar", "zantlfar", "zntifar"]', 'DKL10000831A1', 'zantifar', 'ranitidin');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('v-soy-multi-grain', 'V-Soy Multi-Grain', 'V-Soy Multi-Grain', 'Minuman susu kedelai', 'Obat Keras (Lingkaran Merah K)', 'Minuman', 'Memberikan manfaat susu kedelai dan biji-bijian bagi kesehatan', 'Gunakan sesuai petunjuk dokter atau aturan pakai pada kemasan.', '["V-Soy Multi-Grain"]', '["v-soy multi-grain", "v-soy multi-grai", "v-5oy multi-grain", "v-soy multi-gr4in", "v-soy mu1ti-grain", "v-soy mult1-gra1n", "v-soy multl-graln", "v-soy muiti-grain", "v-s0y multi-grain"]', '["v-5oy multi-grain", "v-s0y multi-grain", "v-soy mu1ti-grain", "v-soy muiti-grain", "v-soy mult1-gra1n", "v-soy multi-gr4in", "v-soy multi-grai", "v-soy multl-graln"]', 'DKL10001543A1', 'vsoymultigrain', 'vsoymultigrain');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('zanamivir', 'Zanamivir', 'Zanamivir', 'Obat antivirus penghambat neuraminidase', 'Obat Keras (Lingkaran Merah K)', 'Serbuk inhalasi oral', 'Mencegah dan mengatasi influenza', 'Dosis zanamivir akan ditentukan oleh dokter sesuai tujuan penggunaan, usia, dan kondisi pasien. Secara umum, dosis zanamivir serbuk inhalasi oral adalah sebagai berikut:', '["Zanamivir", "penyakit paru obstruktif kronis", "gagal ginjal", "penyakit jantung", "ensefalopati", "kejang"]', '["penyakit jantung", "zanamlvlr", "zanamivir", "z4n4mivir", "zanam1v1r", "penyakit paru obstruktif kronis", "gagal ginjal", "ensefalopati", "zanarnivir", "zanamivi", "sanamivir", "znamivir"]', '["sanamivir", "z4n4mivir", "zanam1v1r", "zanamivi", "zanamlvlr", "zanarnivir", "znamivir"]', 'DKL10000945A1', 'zanamivir', 'zanamivir');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('baquinor-tetes-mata', 'Baquinor Tetes Mata', 'Ciprofloxacin', 'Antibiotik jenis quinolone', 'Obat Keras (Lingkaran Merah K)', 'Tetes mata', 'Mengatasi infeksi bakteri di mata', 'Berikut ini adalah dosis umum penggunaan Baquinor Tetes Mata untuk dewasa dan anak usia ≥1 tahun berdasarkan kondisi pasien:', '["Baquinor Tetes Mata"]', '["baquinor tete5 mata", "baqu1nor tetes mata", "baquinor t3t3s mata", "baquin0r tetes mata", "baquinor tetes mat", "baqulnor tetes mata", "b4quinor tetes m4t4", "ciprofloxacin", "baquinor tetes rnata", "baquinor tetes mata"]', '["b4quinor tetes m4t4", "baqu1nor tetes mata", "baquin0r tetes mata", "baquinor t3t3s mata", "baquinor tete5 mata", "baquinor tetes mat", "baquinor tetes rnata", "baqulnor tetes mata"]', 'DKL10001801A1', 'baquinortetesmata', 'ciprofloxacin');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('hemaviton-c', 'Hemaviton C', 'Buffered vitamin C, vitamin D3 , dan zinc', 'Suplemen kesehatan', 'Obat Bebas (Hijau)', 'Botol kaca dan kaleng', 'Membantu meningkatkan sistem kekebalan tubuh', 'Hemaviton C dapat dikonsumsi 1 botol atau kaleng, 1 kali sehari.', '["Hemaviton C"]', '["hemaviton s", "hemaviton c", "hernaviton c", "buffered vitamin c, vitamin d3 , dan zinc", "h3maviton c", "hemavit0n c", "hemavlton c", "hem4viton c", "hemav1ton c", "hemaviton "]', '["h3maviton c", "hem4viton c", "hemav1ton c", "hemavit0n c", "hemaviton ", "hemaviton s", "hemavlton c", "hernaviton c"]', 'DBL10001038A1', 'hemavitonc', 'bufferedvitamincvitamind3danzinc');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('kanamycin', 'Kanamycin', 'Kanamycin', 'Antibiotik golongan aminoglikosida', 'Obat Keras (Lingkaran Merah K)', 'Kapsul dan suntik', 'Mengobati infeksi bakteri', 'Dosis kanamycin berbeda-beda pada tiap pasien. Dokter akan memberikan dosis dan menentukan lama pengobatan sesuai dengan kondisi, usia, dan respons pasien. Kanamycin bisa diberikan dalam bentuk obat minum atau suntikan melalui pembuluh darah (intravena/IV) atau ke dalam otot (intramuskular/IM).', '["Kanamycin", "Kanamycin Capsules", "Kanamycin Meiji", "menyusui", "pendengaran", "berusia lansia"]', '["kanamycin meiji", "kanamycin", "kanamyci", "k4n4mycin", "kanamycin capsules", "kanamyc1n", "kanamycln", "kanamysin", "kanarnycin", "menyusui", "pendengaran", "knamycin"]', '["k4n4mycin", "kanamyc1n", "kanamyci", "kanamycln", "kanamysin", "kanarnycin", "knamycin"]', 'DKL10000923A1', 'kanamycin', 'kanamycin');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('naftidrofuryl-oxalate', 'Naftidrofuryl Oxalate', 'Naftidrofuryl Oxalate', 'Vasodilator', 'Obat Keras (Lingkaran Merah K)', 'Tablet', 'Mengatasi penyakit vaskular perifer dan penyakit serebrovaskuler', 'Berikut ini adalah dosis umum penggunaan naftidrofuryl oxalate berdasarkan kondisi yang akan diobati:', '["Naftidrofuryl Oxalate", "penyakit liver", "termasuk suplemen", "atau produk herbal", "menyusui", "mengunyah"]', '["naftidrofury1 oxa1ate", "penyakit liver", "naft1drofuryl oxalate", "n4ftidrofuryl ox4l4te", "naftidrofuryl oksalate", "naftidrofuryl oxalat", "naftidr0furyl 0xalate", "atau produk herbal", "menyusui", "naftidrofuryi oxaiate", "termasuk suplemen", "naftidrofuryl oxalat3", "naftidrofuryl oxalate"]', '["n4ftidrofuryl ox4l4te", "naft1drofuryl oxalate", "naftidr0furyl 0xalate", "naftidrofury1 oxa1ate", "naftidrofuryi oxaiate", "naftidrofuryl oksalate", "naftidrofuryl oxalat", "naftidrofuryl oxalat3"]', 'DKL10002135A1', 'naftidrofuryloxalate', 'naftidrofuryloxalate');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('pansiptin', 'Pansiptin', 'Sitagliptin', 'Antidiabetes golongan penghambat DPP-4 ( dipeptidyl peptidase 4 inhibitors )', 'Obat Keras (Lingkaran Merah K)', 'Tablet salut selaput', 'Mengontrol kadar gula darah pada penderita diabetes tipe 2', 'Dosis Pansiptin dalam pengobatan diabetes tipe 2 akan disesuaikan oleh dokter dengan kondisi kesehatan dan obat lain yang sedang digunakan oleh pasien. Secara umum, dosis sitagliptin pada Pansiptin adalah 100 mg, 1 kali sehari.', '["Pansiptin"]', '["pansiptin", "panslptln", "p4nsiptin", "pans1pt1n", "pnsiptin", "sitagliptin", "pansipti", "pan5iptin"]', '["p4nsiptin", "pan5iptin", "pans1pt1n", "pansipti", "panslptln", "pnsiptin"]', 'DKL10000950A1', 'pansiptin', 'sitagliptin');
