INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('faktu', 'Faktu', 'Policresulen 50 mg dan cinchocaine 10 mg', 'Antiinflamasi lokal & anestesi lokal', 'Obat Keras (Lingkaran Merah K)', 'Salep', 'Meredakan nyeri, inflamasi, gatal, sensasi panas, serta mempercepat penyembuhan luka pada hemoroid (wasir), fisura ani , dan iritasi di sekitar anus', 'Penggunaan Faktu harus mengikuti petunjuk dokter, karena takarannya bisa berbeda-beda, tergantung pada kondisi kulit. Untuk menangani wasir atau fisura ani, oleskan Faktu secukupnya 2-3 kali sehari.', '["Faktu"]', '["faktu", "policresulen 50 mg dan cinchocaine 10 mg", "phaktu", "f4ktu"]', '["f4ktu", "phaktu"]', 'DKL10000507A1', 'faktu', 'policresulen50mgdancinchocaine10mg');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('hepagusan', 'Hepagusan', 'Heparin sodium', 'Antikoagulan', 'Obat Bebas Terbatas (Lingkaran Biru)', 'Gel', 'Mengatasi memar, lebam, atau gumpalan darah akibat cedera maupun tindakan medis tertentu', 'Dosis umum penggunaan Hepagusan untuk mengatasi memar, lebam, atau gumpalan darah akibat cedera maupun tindakan medis tertentu adalah:', '["Hepagusan"]', '["hpagusan", "hepagu5an", "heparin sodium", "hepagusa", "hep4gus4n", "h3pagusan", "hepagusan"]', '["h3pagusan", "hep4gus4n", "hepagu5an", "hepagusa", "hpagusan"]', 'DTL10000924A1', 'hepagusan', 'heparinsodium');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('barole-20', 'Barole 20', 'R abeprazole', 'Penghambat pompa proton ( proton pump inhibitor )', 'Obat Keras (Lingkaran Merah K)', 'Kapsul', 'Mengurangi gejala asam lambung berlebih Membantu penyembuhan luka pada lambung atau usus dua belas jari Meredakan peradangan pada kerongkongan Membantu mengatasi infeksi Helicobacter pylori Mengatasi kondisi langka dengan produksi asam lambung berlebihan (sindrom Zollinger-Ellison)', 'Dosis Barole 20 dapat berbeda pada setiap orang, tergantung pada usia pasien, jenis penyakit, dan tingkat keparahan kondisinya. Berikut dosis umum rabeprazole dalam Barole 20 untuk berbagai kondisi:', '["Barole 20"]', '["baro1e 20", "r abeprazole", "barole 20", "baroie 20", "bar0le 20", "barole 2", "b4role 20", "brole 20", "barol3 20"]', '["b4role 20", "bar0le 20", "baro1e 20", "baroie 20", "barol3 20", "barole 2", "brole 20"]', 'DKL10000727A1', 'barole20', 'rabeprazole');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('calquence', 'Calquence', 'Acalabrutinib', 'Penghambat protein kinase', 'Obat Keras (Lingkaran Merah K)', 'Kapsul', 'Mengobati leukemia limfostik kronis (LLK) atau limfoma limfostik kecil (LLS), dan limfoma sel mantel (LSM)', 'Berikut adalah dosis dan lama pemakaian Calquence yang umumnya disarankan oleh dokter:', '["Calquence"]', '["salquense", "acalabrutinib", "c4lquence", "ca1quence", "clquence", "caiquence", "calquenc", "calquence", "calqu3nc3"]', '["c4lquence", "ca1quence", "caiquence", "calqu3nc3", "calquenc", "clquence", "salquense"]', 'DKL10000913A1', 'calquence', 'acalabrutinib');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('pantoprazole', 'Pantoprazole', 'Pantoprazole', 'Penghambat pompa proton', 'Obat Keras (Lingkaran Merah K)', 'Tablet, kaplet, dan cairan suntik', 'Mengurangi produksi asam lambung', 'Dokter akan menentukan dosis dan lama pengobatan sesuai kondisi dan usia pasien. Pantoprazole bisa diberikan dalam bentuk obat minum, infus, atau suntik ke pembuluh darah vena (intravena/IV). Berikut adalah penjelasannya:', '["Pantoprazole", "Ciprazol", "Erprazol", "Fiopraz Fastzol", "Pantomex", "Pantopump"]', '["erprazol", "pant0praz0le", "pantomex", "pantoprazoie", "p4ntopr4zole", "fiopraz fastzol", "pantoprazol", "pntoprazole", "pantoprazole", "ciprazol", "pantoprasole", "pantera 20", "pantoprazol3", "pantoprazo1e"]', '["p4ntopr4zole", "pant0praz0le", "pantoprasole", "pantoprazo1e", "pantoprazoie", "pantoprazol", "pantoprazol3", "pntoprazole"]', 'DKL10001279A1', 'pantoprazole', 'pantoprazole');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('nairet', 'Nairet', 'Terbutaline', 'Bronkodilator', 'Obat Keras (Lingkaran Merah K)', 'Tablet, sirop, dan injeksi', 'Meringankan gejala batuk, sesak napas, atau mengi akibat asma atau PPOK', 'Dosis konsumsi Nairet akan ditentukan dokter berdasarkan usia, kondisi, dan respons tubuh pasien terhadap pengobatan. Berikut adalah dosis umum pemberian Nairet berdasarkan bentuk obat:', '["Nairet"]', '["nairet", "niret", "na1ret", "nalret", "nair3t", "terbutaline", "naire", "n4iret"]', '["n4iret", "na1ret", "nair3t", "naire", "nalret", "niret"]', 'DKL10000611A1', 'nairet', 'terbutaline');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('vagistin', 'Vagistin', 'Metronidazole 500 mg dan nystatin 100.000 IU', 'Kombinasi antimikroba (metronidazole) dan antijamur (nystatin)', 'Obat Keras (Lingkaran Merah K)', 'Ovula atau tablet vagina', 'Mengatasi infeksi vagina', 'Dosis Vagistin ditentukan oleh dokter sesuai kondisi pasien. Untuk mengatasi infeksi vagina, dosis Vagistin yang umum adalah 1 ovula per hari selama 7–10 hari berturut-turut.', '["Vagistin"]', '["vag1st1n", "vagi5tin", "metronidazole 500 mg dan nystatin 100.000 iu", "vagisti", "vgistin", "vaglstln", "vagistin", "v4gistin"]', '["v4gistin", "vag1st1n", "vagi5tin", "vagisti", "vaglstln", "vgistin"]', 'DKL10000837A1', 'vagistin', 'metronidazole500mgdannystatin100000iu');
