INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('barzepin', 'Barzepin', 'Oxcarbazepine', 'Antikonvulsan', 'Obat Keras (Lingkaran Merah K)', 'Kaplet salut selaput', 'Mengatasi kejang pada penderita epilepsi', 'Barzepin tersedia dalam bentuk kaplet 300 mg dan kaplet600 mg. Dosis Barzepin yang diberikan oleh dokter dapat berbeda, tergantung pada usia pasien.', '["Barzepin"]', '["brzepin", "barzepin", "oxcarbazepine", "barzepi", "barz3pin", "barzep1n", "b4rzepin", "barsepin", "barzepln"]', '["b4rzepin", "barsepin", "barz3pin", "barzep1n", "barzepi", "barzepln", "brzepin"]', 'DKL10000827A1', 'barzepin', 'oxcarbazepine');
