INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('heparin', 'Heparin', 'Heparin', 'Obat resep dan obat bebas terbatas', 'Obat Keras (Lingkaran Merah K)', 'Suntik, gel, dan salep', 'Mencegah dan mengobati penggumpalan darah', 'Dosis heparin akan ditentukan oleh dokter sesuai kondisi dan respons pasien terhadap pengobatan. Secara umum, berikut adalah dosis heparin berdasarkan bentuk obat dan tujuan pengobatannya:', '["Heparin", "Clotastop", "Heparinol", "Heparin Sodium", "Hepagusan", "Hico"]', '["hparin", "heparin", "heparin sodium", "h3parin", "hepar1n", "hep4rin", "hepagusan", "clotastop", "heparinol", "heparln", "hepari"]', '["h3parin", "hep4rin", "hepar1n", "hepari", "heparln", "hparin"]', 'DKL10000711A1', 'heparin', 'heparin');
