INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('pantopump', 'Pantopump', 'Pantoprazole', 'Penghambat pompa proton', 'Obat Keras (Lingkaran Merah K)', 'Tablet dan suntik', 'Mengurangi produksi asam lambung pada penyakit asam lambung (GERD) dan sindrom Zollinger-Ellison', 'Dosis Pantopump tergantung pada sediaan obat yang digunakan dan kondisi pasien. Secara umum, dosis Pantopump untuk mengurangi produksi asam lambung adalah sebagai berikut:', '["Pantopump"]', '["pantopum", "pantoprazole", "pantopump", "pntopump", "pant0pump", "p4ntopump", "pantopurnp"]', '["p4ntopump", "pant0pump", "pantopum", "pantopurnp", "pntopump"]', 'DKL10000964A1', 'pantopump', 'pantoprazole');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('vaksin-astrazeneca', 'Vaksin AstraZeneca', 'Vaksin AstraZeneca', 'Vaksin COVID-19', 'Obat Keras (Lingkaran Merah K)', 'Suntik', 'Mencegah COVID-19 atau infeksi virus SARS-Cov-2', 'Vaksin AstraZeneca akan diberikan langsung oleh dokter. Dosis dalam sekali suntik adalah 0,5 ml. Penyuntikan vaksin dilakukan sebanyak 2 kali dengan jarak 4–12 minggu. Vaksin ini akan disuntikkan ke dalam otot (intramuskular/IM).', '["Vaksin AstraZeneca", "lemahnya sistem kekebalan tubuh", "menyusui", "penyakit jantung dan pembuluh darah", "penyakit paru dan saluran pernapasan", "suplemen"]', '["vaksin astraz3n3ca", "vaksin astraseneca", "vaksin astrazeneca", "penyakit jantung dan pembuluh darah", "vak5in a5trazeneca", "vaksln astrazeneca", "vaks1n astrazeneca", "vaksin astrazenec", "vaksin astrazenesa", "menderita covid-19", "menyusui", "lemahnya sistem kekebalan tubuh", "v4ksin 4str4zenec4"]', '["v4ksin 4str4zenec4", "vak5in a5trazeneca", "vaks1n astrazeneca", "vaksin astraseneca", "vaksin astraz3n3ca", "vaksin astrazenec", "vaksin astrazenesa", "vaksln astrazeneca"]', 'DKL10001757A1', 'vaksinastrazeneca', 'vaksinastrazeneca');
