INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('camaag', 'Camaag', '200 mg aluminium hidroksida , 200 mg magnesium hidroksida , dan 50 mg simethicone', 'Kombinasi antasida dan antiflatulensi (antikembung)', 'Obat Bebas (Hijau)', 'Suspensi', 'Mengatasi keluhan sakit maag akibat kelebihan asam lambung, seperti pada kondisi gastritis, tukak lambung, dan ulkus duodenum', 'Untuk meredakan keluhan akibat kelebihan asam lambung atau peningkatan gas di dalam saluran pencernaan, Camaag dapat dikonsumsi sesuai dengan dosis umum penggunaannya berikut ini:', '["Camaag"]', '["carnaag", "camaag", "camaa", "samaag", "200 mg aluminium hidroksida , 200 mg magnesium hidroksida , dan 50 mg simethicone", "c4m44g", "cmaag"]', '["c4m44g", "camaa", "carnaag", "cmaag", "samaag"]', 'DBL10000570A1', 'camaag', '200mgaluminiumhidroksida200mgmagnesiumhidroksidadan50mgsimethicone');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('nalbuphine', 'Nalbuphine', 'Nalbuphine', 'Antinyeri golongan opioid', 'Obat Keras (Lingkaran Merah K)', 'Suntik', 'Meredakan rasa sakit atau nyeri sedang hingga berat', 'Dosis nalbuphine akan ditentukan oleh dokter berdasarkan usia, kondisi pasien, dan respons terhadap obat. Nalbuphine akan diberikan dalam bentuk suntikan melalui otot (IM/intramuskular), pembuluh darah vena (IV/intravena), atau bawah kulit (SC/subkutan).', '["Nalbuphine", "ileus paralitik", "penyalahgunaan napza", "sleep apnea", "penyakit jantung", "bradikardia"]', '["penyakit jantung", "na1buphine", "sleep apnea", "naibuphine", "nalbuph1ne", "n4lbuphine", "nalbuphlne", "penyalahgunaan napza", "ileus paralitik", "nalbuphin", "nalbuphin3", "nalbuphine", "nalbufine"]', '["n4lbuphine", "na1buphine", "naibuphine", "nalbufine", "nalbuph1ne", "nalbuphin", "nalbuphin3", "nalbuphlne"]', 'DKL10001030A1', 'nalbuphine', 'nalbuphine');
