INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('pantozol', 'Pantozol', 'Pantoprazole', 'Penghambat pompa proton', 'Obat Keras (Lingkaran Merah K)', 'Tablet dan suntik', 'Mengurangi produksi asam lambung pada penyakit asam lambung (GERD) dan sindrom Zollinger-Ellison', 'Dosis Pantozol akan disesuaikan dengan kondisi yang ditangani dan respons pasien terhadap pengobatan. Secara umum, dosis Pantozol untuk mengurangi produksi asam lambung adalah sebagai berikut:', '["Pantozol"]', '["pantozo", "pantozol", "pant0z0l", "pantosol", "pantozoi", "pntozol", "pantozo1", "pantoprazole", "p4ntozol"]', '["p4ntozol", "pant0z0l", "pantosol", "pantozo", "pantozo1", "pantozoi", "pntozol"]', 'DKL10000855A1', 'pantozol', 'pantoprazole');
