INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('zegavit', 'Zegavit', 'Tiap kaplet mengandung Vitamin E 30 IU, Vitamin C 750 mg, Vitamin B1 15 mg, Vitamin B2 15 mg, Niacinamide 100 mg, Vitamin B6 25 mg, Vitamin B12 12 mcg, Folic acid 0,4 mg, Calcium (dalam bentuk Calcium pantothenate dan Calcium carbonate) 20 mg, Pantothenic acid 20 mg, zinc 20 mg', 'Suplemen multivitamin dan mineral', 'Obat Tradisional / Jamu (Logo Pohon)', 'Kaplet salut selaput', 'Membantu memelihara kesehatan tubuh', 'Dosis umum penggunaan Zegavit untuk orang dewasa dan anak usia >12 tahun adalah 1 kaplet per hari.', '["Zegavit"]', '["segavit", "z3gavit", "zgavit", "zegavlt", "zegavi", "tiap kaplet mengandung vitamin e 30 iu, vitamin c 750 mg, vitamin b1 15 mg, vitamin b2 15 mg, niacinamide 100 mg, vitamin b6 25 mg, vitamin b12 12 mcg, folic acid 0,4 mg, calcium (dalam bentuk calcium pantothenate dan calcium carbonate) 20 mg, pantothenic acid 20 mg, zinc 20 mg", "zegavit", "zeg4vit", "zegav1t"]', '["segavit", "z3gavit", "zeg4vit", "zegav1t", "zegavi", "zegavlt", "zgavit"]', 'TR10000730A1', 'zegavit', 'tiapkapletmengandungvitamine30iuvitaminc750mgvitaminb115mgvitaminb215mgniacinamide100mgvitaminb625mgvitaminb1212mcgfolicacid04mgcalciumdalambentukcalciumpantothenatedancalciumcarbonate20mgpantothenicacid20mgzinc20mg');
