INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('katergi', 'Katergi', 'Mebhydrolin 50 mg', 'Antihistamin', 'Obat Keras (Lingkaran Merah K)', 'Tablet', 'Meredakan gejala alergi pada rhinitis alergi, konjungtivitis alergi, atau biduran', 'Dosis dan durasi pengobatan akan disesuaikan oleh dokter berdasarkan kondisi dan jenis penyakit pasien. Umumnya, dosis Katergi untuk mengatasi gejala alergi, seperti rhinitis alergi, konjungtivitis alergi, atau biduran, berdasarkan usia pasien adalah:', '["Katergi"]', '["katerg1", "katerg", "ktergi", "katergl", "k4tergi", "kat3rgi", "mebhydrolin 50 mg", "katergi"]', '["k4tergi", "kat3rgi", "katerg", "katerg1", "katergl", "ktergi"]', 'DKL10000711A1', 'katergi', 'mebhydrolin50mg');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('famotidine', 'Famotidine', 'Famotidine', 'Antagonis H-2 atau histamine 2 blocker', 'Obat Keras (Lingkaran Merah K)', 'Tablet, kaplet, dan tablet kunyah', 'Meredakan gejala sakit maag, tukak lambung, atau tukak usus dua belas jari (ulkus duodenum)', 'Famotidine digunakan untuk mengatasi penyakit yang disebabkan oleh asam lambung berlebih. Berikut adalah dosis umum famotidine berdasarkan kondisi yang diobati dan usia pasien:', '["Corocyd", "Famocid", "Famotidine", "Hufatidine", "Lexmodine", "Neosanmag"]', '["famot1d1ne", "famocid", "fam0tidine", "famotidin", "hufatidine", "famotldlne", "fmotidine", "famotidine", "f4motidine", "famotidin3", "corocyd", "farnotidine", "lexmodine"]', '["f4motidine", "fam0tidine", "famot1d1ne", "famotidin", "famotidin3", "famotldlne", "farnotidine", "fmotidine"]', 'DKL10001024A1', 'famotidine', 'famotidine');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('camastil', 'Camastil', 'Sildenafil', 'Obat penghambat phosphodiesterase-5 (PDE5)', 'Obat Keras (Lingkaran Merah K)', 'Tablet salut selaput', 'Mengatasi disfungsi ereksi ( impotensi ) atau lemah syahwat', 'Dosis umum sildenafil di dalam Camastil untuk mengatasi disfungsi ereksi adalah 1 tablet, dikonsumsi 1 jam sebelum berhubungan seksual. Dosis maksimal 2 tablet salut selaput Camastil.', '["Camastil"]', '["camastii", "camasti1", "carnastil", "camastil", "sildenafil", "camasti", "camastll", "cama5til", "camast1l", "c4m4stil"]', '["c4m4stil", "cama5til", "camast1l", "camasti", "camasti1", "camastii", "camastll", "carnastil"]', 'DKL10000814A1', 'camastil', 'sildenafil');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('alstein', 'Alstein', 'Acetylcysteine', 'Obat mukolitik (pengencer dahak)', 'Obat Keras (Lingkaran Merah K)', 'Kapsul', 'Mengencerkan dahak', 'Berikut ini adalah dosis umum penggunaan Alstein untuk berdasarkan tujuan pengobatan dan usia pasien:', '["Alstein"]', '["alst3in", "aistein", "alsteln", "4lstein", "a1stein", "al5tein", "alstei", "acetylcysteine", "alstein", "alste1n"]', '["4lstein", "a1stein", "aistein", "al5tein", "alst3in", "alste1n", "alstei", "alsteln"]', 'DKL10000720A1', 'alstein', 'acetylcysteine');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('vaksin-bcg', 'Vaksin BCG', 'Vaksin BCG', 'Vaksin', 'Obat Keras (Lingkaran Merah K)', 'Sediaan oral/topikal sesuai instruksi kemasan.', 'Mencegah tuberkulosis (TBC)', 'Vaksin BCG merupakan salah satu jenis vaksinasi yang wajib diberikan kepada anak. Sesuai dengan jadwal imunisasi yang dikeluarkan oleh IDAI (Ikatan Dokter Anak Indonesia), jadwal penyuntikan vaksin BCG bisa dilakukan dari bayi baru lahir sampai berusia 1 bulan.', '["Vaksin BCG", "BCG Vaccine", "BCG Vaccine SSI", "termasuk leukemia maupun limfoma", "terutama obat antibiotik", "imunosupresan"]', '["vaksin bcg", "bcg vaccine ssi", "vak5in bcg", "vksin bcg", "termasuk leukemia maupun limfoma", "vaks1n bcg", "terutama obat antibiotik", "vaksin bc", "vaksln bcg", "vaksin bsg", "bcg vaccine", "v4ksin bcg"]', '["v4ksin bcg", "vak5in bcg", "vaks1n bcg", "vaksin bc", "vaksin bsg", "vaksln bcg", "vksin bcg"]', 'DKL10000856A1', 'vaksinbcg', 'vaksinbcg');
