INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('heptaminol', 'Heptaminol', 'Heptaminol', 'Obat resep', 'Obat Keras (Lingkaran Merah K)', 'Tablet, suntik', 'Mengatasi hipotensi ortostastik atau meredakan gejala bronkospasme', 'Penggunaan heptaminol untuk menangani hipotensi ortostastik, bronkospasme, dan gangguan jantung tertentu akan ditentukan oleh dokter sesuai dengan keparahan penyakit dan kondisi tiap pasien.', '["Heptaminol", "Hept-A-Myl", "suplemen", "menyusui", "bronkospasme", "seperti sakit kepala"]', '["heptam1nol", "heptamino", "bronkospasme", "heptaminol", "heptaminoi", "hept-a-myl", "menyusui", "h3ptaminol", "suplemen", "heptamin0l", "heptamino1", "hept4minol", "heptamlnol"]', '["h3ptaminol", "hept4minol", "heptam1nol", "heptamin0l", "heptamino", "heptamino1", "heptaminoi", "heptamlnol"]', 'DKL10001041A1', 'heptaminol', 'heptaminol');
