INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('famoxol', 'Famoxol', 'Ambroxol 30 mg per tablet', 'Obat pengencer dahak jenis mukolitik', 'Obat Keras (Lingkaran Merah K)', 'Tablet', 'Mengencerkan dahak pada berbagai kondisi dengan batuk berdahak', 'Sebagai obat batuk berdahak, dosis Famoxol untuk dewasa dan anak usia >12 tahun adalah 1 tablet, 2–3 kali sehari. Sementara itu, untuk anak usia 6–12 tahun, dosisnya ½ tablet, 2–3 kali sehari.', '["Famoxol"]', '["fmoxol", "famoxoi", "f4moxol", "fam0x0l", "famoxo1", "ambroxol 30 mg per tablet", "farnoxol", "famoxo", "famoksol", "famoxol"]', '["f4moxol", "fam0x0l", "famoksol", "famoxo", "famoxo1", "famoxoi", "farnoxol", "fmoxol"]', 'DKL10000726A1', 'famoxol', 'ambroxol30mgpertablet');
