INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('baxiderm', 'Baxiderm', 'Mupirocin', 'Antibiotik', 'Obat Keras (Lingkaran Merah K)', 'Salep', 'Mengatasi infeksi bakteri di kulit', 'Oleskan Baxiderm salep ke kulit yang mengalami infeksi secara tipis-tipis, 2–3 kali sehari. Pengobatan dilakukan maksimal selama 10 hari. Jika salep sudah digunakan secara rutin selama 3–5 hari, tetapi infeksi kulit tidak juga membaik, sebaiknya konsultasikan kepada dokter.', '["Baxiderm"]', '["bax1derm", "baxiderrn", "b4xiderm", "baksiderm", "baxid3rm", "baxlderm", "mupirocin", "baxider", "bxiderm", "baxiderm"]', '["b4xiderm", "baksiderm", "bax1derm", "baxid3rm", "baxider", "baxiderrn", "baxlderm", "bxiderm"]', 'DKL10000812A1', 'baxiderm', 'mupirocin');
