INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('papaverine', 'Papaverine', 'Papaverine', 'Antispasmodik/vasodilator', 'Obat Keras (Lingkaran Merah K)', 'Tablet dan suntik', 'Melemaskan otot polos', 'Dosis umum papaverine tablet adalah 100–300 mg sebanyak 3–5 kali sehari. Sementara itu, dosis papaverine suntik akan ditentukan oleh dokter sesuai dengan kondisi pasien.', '["Papaverine", "Gastromag", "Papaverine HCl", "Papaverine hydrochloride", "Sanmag", "priapismus"]', '["ppaverine", "gastromag", "papaverine", "p4p4verine", "papav3rin3", "papaverin", "papaverlne", "papaverine hcl", "papaver1ne", "sanmag", "papaverine hydrochloride"]', '["p4p4verine", "papav3rin3", "papaver1ne", "papaverin", "papaverlne", "ppaverine"]', 'DKL10001035A1', 'papaverine', 'papaverine');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('vaksin-dengue', 'Vaksin Dengue', 'Vaksin Dengue', 'Vaksin', 'Obat Keras (Lingkaran Merah K)', 'Suntik', 'Mencegah demam berdarah', 'Jadwal pemberian vaksin dengue bisa berbeda berdasarkan jenis yang dipakai. Berikut adalah dosis dan jadwal vaksinasi dengue berdasarkan usia penerima dan jenis vaksin yang digunakan:', '["Vaksin Dengue", "Qdenga", "kemerahan", "seperti demam tinggi", "muntah", "gusi berdarah"]', '["vaks1n dengue", "vksin dengue", "qdenga", "kemerahan", "vaksin d3ngu3", "vak5in dengue", "v4ksin dengue", "vaksln dengue", "muntah", "vaksin dengue", "seperti demam tinggi", "vaksin dengu"]', '["v4ksin dengue", "vak5in dengue", "vaks1n dengue", "vaksin d3ngu3", "vaksin dengu", "vaksln dengue", "vksin dengue"]', 'DKL10001252A1', 'vaksindengue', 'vaksindengue');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('zelona', 'Zelona', 'Diclofenac sodium', 'Obat resep', 'Obat Keras (Lingkaran Merah K)', 'Tablet', 'Meredakan nyeri dan peradangan', 'Dosis dan aturan pakai Zelona yang diberikan oleh dokter kepada tiap pasien bisa berbeda-beda, tergantung pada usia dan kondisi yang ditangani. Berikut ini adalah rekomendasi dosis diclofenac yang terkandung dalam Zelona:', '["Zelona"]', '["zelona", "zelon", "zeiona", "ze1ona", "zlona", "diclofenac sodium", "selona", "z3lona", "zelon4", "zel0na"]', '["selona", "z3lona", "ze1ona", "zeiona", "zel0na", "zelon", "zelon4", "zlona"]', 'DKL10000617A1', 'zelona', 'diclofenacsodium');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('bear-brand', 'Bear Brand', 'Bear Brand', 'Susu', 'Obat Keras (Lingkaran Merah K)', 'Susu cair dalam kemasan kaleng', 'Membantu memenuhi kebutuhan nutrisi harian tubuh', 'Gunakan sesuai petunjuk dokter atau aturan pakai pada kemasan.', '["Bear Brand"]', '["bar brand", "bear brand", "b3ar brand", "bear bran", "be4r br4nd"]', '["b3ar brand", "bar brand", "be4r br4nd", "bear bran"]', 'DKL10000897A1', 'bearbrand', 'bearbrand');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('herclov', 'Herclov', 'Valacyclovir hydrochloride 500 mg', 'Obat antivirus', 'Obat Keras (Lingkaran Merah K)', 'Kaplet salut selaput', 'Menangani infeksi virus herpes, seperti herpes zoster, herpes bibir, atau herpes genital.', 'Penggunaan Herclov perlu disesuaikan dengan kebutuhan dan kondisi kesehatan pasien. Oleh karena itu, Ikuti dosis yang diberikan oleh dokter agar efektivitas obat bekerja dengan optimal. Secara umum, berikut dosis Herclov yang biasa direkomendasikan dokter berdasarkan tujuan pengobatan:', '["Herclov"]', '["herclov", "hercl0v", "herclo", "herdov", "herc1ov", "hrclov", "valacyclovir hydrochloride 500 mg", "h3rclov", "herslov", "herciov"]', '["h3rclov", "herc1ov", "herciov", "hercl0v", "herclo", "herdov", "herslov", "hrclov"]', 'DKL10000723A1', 'herclov', 'valacyclovirhydrochloride500mg');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('camivit-e', 'Camivit E', 'Vitamin E', 'Suplemen vitamin', 'Obat Bebas (Hijau)', 'Kapsul lunak', 'Memenuhi kebutuhan vitamin E harian dan memelihara kesehatan kulit', 'Dosis penggunaan Camivit E untuk membantu memenuhi kebutuhan vitamin E harian dan memelihara kesehatan kulit umumnya adalah 1 kapsul per hari atau sesuai anjuran dokter dan aturan pakai pada kemasan.', '["Camivit E"]', '["c4mivit e", "carnivit e", "samivit e", "cam1v1t e", "camlvlt e", "vitamin e", "cmivit e", "camivit e", "camivit ", "camivit 3"]', '["c4mivit e", "cam1v1t e", "camivit ", "camivit 3", "camlvlt e", "carnivit e", "cmivit e", "samivit e"]', 'DBL10000818A1', 'camivite', 'vitamine');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('fargetix', 'Fargetix', 'Asam mefenamat', 'Obat antiinflamasi nonsteroid ( OAINS )', 'Obat Keras (Lingkaran Merah K)', 'Kaplet', 'Meredakan nyeri ringan hingga sedang, seperti sakit gigi, nyeri haid ( dismenore primer atau menorrhagia ), sakit kepala, nyeri akibat cedera, atau nyeri pascaoperasi', 'Dosis Fargetix yang diresepkan oleh dokter dapat berbeda-beda tergantung kondisi dan usia pasien. Berikut ini adalah dosis umum penggunaan obat ini:', '["Fargetix"]', '["farget1x", "f4rgetix", "fargetiks", "farg3tix", "frgetix", "fargetlx", "fargetix", "phargetix", "asam mefenamat", "fargeti"]', '["f4rgetix", "farg3tix", "farget1x", "fargeti", "fargetiks", "fargetlx", "frgetix", "phargetix"]', 'DKL10000826A1', 'fargetix', 'asammefenamat');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('kb-suntik-1-bulan', 'KB Suntik 1 Bulan', 'KB Suntik 1 Bulan', 'KB suntik', 'Obat Keras (Lingkaran Merah K)', 'Suntik', 'Mencegah kehamilan', 'Dosis KB suntik 1 bulan adalah 0,5 ml (berisi 25 mg medroxyprogesterone dan 5 mg estradiol).', '["KB Suntik 1 Bulan"]', '["kb suntik 1 bu1an", "kb suntik 1 bul4n", "kb suntik 1 bula", "kb suntik 1 buian", "kb suntik 1 bulan", "kb sunt1k 1 bulan", "kb 5untik 1 bulan", "k suntik 1 bulan", "kb suntlk 1 bulan"]', '["k suntik 1 bulan", "kb 5untik 1 bulan", "kb sunt1k 1 bulan", "kb suntik 1 bu1an", "kb suntik 1 buian", "kb suntik 1 bul4n", "kb suntik 1 bula", "kb suntlk 1 bulan"]', 'DKL10001422A1', 'kbsuntik1bulan', 'kbsuntik1bulan');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('naprex-sirup', 'Naprex Sirup', 'Paracetamol', 'Analgetik-antipiretik', 'Obat Bebas (Hijau)', 'Sirop', 'Meredakan nyeri ringan hingga sedang, termasuk sakit gigi dan sakit kepala', 'Anak usia 2–6 tahun: ½ sendok takar (2,5 ml), 3–4 kali sehari. Anak usia 6–12 tahun: 1–2 sendok takar (5–10 ml), 3–4 kali sehari.', '["Naprex Sirup"]', '["naprex sirup", "naprex 5irup", "nprex sirup", "napreks sirup", "paracetamol", "naprex slrup", "naprex s1rup", "naprex siru", "napr3x sirup", "n4prex sirup"]', '["n4prex sirup", "napr3x sirup", "napreks sirup", "naprex 5irup", "naprex s1rup", "naprex siru", "naprex slrup", "nprex sirup"]', 'DBL10001185A1', 'naprexsirup', 'paracetamol');
