INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('panvell', 'Panvell', 'Pantoprazole', 'Penghambat pompa proton', 'Obat Keras (Lingkaran Merah K)', 'Tablet salut enterik dan injeksi', 'Mengurangi produksi asam lambung', 'Dosis Panvell dapat berbeda pada setiap pasien, tergantung pada tujuan penggunaan, bentuk sediaan obat, serta usia pasien. Berikut ini adalah panduan dosis Panvell sediaan tablet berdasarkan kondisi yang ditangani:', '["Panvell"]', '["panve11", "p4nvell", "panvel", "pnvell", "pantoprazole", "panveii", "panv3ll", "panvell"]', '["p4nvell", "panv3ll", "panve11", "panveii", "panvel", "pnvell"]', 'DKL10000722A1', 'panvell', 'pantoprazole');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('samtacid', 'Samtacid', 'Aluminium hidroksida 200 mg , magnesium hidroksida 200 mg, dan simethicone 50 mg', 'Kombinasi antasida dan antiflatulensi (antikembung)', 'Obat Bebas (Hijau)', 'Tablet kunyah', 'Meredakan gejala sakit maag akibat kelebihan asam lambung, termasuk pada gastritis, tukak lambung, dan ulkus duodenum', 'Berikut adalah dosis umum penggunaan Samtacid:', '["Samtacid"]', '["sarntacid", "samtasid", "s4mt4cid", "smtacid", "samtaci", "aluminium hidroksida 200 mg , magnesium hidroksida 200 mg, dan simethicone 50 mg", "5amtacid", "samtacld", "samtacid", "samtac1d"]', '["5amtacid", "s4mt4cid", "samtac1d", "samtaci", "samtacld", "samtasid", "sarntacid", "smtacid"]', 'DBL10000806A1', 'samtacid', 'aluminiumhidroksida200mgmagnesiumhidroksida200mgdansimethicone50mg');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('vaksin-dpt', 'Vaksin DPT', 'Vaksin DPT', 'Vaksin', 'Obat Keras (Lingkaran Merah K)', 'Suntik', 'Mencegah penyakit difteri, pertusis , dan tetanus', 'Sesuai dengan jadwal imunisasi yang dikeluarkan oleh Ikatan Dokter Anak Indonesia (IDAI), vaksin DPT merupakan salah satu vaksin yang wajib diberikan kepada anak. Vaksin DPT primer akan diberikan sebanyak 3 kali dan vaksin booster sebanyak 2 kali.', '["Vaksin DPT", "Vaksin DTP", "pertusis", "penyakit saraf", "kejang", "sindrom Guillain-Barre"]', '["pertusis", "vaks1n dpt", "vaksin dtp", "vaksln dpt", "v4ksin dpt", "vaksin dtp-hb 10", "vksin dpt", "vaksin dtp-hb 5", "vaksin dpt", "vaksin dp", "vak5in dpt"]', '["v4ksin dpt", "vak5in dpt", "vaks1n dpt", "vaksin dp", "vaksln dpt", "vksin dpt"]', 'DKL10000884A1', 'vaksindpt', 'vaksindpt');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('naprex-drops', 'Naprex Drops', 'Paracetamol', 'Analgetik-antipiretik', 'Obat Bebas (Hijau)', 'Cairan tetes sebagai obat tetes oral ( drops )', 'Meredakan nyeri ringan hingga sedang, termasuk sakit gigi dan sakit kepala', 'Anak usia ≤1 tahun: 0,6 ml, 3–4 kali sehari. Anak usia 6–12 tahun: 0,6–1,2 ml, 3–4 kali sehari.', '["Naprex Drops"]', '["nprex drops", "naprex drop", "napreks drops", "naprex dr0ps", "naprex drop5", "n4prex drops", "naprex drops", "napr3x drops", "paracetamol"]', '["n4prex drops", "napr3x drops", "napreks drops", "naprex dr0ps", "naprex drop", "naprex drop5", "nprex drops"]', 'DBL10001174A1', 'naprexdrops', 'paracetamol');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('zemindo', 'Zemindo', 'Oxomemazine dan guaifenesin', 'Kombinasi antihistamin (oxomemazine) dan obat batuk golongan ekspektoran (guaifenesin)', 'Obat Keras (Lingkaran Merah K)', 'Sirup', 'Meredakan batuk akibat alergi atau iritasi, dan membantu pengeluaran dahak', 'Dosis dan lama penggunaan Zemindo akan ditentukan oleh dokter sesuai dengan jenis penyakit, tingkat keparahan infeksi, serta usia dan berat badan pasien. Berikut adalah rincian dosis Zemindo secara umum:', '["Zemindo"]', '["zemlndo", "z3mindo", "semindo", "zemind0", "oxomemazine dan guaifenesin", "zemindo", "zmindo", "zemind", "zem1ndo", "zernindo"]', '["semindo", "z3mindo", "zem1ndo", "zemind", "zemind0", "zemlndo", "zernindo", "zmindo"]', 'DKL10000726A1', 'zemindo', 'oxomemazinedanguaifenesin');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('bebelac-gold-soya', 'Bebelac Gold Soya', 'Bebelac Gold Soya', 'Pengobatan Umum', 'Obat Keras (Lingkaran Merah K)', 'Sediaan oral/topikal sesuai instruksi kemasan.', 'Mengatasi gangguan kesehatan dan meredakan gejala sesuai petunjuk medis.', 'Untuk menyajikan susu ini, tuangkan 3 sendok takar susu (39 gram) Bebelac Gold Soya ke dalam 200 ml air hangat. Setelah itu, aduk sampai Bebelac Gold Soya larut sempurna di dalam air.', '["Bebelac Gold Soya"]', '["bebe1ac go1d soya", "bebel4c gold soy4", "bebelac gold soya", "bebelac gold 5oya", "bebelac gold soy", "b3b3lac gold soya", "bebeiac goid soya", "bebelac g0ld s0ya", "bbelac gold soya"]', '["b3b3lac gold soya", "bbelac gold soya", "bebe1ac go1d soya", "bebeiac goid soya", "bebel4c gold soy4", "bebelac g0ld s0ya", "bebelac gold 5oya", "bebelac gold soy"]', 'DKL10001536A1', 'bebelacgoldsoya', 'bebelacgoldsoya');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('kb-suntik-3-bulan', 'KB Suntik 3 Bulan', 'KB Suntik 3 Bulan', 'KB suntik', 'Obat Keras (Lingkaran Merah K)', 'Suntik', 'Mencegah kehamilan', 'Dosis KB suntik 3 bulan adalah 150 mg, sebaiknya diberikan dalam 5 hari pertama menstruasi atau 5 hari pertama setelah melahirkan.', '["KB Suntik 3 Bulan"]', '["kb suntik 3 bulan", "k suntik 3 bulan", "kb sunt1k 3 bulan", "kb 5untik 3 bulan", "kb suntik 3 buian", "kb suntlk 3 bulan", "kb suntik 3 bula", "kb suntik 3 bu1an", "kb suntik 3 bul4n"]', '["k suntik 3 bulan", "kb 5untik 3 bulan", "kb sunt1k 3 bulan", "kb suntik 3 bu1an", "kb suntik 3 buian", "kb suntik 3 bul4n", "kb suntik 3 bula", "kb suntlk 3 bulan"]', 'DKL10001424A1', 'kbsuntik3bulan', 'kbsuntik3bulan');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('fargoxin', 'Fargoxin', 'Digoxin', 'Antiaritmia', 'Obat Keras (Lingkaran Merah K)', 'Tablet', 'Mengatasi aritmia dan gagal jantung', 'Dosis digoxin dalam Fargoxin akan disesuaikan oleh dokter dengan usia dan kondisi ginjal pasien. Dalam kondisi tertentu, dokter akan menentukan dosis digoxin untuk anak-anak berdasarkan berat badan (BB) pasien.', '["Fargoxin"]', '["phargoxin", "fargoxin", "digoxin", "frgoxin", "fargoksin", "fargoxi", "fargox1n", "farg0xin", "fargoxln", "f4rgoxin"]', '["f4rgoxin", "farg0xin", "fargoksin", "fargox1n", "fargoxi", "fargoxln", "frgoxin", "phargoxin"]', 'DKL10000830A1', 'fargoxin', 'digoxin');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('camoksil', 'Camoksil', 'Amoxicillin', 'Antibiotik penisilin', 'Obat Keras (Lingkaran Merah K)', 'Kapsul', 'Mengobati infeksi bakteri', 'Dosis Camoksil yang diberikan oleh dokter tergantung pada usia, kondisi kesehatan, dan respon tubuh pasien terhadap obat. Berikut ini adalah dosis umum Camoksil untuk mengatasi infeksi bakteri di berbagai bagian tubuh:', '["Camoksil"]', '["camoksil", "camoksll", "cam0ksil", "c4moksil", "camoksii", "camoksi1", "amoxicillin", "camok5il", "camoksi", "camoks1l"]', '["c4moksil", "cam0ksil", "camok5il", "camoks1l", "camoksi", "camoksi1", "camoksii", "camoksll"]', 'DKL10000819A1', 'camoksil', 'amoxicillin');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('naproxen', 'Naproxen', 'Naproxen', 'Antiinflamasi nonsteroid (OAINS)', 'Obat Keras (Lingkaran Merah K)', 'Kaplet', 'Meredakan gejala radang sendi pada rheumatoid arthritis, osteoarthritis , atau ankylosing spondylitis', 'Berikut adalah rincian dosis naproxen berdasarkan tujuan penggunaannya:', '["Naproxen", "Alif", "osteoarthritis", "termasuk nyeri haid", "nyeri terkilir", "tendinitis"]', '["nproxen", "osteoarthritis", "alif", "termasuk nyeri haid", "naproksen", "naproxe", "naprox3n", "nyeri terkilir", "n4proxen", "napr0xen", "naproxen"]', '["n4proxen", "napr0xen", "naproksen", "naprox3n", "naproxe", "nproxen"]', 'DKL10000843A1', 'naproxen', 'naproxen');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('samtaflam', 'Samtaflam', 'Diclofenac potassium', 'Obat antiinflamasi nonsteroid (OAINS)', 'Obat Keras (Lingkaran Merah K)', 'Tablet salut selaput', 'Meredakan radang dan nyeri', 'Dosis dan aturan pakai Samtaflam akan ditentukan dokter sesuai kondisi dan usia pasien. Secara umum, berikut adalah dosis pemberian Samtaflam:', '["Samtaflam"]', '["5amtaflam", "diclofenac potassium", "samtaf1am", "sarntaflarn", "samtaphlam", "samtafiam", "samtafla", "s4mt4fl4m", "smtaflam", "samtaflam"]', '["5amtaflam", "s4mt4fl4m", "samtaf1am", "samtafiam", "samtafla", "samtaphlam", "sarntaflarn", "smtaflam"]', 'DKL10000918A1', 'samtaflam', 'diclofenacpotassium');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('hercum-krim', 'Hercum Krim', 'Clobetasol propionate 0,05%', 'Kortikosteroid topikal', 'Obat Keras (Lingkaran Merah K)', 'Krim', 'Meredakan peradangan di kulit, misalnya akibat eksim, psoriasis, dermatitis, lichen planus , atau lupus', 'Berikut ini adalah dosis umum penggunaan Hercum krim untuk mengatasi penyakit kulit, seperti eksim, dermatitis kontak, atau psoriasis:', '["Hercum Krim"]', '["hercum krlm", "clobetasol propionate 0,05%", "hercum krim", "h3rcum krim", "hrcum krim", "hercurn krirn", "hercum kri", "hersum krim", "hercum kr1m"]', '["h3rcum krim", "hercum kr1m", "hercum kri", "hercum krlm", "hercurn krirn", "hersum krim", "hrcum krim"]', 'DKL10001047A1', 'hercumkrim', 'clobetasolpropionate005');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('zemoxil', 'Zemoxil', 'Amoxicillin', 'Antibiotik golongan penisilin', 'Obat Keras (Lingkaran Merah K)', 'Kaplet dan sirup kering', 'Mengobati infeksi bakteri', 'Dosis Zemoxil dapat berbeda untuk setiap individu dan akan ditentukan oleh dokter berdasarkan usia dan respons tubuh terhadap pengobatan. Berikut adalah rekomendasi dosis amoxicillin yang terkandung dalam Zemoxil:', '["Zemoxil"]', '["zemoxil", "z3moxil", "semoxil", "zemoxi1", "zemoxi", "zemoxii", "zem0xil", "amoxicillin", "zemoksil", "zemox1l"]', '["semoxil", "z3moxil", "zem0xil", "zemoksil", "zemox1l", "zemoxi", "zemoxi1", "zemoxii"]', 'DKL10000744A1', 'zemoxil', 'amoxicillin');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('vaksin-hepatitis-b', 'Vaksin Hepatitis B', 'Vaksin Hepatitis B', 'Vaksin', 'Obat Keras (Lingkaran Merah K)', 'Suntik', 'Mencegah infeksi virus hepatitis B', 'Berdasarkan Peraturan Menteri Kesehatan Republik Indonesia No.42 Tahun 2013 dan No.12 Tahun 2017 tentang penyelenggaraan imunisasi, pemberian vaksin hepatitis B menjadi salah satu imunisasi wajib yang diberikan kepada anak.', '["Vaksin Hepatitis B", "multiple sclerosis", "sistem kekebalan tubuh yang lemah", "penyakit hati", "atau gangguan pembekuan darah", "produk herbal"]', '["vaks1n hepat1t1s b", "vksin hepatitis b", "v4ksin hep4titis b", "vaksln hepatltls b", "vaksin hepatitis b", "multiple sclerosis", "atau gangguan pembekuan darah", "vaksin h3patitis b", "penyakit hati", "sistem kekebalan tubuh yang lemah", "vak5in hepatiti5 b", "vaksin hepatitis "]', '["v4ksin hep4titis b", "vak5in hepatiti5 b", "vaks1n hepat1t1s b", "vaksin h3patitis b", "vaksin hepatitis ", "vaksln hepatltls b", "vksin hepatitis b"]', 'DKL10001689A1', 'vaksinhepatitisb', 'vaksinhepatitisb');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('bebithen', 'Bebithen', 'Dexpanthenol topikal', 'Emolien atau pelembap', 'Obat Bebas (Hijau)', 'Krim', 'Mengatasi kulit kering, kasar, bersisik, dan pecah-pecah', 'Berikut ini adalah dosis umum penggunaan Bebithen untuk mengobati kulit kering, pecah-pecah, lecet, ruam popok, atau iritasi:', '["Bebithen"]', '["bebithe", "b3bith3n", "bbithen", "beblthen", "bebiten", "beb1then", "bebithen", "dexpanthenol topikal"]', '["b3bith3n", "bbithen", "beb1then", "bebiten", "bebithe", "beblthen"]', 'DBL10000801A1', 'bebithen', 'dexpanthenoltopikal');
