INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('faricimab', 'Faricimab', 'Faricimab', 'Anti VEGF ( antivascular endothelial growth factor )', 'Obat Keras (Lingkaran Merah K)', 'Suntikan intravitreal', 'Menangani degenerasi makula tipe basah dan edema makula diabetes', 'Faricimab diberikan melalui suntikan langsung ke dalam bola mata (suntikan intravitreal). Dosis faricimab ditentukan oleh dokter mata berdasarkan kondisi dan respons pasien terhadap obat.', '["Faricimab", "hipertensi okular", "infeksi mata", "glaukoma", "stroke", "mungkin sedang hamil"]', '["infeksi mata", "glaukoma", "hipertensi okular", "stroke", "faricirnab", "f4ricim4b", "faricima", "faricimab", "farlclmab", "fricimab", "farisimab", "far1c1mab", "pharicimab"]', '["f4ricim4b", "far1c1mab", "faricima", "faricirnab", "farisimab", "farlclmab", "fricimab", "pharicimab"]', 'DKL10000894A1', 'faricimab', 'faricimab');
