INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('narmig', 'Narmig', 'Cinnarizine', 'Antivertigo', 'Obat Keras (Lingkaran Merah K)', 'Tablet', 'Mengatasi keluhan mual dan pusing akibat vertigo, telinga berdenging ( tinnitus ), nistagmus, atau penyakit Meniere', 'Berikut ini adalah dosis umum penggunaan Narmig berdasarkan tujuan pengobatan dan usia pasien:', '["Narmig"]', '["cinnarizine", "narmig", "n4rmig", "nrmig", "narm1g", "narrnig", "narmi", "narmlg"]', '["n4rmig", "narm1g", "narmi", "narmlg", "narrnig", "nrmig"]', 'DKL10000606A1', 'narmig', 'cinnarizine');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('paracetamol-infus', 'Paracetamol Infus', 'Paracetamol Infus', 'Analgetik-antipiretik', 'Obat Keras (Lingkaran Merah K)', 'Cairan infus', 'Meredakan nyeri ringan hingga sedang ketika paracetamol sediaan tablet, sirup, atau rektal, tidak memungkinkan untuk digunakan', 'Dosis paracetamol infus akan ditentukan oleh dokter berdasarkan usia, berat badan (BB), dan kondisi pasien. Obat ini diberikan melalui infus selama 15 menit dengan jarak pemberian minimal 4 jam.', '["Paracetamol Infus", "Braunomol", "Eterfix", "Moretic", "Ottopan", "Panorex"]', '["paracetamol infus", "paracetamo1 infus", "paracetamol infu5", "eterfix", "paracetam0l infus", "paracetamoi infus", "paracetamol 1nfus", "p4r4cet4mol infus", "paracetamol infu", "braunomol", "parac3tamol infus", "ottopan", "moretic"]', '["p4r4cet4mol infus", "parac3tamol infus", "paracetam0l infus", "paracetamo1 infus", "paracetamoi infus", "paracetamol 1nfus", "paracetamol infu", "paracetamol infu5"]', 'DKL10001678A1', 'paracetamolinfus', 'paracetamolinfus');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('vaksin-hpv', 'Vaksin HPV', 'Vaksin HPV', 'Vaksin', 'Obat Keras (Lingkaran Merah K)', 'Suntik', 'Mencegah infeksi virus HPV', 'Di Indonesia, vaksin HPV sudah mulai bisa diberikan kepada anak perempuan yang berusia 9 tahun hingga perempuan dewasa berusia 55 tahun. Waktu pemberian yang paling disarankan adalah saat usia 9–26 tahun atau yang belum aktif berhubungan seksual.', '["Vaksin HPV", "kanker", "menyusui", "suplemen", "radioterapi", "bengkak"]', '["vaks1n hpv", "vaksin hpv", "vksin hpv", "vaksln hpv", "vak5in hpv", "vaksin hp", "v4ksin hpv", "kanker", "menyusui", "suplemen", "dan 6 bulan"]', '["v4ksin hpv", "vak5in hpv", "vaks1n hpv", "vaksin hp", "vaksln hpv", "vksin hpv"]', 'DKL10000890A1', 'vaksinhpv', 'vaksinhpv');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('zemplar', 'Zemplar', 'Zemplar', 'Antiparatiroid', 'Obat Keras (Lingkaran Merah K)', 'Suntik', 'Mengatasi hiperparatiroidisme akibat penyakit ginjal kronis', 'Dosis Zemplar ditentukan berdasarkan berat badan dan kondisi pasien. Secara umum, berikut adalah dosis Zemplar:', '["Zemplar"]', '["semplar", "zmplar", "zernplar", "zemplar", "zemp1ar", "zempla", "zempl4r", "z3mplar", "zempiar"]', '["semplar", "z3mplar", "zemp1ar", "zempiar", "zempl4r", "zempla", "zernplar", "zmplar"]', 'DKL10000731A1', 'zemplar', 'zemplar');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('allerzen', 'Allerzen', 'Cetirizine', 'Obat antihistamin', 'Obat Bebas Terbatas (Lingkaran Biru)', 'Tablet dan sirop', 'Meredakan gejala alergi', 'Dosis Allerzen dapat berbeda-beda untuk tiap pasien. Berikut ini adalah dosis umum penggunaan obat ini berdasarkan usia pasien:', '["Allerzen"]', '["4llerzen", "all3rz3n", "allerzen", "alerzen", "a11erzen", "allerze", "cetirizine", "allersen", "aiierzen"]', '["4llerzen", "a11erzen", "aiierzen", "alerzen", "all3rz3n", "allersen", "allerze"]', 'DTL10000829A1', 'allerzen', 'cetirizine');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('becantex', 'Becantex', 'Rebapimide', 'Antasida', 'Obat Keras (Lingkaran Merah K)', 'Tablet salut selaput', 'Mengatasi penyakit lambung seperti gastritis dan tukak lambung', 'Becantex tersedia dalam bentuk tablet salut selaput dengan dosis sebagai berikut:', '["Becantex"]', '["becante", "bcantex", "becanteks", "b3cant3x", "bec4ntex", "rebapimide", "besantex", "becantex"]', '["b3cant3x", "bcantex", "bec4ntex", "becante", "becanteks", "besantex"]', 'DKL10000810A1', 'becantex', 'rebapimide');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('hesperidin', 'Hesperidin', 'Hesperidin', 'Obat herbal, obat wasir', 'Obat Bebas (Hijau)', 'Tablet, kaplet, kapsul', 'Mengatasi wasir dan chronic venous insufficiency', 'Untuk mengobati wasir dan gangguan pembuluh darah, hesperidin sering dikombinasikan dengan diosmin. Berikut adalah dosis hesperidin untuk orang dewasa berdasarkan tujuan pengobatannya:', '["Hesperidin", "Ardium", "Citadium", "Dios", "Dorium", "Elroid"]', '["dios", "h3sp3ridin", "hesperldln", "he5peridin", "ardium", "citadium", "hesperidi", "hesperidin", "hsperidin", "hesper1d1n", "dorium"]', '["h3sp3ridin", "he5peridin", "hesper1d1n", "hesperidi", "hesperldln", "hsperidin"]', 'DBL10001035A1', 'hesperidin', 'hesperidin');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('kenacort', 'Kenacort', 'Triamcinolone', 'Kortikosteroid', 'Obat Keras (Lingkaran Merah K)', 'Tablet atau krim', 'Mengatasi peradangan dan alergi', 'Dosis penggunaan Kenacort tergantung pada varian obatnya. Berikut adalah rincian dosis Kenacort berdasarkan jenis produk:', '["Kenacort"]', '["k3nacort", "knacort", "triamcinolone", "ken4cort", "kenac0rt", "kenasort", "kenacor", "kenacort"]', '["k3nacort", "ken4cort", "kenac0rt", "kenacor", "kenasort", "knacort"]', 'DKL10000823A1', 'kenacort', 'triamcinolone');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('nasamol', 'Nasamol', 'Paracetamol', 'Analgetik-antipiretik', 'Obat Bebas (Hijau)', 'Tablet', 'Meredakan nyeri', 'Berikut adalah dosis umum penggunaan Nasamol untuk meredakan demam dan nyeri berdasarkan usia pasien:', '["Nasamol"]', '["nsamol", "nasamo1", "na5amol", "nasamo", "nasamoi", "n4s4mol", "nasamol", "nasarnol", "paracetamol", "nasam0l"]', '["n4s4mol", "na5amol", "nasam0l", "nasamo", "nasamo1", "nasamoi", "nasarnol", "nsamol"]', 'DBL10000715A1', 'nasamol', 'paracetamol');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('paracetamol-drop', 'Paracetamol Drop', 'Paracetamol Drop', 'Analgetik-antipiretik', 'Obat Bebas (Hijau)', 'Obat tetes atau drop', 'Meredakan nyeri ringan, termasuk sakit gigi dan sakit kepala', 'Dosis paracetamol drop perlu disesuaikan dengan berat badan (BB) anak. Secara umum, dosisnya adalah 10–15 mg/kgBB setiap kali minum, diberikan setiap 4–6 jam, maksimal 4 kali sehari. Jangan melebihi dosis harian total 60 mg/kgBB per 24 jam.', '["Paracetamol Drop", "Alphamol", "Apetic", "Emturnas", "Hufagesic", "Farmadol"]', '["paracetamoi drop", "p4r4cet4mol drop", "paracetamol drop", "paracetamo1 drop", "parasetamol drop", "alphamol", "parac3tamol drop", "paracetamol dro", "paracetarnol drop", "apetic", "hufagesic", "paracetam0l dr0p", "emturnas"]', '["p4r4cet4mol drop", "parac3tamol drop", "paracetam0l dr0p", "paracetamo1 drop", "paracetamoi drop", "paracetamol dro", "paracetarnol drop", "parasetamol drop"]', 'DBL10001566A1', 'paracetamoldrop', 'paracetamoldrop');
