INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('faridexon', 'Faridexon', 'Dexamethasone', 'Kortikosteroid', 'Obat Keras (Lingkaran Merah K)', 'Kaplet', 'Meredakan peradangan pada berbagai kondisi, termasuk radang usus dan radang sendi', 'Berikut adalah rekomendasi dosis dexamethasone di dalam Faridexon berdasarkan kondisi yang ditangani:', '["Faridexon"]', '["faridekson", "f4ridexon", "far1dexon", "faridexon", "faridexo", "faridex0n", "fridexon", "farid3xon", "dexamethasone", "farldexon"]', '["f4ridexon", "far1dexon", "farid3xon", "faridekson", "faridex0n", "faridexo", "farldexon", "fridexon"]', 'DKL10000928A1', 'faridexon', 'dexamethasone');
