INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('hevapir', 'Hevapir', '0,5 mg entecavir', 'Antivirus', 'Obat Keras (Lingkaran Merah K)', 'Tablet dispersible', 'Menangani hepatitis B kronis', 'Dosis Hevapir yang diberikan oleh dokter tergantung pada kondisi serta respons pasien terhadap pengobatan. Secara umum, berikut adalah dosis umum penggunaan Hevapir untuk hepatitis B kronis:', '["Hevapir"]', '["h3vapir", "hevap1r", "hevaplr", "0,5 mg entecavir", "hev4pir", "hvapir", "hevapir", "hevapi"]', '["h3vapir", "hev4pir", "hevap1r", "hevapi", "hevaplr", "hvapir"]', 'DKL10000719A1', 'hevapir', '05mgentecavir');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('naspro', 'Naspro', 'Acetylsalicylic acid 300 mg', 'Analgesik-antipiretik, antiplatelet , antiinflamasi nonsteroid (NSAID)', 'Obat Bebas Terbatas (Lingkaran Biru)', 'Tablet', 'Meredakan nyeri dan demam, mencegah penggumpalan darah pada penyakit jantung atau stroke', 'Dosis Naspro dapat berbeda untuk setiap individu dan akan ditentukan oleh dokter berdasarkan kondisi medis serta respons tubuh terhadap pengobatan. Berikut adalah rekomendasi dosis aspirin yang terkandung dalam Naspro berdasarkan tujuan penggunaannya:', '["Naspro"]', '["acetylsalicylic acid 300 mg", "naspr0", "naspro", "nspro", "n4spro", "naspr", "na5pro"]', '["n4spro", "na5pro", "naspr", "naspr0", "nspro"]', 'DTL10000627A1', 'naspro', 'acetylsalicylicacid300mg');
