INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('farizol-suspensi', 'Farizol Suspensi', 'Metronidazole 125 mg per 5 ml', 'Antibiotik golongan nitromidazole', 'Obat Keras (Lingkaran Merah K)', 'Suspensi atau sirop', 'Mengobati infeksi bakteri dan infeksi parasit', 'Dosis Farizol suspensi yang diberikan dokter bisa berbeda tergantung pada kondisi yang ditangani. Berikut rekomendasi dosis metronidazole dalam Farizol suspensi:', '["Farizol Suspensi"]', '["farizol susp3nsi", "fariz0l suspensi", "farizo1 suspensi", "farizoi suspensi", "farizol 5u5pen5i", "f4rizol suspensi", "metronidazole 125 mg per 5 ml", "farisol suspensi", "farizol suspensi", "far1zol suspens1"]', '["f4rizol suspensi", "far1zol suspens1", "farisol suspensi", "fariz0l suspensi", "farizo1 suspensi", "farizoi suspensi", "farizol 5u5pen5i", "farizol susp3nsi"]', 'DKL10001617A1', 'farizolsuspensi', 'metronidazole125mgper5ml');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('vaksin-moderna', 'Vaksin Moderna', 'Vaksin Moderna', 'Vaksin COVID-19', 'Obat Keras (Lingkaran Merah K)', 'Suntik', 'Mencegah infeksi virus SARS-CoV-2 yang berat', 'Vaksin Moderna dapat diberikan kepada orang dewasa minimal usia 18 tahun yang sedang dalam kondisi sehat. Vaksin primer diberikan sebanyak 2 kali dengan jarak 8 minggu. Dosis dalam sekali suntik adalah 0,5 ml (100 mcg).', '["Vaksin Moderna", "seperti penyakit jantung", "diabetes", "HIV/AIDS", "gangguan pernapasan", "penyakit autoimun"]', '["vaksin moderna", "v4ksin modern4", "hiv/aids", "vaksin m0derna", "seperti penyakit jantung", "vaksin rnoderna", "gangguan pernapasan", "vak5in moderna", "diabetes", "vaks1n moderna", "vaksin mod3rna", "vaksin modern", "vaksin modema"]', '["v4ksin modern4", "vak5in moderna", "vaks1n moderna", "vaksin m0derna", "vaksin mod3rna", "vaksin modema", "vaksin modern", "vaksin rnoderna"]', 'DKL10001362A1', 'vaksinmoderna', 'vaksinmoderna');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('kenalog-in-orabase', 'Kenalog in Orabase', 'Triamcinolone acetonide 0,1%', 'Kortikosteroid topikal', 'Obat Keras (Lingkaran Merah K)', 'Emollient dental paste', 'Sebagai pengobatan tambahan dan untuk meringankan sementara gejala-gejala yang terkait dengan lesi inflamasi atau lesi ulseratif mukosa rongga mulut akibat trauma', 'Oleskan Kenalog in Orabase secukupnya, sekitar 0,6 cm pada lesi, hingga menghasilkan lapisan tipis. Mungkin diperlukan jumlah yang lebih banyak untuk menutup beberapa lesi. Untuk hasil optimal, gunakan secukupnya hingga terbentuk lapisan tipis yang menutupi lesi.', '["Kenalog in Orabase"]', '["kena1og in orabase", "ken4log in or4b4se", "k3nalog in orabas3", "kenalog in oraba5e", "triamcinolone acetonide 0,1%", "kenaiog in orabase", "kenal0g in 0rabase", "kenalog in orabase", "kenalog in orabas", "kenalog 1n orabase"]', '["k3nalog in orabas3", "ken4log in or4b4se", "kena1og in orabase", "kenaiog in orabase", "kenal0g in 0rabase", "kenalog 1n orabase", "kenalog in oraba5e", "kenalog in orabas"]', 'DKL10001685A1', 'kenaloginorabase', 'triamcinoloneacetonide01');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('kenacort-a', 'Kenacort-A', 'Triamcinolone 1 mg (0,1%)', 'Kortikosteroid topikal', 'Obat Keras (Lingkaran Merah K)', 'Krim', 'Mengatasi keluhan akibat radang kulit, seperti pada dermatitis atopik atau psoriasis', 'Oleskan krim Kenacort-A pada area kulit yang mengalami peradangan, 2–4 kali sehari sesuai kebutuhan.', '["Kenacort-A"]', '["knacort-a", "ken4cort-4", "kenac0rt-a", "kenacort-a", "kenacort-", "k3nacort-a", "triamcinolone 1 mg (0,1%)", "kenasort-a"]', '["k3nacort-a", "ken4cort-4", "kenac0rt-a", "kenacort-", "kenasort-a", "knacort-a"]', 'DKL10000933A1', 'kenacorta', 'triamcinolone1mg01');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('beclometasone-topikal', 'Beclometasone Topikal', 'Beclometasone Topikal', 'Kortikosteroid topikal', 'Obat Keras (Lingkaran Merah K)', 'Krim', 'Mengatasi gejala peradangan pada kulit akibat eksim, psoriasis, atau dermatitis', 'Untuk mengatasi eksim, psoriasis, dan dermatitis, oleskan beclometasone topikal sebanyak seujung jari pada area kulit yang ingin diobati. Obat ini bisa digunakan sebanyak 1–3 kali sehari, maksimal 4 minggu jika dipakai di kulit badan, atau 5 hari apabila dipakai pada kulit wajah.', '["Beclometasone Topikal", "psoriasis", "rosacea", "kulit pecah-pecah", "gangguan sistem kekebalan tubuh", "masalah pada sirkulasi darah"]', '["b3clom3tason3 topikal", "beciometasone topikai", "beclomet4sone topik4l", "becl0metas0ne t0pikal", "psoriasis", "kulit pecah-pecah", "gangguan sistem kekebalan tubuh", "bec1ometasone topika1", "beclometa5one topikal", "beclometasone topikal", "beclometasone top1kal", "bclometasone topikal", "rosacea"]', '["b3clom3tason3 topikal", "bclometasone topikal", "bec1ometasone topika1", "beciometasone topikai", "becl0metas0ne t0pikal", "beclomet4sone topik4l", "beclometa5one topikal", "beclometasone top1kal"]', 'DKL10002101A1', 'beclometasonetopikal', 'beclometasonetopikal');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('paracetamol-tablet', 'Paracetamol Tablet', 'Paracetamol Tablet', 'Analgetik-antipiretik', 'Obat Bebas (Hijau)', 'Tablet', 'Meredakan nyeri ringan hingga sedang, termasuk sakit gigi dan sakit kepala', 'Dewasa dan anak usia >12 tahun: 500–1.000 mg, diberikan setiap 4–6 jam sekali. Dosis maksimal 4.000 mg per hari.', '["Paracetamol Tablet", "Amidol Forte", "Bodrex", "Itramol", "Mirasic", "Oskadon"]', '["paracetamoi tabiet", "itramol", "parac3tamol tabl3t", "paracetarnol tablet", "parasetamol tablet", "p4r4cet4mol t4blet", "paracetamol tablet", "bodrex", "paracetam0l tablet", "mirasic", "amidol forte", "paracetamol table", "paracetamo1 tab1et"]', '["p4r4cet4mol t4blet", "parac3tamol tabl3t", "paracetam0l tablet", "paracetamo1 tab1et", "paracetamoi tabiet", "paracetamol table", "paracetarnol tablet", "parasetamol tablet"]', 'DBL10001765A1', 'paracetamoltablet', 'paracetamoltablet');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('sanaflu-plus-batuk', 'Sanaflu Plus Batuk', 'Paracetamol, phenylpropanolamine, dan dextromethorpha', 'Analgesik-antipiretik , dekongestan , antitusif', 'Obat Bebas Terbatas (Lingkaran Biru)', 'Kaplet dan sirop', 'Meredakan gejala flu dan batuk tidak berdahak', 'Berikut ini adalah dosis umum penggunaan Sanaflu Plus Batuk berdasarkan bentuk obat dan usia pasien:', '["Sanaflu Plus Batuk"]', '["sanaf1u p1us batuk", "5anaflu plu5 batuk", "sanafiu pius batuk", "s4n4flu plus b4tuk", "sanaflu plus batuk", "paracetamol, phenylpropanolamine, dan dextromethorpha", "sanaflu plus batu", "sanaphlu plus batuk", "snaflu plus batuk"]', '["5anaflu plu5 batuk", "s4n4flu plus b4tuk", "sanaf1u p1us batuk", "sanafiu pius batuk", "sanaflu plus batu", "sanaphlu plus batuk", "snaflu plus batuk"]', 'DTL10001701A1', 'sanafluplusbatuk', 'paracetamolphenylpropanolaminedandextromethorpha');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('hevit-c', 'Hevit-C', 'Vitamin C', 'Suplemen vitamin', 'Obat Bebas (Hijau)', 'Tablet salut selaput', 'Mencegah dan mengatasi kekurangan vitamin C , membantu menjaga daya tahan tubuh, mempercepat penyembuhan luka , serta berperan sebagai antioksidan', 'Dosis Hevit-C dapat berbeda pada setiap orang, tergantung usia, kebutuhan, serta kondisi kesehatan. Umumnya, dosis untuk dewasa adalah 1 tablet per hari sesuai petunjuk pada kemasan atau anjuran dokter.', '["Hevit-C"]', '["hevit-c", "hevit-s", "hev1t-c", "vitamin c", "hevlt-c", "h3vit-c", "hvit-c", "hevit-"]', '["h3vit-c", "hev1t-c", "hevit-", "hevit-s", "hevlt-c", "hvit-c"]', 'DBL10000624A1', 'hevitc', 'vitaminc');
