INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('alteplase', 'Alteplase', 'Alteplase', 'Fibrinolitik', 'Obat Keras (Lingkaran Merah K)', 'Suntik', 'Memecah gumpalan darah pada pasien serangan jantung, stroke, atau emboli paru', 'Alteplase diberikan melalui suntikan ke pembuluh darah atau IV/intravena. Berikut adalah dosis umum penggunaan alteplase berdasarkan jenis penyakit yang ingin diatasi:', '["Alteplase", "stroke", "termasuk perdarahan otak", "perdarahan saluran cerna", "hepatitis yang sedang aktif", "sirosis"]', '["termasuk perdarahan otak", "4ltepl4se", "ateplase", "a1tep1ase", "hepatitis yang sedang aktif", "alteplas", "stroke", "perdarahan saluran cerna", "alt3plas3", "aitepiase", "altepla5e", "alteplase"]', '["4ltepl4se", "a1tep1ase", "aitepiase", "alt3plas3", "altepla5e", "alteplas", "ateplase"]', 'DKL10000923A1', 'alteplase', 'alteplase');
