INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('zenclovir', 'Zenclovir', 'Acyclovir 5%', 'Obat antivirus', 'Obat Keras (Lingkaran Merah K)', 'Krim', 'Mengobati luka herpes di kulit, termasuk herpes kelamin dan herpes bibir', 'Agar pengobatan efektif, gunakanlah Zenclovir sesegera mungkin sejak gejala awal herpes muncul. Oleskan krim Zenclovir pada lenting-lenting atau luka lepuh, 5 kali sehari setiap 4 jam selama 5 hari. Apabila gejala herpes belum sembuh sepenuhnya, lanjutkan pemakaian Zenclovir selama 5 hari lagi.', '["Zenclovir", "gunakanlah layanan konsultasi online", "atau bagian dalam hidung maupun mulut", "melakukan seks oral", "berhubungan intim", "seperti gelas"]', '["z3nclovir", "melakukan seks oral", "zenclovir", "senclovir", "zenclov1r", "zenciovir", "zencl0vir", "zenclovlr", "zenc1ovir", "acyclovir 5%", "berhubungan intim", "atau bagian dalam hidung maupun mulut", "gunakanlah layanan konsultasi online", "zenclovi"]', '["senclovir", "z3nclovir", "zenc1ovir", "zenciovir", "zencl0vir", "zenclov1r", "zenclovi", "zenclovlr"]', 'DKL10000956A1', 'zenclovir', 'acyclovir5');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('farmabes', 'Farmabes', 'Diltiazem', 'Antagonis kalsium', 'Obat Keras (Lingkaran Merah K)', 'Tablet dan suntik', 'Menurunkan tekanan darah tinggi', 'Farmabes tersedia dalam bentuk tablet dan suntik. Farmabes suntik diberikan melalui suntikan ke dalam pembuluh darah vena (intravena/IV) oleh dokter atau petugas medis di bawah pengawasan dokter.', '["Farmabes"]', '["f4rm4bes", "farmab3s", "pharmabes", "farmabes", "diltiazem", "farrnabes", "farmabe", "frmabes", "farmabe5"]', '["f4rm4bes", "farmab3s", "farmabe", "farmabe5", "farrnabes", "frmabes", "pharmabes"]', 'DKL10000801A1', 'farmabes', 'diltiazem');
