INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('tabos', 'Tabos', 'Paracetamol dan caffeine', 'Analgetik-antipiretik', 'Obat Bebas (Hijau)', 'Kaplet', 'Mengurangi rasa nyeri ringan hingga sedang', 'Untuk meredakan nyeri dan demam, Tabos bisa digunakan dengan dosis yang disesuaikan usia pasien. Berikut ini adalah dosisnya:', '["Tabos"]', '["tabos", "paracetamol dan caffeine", "tabo5", "t4bos", "tab0s"]', '["t4bos", "tab0s", "tabo5"]', 'DBL10000505A1', 'tabos', 'paracetamoldancaffeine');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('l-bio', 'L-Bio', 'Bifidobacterium lactis W51, Bifidobacterium lactis W52, Lactobacillus acidophilus W55, Lactobacillus casei W56, Lactobacillus salivarius W57, dan Lactococcus lactis W58', 'Suplemen probiotik', 'Obat Bebas (Hijau)', 'Serbuk', 'Membantu menjaga kesehatan saluran pencernaan dan memelihara keseimbangan flora usus', 'Dosis L-Bio dapat berbeda-beda tergantung usia, kondisi kesehatan, dan tujuan penggunaan. Secara umum, dosis mengikuti aturan pakai yang tertera pada kemasan atau sesuai anjuran dokter.', '["L-Bio"]', '["l-bi0", "l-bio", "l-b1o", "1-bio", "i-bio", "bifidobacterium lactis w51, bifidobacterium lactis w52, lactobacillus acidophilus w55, lactobacillus casei w56, lactobacillus salivarius w57, dan lactococcus lactis w58", "l-blo"]', '["1-bio", "i-bio", "l-b1o", "l-bi0", "l-blo"]', 'DBL10000403A1', 'lbio', 'bifidobacteriumlactisw51bifidobacteriumlactisw52lactobacillusacidophilusw55lactobacilluscaseiw56lactobacillussalivariusw57danlactococcuslactisw58');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('candesartan', 'Candesartan', 'Candesartan', 'Angiotensin II receptor blocker ( ARB )', 'Obat Keras (Lingkaran Merah K)', 'Tablet', 'Menurunkan tekanan darah tinggi', 'Dokter akan memberikan dosis dan menentukan lama pengobatan sesuai dengan kondisi dan usia pasien. Di bawah ini adalah rincian dosis candesartan:', '["Candesartan", "Blocand", "Blopin", "Blopress", "Blopress Plus", "Candefar"]', '["c4ndes4rt4n", "candesarta", "blopress", "cand3sartan", "blocand", "cndesartan", "sandesartan", "blopress plus", "blopin", "candesartan", "cande5artan"]', '["c4ndes4rt4n", "cand3sartan", "cande5artan", "candesarta", "cndesartan", "sandesartan"]', 'DKL10001124A1', 'candesartan', 'candesartan');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('natrilix-sr', 'Natrilix SR', 'Indapamide', 'Diuretik', 'Obat Keras (Lingkaran Merah K)', 'Tablet salut selaput', 'Menurunkan tekanan darah pada hipertensi dan mengurangi edema', 'Berikut adalah dosis Natrilix SR berdasarkan kondisi yang ingin diatasi:', '["Natrilix SR"]', '["natrlllx sr", "natriiix sr", "natrilix sr", "natri1ix sr", "natrilix 5r", "natr1l1x sr", "indapamide", "natrilix s", "natriliks sr", "n4trilix sr"]', '["n4trilix sr", "natr1l1x sr", "natri1ix sr", "natriiix sr", "natriliks sr", "natrilix 5r", "natrilix s", "natrlllx sr"]', 'DKL10001040A1', 'natrilixsr', 'indapamide');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('tabas', 'Tabas', 'Terbutaline', 'Bronkodilator', 'Obat Keras (Lingkaran Merah K)', 'Tablet dan sirop', 'Mengatasi gejala mengi, batuk, dan sesak napas, akibat asma atau PPOK', 'Dosis Tabas akan disesuaikan dengan bentuk obat dan usia pasien. Berikut ini adalah dosis umum penggunaan Tabas berdasarkan bentuk obat:', '["Tabas"]', '["t4b4s", "taba5", "tabas", "terbutaline"]', '["t4b4s", "taba5"]', 'DKL10000491A1', 'tabas', 'terbutaline');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('farmacrol-forte', 'Farmacrol Forte', 'Alumunium hidroksida , magnesium hidroksida , simethicone dan atau dimethicone/methylpolysiloxane', 'Antasida dan antifatulensi', 'Obat Bebas Terbatas (Lingkaran Biru)', 'Tablet kunyah dan suspensi', 'Membantu mencerna makanan, mengurangi gejala kembung', 'Farmacrol Forte digunakan sesuai anjuran dokter untuk membantu meredakan gejala tertentu. Penting untuk mengikuti dosis yang tepat agar obat bekerja efektif dan aman.', '["Farmacrol Forte"]', '["farmacrol fort3", "farrnacrol forte", "farmacro1 forte", "farmacrol forte", "farmasrol forte", "farmacr0l f0rte", "farmacroi forte", "alumunium hidroksida , magnesium hidroksida , simethicone dan atau dimethicone/methylpolysiloxane", "f4rm4crol forte", "farmacrol fort"]', '["f4rm4crol forte", "farmacr0l f0rte", "farmacro1 forte", "farmacroi forte", "farmacrol fort", "farmacrol fort3", "farmasrol forte", "farrnacrol forte"]', 'DTL10001463A1', 'farmacrolforte', 'alumuniumhidroksidamagnesiumhidroksidasimethiconedanataudimethiconemethylpolysiloxane');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('paracetamol-ibuprofen', 'Paracetamol-Ibuprofen', 'Paracetamol-Ibuprofen', 'Analgetik dan antipiretik , obat antiinflamasi nonsteroid ( OAINS )', 'Obat Bebas Terbatas (Lingkaran Biru)', 'Tablet, kapsul, kaplet, dan suntik', 'Menurunkan demam, serta mengatasi nyeri ringan hingga sedang', 'Berikut adalah dosis umum penggunaan paracetamol-ibuprofen berdasarkan bentuk obatnya:', '["Paracetamol-Ibuprofen", "Alaxan FR", "Bimacyl", "Farsifen PCT", "Kontrafen", "Maxigesic"]', '["paracetamol-ibuprophen", "paracetamol-ibuprofen", "bimacyl", "paracetam0l-ibupr0fen", "paracetamol-1buprofen", "p4r4cet4mol-ibuprofen", "alaxan fr", "paracetamoi-ibuprofen", "kontrafen", "farsifen pct", "parac3tamol-ibuprof3n", "paracetamol-ibuprofe", "paracetamo1-ibuprofen"]', '["p4r4cet4mol-ibuprofen", "parac3tamol-ibuprof3n", "paracetam0l-ibupr0fen", "paracetamo1-ibuprofen", "paracetamoi-ibuprofen", "paracetamol-1buprofen", "paracetamol-ibuprofe", "paracetamol-ibuprophen"]', 'DTL10002112A1', 'paracetamolibuprofen', 'paracetamolibuprofen');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('candetens', 'Candetens', 'Candesartan', 'Angiotensin II receptor blocker ( ARB )', 'Obat Keras (Lingkaran Merah K)', 'Tablet', 'Menurunkan tekanan darah tinggi', 'Dosis dan aturan pakai Candetens ditentukan dokter sesuai kondisi pasien. Secara umum, berikut adalah dosis penggunaan Candetens:', '["Candetens"]', '["sandetens", "cndetens", "c4ndetens", "candetens", "candeten5", "cand3t3ns", "candeten", "candesartan"]', '["c4ndetens", "cand3t3ns", "candeten", "candeten5", "cndetens", "sandetens"]', 'DKL10000917A1', 'candetens', 'candesartan');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('l-bio-kapsul', 'L-Bio Kapsul', 'Bifidobacterium lactis W51, Bifidobacterium lactis W52, Lactobacillus acidophilus W55, Lactobacillus casei W56, Lactobacillus salivarius W57, dan Lactococcus lactis W58', 'Suplemen probiotik', 'Obat Bebas (Hijau)', 'Kapsul', 'Membantu memelihara kesehatan pencernaan', 'Dosis L-Bio Kapsul dapat berbeda-beda tergantung usia, kondisi kesehatan, dan tujuan penggunaan. Secara umum, dosis mengikuti aturan pakai yang tertera pada kemasan atau sesuai anjuran dokter.', '["L-Bio Kapsul"]', '["l-bio kap5ul", "i-bio kapsui", "1-bio kapsu1", "l-bio kapsu", "l-bio k4psul", "bifidobacterium lactis w51, bifidobacterium lactis w52, lactobacillus acidophilus w55, lactobacillus casei w56, lactobacillus salivarius w57, dan lactococcus lactis w58", "l-blo kapsul", "l-bi0 kapsul", "l-bio kapsul", "l-b1o kapsul"]', '["1-bio kapsu1", "i-bio kapsui", "l-b1o kapsul", "l-bi0 kapsul", "l-bio k4psul", "l-bio kap5ul", "l-bio kapsu", "l-blo kapsul"]', 'DBL10001059A1', 'lbiokapsul', 'bifidobacteriumlactisw51bifidobacteriumlactisw52lactobacillusacidophilusw55lactobacilluscaseiw56lactobacillussalivariusw57danlactococcuslactisw58');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('zencocin', 'Zencocin', 'Lincomycin', 'Antibiotik', 'Obat Keras (Lingkaran Merah K)', 'Kapsul', 'Mengobati infeksi bakteri berat Antibiotik alternatif bagi penderita alergi penisilin', 'Zencocin merupakan antibiotik yang digunakan untuk mengatasi infeksi bakteri berat. Dosis Zencocin perlu disesuaikan dengan usia dan berat badan pasien agar pengobatan efektif dan aman. Berikut panduan umum dosis Zencocin :', '["Zencocin"]', '["zencoc1n", "z3ncocin", "lincomycin", "zencocin", "zencocln", "zncocin", "zensosin", "zencoci", "zenc0cin", "sencocin"]', '["sencocin", "z3ncocin", "zenc0cin", "zencoc1n", "zencoci", "zencocln", "zensosin", "zncocin"]', 'DKL10000825A1', 'zencocin', 'lincomycin');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('hexalgin', 'Hexalgin', 'Metamizole', 'Analgetik-antipiretik', 'Obat Keras (Lingkaran Merah K)', 'Kaplet', 'Meredakan nyeri sedang hingga berat', 'Dosis Hexalgin untuk meredakan nyeri dan demam adalah 1 kaplet jika diperlukan. Dosis maksimal 4 kaplet sehari.', '["Hexalgin"]', '["hexalg1n", "hex4lgin", "hexa1gin", "h3xalgin", "heksalgin", "hexalgin", "hexalgln", "hexalgi", "metamizole", "hexaigin"]', '["h3xalgin", "heksalgin", "hex4lgin", "hexa1gin", "hexaigin", "hexalg1n", "hexalgi", "hexalgln"]', 'DKL10000816A1', 'hexalgin', 'metamizole');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('nateran', 'Nateran', 'Exemestane', 'Antikanker golongan aromatase inhibitor', 'Obat Keras (Lingkaran Merah K)', 'Tablet', 'Mengobati kanker payudara', 'Dosis dan lamanya pengobatan dengan Nateran akan disesuaikan dengan kondisi, respons pasien, dan obat-obatan lain yang sedang dikonsumsi pasien. Secara umum, dosis pemberian Nateran berdasarkan kondisi pasien, yaitu:', '["Nateran"]', '["nat3ran", "nteran", "n4ter4n", "exemestane", "nateran", "natera"]', '["n4ter4n", "nat3ran", "natera", "nteran"]', 'DKL10000713A1', 'nateran', 'exemestane');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('bedaquiline', 'Bedaquiline', 'Bedaquiline', 'Antibiotik, Antituberkulosis', 'Obat Keras (Lingkaran Merah K)', 'Tablet', 'Mengatasi tuberkulosis paru', 'Dalam penggunaannya, bedaquiline dikombinasikan dengan setidaknya 3–4 obat antibiotik lain. Dosis dan aturan pakainya akan ditentukan oleh dokter berdasarkan usia atau berat badan pasien.', '["Bedaquiline", "penyakit jantung koroner", "baru mengalami serangan jantung", "hipotiroidisme", "gangguan keseimbangan elektrolit darah", "HIV/AIDS"]', '["b3daquilin3", "gangguan keseimbangan elektrolit darah", "bedaquiiine", "bedaqui1ine", "baru mengalami serangan jantung", "bedaqu1l1ne", "hipotiroidisme", "bedaquilin", "bed4quiline", "bdaquiline", "penyakit jantung koroner", "bedaqulllne", "bedaquiline"]', '["b3daquilin3", "bdaquiline", "bed4quiline", "bedaqu1l1ne", "bedaqui1ine", "bedaquiiine", "bedaquilin", "bedaqulllne"]', 'DKL10001123A1', 'bedaquiline', 'bedaquiline');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('hexcam', 'Hexcam', 'Meloxicam 15 mg', 'Obat antiiflamasi nonsteroid (OAINS)', 'Obat Keras (Lingkaran Merah K)', 'Tablet', 'Meredakan nyeri dan peradangan, terutama yang diakibatkan oleh penyakit radang sendi', 'Hexcam bisa dibeli di apotek sesuai dengan resep dokter yang diberikan secara langsung atau resep digital (e-resep) hasil dari konsultasi lewat Chat Bersama Dokter. Dosis Hexcam yang diberikan disesuaikan dengan usia, kondisi, dan respons pasien terhadap pengobatan.', '["Hexcam"]', '["meloxicam 15 mg", "hexca", "hexcarn", "h3xcam", "hxcam", "hexsam", "hexcam", "hexc4m", "hekscam"]', '["h3xcam", "hekscam", "hexc4m", "hexca", "hexcarn", "hexsam", "hxcam"]', 'DKL10000598A1', 'hexcam', 'meloxicam15mg');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('paracetine-f', 'Paracetine-F', 'Paracetamol 500 mg, caffeine 65 mg', 'Analgetik-antipiretik', 'Obat Bebas (Hijau)', 'Kaplet', 'Meredakan nyeri ringan hingga sedang', 'Berikut adalah dosis umum penggunaan Paracetine-F untuk meredakan demam dan nyeri berdasarkan usia pasien:', '["Paracetine-F"]', '["paracetamol 500 mg, caffeine 65 mg", "paracetine-", "pracetine-f", "parasetine-f", "parac3tin3-f", "paracetine-f", "p4r4cetine-f", "paracetlne-f", "paracetine-ph", "paracet1ne-f"]', '["p4r4cetine-f", "parac3tin3-f", "paracet1ne-f", "paracetine-", "paracetine-ph", "paracetlne-f", "parasetine-f", "pracetine-f"]', 'DBL10001135A1', 'paracetinef', 'paracetamol500mgcaffeine65mg');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('tabos-extra', 'Tabos Extra', 'Paracetamol , ibuprofen , dan kafein', 'Analgesik dan antipiretik , obat antiinflamasi nonsteroid ( OAINS )', 'Obat Bebas Terbatas (Lingkaran Biru)', 'Kaplet', 'Meredakan nyeri ringan hingga sedang', 'Tabos Extra hanya boleh digunakan orang dewasa atau anak usia >12 tahun. Dosis Tabos Extra sebagai obat pereda nyeri dan penurun demam adalah 1 kaplet, 3–4 kali sehari.', '["Tabos Extra"]', '["tbos extra", "t4bos extr4", "tabos extra", "tabos 3xtra", "tabos extr", "paracetamol , ibuprofen , dan kafein", "tabo5 extra", "tab0s extra", "tabos ekstra"]', '["t4bos extr4", "tab0s extra", "tabo5 extra", "tabos 3xtra", "tabos ekstra", "tabos extr", "tbos extra"]', 'DTL10001053A1', 'tabosextra', 'paracetamolibuprofendankafein');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('zendiab', 'Zendiab', 'Metformin 500 mg', 'Obat antidiabetes golongan biguanide', 'Obat Keras (Lingkaran Merah K)', 'Tablet salut selaput', 'Mengontrol kadar gula darah pada penderita diabetes tipe 2', 'Dalam pengobatan diabetes tipe 2, Zendiab bisa digunakan sebagai obat tunggal atau dikombinasikan dengan obat lain yang tergolong antidiabetes, termasuk insulin suntik.', '["Zendiab"]', '["metformin 500 mg", "zend1ab", "zendia", "zendlab", "sendiab", "zendi4b", "zndiab", "zendiab", "z3ndiab"]', '["sendiab", "z3ndiab", "zend1ab", "zendi4b", "zendia", "zendlab", "zndiab"]', 'DKL10000701A1', 'zendiab', 'metformin500mg');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('vaksin-polio', 'Vaksin Polio', 'Vaksin Polio', 'Vaksin', 'Obat Keras (Lingkaran Merah K)', 'Suntik dan tetes mulut', 'Mencegah polio', 'Sesuai dengan jadwal imunisasi yang dikeluarkan oleh Ikatan Dokter Anak Indonesia (IDAI), vaksin polio merupakan salah satu vaksin yang wajib diberikan kepada anak. Vaksin polio pada anak akan diberikan sebanyak 4 kali dan vaksin booster sebanyak 1 kali.', '["Vaksin Polio", "Imovax Polio", "Vaksin Poliomyelitis Inaktif IPV", "termasuk jika alergi terhadap formalin", "neomycin", "streptomycin"]', '["vaksin p0li0", "vaksin poiio", "vaksin poli", "imovax polio", "vaksin po1io", "vaksin polio", "vaksin polio oral bivalen tipe 1 & 3", "v4ksin polio", "vak5in polio", "vaksln pollo", "vaksin poliomyelitis inaktif ipv", "termasuk jika alergi terhadap formalin", "vaks1n pol1o"]', '["v4ksin polio", "vak5in polio", "vaks1n pol1o", "vaksin p0li0", "vaksin po1io", "vaksin poiio", "vaksin poli", "vaksln pollo"]', 'DKL10001167A1', 'vaksinpolio', 'vaksinpolio');
