INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('vaksin-rotavirus', 'Vaksin Rotavirus', 'Vaksin Rotavirus', 'Vaksin', 'Obat Keras (Lingkaran Merah K)', 'Suspensi atau larutan', 'Mencegah terjadinya infeksi rotavirus yang menyebabkan gastroenteritis atau muntaber', 'Vaksin rotavirus masuk dalam program imunisasi pilihan. Sesuai dengan jadwal imunisasi yang dikeluarkan oleh Ikatan Dokter Anak Indonesia (IDAI), vaksin rotavirus bisa diberikan kepada bayi sejak usianya 6 minggu sampai maksimal usia 6–8 bulan, tergantung jenis vaksin yang diberikan.', '["Vaksin Rotavirus", "Rotarix monovalen", "seperti bladder exstrophy", "kanker", "diare", "suplemen"]', '["vaksin rotavirus", "v4ksin rot4virus", "vak5in rotaviru5", "kanker", "vaks1n rotav1rus", "vaksin r0tavirus", "vaksln rotavlrus", "vaksin rotaviru", "diare", "vksin rotavirus", "seperti bladder exstrophy", "rotarix monovalen"]', '["v4ksin rot4virus", "vak5in rotaviru5", "vaks1n rotav1rus", "vaksin r0tavirus", "vaksin rotaviru", "vaksln rotavlrus", "vksin rotavirus"]', 'DKL10001627A1', 'vaksinrotavirus', 'vaksinrotavirus');
