INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('l-theanine', 'l-theanine', 'l-theanine', 'Suplemen asam amino', 'Obat Bebas (Hijau)', 'Kapsul, tablet, dan gummy', 'Meredakan kecemasan dan stres', 'Sebagai suplemen, dosis l-theanine tergantung pada produknya. l-theanine bisa menjadi kandungan tunggal, atau dikombinasikan dengan bahan lain di mana dosisnya akan disesuaikan dengan kandungan lain di dalam produk tersebut.', '["l-theanine"]', '["l-theanin", "i-theanine", "l-theanlne", "l-th3anin3", "1-theanine", "l-the4nine", "l-theanine", "l-teanine", "l-thean1ne"]', '["1-theanine", "i-theanine", "l-teanine", "l-th3anin3", "l-the4nine", "l-thean1ne", "l-theanin", "l-theanlne"]', 'DBL10000997A1', 'ltheanine', 'ltheanine');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('hexos-buzz', 'Hexos Buzz', 'Dichlorobenzyl alcohol dan amylmetacresol', 'Tablet isap antiseptik', 'Obat Bebas (Hijau)', 'Tablet hisap', 'Membantu meredakan sakit tenggorokan', 'Dosis umum Hexos Buzz untuk dewasa dan anak usia di atas 6 tahun adalah 1 tablet hisap setiap 2–3 jam sesuai kebutuhan, dengan batas maksimal 8 tablet hisap per hari. Selalu baca petunjuk penggunaan pada kemasan sebelum mengonsumsi obat ini.', '["Hexos Buzz"]', '["hexos buss", "hexo5 buzz", "dichlorobenzyl alcohol dan amylmetacresol", "hexos buz", "hxos buzz", "heksos buzz", "hexos buzz", "h3xos buzz", "hex0s buzz"]', '["h3xos buzz", "heksos buzz", "hex0s buzz", "hexo5 buzz", "hexos buss", "hexos buz", "hxos buzz"]', 'DBL10000978A1', 'hexosbuzz', 'dichlorobenzylalcoholdanamylmetacresol');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('natrium-picosulfat', 'Natrium Picosulfat', 'Natrium Picosulfat', 'Obat pencahar jenis stimulan', 'Obat Keras (Lingkaran Merah K)', 'Tetes ( drops )', 'Mengatasi konstipasi dan membantu membersihkan usus sebelum pemeriksaan kolonoskopi atau operasi usus.', 'Dosis natrium picosulfat ditentukan berdasarkan usia, kondisi pasien, dan respons tubuh terhadap obat. Secara umum, berikut ini adalah dosis natrium picosulfat berdasarkan tujuannya:', '["Natrium Picosulfat", "Laxoberon", "demam", "nyeri perut yang hebat", "penyakit liver", "penyakit ginjal"]', '["penyakit liver", "natrium pico5ulfat", "natrium picosulphat", "natrium picosu1fat", "nyeri perut yang hebat", "n4trium picosulf4t", "natrium picosulfa", "natr1um p1cosulfat", "natrium pic0sulfat", "demam", "laxoberon", "natrium picosulfat", "natrium picosuifat"]', '["n4trium picosulf4t", "natr1um p1cosulfat", "natrium pic0sulfat", "natrium pico5ulfat", "natrium picosu1fat", "natrium picosuifat", "natrium picosulfa", "natrium picosulphat"]', 'DKL10001818A1', 'natriumpicosulfat', 'natriumpicosulfat');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('farmasal', 'Farmasal', 'Aspirin', 'Obat antiinflamasi nonsteroid (NSAID) dan antiplatelet', 'Obat Bebas Terbatas (Lingkaran Biru)', 'Tablet salut enterik', 'Meredakan nyeri dan demam, mencegah penggumpalan darah pada penyakit jantung atau stroke', 'Dosis Farmasal dapat berbeda untuk setiap individu dan akan ditentukan oleh dokter berdasarkan kondisi medis, serta respons tubuh terhadap pengobatan.', '["Farmasal"]', '["farmasa", "farrnasal", "pharmasal", "farmasal", "farma5al", "frmasal", "farmasai", "farmasa1", "aspirin", "f4rm4s4l"]', '["f4rm4s4l", "farma5al", "farmasa", "farmasa1", "farmasai", "farrnasal", "frmasal", "pharmasal"]', 'DTL10000807A1', 'farmasal', 'aspirin');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('q-pin', 'Q-Pin', 'Quetiapine', 'Antipsikotik atipikal', 'Obat Keras (Lingkaran Merah K)', 'Tablet salut selaput dan tablet lepas lambat', 'Menangani gangguan mental, seperti skizofrenia , depresi mayor, dan gangguan bipolar', 'Dosis Q-Pin ditentukan berdasarkan usia, kondisi, dan respons pasien terhadap pengobatan. Dosis akan ditentukan dan ditingkatkan secara bertahap oleh dokter.', '["Q-Pin"]', '["q-pin", "q-pln", "quetiapine", "q-p1n"]', '["q-p1n", "q-pln"]', 'DKL10000421A1', 'qpin', 'quetiapine');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('befixim', 'Befixim', 'Cefixime', 'Antibiotik golongan sefalosporin', 'Obat Keras (Lingkaran Merah K)', 'Kapsul', 'Mengobati infeksi bakteri', 'Dosis Befixim akan disesuaikan oleh dokter dengan kondisi, tingkat keparahan infeksi, serta usia dan berat badan pasien. Berikut adalah rincian dosisnya:', '["Befixim"]', '["befixim", "befiksim", "b3fixim", "cefixime", "befixirn", "bephixim", "bef1x1m", "bfixim", "beflxlm", "befixi"]', '["b3fixim", "bef1x1m", "befiksim", "befixi", "befixirn", "beflxlm", "bephixim", "bfixim"]', 'DKL10000708A1', 'befixim', 'cefixime');
