INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('tacrine', 'Tacrine', 'Tacrine', 'Penghambat enzim kolinesterase', 'Obat Keras (Lingkaran Merah K)', 'Kapsul', 'Mengatasi demensia akibat penyakit Alzheimer', 'Dosis dan durasi pengobatan akan ditentukan oleh dokter berdasarkan kondisi pasien, respons pasien terhadap pengobatan, dan hasil pemeriksaan fungsi hati pasien.', '["Tacrine", "tukak lambung", "pembesaran kelenjar prostat", "PPOK", "hipotensi", "denyut jantung lambat"]', '["tukak lambung", "tacr1ne", "tacrin", "tcrine", "hipotensi", "tacrlne", "ppok", "t4crine", "tacrine", "tacrin3", "tasrine", "pembesaran kelenjar prostat"]', '["t4crine", "tacr1ne", "tacrin", "tacrin3", "tacrlne", "tasrine", "tcrine"]', 'DKL10000710A1', 'tacrine', 'tacrine');
