INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('q-vit-c', 'Q-Vit C', 'Vitamin C', 'Suplemen vitamin', 'Obat Bebas (Hijau)', 'Kaplet salut selaput', 'Mencegah dan mengatasi kekurangan vitamin C, membantu menjaga daya tahan tubuh, mempercepat penyembuhan luka , serta berperan sebagai antioksidan', 'Gunakan sesuai petunjuk dokter atau aturan pakai pada kemasan.', '["Q-Vit C"]', '["qvit c", "q-vlt c", "q-v1t c", "q-vit c", "q-vit s", "q-vit ", "vitamin c"]', '["q-v1t c", "q-vit ", "q-vit s", "q-vlt c", "qvit c"]', 'DBL10000532A1', 'qvitc', 'vitaminc');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('vaksin-sinopharm', 'Vaksin Sinopharm', 'Vaksin Sinopharm', 'Vaksin COVID-19', 'Obat Keras (Lingkaran Merah K)', 'Suntik', 'Mencegah COVID-19', 'Vaksin Sinopharm disuntikkan sebanyak 2 kali dengan jeda 21–28 hari per dosisnya. Dosis vaksin Sinopharm yang diberikan dalam sekali suntik adalah 0,5 ml.', '["Vaksin Sinopharm", "seperti penyakit jantung", "diabetes", "HIV/AIDS", "gangguan pernapasan", "penyakit autoimun"]', '["hiv/aids", "vaksin sinophar", "seperti penyakit jantung", "vaksin sinopharrn", "vaksln slnopharm", "gangguan pernapasan", "vaksin sinopharm", "v4ksin sinoph4rm", "diabetes", "vaksin sinofarm", "vaks1n s1nopharm", "vaksin sin0pharm", "vak5in 5inopharm"]', '["v4ksin sinoph4rm", "vak5in 5inopharm", "vaks1n s1nopharm", "vaksin sin0pharm", "vaksin sinofarm", "vaksin sinophar", "vaksin sinopharrn", "vaksln slnopharm"]', 'DKL10001597A1', 'vaksinsinopharm', 'vaksinsinopharm');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('farmasil-krim', 'Farmasil Krim', 'Terbinafine', 'Antijamur topikal', 'Obat Keras (Lingkaran Merah K)', 'Krim', 'Mengobati infeksi jamur kulit, seperti panu (tinea versicolor), kutu air ( tinea pedis ), kurap ( tinea corporis ), kurap selangkangan ( tinea cruris ), atau kandidiasis kulit', 'Oleskan Farmasil krim secukupnya di area kulit yang perlu diobati, 1–2 kali sehari. Lama pengobatan berkisar 1–2 minggu, tergantung pada jenis infeksi jamur kulit yang diobati.', '["Farmasil Krim"]', '["farmasi1 krim", "farmasll krlm", "farmasil krim", "farmas1l kr1m", "farrnasil krirn", "farmasii krim", "farmasil kri", "terbinafine", "farma5il krim", "f4rm4sil krim"]', '["f4rm4sil krim", "farma5il krim", "farmas1l kr1m", "farmasi1 krim", "farmasii krim", "farmasil kri", "farmasll krlm", "farrnasil krirn"]', 'DKL10001250A1', 'farmasilkrim', 'terbinafine');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('labeta', 'Labeta', 'Labetalol', 'Penghambat beta', 'Obat Keras (Lingkaran Merah K)', 'Suntik atau infus', 'Mengatasi tekanan darah tinggi atau hipertensi', 'Di Indonesia, Labeta tersedia dalam bentuk suntik. Penggunaan obat ini akan diberikan melalui suntikan ke pembuluh darah (intravena/IV). Berikut ini adalah dosis Labeta berdasarkan tujuan pengobatannya:', '["Labeta"]', '["lab3ta", "l4bet4", "labeta", "iabeta", "1abeta", "labet", "lbeta", "labetalol"]', '["1abeta", "iabeta", "l4bet4", "lab3ta", "labet", "lbeta"]', 'DKL10000585A1', 'labeta', 'labetalol');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('dabigatran', 'Dabigatran', 'Dabigatran', 'Antikoagulan', 'Obat Keras (Lingkaran Merah K)', 'Kapsul', 'Mencegah dan mengatasi penggumpalan darah', 'Dosis dabigatran yang diresepkan dokter dapat berbeda pada tiap pasien. Berikut ini adalah dosis dabigatran berdasarkan tujuan penggunaan dan usia pasien:', '["Dabigatran", "penyakit hati", "stroke", "anemia", "sindrom antifosfolipid", "perdarahan saluran cerna"]', '["dbigatran", "dab1gatran", "dabigatran", "stroke", "anemia", "d4big4tr4n", "dablgatran", "penyakit hati", "dabigatra", "sindrom antifosfolipid"]', '["d4big4tr4n", "dab1gatran", "dabigatra", "dablgatran", "dbigatran"]', 'DKL10001005A1', 'dabigatran', 'dabigatran');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('zenichlor', 'Zenichlor', 'Chloramphenicol', 'Antibiotik', 'Obat Keras (Lingkaran Merah K)', 'Kapsul dan suspensi', 'Mengobati infeksi bakteri', 'Dosis dan lama penggunaan Zenichlor ditentukan berdasarkan jenis infeksi yang diobati, tingkat keparahan infeksi, serta usia dan berat badan pasien. Berikut ini adalah rincian dosis Zenichlor secara umum:', '["Zenichlor"]', '["zen1chlor", "senichlor", "zenichlor", "zenichl0r", "zenichlo", "chloramphenicol", "zenich1or", "zenichior", "zenlchlor", "z3nichlor"]', '["senichlor", "z3nichlor", "zen1chlor", "zenich1or", "zenichior", "zenichl0r", "zenichlo", "zenlchlor"]', 'DKL10000942A1', 'zenichlor', 'chloramphenicol');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('zenirex', 'Zenirex', '5 mg promethazine, 4 mg ekstrak ipecacuanhae , 50 mg guaifenesin', 'Obat batuk kombinasi antihistamin , bahan herbal, dan ekspektoran', 'Obat Bebas (Hijau)', 'Sirop', 'Meredakan batuk berdahak yang disertai gejala alergi', 'Dosis umum penggunaan Zenirex untuk meredakan batuk berdahak yang disertai gejala alergi:', '["Zenirex"]', '["senirex", "zenlrex", "zenireks", "5 mg promethazine, 4 mg ekstrak ipecacuanhae , 50 mg guaifenesin", "zenirex", "znirex", "zen1rex", "z3nir3x", "zenire"]', '["senirex", "z3nir3x", "zen1rex", "zenire", "zenireks", "zenlrex", "znirex"]', 'DBL10000741A1', 'zenirex', '5mgpromethazine4mgekstrakipecacuanhae50mgguaifenesin');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('vaksin-sinovac', 'Vaksin Sinovac', 'Vaksin Sinovac', 'Vaksin COVID-19', 'Obat Keras (Lingkaran Merah K)', 'Suntik', 'Mencegah infeksi virus SARS-CoV-2 yang berat', 'Vaksin Sinovac dapat diberikan kepada anak usia 6 tahun sampai lansia (>60 tahun) yang sedang dalam kondisi sehat. Vaksin akan diberikan sebanyak 2 kali dengan jarak 28 hari. Dosis dalam sekali suntik adalah 0,5 ml.', '["Vaksin Sinovac", "seperti penyakit jantung", "diabetes", "HIV/AIDS", "gangguan pernapasan", "penyakit autoimun"]', '["vaksin sin0vac", "vaksin sinovas", "hiv/aids", "vaks1n s1novac", "v4ksin sinov4c", "vaksln slnovac", "vksin sinovac", "seperti penyakit jantung", "gangguan pernapasan", "vak5in 5inovac", "vaksin sinovac", "diabetes", "vaksin sinova"]', '["v4ksin sinov4c", "vak5in 5inovac", "vaks1n s1novac", "vaksin sin0vac", "vaksin sinova", "vaksin sinovas", "vaksln slnovac", "vksin sinovac"]', 'DKL10001375A1', 'vaksinsinovac', 'vaksinsinovac');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('tacrolimus', 'Tacrolimus', 'Tacrolimus', 'Obat imunosupresif', 'Obat Keras (Lingkaran Merah K)', 'Cairan infus, kapsul, salep', 'Mencegah dan mengobati respons penolakan tubuh terhadap organ baru pascatindakan transplantasi jantung, ginjal, hati, paru-paru, atau pankreas, serta mengatasi dermatitis atopik.', 'Dokter akan menentukan dosis tacrolimus berdasarkan bentuk obat, usia dan berat badan pasien, serta tujuan penggunaannya. Berikut adalah rincian dosisnya:', '["Tacrolimus", "Prograf", "Prograf XL", "ginjal", "hati", "paru-paru"]', '["hati", "prograf", "tacroiimus", "tacrolimus", "tacrolirnus", "t4crolimus", "tacr0limus", "tacrol1mus", "prograf xl", "tacrolimu5", "tacro1imus", "tacrolimu", "ginjal"]', '["t4crolimus", "tacr0limus", "tacro1imus", "tacroiimus", "tacrol1mus", "tacrolimu", "tacrolimu5", "tacrolirnus"]', 'DKL10001059A1', 'tacrolimus', 'tacrolimus');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('candotens', 'Candotens', 'Candesartan', 'Obat resep', 'Obat Keras (Lingkaran Merah K)', 'Tablet', 'Mengatasi hipertensi', 'Dosis dan aturan pakai Candotens ditentukan oleh dokter sesuai kondisi pasien. Secara umum, berikut adalah dosis penggunaan Candotens:', '["Candotens"]', '["candotens", "candoten", "candot3ns", "cand0tens", "candoten5", "c4ndotens", "sandotens", "cndotens", "candesartan"]', '["c4ndotens", "cand0tens", "candot3ns", "candoten", "candoten5", "cndotens", "sandotens"]', 'DKL10000927A1', 'candotens', 'candesartan');
