INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('nausile', 'Nausile', 'Metoclopramide HCL 10 mg', 'Antiemetik atau obat antimuntah', 'Obat Keras (Lingkaran Merah K)', 'Tablet', 'Meredakan mual dan muntah yang disebabkan oleh gangguan pencernaan, misalnya penyakit asam lambung (GERD) atau gastroenteritis .', 'Dokter akan menjelaskan dosis konsumsi Nausile ketika meresepkan obat ini. Dosisnya biasanya akan disesuaikan dengan usia dan kondisi pasien, serta respons tubuh terhadap pengobatan.', '["Nausile"]', '["metoclopramide hcl 10 mg", "nau5ile", "nausi1e", "nausile", "nausiie", "n4usile", "nausil", "nauslle", "nausil3", "naus1le"]', '["n4usile", "nau5ile", "naus1le", "nausi1e", "nausiie", "nausil", "nausil3", "nauslle"]', 'DKL10000721A1', 'nausile', 'metoclopramidehcl10mg');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('benczema', 'Benczema', 'Betamethasone 1 mg', 'Obat kortikosteroid topikal', 'Obat Keras (Lingkaran Merah K)', 'Krim', 'Menangani gejala peradangan pada kulit akibat eksim, dermatitis kontak, atau psoriasis', 'Untuk mengatasi kondisi peradangan di kulit, seperti eksim, dermatitis kontak, ataupun psoriasis, Anda dapat menggunakan Benczema dengan dosis umumnya berikut ini:', '["Benczema"]', '["benczema", "benczerna", "benczem4", "bnczema", "benczem", "betamethasone 1 mg", "b3ncz3ma", "bencsema", "benszema"]', '["b3ncz3ma", "bencsema", "benczem", "benczem4", "benczerna", "benszema", "bnczema"]', 'DKL10000805A1', 'benczema', 'betamethasone1mg');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('zenon', 'Zenon', 'Ezetimibe dan rosuvastatin', 'Obat penurun kolesterol', 'Obat Keras (Lingkaran Merah K)', 'Tablet', 'Menurunkan kadar kolesterol tinggi', 'Dosis Zenon ditentukan oleh dokter berdasarkan kadar kolesterol LDL, target terapi, serta respons pasien terhadap pengobatan. Obat ini digunakan sebagai pengganti terapi ezetimibe dan rosuvastatin yang sebelumnya diberikan secara terpisah dengan dosis yang sama.', '["Zenon"]', '["zenon", "ezetimibe dan rosuvastatin", "z3non", "senon", "zen0n"]', '["senon", "z3non", "zen0n"]', 'DKL10000522A1', 'zenon', 'ezetimibedanrosuvastatin');
