INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('quetiapine', 'Quetiapine', 'Quetiapine', 'Antipsikotik atipikal', 'Obat Keras (Lingkaran Merah K)', 'Tablet salut selaput', 'Mengobati gangguan mental, seperti skizofrenia , mengatasi dan mencegah gangguan bipolar , dan mengobati depresi.', 'Dosis quetiapine akan disesuaikan oleh dokter berdasarkan kondisi dan respons pasien terhadap pengobatan, serta obat yang sedang digunakan oleh pasien. Berikut adalah dosis umum quetiapine untuk orang dewasa:', '["Quetiapine", "Q-Pin", "Q-Pin Xr", "Quetiapine Fumarate", "Quetvell XR", "Seroquel"]', '["qu3tiapin3", "quetlaplne", "quetiapine fumarate", "quetiapine", "q-pin", "quetiapin", "q-pin xr", "quetvell xr", "qetiapine", "quet1ap1ne", "queti4pine"]', '["qetiapine", "qu3tiapin3", "quet1ap1ne", "queti4pine", "quetiapin", "quetlaplne"]', 'DKL10001045A1', 'quetiapine', 'quetiapine');
