INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('nebacetin', 'Nebacetin', 'Kombinasi neomycin dan bacitracin', 'Kombinasi a ntibiotik aminoglikosida dan antibiotik polipeptida', 'Obat Keras (Lingkaran Merah K)', 'Krim', 'Mengobati infeksi bakteri pada kulit', 'Penggunaan Nebacetin harus mengikuti petunjuk dokter karena dosis dan frekuensi pemakaian dapat berbeda, tergantung usia dan kondisi kulit. Umumnya, obat ini digunakan dengan cara dioleskan tipis-tipis ke bagian kulit yang bermasalah sebanyak 1-3 kali sehari.', '["Nebacetin"]', '["kombinasi neomycin dan bacitracin", "n3bac3tin", "nbacetin", "neb4cetin", "nebacetln", "nebasetin", "nebacet1n", "nebaceti", "nebacetin"]', '["n3bac3tin", "nbacetin", "neb4cetin", "nebacet1n", "nebaceti", "nebacetln", "nebasetin"]', 'DKL10000905A1', 'nebacetin', 'kombinasineomycindanbacitracin');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('benocetam', 'Benocetam', 'Piracetam', 'Nootropik dan neurotonik/neurotropik', 'Obat Keras (Lingkaran Merah K)', 'Kaplet salut selaput, tablet, dan suntik', 'Mengatasi gangguan pergerakan mioklonus kortikal; vertigo; atau gangguan kognitif, misalnya akibat demensia atau penyakit Alzheimer', 'Berikut ini adalah dosis umum penggunaan Benocetam berdasarkan bentuk obat dan kondisi pasien:', '["Benocetam"]', '["benocetarn", "bnocetam", "benoceta", "b3noc3tam", "benosetam", "piracetam", "benocet4m", "ben0cetam", "benocetam"]', '["b3noc3tam", "ben0cetam", "benocet4m", "benoceta", "benocetarn", "benosetam", "bnocetam"]', 'DKL10000910A1', 'benocetam', 'piracetam');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('valacyclovir', 'Valacyclovir', 'Valacyclovir', 'Antivirus', 'Obat Keras (Lingkaran Merah K)', 'Kaplet dan tablet', 'Mengatasi infeksi virus herpes', 'Dosis valacyclovir akan ditentukan oleh dokter berdasarkan kondisi, respons tubuh, dan usia pasien. Secara umum, berikut adalah dosis valacyclovir:', '["Valacyclovir", "Cloviar", "Herclov", "Iclofar", "Inclovir", "Norus"]', '["herclov", "vaiacyciovir", "valacyclovir", "valacyclovi", "valacycl0vir", "iclofar", "valacyclovlr", "cloviar", "valacyclov1r", "v4l4cyclovir", "valacydovir", "inclovir", "va1acyc1ovir"]', '["v4l4cyclovir", "va1acyc1ovir", "vaiacyciovir", "valacycl0vir", "valacyclov1r", "valacyclovi", "valacyclovlr", "valacydovir"]', 'DKL10001263A1', 'valacyclovir', 'valacyclovir');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('tagasal-expectorant', 'Tagasal Expectorant', 'Salbutamol 1 mg dan guaifenesin 50 mg', 'Kombinasi bronkodilator kerja cepat ( agonis beta -2) dan ekspektoran', 'Obat Keras (Lingkaran Merah K)', 'Sirop', 'Meringankan gejala sesak napas, mengi, dan batuk berdahak akibat asma, bronkitis kronis, emfisema, serta penyakit paru obstruktif kronis (PPOK)', 'Secara umum, dosis Tagasal Expectorant akan disesuaikan dengan kondisi dan usia pasien. Berikut ini adalah dosis umum penggunaan Tagasal Expectorant:', '["Tagasal Expectorant"]', '["taga5al expectorant", "tagasai expectorant", "tagasa1 expectorant", "tagasal ekspectorant", "t4g4s4l expector4nt", "salbutamol 1 mg dan guaifenesin 50 mg", "tagasal expect0rant", "tagasal expectoran", "tagasal expectorant", "tagasal 3xp3ctorant"]', '["t4g4s4l expector4nt", "taga5al expectorant", "tagasa1 expectorant", "tagasai expectorant", "tagasal 3xp3ctorant", "tagasal ekspectorant", "tagasal expect0rant", "tagasal expectoran"]', 'DKL10001898A1', 'tagasalexpectorant', 'salbutamol1mgdanguaifenesin50mg');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('farsemix', 'Farsemix', 'Desoximetasone 0,5 mg dan neomycin 5 mg', 'Kombinasi kortikosteroid topikal dan antibiotik topikal golongan aminoglikosida', 'Obat Keras (Lingkaran Merah K)', 'Krim', 'Mengatasi peradangan pada kulit atau dermatitis yang disertai infeksi bakteri', 'Farsemix umumnya digunakan dalam pengobatan dermatitis yang disertai infeksi bakteri. Oleskan Farsemix secara merata pada area kulit yang perlu diobati, 2–3 kali sehari. Lama pengobatan 7 hari atau sesuai petunjuk dokter.', '["Farsemix"]', '["farsemlx", "desoximetasone 0,5 mg dan neomycin 5 mg", "farsemiks", "farsernix", "farsemi", "fars3mix", "far5emix", "farsemix", "farsem1x", "f4rsemix"]', '["f4rsemix", "far5emix", "fars3mix", "farsem1x", "farsemi", "farsemiks", "farsemlx", "farsernix"]', 'DKL10000831A1', 'farsemix', 'desoximetasone05mgdanneomycin5mg');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('allohex', 'Allohex', 'Loratadine', 'Antihistamin', 'Obat Keras (Lingkaran Merah K)', 'Tablet', 'Meredakan gejala alergi', 'Berikut ini adalah dosis umum penggunaan Allohex berdasarkan usia pasien:', '["Allohex"]', '["4llohex", "a11ohex", "all0hex", "alloh3x", "aiiohex", "allohe", "allohex", "alloheks", "loratadine", "alohex"]', '["4llohex", "a11ohex", "aiiohex", "all0hex", "alloh3x", "allohe", "alloheks", "alohex"]', 'DKL10000717A1', 'allohex', 'loratadine');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('daiticin', 'Daiticin', '500 mg thiamphenicol', 'Antibiotik', 'Obat Keras (Lingkaran Merah K)', 'Kapsul', 'Mengobati infeksi bakteri, termasuk pada penyakit menular seksual', 'Dosis Daiticin akan ditentukan dokter berdasarkan kondisi medis dan respons tubuh pasien terhadap pengobatan. Secara umum, berikut adalah dosis Daiticin untuk mengobati infeksi bakteri:', '["Daiticin"]', '["daitisin", "diticin", "d4iticin", "daltlcln", "daitici", "da1t1c1n", "daiticin", "500 mg thiamphenicol"]', '["d4iticin", "da1t1c1n", "daitici", "daitisin", "daltlcln", "diticin"]', 'DKL10000805A1', 'daiticin', '500mgthiamphenicol');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('labore-moisturizer', 'Labore Moisturizer', 'Labore Moisturizer', 'Skin care', 'Obat Keras (Lingkaran Merah K)', 'Krim dan gel', 'Melembapkan kulit sensitif', 'Tuangkan Labore Moisturizer secukupnya pada telapak tangan. Setelah itu, usapkan pada wajah dan leher, dapat digunakan lebih banyak pada area yang sangat kering jika diperlukan.', '["Labore Moisturizer"]', '["labore moi5turizer", "labor3 moisturiz3r", "1abore moisturizer", "labore mo1stur1zer", "lab0re m0isturizer", "labore moisturiser", "labore moisturizer", "l4bore moisturizer", "iabore moisturizer"]', '["1abore moisturizer", "iabore moisturizer", "l4bore moisturizer", "lab0re m0isturizer", "labor3 moisturiz3r", "labore mo1stur1zer", "labore moi5turizer", "labore moisturiser"]', 'DKL10001826A1', 'laboremoisturizer', 'laboremoisturizer');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('quetvell-xr', 'Quetvell XR', 'Quetiapine', 'Antipsikotik atipikal', 'Obat Keras (Lingkaran Merah K)', 'Tablet lepas lambat', 'Mengobati gangguan mental, seperti skizofrenia , depresi mayor, dan gangguan bipolar', 'Dosis Quetvell XR ditentukan berdasarkan usia, kondisi, dan respons pasien terhadap pengobatan. Dosis akan ditentukan dan ditingkatkan secara bertahap oleh dokter.', '["Quetvell XR"]', '["quetve11 xr", "quetiapine", "qetvell xr", "quetvell x", "quetvell xr", "quetvell ksr", "quetveii xr", "qu3tv3ll xr"]', '["qetvell xr", "qu3tv3ll xr", "quetve11 xr", "quetveii xr", "quetvell ksr", "quetvell x"]', 'DKL10001052A1', 'quetvellxr', 'quetiapine');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('zensoderm', 'Zensoderm', 'Kombinasi betametason dan gentamicin', 'Kombinasi kortikosteroid topikal dan antibiotik topikal dari golongan aminoglikosida', 'Obat Keras (Lingkaran Merah K)', 'Krim', 'Mengobati infeksi bakteri pada kulit', 'Penggunaan Zensoderm harus sesuai petunjuk dokter, karena dosisnya bisa berbeda tergantung kondisi kulit. Secara umum, Zensoderm dioleskan tipis-tipis pada area kulit yang mengalami masalah sebanyak 2–3 kali sehari.', '["Zensoderm"]', '["znsoderm", "z3nsod3rm", "sensoderm", "zensoderm", "kombinasi betametason dan gentamicin", "zen5oderm", "zens0derm", "zensoderrn", "zensoder"]', '["sensoderm", "z3nsod3rm", "zen5oderm", "zens0derm", "zensoder", "zensoderrn", "znsoderm"]', 'DKL10000951A1', 'zensoderm', 'kombinasibetametasondangentamicin');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('iafed', 'Iafed', 'Dexchlorpheniramine maleate 2 mg, guaifenesin 100 mg, dan pseudoephedrine HCl 30 mg', 'Obat flu kombinasi dekongestan (pseudoephedrine), antihistamin (dexchlorpheniramine maleate), dan ekspektoran (guaifenesin)', 'Obat Bebas Terbatas (Lingkaran Biru)', 'Tablet dan sirop', 'Mengatasi gejala flu yang disertai batuk', 'Untuk mengatasi gejala flu disertai dengan batuk berdahak, berikut ini adalah dosis umum penggunaan Iafed berdasarkan bentuk sediaannya:', '["Iafed"]', '["dexchlorpheniramine maleate 2 mg, guaifenesin 100 mg, dan pseudoephedrine hcl 30 mg", "iaphed", "iaf3d", "i4fed", "iafed", "1afed", "lafed"]', '["1afed", "i4fed", "iaf3d", "iaphed", "lafed"]', 'DTL10000473A1', 'iafed', 'dexchlorpheniraminemaleate2mgguaifenesin100mgdanpseudoephedrinehcl30mg');
