INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('quidex', 'Quidex', 'Ciprofloxacin 500 mg', 'Antibiotik jenis quinolone', 'Obat Keras (Lingkaran Merah K)', 'Tablet salut selaput', 'Mengatasi infeksi bakteri', 'Dosis Quidex pada tiap pasien tergantung pada kondisi yang ditangani. Namun, secara umum dosis Quidex yang diberikan dokter adalah:', '["Quidex"]', '["qidex", "quldex", "qu1dex", "quid3x", "quidex", "quideks", "quide", "ciprofloxacin 500 mg"]', '["qidex", "qu1dex", "quid3x", "quide", "quideks", "quldex"]', 'DKL10000624A1', 'quidex', 'ciprofloxacin500mg');
