INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('valciron', 'Valciron', 'Valacyclovir hydrochloride 500 mg', 'Obat antivirus', 'Obat Keras (Lingkaran Merah K)', 'Kaplet salut selaput', 'Menangani infeksi virus herpes, seperti herpes zoster, herpes bibir, atau herpes genital.', 'Dosis Valciron akan ditentukan oleh dokter berdasarkan kondisi, usia, dan respons pasien terhadap pengobatan. Berikut adalah dosis umum Valciron sesuai tujuan pengobatannya:', '["Valciron"]', '["valciron", "vaiciron", "v4lciron", "valcir0n", "valclron", "valacyclovir hydrochloride 500 mg", "valc1ron", "va1ciron", "valsiron", "valciro"]', '["v4lciron", "va1ciron", "vaiciron", "valc1ron", "valcir0n", "valciro", "valclron", "valsiron"]', 'DKL10000830A1', 'valciron', 'valacyclovirhydrochloride500mg');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('beneuron', 'Beneuron', 'Thiamine mononitrate (vitamin B1) 100 mg, pyridoxine hydrochloride (vitamin B6) 200 mg, dan cyanocobalamin (vitamin B12) 0,2 mg', 'Suplemen vitamin', 'Obat Bebas (Hijau)', 'Tablet salut gula', 'Mengatasi gejala gangguan saraf karena kekurangan vitamin B1, B6, dan B12.', 'Dosis Beneuron sebagai obat saraf atau obat kesemutan yang dianjurkan adalah 1 tablet per hari, atau menurut petunjuk dokter.', '["Beneuron"]', '["beneuron", "thiamine mononitrate (vitamin b1) 100 mg, pyridoxine hydrochloride (vitamin b6) 200 mg, dan cyanocobalamin (vitamin b12) 0,2 mg", "beneuro", "bneuron", "beneur0n", "b3n3uron"]', '["b3n3uron", "beneur0n", "beneuro", "bneuron"]', 'DBL10000830A1', 'beneuron', 'thiaminemononitratevitaminb1100mgpyridoxinehydrochloridevitaminb6200mgdancyanocobalaminvitaminb1202mg');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('benodex', 'Benodex', 'Dexamethasone', 'Kortikosteroid', 'Obat Keras (Lingkaran Merah K)', 'Kapet dan suntik', 'Menangani peradangan pada berbagai kondisi, seperti radang sendi , alergi, asma, lupus , atau psoriasis', 'Dosis Benodex yang diberikan dokter kepada tiap pasien tergantung pada sediaan obat dan kondisi yang ditangani. Berikut adalah dosis Benodex untuk orang dewasa berdasarkan sediaan obatnya:', '["Benodex"]', '["benode", "benodeks", "b3nod3x", "bnodex", "benodex", "dexamethasone", "ben0dex"]', '["b3nod3x", "ben0dex", "benode", "benodeks", "bnodex"]', 'DKL10000709A1', 'benodex', 'dexamethasone');
