INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('valcor', 'Valcor', 'Valacyclovir 500 mg', 'Antibiotik', 'Obat Keras (Lingkaran Merah K)', 'Tablet salut selaput', 'Mengatasi infeksi virus herpes', 'Valcor harus digunakan sesuai dosis yang ditentukan dokter, karena setiap pasien memiliki kondisi yang berbeda-beda termasuk usia, berat badan, dan tingkat keparahan infeksi. Berikut adalah panduan umum dosis valacyclovir dalam Valcor:', '["Valcor"]', '["va1cor", "v4lcor", "valc0r", "valacyclovir 500 mg", "vlcor", "vaicor", "valcor", "valco", "valsor"]', '["v4lcor", "va1cor", "vaicor", "valc0r", "valco", "valsor", "vlcor"]', 'DKL10000615A1', 'valcor', 'valacyclovir500mg');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('farsifen', 'Farsifen', 'Farsifen Kaplet dan Farsifen Forte: ibuprofen', 'Obat antiinflamasi nonsteroid ( OAINS ), antipretik, dan analgesik', 'Obat Keras (Lingkaran Merah K)', 'Kaplet, suspensi', 'Meredakan demam, nyeri, dan peradangan', 'Berikut ini adalah dosis Farsifen untuk meredakan nyeri dan peradangan berdasarkan usia pasien, jenis, dan kandungan obat:', '["Farsifen"]', '["fars1fen", "f4rsifen", "farsif3n", "farsifen kaplet dan farsifen forte: ibuprofen", "pharsiphen", "farsifen", "farsife", "farslfen", "far5ifen", "frsifen"]', '["f4rsifen", "far5ifen", "fars1fen", "farsif3n", "farsife", "farslfen", "frsifen", "pharsiphen"]', 'DKL10000814A1', 'farsifen', 'farsifenkapletdanfarsifenforteibuprofen');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('ibrance', 'Ibrance', 'Palbociclib', 'Terapi Target untuk Kanker', 'Obat Keras (Lingkaran Merah K)', 'Tablet salut selaput', 'Pengobatan kanker payudara stadium lanjut atau yang sudah menyebar ( metastasis )', 'Dosis Ibrance bisa berbeda pada tiap orang, tergantung jenis gangguan yang dialami dan seberapa parah kondisinya. Secara umum, dosisnya adalah sebagai berikut:', '["Ibrance"]', '["ibr4nce", "1brance", "palbociclib", "irance", "ibrance", "ibranc", "ibranse", "lbrance", "ibranc3"]', '["1brance", "ibr4nce", "ibranc", "ibranc3", "ibranse", "irance", "lbrance"]', 'DKL10000692A1', 'ibrance', 'palbociclib');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('valdimex', 'Valdimex', 'Diazepam', 'Benzodiazepine', 'Obat Keras (Lingkaran Merah K)', 'Injeksi', 'Menghentikan kejang , mengatasi gangguan kecemasan, melemaskan otot yang tegang atau kaku, dan memberikan efek penenang sebelum prosedur medis tertentu.', 'Valdimex injeksi diberikan oleh tenaga medis di fasilitas kesehatan. Dosis dan cara pemberian akan disesuaikan dengan kondisi pasien, seperti untuk kejang akut atau sedasi sebelum prosedur medis.', '["Valdimex"]', '["v4ldimex", "va1dimex", "valdim3x", "valdimeks", "diazepam", "valdirnex", "valdimex", "vaidimex", "valdime", "vald1mex"]', '["v4ldimex", "va1dimex", "vaidimex", "vald1mex", "valdim3x", "valdime", "valdimeks", "valdirnex"]', 'DKL10000826A1', 'valdimex', 'diazepam');
