INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('zentra', 'Zentra', 'Triprolidine dan pseudoephedrine', 'Obat batuk pilek dan alergi', 'Obat Keras (Lingkaran Merah K)', 'Kaplet dan sirop', 'Meringankan gejala alergi, flu, atau pilek, seperti bersin-bersin serta hidung meler atau tersumbat', 'Dosis dan aturan pakai Zentra ditentukan oleh dokter sesuai usia dan kondisi pasien. Berikut ini adalah dosis umum penggunaan Zentra:', '["Zentra"]', '["z3ntra", "zentr", "zntra", "zentr4", "zentra", "sentra", "triprolidine dan pseudoephedrine"]', '["sentra", "z3ntra", "zentr", "zentr4", "zntra"]', 'DKL10000628A1', 'zentra', 'triprolidinedanpseudoephedrine');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('farsifen-pct', 'Farsifen PCT', 'Paracetamol dan 200 mg ibuprofen', 'Analgesik dan antipiretik , obat antiinflamasi nonsteroid ( OAINS )', 'Obat Bebas Terbatas (Lingkaran Biru)', 'Kaplet', 'Mengatasi nyeri ringan hingga sedang, serta menurunkan demam', 'Dosis umum Farsifen PCT untuk meredakan nyeri dan menurunkan demam pada orang dewasa adalah 1 kaplet, diminum 3–4 kali sehari.', '["Farsifen PCT"]', '["paracetamol dan 200 mg ibuprofen", "far5ifen pct", "farslfen pct", "farsif3n pct", "farsifen pst", "f4rsifen pct", "farsifen pct", "fars1fen pct", "frsifen pct", "farsifen pc"]', '["f4rsifen pct", "far5ifen pct", "fars1fen pct", "farsif3n pct", "farsifen pc", "farsifen pst", "farslfen pct", "frsifen pct"]', 'DTL10001077A1', 'farsifenpct', 'paracetamoldan200mgibuprofen');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('caduet', 'Caduet', 'Amlodipine besilate dan Atorvastatin calcium trihydrate', 'Obat antihipertensi (amlodipine) dan penurun kolesterol (atorvastatin)', 'Obat Keras (Lingkaran Merah K)', 'Tablet salut selaput', 'Menurunkan tekanan darah pada penderita hipertensi, menurunkan kadar kolesterol jahat (LDL) dan trigliserida, meningkatkan kadar kolesterol baik (HDL), dan menurunkan risiko penyakit jantung dan stroke', 'Dosis Caduet Tablet umumnya disesuaikan dengan kondisi kesehatan, usia, dan riwayat penyakit yang diderita pasien. Namun, Caduet yang mengandung amlodipine dan atorvastatin dapat dikonsumsi dengan dosis umum berikut ini:', '["Caduet"]', '["cadue", "amlodipine besilate dan atorvastatin calcium trihydrate", "cduet", "saduet", "cadu3t", "caduet", "c4duet"]', '["c4duet", "cadu3t", "cadue", "cduet", "saduet"]', 'DKL10000598A1', 'caduet', 'amlodipinebesilatedanatorvastatincalciumtrihydrate');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('lacoldin', 'Lacoldin', 'Paracetamol, phenylpropanolamine HCl, dextromethorphan HBr, dan chlorpheniramine maleate', 'Dekongestan, antitusif, antihistamin, dan analgetik-antipiretik', 'Obat Bebas Terbatas (Lingkaran Biru)', 'Tablet dan sirop', 'Meringankan gejala flu yang disertai batuk', 'Berikut ini adalah dosis Lacoldin untuk meredakan gejala flu yang disertai batuk berdasarkan bentuk obatnya:', '["Lacoldin"]', '["1aco1din", "iacoidin", "lacoldln", "lacold1n", "paracetamol, phenylpropanolamine hcl, dextromethorphan hbr, dan chlorpheniramine maleate", "lacoldin", "lacoldi", "lac0ldin", "l4coldin", "lasoldin"]', '["1aco1din", "iacoidin", "l4coldin", "lac0ldin", "lacold1n", "lacoldi", "lacoldln", "lasoldin"]', 'DTL10000806A1', 'lacoldin', 'paracetamolphenylpropanolaminehcldextromethorphanhbrdanchlorpheniraminemaleate');
