INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('quinela', 'Quinela', 'Hydroquinone', 'Obat pencerah kulit', 'Obat Keras (Lingkaran Merah K)', 'Krim', 'Mencerahkan kulit yang menggelap atau mengalami hiperpigmentasi karena paparan sinar matahari, penuaan atau peradangan pada kulit', 'Quinela merupakan obat resep yang penggunaannya harus mengikuti anjuran dokter. Dosis pemakaian obat ini umumnya adalah 2 kali sehari yang dapat dioleskan secara tipis ke area kulit yang bermasalah.', '["Quinela"]', '["qu1nela", "quinel", "qulnela", "quin3la", "quinel4", "quineia", "quine1a", "quinela", "qinela", "hydroquinone"]', '["qinela", "qu1nela", "quin3la", "quine1a", "quineia", "quinel", "quinel4", "qulnela"]', 'DKL10000719A1', 'quinela', 'hydroquinone');
