INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('quinidine', 'Quinidine', 'Quinidine', 'Obat resep', 'Obat Keras (Lingkaran Merah K)', 'Tablet dan suntik', 'Mengobati gangguan irama jantung dan malaria', 'Dokter akan menyesuaikan dosis quinidine dengan usia, kondisi, tingkat keparahan kondisi, respon pasien terhadap obat ini. Berikut ini adalah dosis yang umumnya disarankan untuk quinidine bentuk tablet:', '["Quinidine", "seperti AV block", "myasthenia gravis", "menyusui", "penyakit ginjal", "penyakit hati"]', '["penyakit ginjal", "qu1n1d1ne", "quinidin", "quinidine", "menyusui", "seperti av block", "qinidine", "qulnldlne", "myasthenia gravis", "quinidin3"]', '["qinidine", "qu1n1d1ne", "quinidin", "quinidin3", "qulnldlne"]', 'DKL10000934A1', 'quinidine', 'quinidine');
