INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('dalacin-c', 'Dalacin C', 'Clindamycin 300 mg', 'Antibiotik turunan dari lincomycin', 'Obat Keras (Lingkaran Merah K)', 'Kapsul', 'Mengobati infeksi bakteri', 'Dosis Dalacin C ditentukan berdasarkan usia, berat badan, serta tingkat keparahan infeksi. Berikut dosis umum clindamycin dalam Dalacin C:', '["Dalacin C"]', '["daiacin c", "dalac1n c", "d4l4cin c", "dalacin c", "dalacln c", "dalasin s", "clindamycin 300 mg", "dalacin ", "da1acin c", "dlacin c"]', '["d4l4cin c", "da1acin c", "daiacin c", "dalac1n c", "dalacin ", "dalacln c", "dalasin s", "dlacin c"]', 'DKL10000783A1', 'dalacinc', 'clindamycin300mg');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('nemic', 'Nemic', 'Asam mefenamat', 'Obat antiinflamasi nonsteroid (OAINS)', 'Obat Keras (Lingkaran Merah K)', 'Kaplet', 'Meredakan nyeri ringan hingga sedang', 'Dosis Nemic yang diresepkan oleh dokter dapat berbeda-beda tergantung kondisi dan usia pasien. Berikut ini adalah dosis umum pemberian Nemic:', '["Nemic"]', '["nemis", "nemic", "nem1c", "nemlc", "nernic", "n3mic", "asam mefenamat"]', '["n3mic", "nem1c", "nemis", "nemlc", "nernic"]', 'DKL10000492A1', 'nemic', 'asammefenamat');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('tamcocin', 'Tamcocin', 'Lincomycin', 'Antibiotik lincosamide', 'Obat Keras (Lingkaran Merah K)', 'Kapsul', 'Mengatasi infeksi bakteri pada paru-paru, kulit, tulang, dan sendi', 'Berikut ini adalah dosis umum penggunaan Tamcocin untuk mengatasi infeksi bakteri berat berdasarkan usia atau berat badan pasien:', '["Tamcocin"]', '["tamc0cin", "lincomycin", "t4mcocin", "tamcocln", "tamcoci", "tamsosin", "tamcocin", "tmcocin", "tamcoc1n", "tarncocin"]', '["t4mcocin", "tamc0cin", "tamcoc1n", "tamcoci", "tamcocln", "tamsosin", "tarncocin", "tmcocin"]', 'DKL10000814A1', 'tamcocin', 'lincomycin');
