INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('cafmosol', 'Cafmosol', 'Paracetamol 600 mg, caffeine 50 mg', 'Analgetik-antipiretik', 'Obat Bebas (Hijau)', 'Kaplet', 'Mengurangi nyeri ringan hingga sedang', 'Meski merupakan obat bebas, Cafmosol tetap harus digunakan sesuai dengan dosis umum penggunaannya. Berikut ini adalah dosis penggunaan Cafmosol untuk meredakan demam dan nyeri berdasarkan usia pasien:', '["Cafmosol"]', '["caphmosol", "cafrnosol", "c4fmosol", "cafm0s0l", "cafmoso1", "cafmosol", "cafmosoi", "cafmo5ol", "cafmoso", "paracetamol 600 mg, caffeine 50 mg"]', '["c4fmosol", "cafm0s0l", "cafmo5ol", "cafmoso", "cafmoso1", "cafmosoi", "cafrnosol", "caphmosol"]', 'DBL10000820A1', 'cafmosol', 'paracetamol600mgcaffeine50mg');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('daktazol', 'Daktazol', 'Miconazole', 'Antijamur topikal', 'Obat Bebas Terbatas (Lingkaran Biru)', 'Krim', 'Mengobati infeksi jamur kulit, seperti panu , kutu air ( tinea pedis ), kurap di leher dan badan ( tinea corporis ), kurap selangkangan ( tinea cruris ), atau kandidiasis kulit .', 'Oleskan Daktazol di area kulit yang perlu diobati, 2 kali sehari. Lama pengobatan tergantung pada jenis dan luas infeksi, umumnya 2–6 minggu atau hingga gejala sembuh total. Untuk mencegah kambuh kembali, pengobatan harus diteruskan sampai 1 minggu setelah semua gejala hilang.', '["Daktazol"]', '["daktazo", "d4kt4zol", "dktazol", "daktazo1", "daktaz0l", "daktazol", "daktasol", "daktazoi", "miconazole"]', '["d4kt4zol", "daktasol", "daktaz0l", "daktazo", "daktazo1", "daktazoi", "dktazol"]', 'DTL10000826A1', 'daktazol', 'miconazole');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('cal-95', 'Cal-95', 'Coral calcium , natural soy isoflavon e, vitamin D3, vitamin K1, magnesium, zinc, boron', 'Suplemen vitamin dan mineral', 'Obat Tradisional / Jamu (Logo Pohon)', 'Kaplet', 'Menjaga kesehatan tulang', 'Dosis Cal-95 yang dianjurkan adalah sebanyak 1–3 kaplet per hari.', '["Cal-95"]', '["cl-95", "ca1-95", "cai-95", "cal-95", "c4l-95", "sal-95", "coral calcium , natural soy isoflavon e, vitamin d3, vitamin k1, magnesium, zinc, boron", "cal-9"]', '["c4l-95", "ca1-95", "cai-95", "cal-9", "cl-95", "sal-95"]', 'TR10000427A1', 'cal95', 'coralcalciumnaturalsoyisoflavonevitamind3vitamink1magnesiumzincboron');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('farsiretic', 'Farsiretic', 'Furosemide', 'Diuretik', 'Obat Keras (Lingkaran Merah K)', 'Tablet', 'Menangani edema akibat gagal jantung kongestif, penyakit ginjal, atau sirosis', 'Farsiretic tersedia dalam bentuk tablet 40 mg. Dosis Farsiretic yang diberikan oleh dokter tergantung pada kondisi, usia, dan respons tubuh terhadap pengobatan. Untuk anak-anak, dosis obat juga diberikan berdasarkan berat badan.', '["Farsiretic"]', '["far5iretic", "farsiretic", "farslretlc", "f4rsiretic", "frsiretic", "furosemide", "farsir3tic", "farsireti", "fars1ret1c", "farsiretis"]', '["f4rsiretic", "far5iretic", "fars1ret1c", "farsir3tic", "farsireti", "farsiretis", "farslretlc", "frsiretic"]', 'DKL10001036A1', 'farsiretic', 'furosemide');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('ibrutinib', 'Ibrutinib', 'Ibrutinib', 'Obat penghambat protein kinase', 'Obat Keras (Lingkaran Merah K)', 'Tablet', 'Mengobati kanker darah , limfoma, dan graft versus host disease', 'Dosis dan aturan pakai ibrutinib akan ditentukan oleh dokter berdasarkan usia atau kondisi pasien. Berikut adalah dosis umum ibrutinib berdasarkan kondisi yang diatasi:', '["Ibrutinib", "limfoma", "aritmia", "gangguan perdarahan", "hipertensi", "kolesterol tinggi"]', '["aritmia", "ibrutini", "lbrutlnlb", "hipertensi", "limfoma", "1brut1n1b", "ibrutinib", "gangguan perdarahan", "irutinib"]', '["1brut1n1b", "ibrutini", "irutinib", "lbrutlnlb"]', 'DKL10000936A1', 'ibrutinib', 'ibrutinib');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('lacons', 'Lacons', 'Laktulosa', 'Obat pencahar', 'Obat Bebas (Hijau)', 'Sirop', 'Meredakan sembelit atau susah buang air besar.', 'Gunakan sesuai petunjuk dokter atau aturan pakai pada kemasan.', '["Lacons"]', '["lasons", "laktulosa", "lcons", "lacon", "lacon5", "iacons", "l4cons", "1acons", "lac0ns", "lacons"]', '["1acons", "iacons", "l4cons", "lac0ns", "lacon", "lacon5", "lasons", "lcons"]', 'DBL10000608A1', 'lacons', 'laktulosa');
