INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('dalfarol', 'Dalfarol', '200 IU vitamin E', 'Suplemen vitamin', 'Obat Bebas (Hijau)', 'Sediaan oral/topikal sesuai instruksi kemasan.', 'Memenuhi kebutuhan vitamin E harian dan memelihara kesehatan kulit', 'Dosis penggunaan Dalfarol untuk membantu memenuhi kebutuhan vitamin E harian dan memelihara kesehatan kulit adalah:', '["Dalfarol"]', '["da1faro1", "dalfarol", "dalfar0l", "d4lf4rol", "daifaroi", "dalpharol", "200 iu vitamin e", "dlfarol", "dalfaro"]', '["d4lf4rol", "da1faro1", "daifaroi", "dalfar0l", "dalfaro", "dalpharol", "dlfarol"]', 'DBL10000805A1', 'dalfarol', '200iuvitamine');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('quinolone', 'Quinolone', 'Quinolone', 'Pengobatan Umum', 'Obat Keras (Lingkaran Merah K)', 'Sediaan oral/topikal sesuai instruksi kemasan.', 'Mengatasi gangguan kesehatan dan meredakan gejala sesuai petunjuk medis.', 'Gunakan sesuai petunjuk dokter atau aturan pakai pada kemasan.', '["Quinolone", "bronkitis akut", "Urotractin", "cairan suntik", "tetes mata", "Bimaflox"]', '["qinolone", "quino1one", "quinolone", "quin0l0ne", "quinolon3", "bronkitis akut", "quinoione", "quinolon", "tetes mata", "qu1nolone", "qulnolone", "urotractin", "cairan suntik"]', '["qinolone", "qu1nolone", "quin0l0ne", "quino1one", "quinoione", "quinolon", "quinolon3", "qulnolone"]', 'DKL10000954A1', 'quinolone', 'quinolone');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('tamezol', 'Tamezol', 'Omeprazole', 'Penghambat pompa proton', 'Obat Keras (Lingkaran Merah K)', 'Kapsul lepas tunda', 'Menekan produksi asam lambung', 'Dokter akan menentukan dosis Tamezol dan lama pengobatannya berdasarkan usia, kondisi, atau respons tubuh pasien terhadap obat. Untuk anak-anak, dosis disesuaikan dengan berat badan (BB).', '["Tamezol"]', '["tamezol", "tarnezol", "tamezoi", "tamezo", "t4mezol", "tamesol", "tamezo1", "tamez0l", "omeprazole", "tam3zol"]', '["t4mezol", "tam3zol", "tamesol", "tamez0l", "tamezo", "tamezo1", "tamezoi", "tarnezol"]', 'DKL10000732A1', 'tamezol', 'omeprazole');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('valemia', 'Valemia', 'Simvastatin', 'Obat penurun kolesterol golongan statin', 'Obat Keras (Lingkaran Merah K)', 'Tablet salut selaput', 'Menurunkan kadar kolesterol dalam darah', 'Dosis Valemia dapat berbeda-beda untuk tiap pasien. Berikut ini adalah dosis umum penggunaan obat ini berdasarkan tujuan pengobatan dan usia pasien:', '["Valemia"]', '["simvastatin", "vaiemia", "valemla", "v4lemi4", "valemi", "val3mia", "valernia", "valem1a", "va1emia", "valemia"]', '["v4lemi4", "va1emia", "vaiemia", "val3mia", "valem1a", "valemi", "valemla", "valernia"]', 'DKL10000703A1', 'valemia', 'simvastatin');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('calacort', 'Calacort', 'Desonide 0,5 mg', 'Kortikosteroid topikal', 'Obat Keras (Lingkaran Merah K)', 'Krim', 'Meredakan gatal-gatal dan gejala peradangan pada kulit akibat sejumlah kondisi, seperti dermatitis , eksim, atau psoriasis', 'Untuk meredakan keluhan radang kulit, oleskan krim Calacort secara merata pada area kulit yang perlu diobati, 1–3 kali sehari atau sesuai petunjuk dokter. Jika keluhan tidak membaik setelah 2 minggu penggunaan, sebaiknya konsultasikan kembali ke dokter untuk evaluasi lebih lanjut.', '["Calacort"]', '["calac0rt", "salasort", "clacort", "calacort", "c4l4cort", "ca1acort", "calacor", "desonide 0,5 mg", "caiacort"]', '["c4l4cort", "ca1acort", "caiacort", "calac0rt", "calacor", "clacort", "salasort"]', 'DKL10000809A1', 'calacort', 'desonide05mg');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('zeos', 'Zeos', 'Loratadine', 'Antihistamin', 'Obat Keras (Lingkaran Merah K)', 'Sirop', 'Mengatasi keluhan alergi, seperti pada rhinitis alergi , biduran, atau konjungtivitis alergi', 'Secara umum, berikut adalah dosis penggunaan Zeos untuk mengobati alergi:', '["Zeos"]', '["seos", "ze0s", "zeos", "z3os", "zeo5", "loratadine"]', '["seos", "z3os", "ze0s", "zeo5"]', 'DKL10000417A1', 'zeos', 'loratadine');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('damaben', 'Damaben', 'Metoclopramide', 'Antiemetik', 'Obat Keras (Lingkaran Merah K)', 'Tablet, sirop, drops, dan suntik', 'Meredakan mual dan muntah', 'Berikut ini adalah dosis umum penggunaan Damaben berdasarkan kondisi pasien:', '["Damaben"]', '["metoclopramide", "damab3n", "damabe", "d4m4ben", "darnaben", "dmaben", "damaben"]', '["d4m4ben", "damab3n", "damabe", "darnaben", "dmaben"]', 'DKL10000680A1', 'damaben', 'metoclopramide');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('farsix', 'Farsix', 'Furosemide', 'Diuretik', 'Obat Keras (Lingkaran Merah K)', 'Tablet dan injeksi', 'Mengatasi penumpukan cairan di dalam tubuh', 'Dosis Farsix berbeda-beda, tergantung pada usia, berat badan, jenis gangguan yang diobati dan bentuk sediaannya. Berikut ringkasan dosis umum furosemide dalam Farsix:', '["Farsix"]', '["far5ix", "f4rsix", "farsi", "fars1x", "pharsix", "frsix", "farsix", "furosemide", "farslx", "farsiks"]', '["f4rsix", "far5ix", "fars1x", "farsi", "farsiks", "farslx", "frsix", "pharsix"]', 'DKL10000621A1', 'farsix', 'furosemide');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('ibuprofen-rektal', 'Ibuprofen Rektal', 'Ibuprofen Rektal', 'Obat antiinflamasi nonsteroid ( NSAID )', 'Obat Keras (Lingkaran Merah K)', 'Enema dan suppositoria', 'Meredakan nyeri skala ringan hingga sedang, misalnya pada sakit gigi, nyeri haid , atau nyeri akibat terkilir', 'Berikut adalah dosis ibuprofen rektal untuk meredakan demam dan nyeri berdasarkan sediaan obatnya:', '["Ibuprofen Rektal", "Iprox Enema", "misalnya pada sakit gigi", "nyeri haid", "seperti pada rheumatoid arthritis", "osteoarthritis"]', '["ibuprofen rekta", "ibuprofen rekta1", "seperti pada rheumatoid arthritis", "iprox enema", "nyeri haid", "1buprofen rektal", "ibuprofen rektal", "ibuprofen rektai", "misalnya pada sakit gigi", "ibupr0fen rektal", "ibuprof3n r3ktal", "ibuprofen rekt4l", "ibuprophen rektal"]', '["1buprofen rektal", "ibupr0fen rektal", "ibuprof3n r3ktal", "ibuprofen rekt4l", "ibuprofen rekta", "ibuprofen rekta1", "ibuprofen rektai", "ibuprophen rektal"]', 'DKL10001581A1', 'ibuprofenrektal', 'ibuprofenrektal');
