INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('lacosib', 'Lacosib', 'Etoricoxib', 'Obat antiinflamasi nonsteroid ( OAINS ) jenis COX-2 inhibitor', 'Obat Keras (Lingkaran Merah K)', 'Tablet salut selaput', 'Mengatasi nyeri muskuloskeletal (nyeri pada sendi, ligamen, otot, tendon, atau tulang) yang bersifat kronis atau berkepanjangan.', 'Dosis Lacosib yang diresepkan oleh dokter dapat berbeda-beda pada tiap pasien. Berikut ini adalah dosis umum penggunaan Lacosib berdasarkan kondisi pasien:', '["Lacosib"]', '["l4cosib", "iacosib", "laco5ib", "lacosib", "lacoslb", "lac0sib", "lacos1b", "lacosi", "etoricoxib", "1acosib"]', '["1acosib", "iacosib", "l4cosib", "lac0sib", "laco5ib", "lacos1b", "lacosi", "lacoslb"]', 'DKL10000701A1', 'lacosib', 'etoricoxib');
