INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('neo-gynoxa', 'Neo Gynoxa', 'Metronidazole 500 mg dan nystatin 100.000 IU', 'Kombinasi antimikroba dan antijamur', 'Obat Keras (Lingkaran Merah K)', 'Ovula atau tablet vagina', 'Mengatasi infeksi vagina', 'Dosis Neo Gynoxa ditentukan oleh dokter sesuai kondisi pasien. Untuk mengatasi infeksi vagina, dosis Neo Gynoxa yang umum adalah 1 ovula per hari selama 7–10 hari berturut-turut.', '["Neo Gynoxa"]', '["metronidazole 500 mg dan nystatin 100.000 iu", "neo gynoksa", "no gynoxa", "n3o gynoxa", "neo gynoxa", "neo gynox", "ne0 gyn0xa", "neo gynox4"]', '["n3o gynoxa", "ne0 gyn0xa", "neo gynoksa", "neo gynox", "neo gynox4", "no gynoxa"]', 'DKL10000952A1', 'neogynoxa', 'metronidazole500mgdannystatin100000iu');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('farsorbid', 'Farsorbid', 'Isosorbide dinitrate', 'Nitrat', 'Obat Keras (Lingkaran Merah K)', 'Tablet, tablet sublingual, dan suntik', 'Mencegah dan mengobati angina pektoris', 'Dosis Farsorbid yang diberikan dokter dapat berbeda pada tiap pasien, tergantung pada sediaan obat dan kondisi yang ditangani. Berikut adalah penjelasannya:', '["Farsorbid"]', '["isosorbide dinitrate", "farsorb1d", "farsorbid", "fars0rbid", "farsorbld", "farsorbi", "f4rsorbid", "pharsorbid", "frsorbid", "far5orbid"]', '["f4rsorbid", "far5orbid", "fars0rbid", "farsorb1d", "farsorbi", "farsorbld", "frsorbid", "pharsorbid"]', 'DKL10000924A1', 'farsorbid', 'isosorbidedinitrate');
