INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('neo-napacin', 'Neo Napacin', 'Teofilin dan ephedrine', 'Bronkodilator', 'Obat Keras (Lingkaran Merah K)', 'Tablet', 'Mengatasi gejala mengi, batuk, dan sesak napas, akibat asma atau PPOK', 'Dosis Neo Napacin berbeda-beda tergantung bentuk obat, usia, dan kondisi kesehatan pasien. Berikut panduan dosis umum teofilin dan ephedrine dalam Neo Napacin:', '["Neo Napacin"]', '["ne0 napacin", "neo napaci", "neo napacin", "no napacin", "n3o napacin", "neo napasin", "neo napac1n", "neo napacln", "neo n4p4cin", "teofilin dan ephedrine"]', '["n3o napacin", "ne0 napacin", "neo n4p4cin", "neo napac1n", "neo napaci", "neo napacln", "neo napasin", "no napacin"]', 'DKL10001020A1', 'neonapacin', 'teofilindanephedrine');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('radium', 'Radium', 'Radium', 'Zat radioaktif', 'Obat Keras (Lingkaran Merah K)', 'Suntik', 'Mengobati kanker prostat yang menyebar ke tulang', 'Dokter akan menentukan dosis radium suntik berdasarkan berat badan pasien. Dosis dapat berubah bila terjadi kenaikan atau penurunan berat badan pada pasien.', '["Radium", "menyusui", "trombositopenia", "gangguan fungsi ginjal", "tinja", "suplemen"]', '["gangguan fungsi ginjal", "r4dium", "radiurn", "radium", "trombositopenia", "tinja", "radlum", "rdium", "menyusui", "rad1um", "radiu"]', '["r4dium", "rad1um", "radiu", "radiurn", "radlum", "rdium"]', 'DKL10000610A1', 'radium', 'radium');
