INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('lactobacillus-acidophilus', 'Lactobacillus acidophilus', 'Lactobacillus acidophilus', 'Probiotik', 'Obat Bebas (Hijau)', 'Kapsul, serbuk, tablet salut selaput', 'Menjaga keseimbangan bakteri baik dalam saluran cerna dan membantu mengatasi diare', 'Lactobacillus acidophilus sering ditemukan dalam bentuk suplemen atau produk fermentasi, seperti yoghurt. Ikuti aturan pakai yang tertera pada kemasan atau anjuran dokter saat mengonsumsi produk ini.', '["Lactobacillus acidophilus", "Hexbio", "Lacto-B", "Liprolac Baby", "L-Bio", "Protexin"]', '["lactobacillus acidofilus", "l4ctob4cillus 4cidophilus", "lact0bacillus acid0philus", "liprolac baby", "iactobaciiius acidophiius", "lactobac1llus ac1doph1lus", "1actobaci11us acidophi1us", "lactobacillu5 acidophilu5", "fruit 18", "lactobacillus acidophilu", "lactobacillus acidophilus", "lacto-b", "hexbio"]', '["1actobaci11us acidophi1us", "iactobaciiius acidophiius", "l4ctob4cillus 4cidophilus", "lact0bacillus acid0philus", "lactobac1llus ac1doph1lus", "lactobacillu5 acidophilu5", "lactobacillus acidofilus", "lactobacillus acidophilu"]', 'DBL10002551A1', 'lactobacillusacidophilus', 'lactobacillusacidophilus');
