INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('neo-rheumacyl-neuro', 'Neo Rheumacyl Neuro', 'Ibuprofen 200 mg, thiamin mononitrate ( vitamin B1 ) 50 mg, pyridoxine ( vitamin B6 ) 100 mg, dan cynacobalamine ( vitamin B12 ) 100 mcg', 'Obat antiinflamasi nonsteroid ( NSAID ) kombinasi vitamin neurotropik', 'Obat Bebas Terbatas (Lingkaran Biru)', 'Kaplet salut selaput', 'Meredakan nyeri yang disertai dengan kebas, kesemutan, atau kram', 'Dosis Neo Rheumacyl Neuro untuk orang dewasa adalah 1 kaplet, 3 kali sehari.', '["Neo Rheumacyl Neuro"]', '["ne0 rheumacyl neur0", "neo rheurnacyl neuro", "n3o rh3umacyl n3uro", "neo rheumasyl neuro", "neo rheumacyl neur", "neo rheumacy1 neuro", "neo rheum4cyl neuro", "neo rheumacyl neuro", "ibuprofen 200 mg, thiamin mononitrate ( vitamin b1 ) 50 mg, pyridoxine ( vitamin b6 ) 100 mg, dan cynacobalamine ( vitamin b12 ) 100 mcg", "neo rheumacyi neuro"]', '["n3o rh3umacyl n3uro", "ne0 rheumacyl neur0", "neo rheum4cyl neuro", "neo rheumacy1 neuro", "neo rheumacyi neuro", "neo rheumacyl neur", "neo rheumasyl neuro", "neo rheurnacyl neuro"]', 'DTL10001813A1', 'neorheumacylneuro', 'ibuprofen200mgthiaminmononitratevitaminb150mgpyridoxinevitaminb6100mgdancynacobalaminevitaminb12100mcg');
