INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('rafacort', 'Rafacort', 'Triamcinolone 4 mg', 'Kortikosteroid', 'Obat Keras (Lingkaran Merah K)', 'Kaplet', 'Mengatasi peradangan dan reaksi alergi', 'Berdasarkan kandungannya, rekomendasi dosis Rafacort untuk dewasa adalah 4–48 mg per hari, tergantung pada jenis dan tingkat keparahan penyakit yang diobati.', '["Rafacort"]', '["rafac0rt", "rafasort", "raphacort", "rfacort", "rafacort", "r4f4cort", "rafacor", "triamcinolone 4 mg"]', '["r4f4cort", "rafac0rt", "rafacor", "rafasort", "raphacort", "rfacort"]', 'DKL10000818A1', 'rafacort', 'triamcinolone4mg');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('valsartan', 'Valsartan', 'Valsartan', 'Angiotensin receptor blocker (ARB)', 'Obat Keras (Lingkaran Merah K)', 'Tablet dan kaplet', 'Mengatasi hipertensi atau gagal jantung', 'Dosis valsartan yang diberikan dokter dapat berbeda, tergantung pada usia dan kondisi pasien. Berikut ini adalah rincian dosis umum valsartan:', '["Valsartan", "Diovan", "Exforge", "Lapiva", "Pavartan", "Tensor"]', '["exforge", "tensor", "pavartan", "valsartan", "v4ls4rt4n", "va1sartan", "vaisartan", "val5artan", "valsarta", "vlsartan", "lapiva", "diovan"]', '["v4ls4rt4n", "va1sartan", "vaisartan", "val5artan", "valsarta", "vlsartan"]', 'DKL10000940A1', 'valsartan', 'valsartan');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('zibramax', 'Zibramax', 'Azithromycin', 'Antibiotik makrolida', 'Obat Keras (Lingkaran Merah K)', 'Kaplet salut selaput dan sirup', 'Mengobati infeksi bakteri', 'Dosis Zibramax dapat berbeda untuk setiap individu dan akan ditentukan oleh dokter berdasarkan kondisi medis, serta respons tubuh terhadap pengobatan.', '["Zibramax"]', '["zibramax", "zibr4m4x", "zibrarnax", "zibrama", "zibramaks", "zlbramax", "sibramax", "z1bramax", "zbramax", "azithromycin"]', '["sibramax", "z1bramax", "zbramax", "zibr4m4x", "zibrama", "zibramaks", "zibrarnax", "zlbramax"]', 'DKL10000830A1', 'zibramax', 'azithromycin');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('zevask', 'Zevask', 'Amlodipine', 'Antagonis kalsium', 'Obat Keras (Lingkaran Merah K)', 'Kaplet', 'Menurunkan tekanan darah pada hipertensi', 'Dosis Zevask yang diberikan oleh dokter tergantung pada usia, kondisi kesehatan, dan respon tubuh pasien terhadap obat. Berikut ini adalah dosis umum Zevask untuk mengobati hipertensi atau angina pektoris:', '["Zevask"]', '["zev4sk", "amlodipine", "zevas", "zeva5k", "zvask", "zevask", "z3vask", "sevask"]', '["sevask", "z3vask", "zev4sk", "zeva5k", "zevas", "zvask"]', 'DKL10000628A1', 'zevask', 'amlodipine');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('lactobacillus-plantarum', 'Lactobacillus plantarum', 'Lactobacillus plantarum', 'Suplemen probiotik', 'Obat Bebas (Hijau)', 'Tablet kunyah dan serbuk', 'Membantu mengatasi masalah pencernaan, infeksi saluran pencernaan, infeksi vagina, infeksi saluran kemih, dan dermatitis atopik (eksim)', 'Dosis umum penggunaan Lactobacillus plantarum adalah 50 juta hingga 10 milyar CFU, diminum 1 kali sehari.', '["Lactobacillus plantarum", "infeksi saluran pencernaan", "infeksi vagina", "infeksi saluran kemih", "produk herbal", "kering"]', '["lact0bacillus plantarum", "iactobaciiius piantarum", "infeksi vagina", "lactobacillus plantaru", "infeksi saluran kemih", "lactobacillu5 plantarum", "lactobacillus plantarurn", "produk herbal", "1actobaci11us p1antarum", "lactobacillus plantarum", "l4ctob4cillus pl4nt4rum", "infeksi saluran pencernaan", "lactobac1llus plantarum"]', '["1actobaci11us p1antarum", "iactobaciiius piantarum", "l4ctob4cillus pl4nt4rum", "lact0bacillus plantarum", "lactobac1llus plantarum", "lactobacillu5 plantarum", "lactobacillus plantaru", "lactobacillus plantarurn"]', 'DBL10002358A1', 'lactobacillusplantarum', 'lactobacillusplantarum');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('dapagliz', 'Dapagliz', 'Dapagliflozin', 'Antidiabetes', 'Obat Keras (Lingkaran Merah K)', 'Tablet salut selaput', 'Mengontrol kadar gula darah pada diabetes tipe 2', 'Berikut ini adalah dosis umum penggunaan Dapagliz berdasarkan kondisi pasien:', '["Dapagliz"]', '["d4p4gliz", "dapagli", "dapagllz", "dapagiiz", "dapag1iz", "dapagliz", "dpagliz", "dapagl1z", "dapagliflozin", "dapaglis"]', '["d4p4gliz", "dapag1iz", "dapagiiz", "dapagl1z", "dapagli", "dapaglis", "dapagllz", "dpagliz"]', 'DKL10000812A1', 'dapagliz', 'dapagliflozin');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('tapentadol', 'Tapentadol', 'Tapentadol', 'Antinyeri golongan opioid', 'Obat Keras (Lingkaran Merah K)', 'Tablet', 'Mengatasi nyeri sedang hingga berat, serta mengobati nyeri neuropatik pada pasien diabetes', 'Dokter akan menentukan dosis dan durasi pengobatan dengan tapentadol berdasarkan usia, kondisi, dan respons tubuh obat. Berikut ini adalah dosis tapentadol untuk orang dewasa berdasarkan kondisi pasien:', '["Tapentadol", "gangguan pernapasan berat", "obstruksi usus", "penyakit liver", "tumor otak", "penyakit kandung empedu"]', '["penyakit liver", "obstruksi usus", "tapentad0l", "tpentadol", "tapentadoi", "tapentado", "tap3ntadol", "tapentado1", "gangguan pernapasan berat", "tapentadol", "t4pent4dol", "tumor otak"]', '["t4pent4dol", "tap3ntadol", "tapentad0l", "tapentado", "tapentado1", "tapentadoi", "tpentadol"]', 'DKL10001036A1', 'tapentadol', 'tapentadol');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('actos', 'Actos', 'Pioglitazone', 'Antidiabetes', 'Obat Keras (Lingkaran Merah K)', 'Tablet', 'Menurunkan kadar gula darah pada pasien diabetes tipe 2', 'Dosis Actos untuk mengobati diabetes tipe 2 pada orang dewasa adalah 15–30 mg, 1 kali sehari. Dosis maksimal 45 mg 1 kali sehari. Bila diperlukan, pengobatan dengan obat ini bisa dikombinasikan dengan obat diabetes lain, seperti sulfonilurea, metformin atau insulin.', '["Actos"]', '["actos", "4ctos", "astos", "pioglitazone", "acto5", "act0s"]', '["4ctos", "act0s", "acto5", "astos"]', 'DKL10000506A1', 'actos', 'pioglitazone');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('obat-anak-sumang-cap-pedang', 'Obat Anak Sumang Cap Pedang', 'Paracetamol', 'Analgetik-antipiretik', 'Obat Bebas (Hijau)', 'Puyer atau serbuk', 'Meredakan nyeri ringan, termasuk sakit gigi dan sakit kepala', 'Anak 2–5 tahun: 1 saset, 3–4 kali sehari. Anak 6–12 tahun: 2–3 saset, 3–4 kali sehari.', '["Obat Anak Sumang Cap Pedang"]', '["ob4t 4n4k sum4ng c4p ped4ng", "0bat anak sumang cap pedang", "obat anak sumang cap pedang", "obat anak sumang cap pedan", "obat anak sumang sap pedang", "oat anak sumang cap pedang", "obat anak surnang cap pedang", "obat anak sumang cap p3dang", "obat anak 5umang cap pedang", "paracetamol"]', '["0bat anak sumang cap pedang", "oat anak sumang cap pedang", "ob4t 4n4k sum4ng c4p ped4ng", "obat anak 5umang cap pedang", "obat anak sumang cap p3dang", "obat anak sumang cap pedan", "obat anak sumang sap pedang", "obat anak surnang cap pedang"]', 'DBL10002383A1', 'obatanaksumangcappedang', 'paracetamol');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('valsartan-hydrochlorothiazide', 'Valsartan-Hydrochlorothiazide', 'Valsartan-Hydrochlorothiazide', 'Kombinasi ARB (valsartan) dan diuretik thiazide ( hydrochlorothiazide)', 'Obat Keras (Lingkaran Merah K)', 'Tablet salut selaput', 'Menurunkan tekanan darah pada pasien hipertensi', 'Dosis penggunaan valsartan-hydrochlorothiazide akan ditentukan oleh dokter sesuai dengan kondisi kesehatan dan respons tubuh pasien terhadap pengobatan. Umumnya, tiap tablet obat mengandung valsartan-hydrochlorothiazide dengan jumlah yang bervariasi, yaitu:', '["Valsartan-Hydrochlorothiazide", "hydrochlorothiazide", "penyakit ginjal", "penyakit hati dan kandung empedu", "penyakit asam urat", "gangguan kelenjar paratiroid"]', '["valsartan-hydrochlorothiazide", "penyakit ginjal", "valsartan-hydrochlorothiazid", "valsartan-hydrochloroth1az1de", "va1sartan-hydroch1orothiazide", "penyakit asam urat", "v4ls4rt4n-hydrochlorothi4zide", "val5artan-hydrochlorothiazide", "penyakit hati dan kandung empedu", "valsartan-hydr0chl0r0thiazide", "valsartan-hydrochlorothiaside", "hydrochlorothiazide", "vaisartan-hydrochiorothiazide"]', '["v4ls4rt4n-hydrochlorothi4zide", "va1sartan-hydroch1orothiazide", "vaisartan-hydrochiorothiazide", "val5artan-hydrochlorothiazide", "valsartan-hydr0chl0r0thiazide", "valsartan-hydrochloroth1az1de", "valsartan-hydrochlorothiaside", "valsartan-hydrochlorothiazid"]', 'DKL10003000A1', 'valsartanhydrochlorothiazide', 'valsartanhydrochlorothiazide');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('fasgo', 'Fasgo', 'Paracetamol', 'Analgetik-antipiretik', 'Obat Bebas (Hijau)', 'Kaplet', 'Meredakan nyeri ringan hingga sedang, termasuk sakit gigi dan sakit kepala', 'Dewasa dan anak usia >12 tahun: 1–2 tablet, 3–4 kali sehari. Anak 6–12 tahun: ½–1 tablet, 3–4 kali sehari.', '["Fasgo"]', '["fasg0", "fasgo", "phasgo", "f4sgo", "fa5go", "paracetamol"]', '["f4sgo", "fa5go", "fasg0", "phasgo"]', 'DBL10000496A1', 'fasgo', 'paracetamol');
