INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('calcimega', 'Calcimega', 'Kalsium fosfat 450 mg, DHA 100 mg, Omega-3 20 mg, vitamin B1 (thiamine HCI) 2 mg, vitamin B6 (pyridoxine) 1,5 mg, vitamin B12 (cyanocobalamin) 5 mcg, vitamin D3 400 IU, dan vitamin B3 (nicotinamide) 10 mg', 'Suplemen', 'Obat Bebas (Hijau)', 'Sediaan oral/topikal sesuai instruksi kemasan.', 'Memenuhi kebutuhan nutrisi tubuh', 'Berikut adalah dosis umum penggunaan Calcimega untuk memenuhi kebutuhan nutrisi tubuh sekaligus memelihara kesehatan tulang dan gigi:', '["Calcimega"]', '["calcim3ga", "calcimeg", "calclmega", "kalsium fosfat 450 mg, dha 100 mg, omega-3 20 mg, vitamin b1 (thiamine hci) 2 mg, vitamin b6 (pyridoxine) 1,5 mg, vitamin b12 (cyanocobalamin) 5 mcg, vitamin d3 400 iu, dan vitamin b3 (nicotinamide) 10 mg", "caicimega", "ca1cimega", "calcimega", "calc1mega", "calcirnega", "c4lcimeg4"]', '["c4lcimeg4", "ca1cimega", "caicimega", "calc1mega", "calcim3ga", "calcimeg", "calcirnega", "calclmega"]', 'DBL10000886A1', 'calcimega', 'kalsiumfosfat450mgdha100mgomega320mgvitaminb1thiaminehci2mgvitaminb6pyridoxine15mgvitaminb12cyanocobalamin5mcgvitamind3400iudanvitaminb3nicotinamide10mg');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('lactobacillus-reuteri', 'Lactobacillus reuteri', 'Lactobacillus reuteri', 'Probiotik', 'Obat Bebas (Hijau)', 'Kapsul', 'Menjaga kesehatan fungsi saluran pencernaan; mengatasi gangguan pencernaan; menjaga kesehatan gigi, gusi, dan mulut; serta sebagai pengobatan tambahan pada infeksi saluran kemih atau infeksi vagina', 'Berikut adalah dosis umum Lactobacillus reuteri:', '["Lactobacillus reuteri", "Floragyn", "Interlac", "Interlac Rasa Strawberry", "Interlac Rasa Lemon", "Interlac Pro-D"]', '["lact0bacillus reuteri", "interlac rasa strawberry", "1actobaci11us reuteri", "lactobacillus reuteri", "lactobacillu5 reuteri", "interlac", "lactobacillus r3ut3ri", "lactobac1llus reuter1", "interlac rasa lemon", "iactobaciiius reuteri", "l4ctob4cillus reuteri", "lactobacillus reuter", "floragyn"]', '["1actobaci11us reuteri", "iactobaciiius reuteri", "l4ctob4cillus reuteri", "lact0bacillus reuteri", "lactobac1llus reuter1", "lactobacillu5 reuteri", "lactobacillus r3ut3ri", "lactobacillus reuter"]', 'DBL10002146A1', 'lactobacillusreuteri', 'lactobacillusreuteri');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('obat-antidiabetes', 'Obat Antidiabetes', 'Obat Antidiabetes', 'Pengobatan Umum', 'Obat Keras (Lingkaran Merah K)', 'Sediaan oral/topikal sesuai instruksi kemasan.', 'Mengatasi gangguan kesehatan dan meredakan gejala sesuai petunjuk medis.', 'Antidiabetes terbagi dalam beberapa golongan obat. Masing-masing golongan tersebut memiliki cara kerja yang berbeda dalam menurunkan kadar gula darah tinggi pada penderita diabetes.', '["Obat Antidiabetes", "keluhan yang timbul akibat diabetes", "seperti sering haus", "sering lapar", "dan sering buang air kecil", "Merek Dagang"]', '["obat antidiabetes", "0bat antidiabetes", "dan sering buang air kecil", "obat antidiabete", "oat antidiabetes", "obat antidiab3t3s", "keluhan yang timbul akibat diabetes", "ob4t 4ntidi4betes", "sering lapar", "seperti sering haus", "obat antidiabete5", "obat antldlabetes", "obat ant1d1abetes"]', '["0bat antidiabetes", "oat antidiabetes", "ob4t 4ntidi4betes", "obat ant1d1abetes", "obat antidiab3t3s", "obat antidiabete", "obat antidiabete5", "obat antldlabetes"]', 'DKL10001651A1', 'obatantidiabetes', 'obatantidiabetes');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('tarivid', 'Tarivid', 'Ofloxacin', 'Antibiotik quinolone', 'Obat Keras (Lingkaran Merah K)', 'Tablet', 'Mengobati infeksi bakteri, seperti infeksi saluran kemih, saluran napas, saluran pencernaan, kulit, tulang, hingga sendi', 'Dosis Tarivid akan disesuaikan dengan jenis infeksi, tingkat keparahan, usia, serta kondisi kesehatan pasien. Berikut ini beberapa contoh aturan pakai Tarivid yang umum diberikan sesuai kondisi yang diobati:', '["Tarivid"]', '["tar1v1d", "tarlvld", "tarivi", "t4rivid", "ofloxacin", "trivid", "tarivid"]', '["t4rivid", "tar1v1d", "tarivi", "tarlvld", "trivid"]', 'DKL10000723A1', 'tarivid', 'ofloxacin');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('raloxifen', 'Raloxifen', 'Raloxifen', 'Selective estrogen receptor modulators (terapi pengganti hormon)', 'Obat Keras (Lingkaran Merah K)', 'Tablet', 'Mencegah atau mengobati osteoporosis pada wanita pascamenopause', 'Dosis raloxifen akan diberikan oleh dokter sesuai kondisi pasien. Berikut adalah dosis raloxifen berdasarkan kondisi yang ditangani.', '["Raloxifen", "penyakit jantung koroner", "gagal jantung kongestif", "gangguan irama jantung", "trigliserida tinggi", "atau pernah mengalami penggumpalan darah"]', '["raloxife", "gangguan irama jantung", "r4loxifen", "raloxif3n", "raloksifen", "ra1oxifen", "gagal jantung kongestif", "trigliserida tinggi", "raioxifen", "penyakit jantung koroner", "ralox1fen", "ral0xifen", "raloxifen"]', '["r4loxifen", "ra1oxifen", "raioxifen", "ral0xifen", "raloksifen", "ralox1fen", "raloxif3n", "raloxife"]', 'DKL10000936A1', 'raloxifen', 'raloxifen');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('actrel', 'Actrel', 'Celecoxib', 'OAINS jenis COX-2 inhibitor', 'Obat Keras (Lingkaran Merah K)', 'Kapsul', 'Meredakan nyeri akibat osteoarthritis, rheumatoid arthritis, ankylosing spondylitis , juvenile idiopathic arthritis, migrain akut , atau dismenore', 'Berikut ini adalah dosis umum penggunaan Actrel berdasarkan kondisi dan usia pasien:', '["Actrel"]', '["astrel", "actrel", "celecoxib", "actr3l", "actre1", "atrel", "actrei", "4ctrel", "actre"]', '["4ctrel", "actr3l", "actre", "actre1", "actrei", "astrel", "atrel"]', 'DKL10000603A1', 'actrel', 'celecoxib');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('calcitonin', 'Calcitonin', 'Calcitonin', 'Preparat hormon', 'Obat Keras (Lingkaran Merah K)', 'Suntik', 'Menangani penyakit Paget, osteoporosis pascamenopause, dan hiperkalsemia.', 'Dosis calcitonin akan diberikan oleh dokter sesuai dengan kondisi yang ditangani, berat badan pasien, dan respons tubuh pasien terhadap obat. Calcitonin diberikan melalui suntikan ke jaringan lemak di bawah kulit atau ke dalam otot.', '["Calcitonin", "osteoporosis pascamenopause", "penyakit ginjal", "kekurangan kalsium hipokalsemia", "menyusui", "pusing"]', '["penyakit ginjal", "kekurangan kalsium hipokalsemia", "osteoporosis pascamenopause", "ca1citonin", "calcit0nin", "calc1ton1n", "calcitoni", "calcltonln", "clcitonin", "caicitonin", "calcitonin", "menyusui", "c4lcitonin"]', '["c4lcitonin", "ca1citonin", "caicitonin", "calc1ton1n", "calcit0nin", "calcitoni", "calcltonln", "clcitonin"]', 'DKL10001028A1', 'calcitonin', 'calcitonin');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('fasgo-forte-sirup', 'Fasgo Forte Sirup', 'Paracetamol', 'Analgetik-antipiretik', 'Obat Bebas (Hijau)', 'Sirop', 'Meredakan nyeri ringan, termasuk sakit gigi dan sakit kepala', 'Anak 6–12 tahun: 5–10 ml, 3–4 kali sehari. Anak >12 tahun: 10 ml, 3–4 kali sehari.', '["Fasgo Forte Sirup"]', '["fa5go forte 5irup", "fasgo fort3 sirup", "f4sgo forte sirup", "fasgo forte sirup", "fsgo forte sirup", "fasgo forte siru", "fasgo forte slrup", "fasgo forte s1rup", "fasg0 f0rte sirup", "paracetamol"]', '["f4sgo forte sirup", "fa5go forte 5irup", "fasg0 f0rte sirup", "fasgo fort3 sirup", "fasgo forte s1rup", "fasgo forte siru", "fasgo forte slrup", "fsgo forte sirup"]', 'DBL10001603A1', 'fasgofortesirup', 'paracetamol');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('dapsone', 'Dapsone', 'Dapsone', 'Antibiotik golongan sulfone', 'Obat Keras (Lingkaran Merah K)', 'Gel dan tablet', 'Mengobati kusta, dermatitis herpetiformis, dan jerawat, serta mengobati dan mencegah pneumocystis jiroveci pneumonia, atau toksoplasmosis, pada penderita HIV/AIDS.', 'Dosis dan durasi penggunaan dapsone akan ditentukan oleh dokter sesuai kondisi yang ingin ditangani dan usia pasien. Berikut ini adalah pembagian dosis dapsone berdasarkan bentuk obat dan kondisi yang akan ditangani:', '["Dapsone", "dermatitis herpetiformis", "dan jerawat", "atau toksoplasmosis", "porfiria", "methemoglobinemia"]', '["dapson", "dapson3", "dpsone", "dap5one", "atau toksoplasmosis", "dapsone", "porfiria", "dermatitis herpetiformis", "daps0ne", "dan jerawat", "d4psone"]', '["d4psone", "dap5one", "daps0ne", "dapson", "dapson3", "dpsone"]', 'DKL10000714A1', 'dapsone', 'dapsone');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('iflacort', 'Iflacort', 'Mometasone furoate 0.1%', 'Obat kortikosteroid', 'Obat Keras (Lingkaran Merah K)', 'Krim', 'Meredakan gejala peradangan pada kulit, yang disebabkan oleh reaksi alergi, dermatitis atopik ( eksim ), dermatitis seboroik , dan psoriasis.', 'Untuk mengatasi peradangan pada kulit, oleskan Iflacort ke area kulit yang meradang sebanyak 1 kali sehari. Iflacort sebaiknya tidak digunakan lebih dari 3 minggu.', '["Iflacort"]', '["mometasone furoate 0.1%", "1flacort", "iflacort", "if1acort", "iflasort", "iflac0rt", "ifiacort", "iflacor", "ilacort", "ifl4cort"]', '["1flacort", "if1acort", "ifiacort", "ifl4cort", "iflac0rt", "iflacor", "iflasort", "ilacort"]', 'DKL10000820A1', 'iflacort', 'mometasonefuroate01');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('wamistra', 'Wamistra', '2,5 mg letrozole', 'Antiestrogen', 'Obat Keras (Lingkaran Merah K)', 'Tablet salut selaput', 'Menangani kanker payudara pada wanita yang sudah menopause', 'Berikut ini adalah dosis umum penggunaan Wamistra untuk menangani kanker payudara pada wanita yang sudah menopause:', '["Wamistra"]', '["wamlstra", "wami5tra", "wam1stra", "wmistra", "warnistra", "2,5 mg letrozole", "wamistr", "wamistra", "w4mistr4"]', '["w4mistr4", "wam1stra", "wami5tra", "wamistr", "wamlstra", "warnistra", "wmistra"]', 'DKL10000840A1', 'wamistra', '25mgletrozole');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('lactobacillus-rhamnosus', 'Lactobacillus rhamnosus', 'Lactobacillus rhamnosus', 'Suplemen probiotik', 'Obat Bebas (Hijau)', 'Tablet, kapsul, bubuk saset, cair', 'Menjaga kesehatan usus, mengatasi gangguan pencernaan, dan membantu mengobati infeksi saluran kemih dan kelamin', 'Berikut adalah dosis Lactobacillus rhamnosus yang dianjurkan berdasarkan tujuan:', '["Lactobacillus rhamnosus", "Floragyn", "Protexin", "Lacidofil", "Chlostanin Maternity", "Chlostanin Hoken"]', '["l4ctob4cillus rh4mnosus", "protexin", "lacidofil", "lactobacillus rhamnosus", "iactobaciiius rhamnosus", "lact0bacillus rhamn0sus", "lactobacillu5 rhamno5u5", "lactobacillus rharnnosus", "1actobaci11us rhamnosus", "pro em-1", "lactobac1llus rhamnosus", "lactobacillus rhamnosu", "floragyn"]', '["1actobaci11us rhamnosus", "iactobaciiius rhamnosus", "l4ctob4cillus rh4mnosus", "lact0bacillus rhamn0sus", "lactobac1llus rhamnosus", "lactobacillu5 rhamno5u5", "lactobacillus rhamnosu", "lactobacillus rharnnosus"]', 'DBL10002370A1', 'lactobacillusrhamnosus', 'lactobacillusrhamnosus');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('obat-antihipertensi', 'Obat Antihipertensi', 'Obat Antihipertensi', 'Pengobatan Umum', 'Obat Keras (Lingkaran Merah K)', 'Sediaan oral/topikal sesuai instruksi kemasan.', 'Mengatasi gangguan kesehatan dan meredakan gejala sesuai petunjuk medis.', 'Obat antihipertensi hanya boleh digunakan berdasarkan resep dokter. Berikut ini adalah penjelasan dan pembagian jenis obat antihipertensi:', '["Obat Antihipertensi", "pembuluh darah dalam melebar", "aliran darah dapat lebih lancar", "Captopril", "Etapril", "Farmoten"]', '["ob4t 4ntihipertensi", "obat ant1h1pertens1", "aliran darah dapat lebih lancar", "oat antihipertensi", "obat antihiperten5i", "captopril", "etapril", "0bat antihipertensi", "obat antihipertens", "obat antihipertensi", "pembuluh darah dalam melebar", "obat antihip3rt3nsi", "obat antlhlpertensl"]', '["0bat antihipertensi", "oat antihipertensi", "ob4t 4ntihipertensi", "obat ant1h1pertens1", "obat antihip3rt3nsi", "obat antihiperten5i", "obat antihipertens", "obat antlhlpertensl"]', 'DKL10001901A1', 'obatantihipertensi', 'obatantihipertensi');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('ramadexon', 'Ramadexon', 'Dexamethasone', 'Kortikosteroid', 'Obat Keras (Lingkaran Merah K)', 'Kaplet', 'Meredakan peradangan, reaksi alergi, penyakit autoimun , asma , dan gangguan kulit atau sendi.', 'Dosis Ramadexon akan ditentukan oleh dokter berdasarkan kondisi dan usia pasien. Berikut adalah penjelasannya:', '["Ramadexon"]', '["rarnadexon", "ramadexo", "ramad3xon", "dexamethasone", "ramadexon", "ramadex0n", "rmadexon", "ramadekson", "r4m4dexon"]', '["r4m4dexon", "ramad3xon", "ramadekson", "ramadex0n", "ramadexo", "rarnadexon", "rmadexon"]', 'DKL10000927A1', 'ramadexon', 'dexamethasone');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('acyclovir-oral', 'Acyclovir Tablet', 'Acyclovir Tablet', 'Obat antivirus', 'Obat Keras (Lingkaran Merah K)', 'Tablet', 'Mengatasi infeksi virus herpes, seperti cacar air, cacar ular , atau herpes genital', 'Berikut ini adalah dosis umum penggunaan acyclovir tablet berdasarkan kondisi dan usia pasien:', '["Acyclovir Tablet", "Acifar", "Aciclovir Novell", "Clinovir", "Samclovir", "Virpes tablet"]', '["acifar", "acyclovir tablet", "samclovir", "4cyclovir t4blet", "acyc1ovir tab1et", "clinovir", "acyclov1r tablet", "acyciovir tabiet", "aciclovir novell", "acycl0vir tablet", "acyclovir tabl3t", "acyclovlr tablet", "acyclovir table"]', '["4cyclovir t4blet", "acyc1ovir tab1et", "acyciovir tabiet", "acycl0vir tablet", "acyclov1r tablet", "acyclovir tabl3t", "acyclovir table", "acyclovlr tablet"]', 'DKL10001576A1', 'acyclovirtablet', 'acyclovirtablet');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('warfarin', 'Warfarin', 'Warfarin', 'Antikoagulan', 'Obat Keras (Lingkaran Merah K)', 'Tablet', 'Mencegah dan mengatasi penggumpalan darah', 'Dosis awal warfarin biasanya 5–10 mg per hari selama 1–2 hari. Dosis perawatan ditentukan oleh dokter sesuai hasil pemeriksaan darah, umumnya antara 3–9 mg per hari.', '["Notisil", "Warfarin", "kecanduan minuman beralkohol", "gangguan mental atau suasana hati", "gangguan ingatan", "penyakit hati"]', '["w4rf4rin", "wrfarin", "kecanduan minuman beralkohol", "warpharin", "warfarln", "warfarin", "gangguan mental atau suasana hati", "warfar1n", "warfari", "notisil", "simarc 2"]', '["w4rf4rin", "warfar1n", "warfari", "warfarln", "warpharin", "wrfarin"]', 'DKL10000826A1', 'warfarin', 'warfarin');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('calcitonin-nasal-spray', 'Calcitonin Nasal Spray', 'Calcitonin Nasal Spray', 'Preparat hormon', 'Obat Keras (Lingkaran Merah K)', 'Semprot hidung', 'Mengatasi osteoporosis pada wanita yang sudah menopause lebih dari 5 tahun', 'Dosis calcitonin nasal spray untuk mengatasi osteoporosis pada wanita yang sudah menopause lebih dari 5 tahun adalah 200 unit (1 kali semprotan) per hari. Gunakan semprotan hidung ini hanya pada 1 sisi lubang hidung per hari. Gunakan ke lubang hidung yang lain pada hari berikutnya.', '["Calcitonin Nasal Spray", "menyusui", "kadar kalsium rendah hipokalsemia", "kekurangan vitamin D", "kering", "berkerak"]', '["kering", "calcitonin nasal spray", "kadar kalsium rendah hipokalsemia", "calcit0nin nasal spray", "calc1ton1n nasal spray", "calcltonln nasal spray", "calcitonin na5al 5pray", "ca1citonin nasa1 spray", "c4lcitonin n4s4l spr4y", "menyusui", "kekurangan vitamin d", "caicitonin nasai spray", "calcitonin nasal spra"]', '["c4lcitonin n4s4l spr4y", "ca1citonin nasa1 spray", "caicitonin nasai spray", "calc1ton1n nasal spray", "calcit0nin nasal spray", "calcitonin na5al 5pray", "calcitonin nasal spra", "calcltonln nasal spray"]', 'DKL10002114A1', 'calcitoninnasalspray', 'calcitoninnasalspray');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('ramadrinate', 'Ramadrinate', 'Dimenhydrinate', 'Antiemetik golongan antihistamin', 'Obat Bebas Terbatas (Lingkaran Biru)', 'Tablet', 'Mencegah atau mengobati mual, muntah, atau vertigo akibat mabuk perjalanan', 'Berikut adalah dosis umum penggunaan Ramadrinate untuk mengatasi mabuk perjalanan yang mengakibatkan mual, muntah, atau vertigo:', '["Ramadrinate"]', '["rmadrinate", "dimenhydrinate", "ramadr1nate", "rarnadrinate", "ramadrinat3", "ramadrinate", "ramadrinat", "ramadrlnate", "r4m4drin4te"]', '["r4m4drin4te", "ramadr1nate", "ramadrinat", "ramadrinat3", "ramadrlnate", "rarnadrinate", "rmadrinate"]', 'DTL10001128A1', 'ramadrinate', 'dimenhydrinate');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('fasgo-sirup', 'Fasgo Sirup', 'Paracetamol', 'Analgetik-antipiretik', 'Obat Bebas (Hijau)', 'Sirop', 'Meredakan nyeri ringan, termasuk sakit gigi dan sakit kepala', 'Dosis Fasgo sirup perlu disesuaikan dengan berat badan (BB) anak. Secara umum, dosisnya adalah 10–15 mg/kgBB setiap kali minum, diberikan setiap 4–6 jam, maksimal 4 kali sehari. Jangan melebihi dosis harian total 60 mg/kgBB per 24 jam.', '["Fasgo Sirup"]', '["phasgo sirup", "fsgo sirup", "fasg0 sirup", "fasgo s1rup", "fa5go 5irup", "fasgo slrup", "fasgo sirup", "f4sgo sirup", "fasgo siru", "paracetamol"]', '["f4sgo sirup", "fa5go 5irup", "fasg0 sirup", "fasgo s1rup", "fasgo siru", "fasgo slrup", "fsgo sirup", "phasgo sirup"]', 'DBL10001059A1', 'fasgosirup', 'paracetamol');
