INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('dapyrin', 'Dapyrin', 'Dapyrin tablet:', 'Analgesik dan antipiretik', 'Obat Bebas (Hijau)', 'Tablet dan sirop', 'Meredakan nyeri dan demam', 'Berikut ini dosis Dapyrin untuk meredakan demam dan nyeri berdasarkan bentuk obat dan usia pasien:', '["Dapyrin"]', '["dapyrin tablet:", "dapyrin", "d4pyrin", "dpyrin", "dapyri", "dapyr1n", "dapyrln"]', '["d4pyrin", "dapyr1n", "dapyri", "dapyrln", "dpyrin"]', 'DBL10000727A1', 'dapyrin', 'dapyrintablet');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('lactogrow', 'LACTOGROW - Nutrisi untuk Dukung Pencernaan Sehat Anak', 'LACTOGROW - Nutrisi untuk Dukung Pencernaan Sehat Anak', 'Susu pertumbuhan anak', 'Obat Keras (Lingkaran Merah K)', 'Susu bubuk', 'Membantu memelihara kesehatan pencernaan anak', 'Dosis dan takaran pemberian LACTOGROW ditentukan berdasarkan varian produk dan usia anak. Berikut ini adalah dosis atau takaran umum pemberian LACTOGROW kepada anak:', '["LACTOGROW - Nutrisi untuk Dukung Pencernaan Sehat Anak"]', '["lactogrow - nutrisi untuk dukung pencemaan sehat anak", "iactogrow - nutrisi untuk dukung pencernaan sehat anak", "lactogrow - nutrisi untuk dukung pencernaan sehat anak", "lactogrow - nutr1s1 untuk dukung pencernaan sehat anak", "lact0gr0w - nutrisi untuk dukung pencernaan sehat anak", "lactogrow - nutrisi untuk dukung p3nc3rnaan s3hat anak", "1actogrow - nutrisi untuk dukung pencernaan sehat anak", "lactogrow - nutri5i untuk dukung pencernaan 5ehat anak", "l4ctogrow - nutrisi untuk dukung pencern44n seh4t 4n4k"]', '["1actogrow - nutrisi untuk dukung pencernaan sehat anak", "iactogrow - nutrisi untuk dukung pencernaan sehat anak", "l4ctogrow - nutrisi untuk dukung pencern44n seh4t 4n4k", "lact0gr0w - nutrisi untuk dukung pencernaan sehat anak", "lactogrow - nutr1s1 untuk dukung pencernaan sehat anak", "lactogrow - nutri5i untuk dukung pencernaan 5ehat anak", "lactogrow - nutrisi untuk dukung p3nc3rnaan s3hat anak", "lactogrow - nutrisi untuk dukung pencemaan sehat anak"]', 'DKL10004797A1', 'lactogrownutrisiuntukdukungpencernaansehatanak', 'lactogrownutrisiuntukdukungpencernaansehatanak');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('obat-antivirus', 'Obat Antivirus', 'Obat Antivirus', 'Pengobatan Umum', 'Obat Keras (Lingkaran Merah K)', 'Sediaan oral/topikal sesuai instruksi kemasan.', 'Mengatasi gangguan kesehatan dan meredakan gejala sesuai petunjuk medis.', 'Gunakan sesuai petunjuk dokter atau aturan pakai pada kemasan.', '["Obat Antivirus", "Heplav", "Diltra", "Duviral", "Lamivudine-Zidovudine", "Telado"]', '["lamivudine-zidovudine", "oat antivirus", "obat antlvlrus", "obat antiviru", "duviral", "obat ant1v1rus", "obat antiviru5", "heplav", "ob4t 4ntivirus", "0bat antivirus", "obat antivirus", "diltra"]', '["0bat antivirus", "oat antivirus", "ob4t 4ntivirus", "obat ant1v1rus", "obat antiviru", "obat antiviru5", "obat antlvlrus"]', 'DKL10001387A1', 'obatantivirus', 'obatantivirus');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('tarivid-tetes-mata', 'Tarivid Tetes Mata', 'Ofloxacin', 'Antibiotik quinolone', 'Obat Keras (Lingkaran Merah K)', 'Tetes mata', 'Mengobati infeksi bakteri pada mata', 'Berikut ini adalah dosis penggunaan Tarivid tetes mata untuk mengobati infeksi bakteri pada anak-anak dan orang dewasa:', '["Tarivid Tetes Mata"]', '["t4rivid tetes m4t4", "ofloxacin", "tarivid tetes mat", "tarivid tetes mata", "tarivid t3t3s mata", "tarlvld tetes mata", "tarivid tete5 mata", "tarivid tetes rnata", "tar1v1d tetes mata", "trivid tetes mata"]', '["t4rivid tetes m4t4", "tar1v1d tetes mata", "tarivid t3t3s mata", "tarivid tete5 mata", "tarivid tetes mat", "tarivid tetes rnata", "tarlvld tetes mata", "trivid tetes mata"]', 'DKL10001691A1', 'tarividtetesmata', 'ofloxacin');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('acyclovir-topical', 'Acyclovir Topikal', 'Acyclovir Topikal', 'Obat antivirus', 'Obat Keras (Lingkaran Merah K)', 'Krim', 'Mengobati gejala herpes di kulit, bibir, atau kelamin.', 'Untuk mengobati herpes kulit, herpes kelamin, atau herpes bibir, oleskan acyclovir krim pada lenting-lenting atau luka lepuh, 5 kali sehari setiap 4 jam selama 4–10 hari.', '["Acyclovir Topikal", "Aciclovir", "Acifar", "Acyclovir", "Clinovir", "Herpiclof"]', '["acifar", "acyciovir topikai", "acyclov1r top1kal", "acyclovlr toplkal", "acydovir topikal", "clinovir", "aciclovir", "acycl0vir t0pikal", "acyclovir", "4cyclovir topik4l", "acyclovir topika", "acyc1ovir topika1", "acyclovir topikal"]', '["4cyclovir topik4l", "acyc1ovir topika1", "acyciovir topikai", "acycl0vir t0pikal", "acyclov1r top1kal", "acyclovir topika", "acyclovlr toplkal", "acydovir topikal"]', 'DKL10001696A1', 'acyclovirtopikal', 'acyclovirtopikal');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('tarmeson', 'Tarmeson', 'Desoximetasone 0,25%', 'Kortikosteroid topikal', 'Obat Keras (Lingkaran Merah K)', 'Krim', 'Meredakan gatal-gatal dan gejala peradangan pada kulit akibat sejumlah kondisi, seperti dermatitis , eksim, atau psoriasis', 'Untuk mengobati peradangan dan gatal-gatal akibat eksim, dermatitis, atau alergi, oleskan krim Tarmeson secara merata pada area kulit yang perlu diobati, 1–2 kali sehari atau sesuai petunjuk dokter. Lama pengobatan tidak boleh lebih dari 4 minggu.', '["Tarmeson"]', '["trmeson", "desoximetasone 0,25%", "t4rmeson", "tarmes0n", "tarrneson", "tarme5on", "tarm3son", "tarmeson", "tarmeso"]', '["t4rmeson", "tarm3son", "tarme5on", "tarmes0n", "tarmeso", "tarrneson", "trmeson"]', 'DKL10000841A1', 'tarmeson', 'desoximetasone025');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('wegovy', 'Wegovy', 'Semaglutide', 'Antidiabetes jenis glucagon-like peptide-1 (GLP-1) receptor agonist', 'Obat Keras (Lingkaran Merah K)', 'Injeksi (suntik)', 'Menurunkan berat badan pada orang dewasa dengan obesitas atau kelebihan berat badan', 'Dosis dan aturan pakai Wegovy ditentukan oleh dokter sesuai kondisi pasien. Secara umum, berikut adalah dosis penggunaan Wegovy:', '["Wegovy"]', '["wegov", "weg0vy", "semaglutide", "wgovy", "w3govy", "wegovy"]', '["w3govy", "weg0vy", "wegov", "wgovy"]', 'DKL10000641A1', 'wegovy', 'semaglutide');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('calcitriol', 'Calcitriol', 'Calcitriol', 'Analog vitamin D', 'Obat Keras (Lingkaran Merah K)', 'Kapsul', 'Mengatasi dan mencegah kekurangan kalsium dan penyakit tulang pada penderita gangguan fungsi ginjal dan kelenjar paratiroid', 'Dosis calcitriol yang diresepkan dokter dapat berbeda pada tiap pasien. Berikut ini adalah dosis umum calcitriol berdasarkan kondisi dan usia pasien:', '["Calcitriol", "Calesco", "Kolkatriol", "Oscal", "Ostovel", "Ostriol"]', '["c4lcitriol", "ostovel", "calc1tr1ol", "calesco", "clcitriol", "oscal", "ca1citrio1", "calcitri0l", "kolkatriol", "calcltrlol", "calcitrio", "caicitrioi", "calcitriol"]', '["c4lcitriol", "ca1citrio1", "caicitrioi", "calc1tr1ol", "calcitri0l", "calcitrio", "calcltrlol", "clcitriol"]', 'DKL10001030A1', 'calcitriol', 'calcitriol');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('darifenacin', 'Darifenacin', 'Darifenacin', 'Antispasmodik', 'Obat Keras (Lingkaran Merah K)', 'Tablet, tablet pelepasan lambat', 'Meredakan inkontinensia urine.', 'Darifenacin umunya tersedia dalam bentuk tablet sediaan 7,5 mg dan 15 mg. Dokter akan menentukan dosis berdasarkan kondisi medis dan respons pasien terhadap pengobatan.', '["Darifenacin", "glaukoma sudut sempit", "myasthenia gravis", "kolitis ulseratif yang berat", "toxic megacolon", "menyusui"]', '["darif3nacin", "darifenasin", "dariphenacin", "darifenacin", "drifenacin", "kolitis ulseratif yang berat", "d4rifen4cin", "dar1fenac1n", "darlfenacln", "toxic megacolon", "darifenaci", "myasthenia gravis", "glaukoma sudut sempit"]', '["d4rifen4cin", "dar1fenac1n", "darif3nacin", "darifenaci", "darifenasin", "dariphenacin", "darlfenacln", "drifenacin"]', 'DKL10001108A1', 'darifenacin', 'darifenacin');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('fasidol', 'Fasidol', 'Paracetamol, kafein', 'Analgesik dan antipiretik', 'Obat Bebas (Hijau)', 'Kaplet, sirop, dan drops', 'Menurunkan demam dan meredakan nyeri, seperti sakit kepala, sakit gigi, nyeri haid, atau nyeri otot.', 'Berikut adalah dosis Fasidol berdasarkan varian produknya:', '["Fasidol"]', '["fa5idol", "f4sidol", "paracetamol, kafein", "fasido1", "fas1dol", "fasid0l", "fasidoi", "fasldol", "fasido", "fasidol"]', '["f4sidol", "fa5idol", "fas1dol", "fasid0l", "fasido", "fasido1", "fasidoi", "fasldol"]', 'DBL10000706A1', 'fasidol', 'paracetamolkafein');
