INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('adafimab', 'Adafimab', 'Adalimumab', 'Disease-Modifying Anti-Rheumatic Drugs (DMARDs) / Imunosupresan', 'Obat Keras (Lingkaran Merah K)', 'Suntik', 'Meredakan gejala peradangan pada penyakit rheumatoid arthritis, juvenile idiopathic arthritis, artritis psoriasis , plak psoriasis, spondylitis ankylosing , kolitis ulseratif, dan penyakit Crohn', 'Obat Adafimab akan diberikan melalui suntikan di bawah kulit (subkutan/SC). Dokter akan menentukan dosis Adafimab berdasarkan kondisi yang ingin ditangani. Berikut ini adalah penjelasannya:', '["Adafimab"]', '["adaf1mab", "adafirnab", "aafimab", "adafima", "adafimab", "adaflmab", "adalimumab", "adaphimab", "4d4fim4b"]', '["4d4fim4b", "aafimab", "adaf1mab", "adafima", "adafirnab", "adaflmab", "adaphimab"]', 'DKL10000773A1', 'adafimab', 'adalimumab');
