INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('gabapentin', 'Gabapentin', 'Gabapentin', 'Antikonvulsan dan pereda nyeri neuropati', 'Obat Keras (Lingkaran Merah K)', 'Kapsul', 'Meredakan kejang dan nyeri neuropati , termasuk akibat herpes', 'Penentuan dosis gabapentin tergantung pada kondisi yang diderita pasien. Berikut adalah dosis umum penggunaan gabapentin berdasarkan kondisi yang ingin diatasi:', '["Alpentin", "Epiven", "Gabapentin", "Gabasant", "Gabatin", "Gabesco"]', '["gabapentln", "gabapentin", "epiven", "gabapenti", "gabasant", "gabapent1n", "gabatin", "gabap3ntin", "g4b4pentin", "alpentin", "gbapentin"]', '["g4b4pentin", "gabap3ntin", "gabapent1n", "gabapenti", "gabapentln", "gbapentin"]', 'DKL10001017A1', 'gabapentin', 'gabapentin');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('calesco', 'Calesco', '0,25 mcg calcitriol', 'Analog vitamin D', 'Obat Keras (Lingkaran Merah K)', 'Kapsul lunak', 'Mengatasi dan mencegah kekurangan kalsium dan penyakit tulang pada penderita gangguan fungsi ginjal dan kelenjar paratiroid', 'Dosis Calesco yang diresepkan dokter dapat berbeda pada tiap pasien. Berikut ini adalah dosis umum Calesco berdasarkan kondisi yang diobati dan usia pasien:', '["Calesco"]', '["clesco", "caiesco", "calesco", "c4lesco", "ca1esco", "cale5co", "calesc0", "cal3sco", "calesc", "0,25 mcg calcitriol"]', '["c4lesco", "ca1esco", "caiesco", "cal3sco", "cale5co", "calesc", "calesc0", "clesco"]', 'DKL10000698A1', 'calesco', '025mcgcalcitriol');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('adalimumab', 'Adalimumab', 'Adalimumab', 'Disease-Modifying Anti-Rheumatic Drugs ( DMARDs ) / Imunosupresan', 'Obat Keras (Lingkaran Merah K)', 'Cairan suntik', 'Meredakan gejala peradangan pada penyakit rheumatoid arthritis , juvenile idiopathic arthritis , artritis psoriasis, plak psoriasis, spondylitis ankilosa, kolitis ulseratif, penyakit Crohn, hidradenitis suppurativa, dan uveitis.', 'Obat adalimumab akan diberikan melalui suntikan di bawah kulit (subkutan/SC). Dokter akan menentukan dosis adalimumab berdasarkan kondisi yang ingin ditangani. Berikut ini adalah penjelasannya:', '["Adalimumab", "Rheumatoid arthritis", "bengkak", "dan kaku Juvenile idiopathic arthritis", "Amgevita", "Humira"]', '["ada1imumab", "dan kaku juvenile idiopathic arthritis", "adalirnurnab", "adalimuma", "rheumatoid arthritis", "amgevita", "bengkak", "adaiimumab", "4d4limum4b", "adalimumab", "adallmumab", "aalimumab", "adal1mumab"]', '["4d4limum4b", "aalimumab", "ada1imumab", "adaiimumab", "adal1mumab", "adalimuma", "adalirnurnab", "adallmumab"]', 'DKL10001005A1', 'adalimumab', 'adalimumab');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('caliberi', 'Caliberi', 'Tadalafil', 'Penghambat phosphodiesterase -5 (PDE5)', 'Obat Keras (Lingkaran Merah K)', 'Orodispersible film', 'Mengobati impotensi dan gejala pembesaran prostat jinak', 'Dosis Caliberi akan disesuaikan oleh dokter berdasarkan kondisi yang diderita pasien. Secara umum, berikut adalah rincian dosis Caliberi:', '["Caliberi"]', '["cal1ber1", "caliber", "c4liberi", "cliberi", "caliberi", "ca1iberi", "tadalafil", "callberl", "caiiberi", "calib3ri"]', '["c4liberi", "ca1iberi", "caiiberi", "cal1ber1", "calib3ri", "caliber", "callberl", "cliberi"]', 'DKL10000795A1', 'caliberi', 'tadalafil');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('taxegram', 'Taxegram', 'Cefotaxime', 'Antibiotik sefalosporin', 'Obat Keras (Lingkaran Merah K)', 'Suntik', 'Menangani infeksi bakteri dan mencegah infeksi operasi', 'Taxegram akan disuntikkan melalui otot (intramuskular/IM) atau pembuluh darah (intravena/IV) oleh dokter atau petugas medis di bawah pengawasan dokter. Berikut ini adalah dosis umum penggunaan Taxegram berdasarkan kondisi yang akan ditangani:', '["Taxegram"]', '["taxegram", "tax3gram", "txegram", "t4xegr4m", "taxegra", "taxegrarn", "taksegram", "cefotaxime"]', '["t4xegr4m", "taksegram", "tax3gram", "taxegra", "taxegrarn", "txegram"]', 'DKL10000825A1', 'taxegram', 'cefotaxime');
