INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('ikagen-salep-kulit', 'Ikagen Salep Kulit', 'Gentamicin', 'Antibiotik golongan aminoglikosida', 'Obat Keras (Lingkaran Merah K)', 'Salep kulit', 'Mengobati infeksi kulit yang disebabkan oleh bakteri, seperti: Impetigo Bisul Folikulitis Luka bernanah', 'Untuk mengobati infeksi kulit akibat bakteri, oleskan salep Ikagen secara merata pada area kulit yang perlu diobati, 3–4 kali sehari atau sesuai petunjuk dokter.', '["Ikagen Salep Kulit"]', '["ik4gen s4lep kulit", "ikagen sa1ep ku1it", "ikagen salep kulit", "1kagen salep kul1t", "gentamicin", "ikagen 5alep kulit", "ikag3n sal3p kulit", "iagen salep kulit", "ikagen saiep kuiit", "ikagen salep kuli"]', '["1kagen salep kul1t", "iagen salep kulit", "ik4gen s4lep kulit", "ikag3n sal3p kulit", "ikagen 5alep kulit", "ikagen sa1ep ku1it", "ikagen saiep kuiit", "ikagen salep kuli"]', 'DKL10001677A1', 'ikagensalepkulit', 'gentamicin');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('gabasant', 'Gabasant', 'Gabapentin 300 mg', 'Antikonvulsan atau antikejang', 'Obat Keras (Lingkaran Merah K)', 'Kapsul', 'Meredakan kejang epilepsi dan nyeri saraf (neuropati), termasuk yang dipicu oleh herpes zoster .', 'Dosis dan durasi penggunaan Gabasant akan ditentukan oleh dokter sesuai dengan kondisi yang ditangani.', '["Gabasant"]', '["gabasan", "gabasant", "gaba5ant", "g4b4s4nt", "gabapentin 300 mg", "gbasant"]', '["g4b4s4nt", "gaba5ant", "gabasan", "gbasant"]', 'DKL10000801A1', 'gabasant', 'gabapentin300mg');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('lafen', 'Lafen', 'Diclofenac sodium', 'Obat antiinflamasi nonsteroid (OAINS)', 'Obat Keras (Lingkaran Merah K)', 'Tablet salut enterik', 'Meredakan nyeri dan peradangan, seperti nyeri sendi akibat arthritis, nyeri otot, nyeri punggung, dan nyeri haid', 'Dosis Lafen ditentukan oleh dokter berdasarkan kondisi medis dan respons pasien terhadap pengobatan. Secara umum, dosis diclofenac sodium untuk dewasa adalah:', '["Lafen"]', '["laphen", "l4fen", "laf3n", "iafen", "diclofenac sodium", "lafen", "1afen"]', '["1afen", "iafen", "l4fen", "laf3n", "laphen"]', 'DKL10000486A1', 'lafen', 'diclofenacsodium');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('obat-pencahar', 'Obat Pencahar', 'Obat Pencahar', 'Pengobatan Umum', 'Obat Keras (Lingkaran Merah K)', 'Sediaan oral/topikal sesuai instruksi kemasan.', 'Mengatasi gangguan kesehatan dan meredakan gejala sesuai petunjuk medis.', 'Obat pencahar terbagi dalam lima jenis. Masing-masing jenis obat tersebut memiliki cara kerja yang berbeda dalam mengatasi sembelit. Efek laksatif dari obat pencahar juga bisa dirasakan dalam waktu yang bervariasi, mulai dari 15 menit sampai 72 jam, tergantung jenis dan sediaan obat yang digunakan.', '["Obat Pencahar", "Fibrozee", "Fibrefirst Plus", "Femmy Fyber", "Maximus", "suspensi"]', '["obat p3ncahar", "femmy fyber", "fibrefirst plus", "obat pencahar", "0bat pencahar", "ob4t penc4h4r", "maximus", "oat pencahar", "obat pensahar", "fibrozee", "obat pencaha"]', '["0bat pencahar", "oat pencahar", "ob4t penc4h4r", "obat p3ncahar", "obat pencaha", "obat pensahar"]', 'DKL10001224A1', 'obatpencahar', 'obatpencahar');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('laflanac', 'Laflanac', 'Diclofenac potassium 25 mg', 'Obat anti inflamasi nonsteroid', 'Obat Keras (Lingkaran Merah K)', 'Tablet', 'Meredakan gejala peradangan, seperti nyeri dan bengkak, migrain , sakit gigi, nyeri menstruasi, nyeri otot, nyeri atau radang sendi', 'Dosis Laflanac akan disesuaikan oleh dokter dengan tujuan pengobatan dan kondisi pasien. Berikut adalah dosis umum dari konsumsi Laflanac pada orang dewasa:', '["Laflanac"]', '["iafianac", "laphlanac", "l4fl4n4c", "laflana", "laflanac", "laflanas", "1af1anac", "lflanac", "diclofenac potassium 25 mg"]', '["1af1anac", "iafianac", "l4fl4n4c", "laflana", "laflanas", "laphlanac", "lflanac"]', 'DKL10000786A1', 'laflanac', 'diclofenacpotassium25mg');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('dasatinib', 'Dasatinib', 'Dasatinib', 'Obat antikanker jenis penghambat protein kinase', 'Obat Keras (Lingkaran Merah K)', 'Tablet', 'Menangani kanker darah jenis chronic myeloid leukemia (CML) dan acute lymphoblastic leukemia (ALL)', 'Berikut ini adalah dosis dasatinib untuk orang dewasa berdasarkan jenis kanker darah yang akan diobati:', '["Dasatinib", "perdarahan saluran cerna", "intoleransi laktosa", "penyakit paru-paru", "penyakit jantung", "hipokalemia"]', '["dasatinib", "penyakit jantung", "dsatinib", "dasatlnlb", "dasat1n1b", "intoleransi laktosa", "perdarahan saluran cerna", "da5atinib", "dasatini", "penyakit paru-paru", "d4s4tinib"]', '["d4s4tinib", "da5atinib", "dasat1n1b", "dasatini", "dasatlnlb", "dsatinib"]', 'DKL10000911A1', 'dasatinib', 'dasatinib');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('taxime', 'Taxime', 'Cefixime', 'Antibiotik golongan sefalosporin', 'Obat Keras (Lingkaran Merah K)', 'Kaplet, kapsul, dan sirop kering', 'Mengobati infeksi bakteri', 'Dosis Taxime dapat berbeda-beda, tergantung pada kondisi, tingkat keparahan infeksi, serta usia dan berat badan pasien. Secara umum, berikut adalah rincian dosis Taxime sesuai kondisi yang diobati:', '["Taxime"]', '["cefixime", "taxirne", "taxime", "taksime", "tax1me", "t4xime", "taxim", "taxim3", "txime", "taxlme"]', '["t4xime", "taksime", "tax1me", "taxim", "taxim3", "taxirne", "taxlme", "txime"]', 'DKL10000616A1', 'taxime', 'cefixime');
