INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('adapalene', 'Adapalene', 'Adapalene', 'Obat resep', 'Obat Keras (Lingkaran Merah K)', 'Krim, gel', 'Mencegah dan mengatasi jerawat atau komedo', 'Dosis dan aturan pakai adapalene akan ditentukan oleh dokter berdasarkan usia dan kondisi pasien. Berikut adalah dosis umum adapalene:', '["Adapalene"]', '["adapalene", "adapalen", "adapal3n3", "adapa1ene", "adapaiene", "aapalene", "4d4p4lene"]', '["4d4p4lene", "aapalene", "adapa1ene", "adapaiene", "adapal3n3", "adapalen"]', 'DKL10000891A1', 'adapalene', 'adapalene');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('widoxil', 'WIdoxil', '500 mg cefadroxil', 'Antibiotik golongan sefalosporin', 'Obat Keras (Lingkaran Merah K)', 'Kapsul', 'Mengobati infeksi bakteri pada kulit dan jaringan, otot dan tulang, saluran pernapasan, saluran kemih, serta area kemaluan', 'Dosis dan aturan pakai Widoxil ditentukan oleh dokter sesuai kondisi pasien. Secara umum, berikut adalah dosis penggunaan Widoxil:', '["WIdoxil"]', '["widoxil", "500 mg cefadroxil", "wldoxll", "widoksil", "wdoxil", "widoxi", "widoxii", "wid0xil", "widoxi1", "w1dox1l"]', '["w1dox1l", "wdoxil", "wid0xil", "widoksil", "widoxi", "widoxi1", "widoxii", "wldoxll"]', 'DKL10000704A1', 'widoxil', '500mgcefadroxil');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('winatin', 'Winatin', 'Loratadine', 'Antihistamin', 'Obat Keras (Lingkaran Merah K)', 'Kaplet', 'Meredakan gejala alergi , seperti rhinitis alergi , biduran, atau konjungtivitis alergi', 'Dosis umum Winatin untuk meredakan gejala alergi pada orang dewasa dan anak usia >12 tahun adalah 1 tablet, 1 kali sehari.', '["Winatin"]', '["wlnatln", "w1nat1n", "win4tin", "loratadine", "wnatin", "winati", "winatin"]', '["w1nat1n", "win4tin", "winati", "wlnatln", "wnatin"]', 'DKL10000730A1', 'winatin', 'loratadine');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('calinda', 'Calinda', 'Clindamycin 300 mg', 'Antibiotik golongan lincosamide atau lincomycin', 'Obat Keras (Lingkaran Merah K)', 'Kapsul', 'Mengatasi infeksi bakteri', 'Penentuan dosis Calinda sepenuhnya berada di bawah pertimbangan dokter. Usia, tingkat keparahan infeksi, dan respons tubuh pasien menjadi faktor penentu. Meski demikian, ada dosis umum pemberian obat antibiotik ini berdasarkan usia, yaitu:', '["Calinda"]', '["calinda", "c4lind4", "calind", "cal1nda", "clinda", "ca1inda", "clindamycin 300 mg", "callnda", "salinda", "caiinda"]', '["c4lind4", "ca1inda", "caiinda", "cal1nda", "calind", "callnda", "clinda", "salinda"]', 'DKL10000684A1', 'calinda', 'clindamycin300mg');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('iliadin', 'Iliadin', 'Oxymetazoline', 'Dekongestan', 'Obat Bebas Terbatas (Lingkaran Biru)', 'Semprot hidung dan tetes hidung', 'Meringankan gejala hidung tersumbat karena flu, batuk pilek, sinusitis, atau rhinitis alergi.', 'Berikut adalah dosis Iliadin untuk menghilangkan keluhan hidung tersumbat sesuai bentuk sediaannya:', '["Iliadin"]', '["iliadi", "iliadin", "oxymetazoline", "1l1ad1n", "iiadin", "i1iadin", "iiiadin", "ili4din", "llladln"]', '["1l1ad1n", "i1iadin", "iiadin", "iiiadin", "ili4din", "iliadi", "llladln"]', 'DTL10000698A1', 'iliadin', 'oxymetazoline');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('lagas', 'Lagas', 'Lansoprazole', 'Penghambat pompa proton', 'Obat Keras (Lingkaran Merah K)', 'Kaplet lepas tunda', 'Menurunkan produksi asam lambung dan mengatasi tukak lambung, ulkus duodenum , serta GERD', 'Berikut ini adalah dosis umum penggunaan Lagas berdasarkan kondisi pasien:', '["Lagas"]', '["lagas", "1agas", "lansoprazole", "l4g4s", "laga5", "iagas"]', '["1agas", "iagas", "l4g4s", "laga5"]', 'DKL10000488A1', 'lagas', 'lansoprazole');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('ramoxyl', 'Ramoxyl', 'Amoxicillin 500 mg', 'Antibiotik penisilin', 'Obat Keras (Lingkaran Merah K)', 'Kaplet', 'Mengobati infeksi bakteri', 'Dosis Ramoxyl akan disesuaikan oleh dokter berdasarkan kondisi yang diderita pasien. Secara umum, berikut adalah rincian dosis Ramoxyl untuk mengatasi infeksi bakteri di berbagai bagian tubuh:', '["Ramoxyl"]', '["ramoxy", "r4moxyl", "amoxicillin 500 mg", "ramoxy1", "ramoxyl", "rmoxyl", "ram0xyl", "ramoksyl", "ramoxyi", "rarnoxyl"]', '["r4moxyl", "ram0xyl", "ramoksyl", "ramoxy", "ramoxy1", "ramoxyi", "rarnoxyl", "rmoxyl"]', 'DKL10000748A1', 'ramoxyl', 'amoxicillin500mg');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('gabatin', 'Gabatin', 'Gabapentin', 'Antikonvulsan atau antikejang', 'Obat Keras (Lingkaran Merah K)', 'Kapsul', 'Menangani kejang epilepsi', 'Dokter akan menyesuaikan dosis Gabatin sesuai dengan kondisi kesehatan dan usia pasien. Berikut adalah dosis umum penggunaan Gabatin:', '["Gabatin"]', '["gabapentin", "gbatin", "gabat1n", "gabatln", "gabati", "gabatin", "g4b4tin"]', '["g4b4tin", "gabat1n", "gabati", "gabatln", "gbatin"]', 'DKL10000694A1', 'gabatin', 'gabapentin');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('tazimut', 'Tazimut', 'Dexamethasone', 'Kortikosteroid', 'Obat Keras (Lingkaran Merah K)', 'Tablet', 'Meredakan peradangan, reaksi alergi, penyakit autoimun , asma, dan gangguan kulit atau sendi.', 'Dosis Tazimut ditentukan oleh dokter berdasarkan kondisi yang ditangani, tingkat keparahan penyakit, serta respons pasien terhadap pengobatan.', '["Tazimut"]', '["tazimut", "tazlmut", "tasimut", "tazirnut", "tzimut", "dexamethasone", "tazimu", "taz1mut", "t4zimut"]', '["t4zimut", "tasimut", "taz1mut", "tazimu", "tazirnut", "tazlmut", "tzimut"]', 'DKL10000750A1', 'tazimut', 'dexamethasone');
