INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('wiros', 'Wiros', 'Piroxicam 20 mg', 'Obat antiinflamasi nonsteroid ( OAINS )', 'Obat Keras (Lingkaran Merah K)', 'Kapsul', 'Meredakan nyeri dan peradangan', 'Berikut ini adalah dosis umum penggunaan Wiros untuk menangani nyeri dan peradangan akibat osteoarthritis, rheumatoid arthritis, dan ankylosing spondylitis:', '["Wiros"]', '["wiros", "piroxicam 20 mg", "wiro5", "wir0s", "w1ros", "wlros"]', '["w1ros", "wir0s", "wiro5", "wlros"]', 'DKL10000532A1', 'wiros', 'piroxicam20mg');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('dasnib', 'Dasnib', 'Dasatinib', 'Obat antikanker jenis penghambat protein kinase', 'Obat Keras (Lingkaran Merah K)', 'Tablet', 'Menangani kanker darah jenis chronic myeloid leukemia (CML) dan acute lymphoblastic leukemia (ALL)', 'Berikut ini adalah dosis Dasnib untuk orang dewasa berdasarkan jenis kanker darah yang akan diobati:', '["Dasnib"]', '["dasatinib", "d4snib", "dsnib", "dasnib", "dasnlb", "dasni", "da5nib", "dasn1b"]', '["d4snib", "da5nib", "dasn1b", "dasni", "dasnlb", "dsnib"]', 'DKL10000593A1', 'dasnib', 'dasatinib');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('gabatrop', 'Gabatrop', 'Pregabalin', 'Obat antikonvulsan', 'Obat Keras (Lingkaran Merah K)', 'Kapsul', 'Mengendalikan kejang parsial pada penderita epilepsi', 'Dalam pengobatan nyeri neuropati, fibromyalgia, epilepsi, atau gangguan kecemasan, dosis Gabatrop untuk orang dewasa adalah 150–600 mg per hari, dibagi dalam 2–3 kali jadwal konsumsi, tergantung pada kondisi yang ditangani.', '["Gabatrop"]', '["gbatrop", "g4b4trop", "gabatrop", "pregabalin", "gabatr0p", "gabatro"]', '["g4b4trop", "gabatr0p", "gabatro", "gbatrop"]', 'DKL10000816A1', 'gabatrop', 'pregabalin');
