INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('gabiron', 'Gabiron', 'Gabapentin', 'Antikonvulsan atau antikejang', 'Obat Keras (Lingkaran Merah K)', 'Kapsul', 'Meredakan kejang epilepsi dan nyeri saraf (neuropati) yang diakibatkan oleh diabetes, herpes zoster, dan sindrom kaki gelisah', 'Dosis minum Gabiron dapat berbeda pada setiap orang, karena bergantung pada kondisi, usia, dan respons pasien terhadap pengobatan. Namun, ada dosis umum pemberian obat ini berdasarkan kondisi, yaitu:', '["Gabiron"]', '["gabiron", "gabiro", "gabapentin", "gabir0n", "gablron", "g4biron", "gab1ron", "gbiron"]', '["g4biron", "gab1ron", "gabir0n", "gabiro", "gablron", "gbiron"]', 'DKL10000706A1', 'gabiron', 'gabapentin');
