INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('imatinib', 'Imatinib', 'Imatinib', 'Obat antikanker golongan penghambat protein kinase', 'Obat Keras (Lingkaran Merah K)', 'Tablet dan kapsul', 'Mengobati leukemia, gastrointestinal stromal tumors (GIST), sindrom mielodisplasia, sindrom hipereosinofilik, mastositosis sistemik agresif, serta dermatofibrosarcoma protuberans yang sulit diatasi melalui operasi', 'Dokter akan menentukan dosis dan durasi pengobatan dengan imatinib berdasarkan usia, kondisi, dan respons tubuh pasien terhadap obat. Berikut ini adalah dosis imatinib berdasarkan kondisi yang ingin ditangani:', '["Imatinib", "Glivec", "Imatero", "Leukivec", "Mianib", "Nivec"]', '["leukivec", "iatinib", "imatero", "1mat1n1b", "irnatinib", "im4tinib", "lmatlnlb", "imnib 400", "imatini", "glivec", "imatinib"]', '["1mat1n1b", "iatinib", "im4tinib", "imatini", "irnatinib", "lmatlnlb"]', 'DKL10000813A1', 'imatinib', 'imatinib');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('ranexa', 'Ranexa', 'Ranolazine', 'Antiangina', 'Obat Keras (Lingkaran Merah K)', 'Tablet lepas lambat', 'Mencegah atau mengurangi terjadinya angina pektoris', 'Dosis Ranexa akan ditentukan dokter sesuai kondisi kesehatan dan respons terhadap pengobatan. Berikut rekomendasi dosis umum ranolazine yang terkandung dalam Ranexa:', '["Ranexa"]', '["ranolazine", "raneksa", "ranexa", "r4nex4", "rnexa", "ranex", "ran3xa"]', '["r4nex4", "ran3xa", "raneksa", "ranex", "rnexa"]', 'DKL10000607A1', 'ranexa', 'ranolazine');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('adenosine', 'Adenosine', 'Adenosine', 'Vasodilator', 'Obat Keras (Lingkaran Merah K)', 'Suntik', 'Sebagai obat tambahan dalam pemeriksaan radiologi jantung', 'Adenosine akan disuntikkan ke pembuluh darah (intravena/IV) secara langsung atau melalui infus. Penyuntikan akan dilakukan langsung oleh dokter atau petugas medis di bawah pengawasan dokter di rumah sakit. Secara umum, berikut dosis adenosine berdasarkan tujuan penggunaannya:', '["Adenosine", "Bio ATP", "Lapibion", "Neuro ATP", "Vitap", "sick sinus syndrome"]', '["adenoslne", "adenosin", "adenosine", "ad3nosin3", "vitap", "bio atp", "adeno5ine", "adenos1ne", "lapibion", "aenosine", "4denosine", "neuro atp", "aden0sine"]', '["4denosine", "ad3nosin3", "aden0sine", "adeno5ine", "adenos1ne", "adenosin", "adenoslne", "aenosine"]', 'DKL10000918A1', 'adenosine', 'adenosine');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('lameson', 'Lameson', 'Methylprednisolone', 'Kortikosteroid', 'Obat Keras (Lingkaran Merah K)', 'Tablet, suspensi, dan suntik', 'Mengatasi peradangan, reaksi alergi, dan penyakit autoimun', 'Dosis Lameson yang diberikan dokter bisa berbeda-beda, tergantung pada kondisi yang ingin ditangani, derajat keparahan penyakit, dan respons tubuh pasien terhadap obat. Secara umum, dosis Lameson berdasarkan bentuk sediaan dan kondisi yang ditangani adalah sebagai berikut:', '["Lameson"]', '["l4meson", "methylprednisolone", "lameson", "iameson", "lame5on", "lam3son", "larneson", "1ameson", "lameso", "lames0n"]', '["1ameson", "iameson", "l4meson", "lam3son", "lame5on", "lames0n", "lameso", "larneson"]', 'DKL10000719A1', 'lameson', 'methylprednisolone');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('ociderm-n', 'Ociderm-N', 'Kombinasi fluocinolone 0,25 mg dan neomycin 5 mg', 'Kombinasi kortikosteroid topikal (fluocinolone) dan antibiotik topikal golongan aminoglikosida (neomycin)', 'Obat Keras (Lingkaran Merah K)', 'Krim', 'Mengatasi dermatitis yang disertai infeksi bakteri', 'Penggunaan Ociderm-N harus mengikuti petunjuk dokter karena dosis dan frekuensi pemakaian dapat berbeda, tergantung kondisi kulit. Umumnya, untuk mengatasi dermatitis yang disertai infeksi bakteri, oleskan krim Ociderm-N tipis dan merata pada area kulit yang bermasalah sebanyak 2–4 kali sehari.', '["Ociderm-N"]', '["oclderm-n", "0ciderm-n", "osiderm-n", "oc1derm-n", "oiderm-n", "ociderm-", "kombinasi fluocinolone 0,25 mg dan neomycin 5 mg", "ociderrn-n", "ociderm-n", "ocid3rm-n"]', '["0ciderm-n", "oc1derm-n", "ocid3rm-n", "ociderm-", "ociderrn-n", "oclderm-n", "oiderm-n", "osiderm-n"]', 'DKL10000830A1', 'ocidermn', 'kombinasifluocinolone025mgdanneomycin5mg');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('octenidine', 'Octenidine', 'Octenidine', 'Antiseptik bispyridine', 'Obat Bebas (Hijau)', 'Semprot atau gel', 'Menjaga kebersihan luka dan mencegah infeksi pada luka', 'Berikut adalah dosis umum pemakaian octenidine untuk menjaga kebersihan luka dan mencegah infeksi pada luka:', '["Octenidine", "Betadine Antiseptic Clear Spray", "Ceradan Diaper Krim", "Hexadine", "Innadine", "Lukajel"]', '["octen1d1ne", "otenidine", "octenidin", "hexadine", "octenidine", "ostenidine", "betadine antiseptic clear spray", "innadine", "oct3nidin3", "octenldlne", "ceradan diaper krim", "0ctenidine"]', '["0ctenidine", "oct3nidin3", "octen1d1ne", "octenidin", "octenldlne", "ostenidine", "otenidine"]', 'DBL10001026A1', 'octenidine', 'octenidine');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('ranigen', 'Ranigen', 'Ranitidin 150 mg', 'Antagonis H2', 'Obat Keras (Lingkaran Merah K)', 'Tablet salut selaput', 'Menurunkan produksi asam lambung', 'Dosis Ranigen dapat berbeda tergantung kondisi yang ditangani. Berikut ini adalah rincian dosis Ranigen:', '["Ranigen"]', '["ranig3n", "ran1gen", "rnigen", "ranigen", "ranitidin 150 mg", "ranlgen", "ranige", "r4nigen"]', '["r4nigen", "ran1gen", "ranig3n", "ranige", "ranlgen", "rnigen"]', 'DKL10000708A1', 'ranigen', 'ranitidin150mg');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('tecentriq', 'Tecentriq', 'Atezolizumab', 'Imunoterapi kanker', 'Obat Keras (Lingkaran Merah K)', 'Cairan infus', 'Menangani beberapa jenis kanker, seperti melanoma , kanker paru-paru, sarkoma jaringan lunak , kanker kandung kemih, dan kanker hati', 'Berikut ini adalah dosis Tecentriq untuk orang dewasa berdasarkan jenis kanker yang akan diobati:', '["Tecentriq"]', '["tcentriq", "tecentr1q", "tecentriq", "tesentriq", "tecentri", "atezolizumab", "tecentrlq", "t3c3ntriq"]', '["t3c3ntriq", "tcentriq", "tecentr1q", "tecentri", "tecentrlq", "tesentriq"]', 'DKL10000943A1', 'tecentriq', 'atezolizumab');
