INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('x-cam', 'X-Cam', 'Meloxicam', 'Obat antiinflamasi nonsteroid ( OAINS )', 'Obat Keras (Lingkaran Merah K)', 'Tablet', 'Mengatasi gejala osteoarthritis dan rheumatoid arthritis', 'Dosis X-Cam ditentukan berdasarkan sediaan obat, kondisi yang diatasi, tingkat keparahan penyakit, serta usia pasien. Secara umum dosis X-Cam yang diberikan kepada pasien adalah:', '["X-Cam"]', '["x-cam", "meloxicam", "x-sam", "ks-cam", "x-carn", "x-c4m"]', '["ks-cam", "x-c4m", "x-carn", "x-sam"]', 'DKL10000406A1', 'xcam', 'meloxicam');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('gaforin', 'Gaforin', 'Gatifloxacin', 'Antibiotik golongan quinolone', 'Obat Keras (Lingkaran Merah K)', 'Tetes mata ( eye drop )', 'Mengobati konjungtivitis dan keratitis akibat infeksi bakteri', 'Berikut adalah rekomendasi dosis Gaforin pada orang dewasa dan anak usia ≥1 tahun:', '["Gaforin"]', '["gatifloxacin", "gaforln", "gaforin", "gafori", "gaf0rin", "gaphorin", "gforin", "gafor1n", "g4forin"]', '["g4forin", "gaf0rin", "gafor1n", "gafori", "gaforln", "gaphorin", "gforin"]', 'DKL10000710A1', 'gaforin', 'gatifloxacin');
