INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('allylestrenol', 'Allylestrenol', 'Allylestrenol', 'Progesteron sintetis', 'Obat Keras (Lingkaran Merah K)', 'Tablet', 'Mencegah keguguran yang diakibatkan oleh kurangnya hormon progesteron', 'Dosis dan aturan pakai allylestrenol ditentukan oleh dokter sesuai usia dan kondisi pasien. Secara umum, dosis pemberian allylestrenol sesuai tujuannya adalah:', '["Allylestrenol", "Alyrenol", "Nobor", "Obstanon", "Preabor", "Pregnolin"]', '["a11y1estreno1", "aiiyiestrenoi", "preabor", "obstanon", "nobor", "allylestrenol", "allyle5trenol", "allyl3str3nol", "allylestren0l", "allylestreno", "alyrenol", "alylestrenol", "4llylestrenol"]', '["4llylestrenol", "a11y1estreno1", "aiiyiestrenoi", "allyl3str3nol", "allyle5trenol", "allylestren0l", "allylestreno", "alylestrenol"]', 'DKL10001386A1', 'allylestrenol', 'allylestrenol');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('lameson-sirup', 'Lameson Sirup', 'Methylprednisolone', 'Kortikosteroid', 'Obat Keras (Lingkaran Merah K)', 'Sirup', 'Mengurangi peradangan, mengatasi reaksi alergi berat, menangani penyakit autoimun, serta membantu mencegah reaksi penolakan organ setelah transplantasi', 'Dosis Lameson Sirup akan ditentukan oleh dokter berdasarkan penyakit yang diobati, tingkat keparahan kondisi, serta respons pasien terhadap pengobatan.', '["Lameson Sirup"]', '["lameson s1rup", "methylprednisolone", "l4meson sirup", "lameson siru", "lame5on 5irup", "lam3son sirup", "lameson sirup", "iameson sirup", "lames0n sirup", "1ameson sirup"]', '["1ameson sirup", "iameson sirup", "l4meson sirup", "lam3son sirup", "lame5on 5irup", "lames0n sirup", "lameson s1rup", "lameson siru"]', 'DKL10001282A1', 'lamesonsirup', 'methylprednisolone');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('imboost-bone', 'Imboost Bone', 'Tiap tablet effervescent mengandung kalsium 250 mg, vitamin C 500 mg, vitamin D 400 IU, vitamin B6 15 mg, vitamin K2 50 mcg, zinc picolinate 10 mg, dan magnesium 50 mg', 'Suplemen', 'Obat Bebas (Hijau)', 'Tablet effervescent', 'Membantu menjaga kesehatan tulang dan gigi', 'Untuk menjaga kesehatan tulang dan gigi, Imboost Bone bisa dikonsumsi 1 tablet effervescent per hari.', '["Imboost Bone"]', '["lmboost bone", "imboost bon", "1mboost bone", "imboost bon3", "imboost bone", "iboost bone", "imb00st b0ne", "irnboost bone", "imboo5t bone", "tiap tablet effervescent mengandung kalsium 250 mg, vitamin c 500 mg, vitamin d 400 iu, vitamin b6 15 mg, vitamin k2 50 mcg, zinc picolinate 10 mg, dan magnesium 50 mg"]', '["1mboost bone", "iboost bone", "imb00st b0ne", "imboo5t bone", "imboost bon", "imboost bon3", "irnboost bone", "lmboost bone"]', 'DBL10001153A1', 'imboostbone', 'tiaptableteffervescentmengandungkalsium250mgvitaminc500mgvitamind400iuvitaminb615mgvitamink250mcgzincpicolinate10mgdanmagnesium50mg');
INSERT INTO medicines (id, medicine_name, generic_name, category, bpom_class, dosage_and_forms, indications, usage_instructions, brand_names, alias_names, common_misspellings, bpom_registration, normalized_name, normalized_generic) VALUES ('octreotide', 'Octreotide', 'Octreotide', 'Octapeptide', 'Obat Keras (Lingkaran Merah K)', 'Injeksi', 'Menurunkan jumlah hormon pertumbuhan pada penderita akromegali , mengontrol gejala diare dan flushing pada wajah dan leher akibat tumor karsinoid dan VIP tumor.', 'Octreotide hanya boleh diberikan oleh dokter atau petugas medis di bawah pengawasan dokter. Dosis disesuaikan dengan kondisi dan respons pasien terhadap obat. Berikut adalah rincian dosis octreotide untuk pasien dewasa berdasarkan tujuan pengobatannya:', '["Octreotide", "Sandostatin Lar", "Octide", "penyakit ginjal", "penyakit liver", "gangguan tiroid"]', '["penyakit ginjal", "penyakit liver", "0ctre0tide", "sandostatin lar", "octreot1de", "octreotid", "ostreotide", "octreotlde", "otreotide", "octide", "octr3otid3", "octreotide"]', '["0ctre0tide", "octr3otid3", "octreot1de", "octreotid", "octreotlde", "ostreotide", "otreotide"]', 'DKL10001042A1', 'octreotide', 'octreotide');
